 // console.log('NO INTERSECTION FOUND, RETURN NODE CENTER', node);\\n    return node;\\n  }\\n\\n  if (intersections.length &gt; 1) {\\n    // More intersections, find the one nearest to edge end point\\n    intersections.sort(function (p, q) {\\n      var pdx = p.x - point.x;\\n      var pdy = p.y - point.y;\\n      var distp = Math.sqrt(pdx * pdx + pdy * pdy);\\n\\n      var qdx = q.x - point.x;\\n      var qdy = q.y - point.y;\\n      var distq = Math.sqrt(qdx * qdx + qdy * qdy);\\n\\n      return distp &lt; distq ? -1 : distp === distq ? 0 : 1;\\n    });\\n  }\\n  return intersections[0];\\n}\\n\"</span>,<span class=\"code-string\">\"import { select } from 'd3';\\nimport { log } from '../logger'; // eslint-disable-line\\nimport { labelHelper, updateNodeBounds, insertPolygonShape } from './shapes/util';\\nimport { getConfig } from '../config';\\nimport intersect from './intersect/index.js';\\nimport createLabel from './createLabel';\\nimport note from './shapes/note';\\nimport { parseMember } from '../diagrams/class/svgDraw';\\nimport { evaluate, sanitizeText as sanitize } from '../diagrams/common/common';\\n\\nconst sanitizeText = (txt) =&gt; sanitize(txt, getConfig());\\n\\nconst question = (parent, node) =&gt; {\\n  const { shapeSvg, bbox } = labelHelper(parent, node, undefined, true);\\n\\n  const w = bbox.width + node.padding;\\n  const h = bbox.height + node.padding;\\n  const s = w + h;\\n  const points = [\\n    { x: s / 2, y: 0 },\\n    { x: s, y: -s / 2 },\\n    { x: s / 2, y: -s },\\n    { x: 0, y: -s / 2 },\\n  ];\\n\\n  log.info('Question main (Circle)');\\n\\n  const questionElem = insertPolygonShape(shapeSvg, s, s, points);\\n  questionElem.attr('style', node.style);\\n  updateNodeBounds(node, questionElem);\\n\\n  node.intersect = function (point) {\\n    log.warn('Intersect called');\\n    return intersect.polygon(node, points, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst choice = (parent, node) =&gt; {\\n  const shapeSvg = parent\\n  