 @param borders\\n * @param totalWidth\\n * @param totalHeight\\n */\\nfunction applyNodePropertyBorders(rect, borders, totalWidth, totalHeight) {\\n  const strokeDashArray = [];\\n  const addBorder = (length) =&gt; {\\n    strokeDashArray.push(length);\\n    strokeDashArray.push(0);\\n  };\\n  const skipBorder = (length) =&gt; {\\n    strokeDashArray.push(0);\\n    strokeDashArray.push(length);\\n  };\\n  if (borders.includes('t')) {\\n    log.debug('add top border');\\n    addBorder(totalWidth);\\n  } else {\\n    skipBorder(totalWidth);\\n  }\\n  if (borders.includes('r')) {\\n    log.debug('add right border');\\n    addBorder(totalHeight);\\n  } else {\\n    skipBorder(totalHeight);\\n  }\\n  if (borders.includes('b')) {\\n    log.debug('add bottom border');\\n    addBorder(totalWidth);\\n  } else {\\n    skipBorder(totalWidth);\\n  }\\n  if (borders.includes('l')) {\\n    log.debug('add left border');\\n    addBorder(totalHeight);\\n  } else {\\n    skipBorder(totalHeight);\\n  }\\n  rect.attr('stroke-dasharray', strokeDashArray.join(' '));\\n}\\n\\nconst rectWithTitle = (parent, node) =&gt; {\\n  // const { shapeSvg, bbox, halfPadding } = labelHelper(parent, node, 'node ' + node.classes);\\n\\n  let classes;\\n  if (!node.classes) {\\n    classes = 'node default';\\n  } else {\\n    classes = 'node ' + node.classes;\\n  }\\n  // Add outer g element\\n  const shapeSvg = parent\\n    .insert('g')\\n    .attr('class', classes)\\n    .attr('id', node.domId || node.id);\\n\\n  // Create the title label and insert it after the rect\\n  const rect = shapeSvg.insert('rect', ':first-child');\\n  // const innerRect = shapeSvg.insert('rect');\\n  const innerLine = shapeSvg.insert('line');\\n\\n  const label = shapeSvg.insert('g').attr('class', 'label');\\n\\n  const text2 = node.labelText.flat ? node.labelText.flat() : node.labelText;\\n  // const text2 = typeof text2prim === 'object' ? text2prim[0] : text2prim;\\n\\n  let title = '';\\n  if (typeof text2 === 'object') {\\n    title = text2[0];\\n  } else {\\n    title = text2;\\n  }\\n  log.info('Label text abc79', title, text2, typeof text2 === 'object');\\n\\n  const text = label.node().appendChild(createLabel(title, node.labelStyle, true, true));\\n  let bbox = { width: 0, height: 0 };\\n  if (evaluate(getConfig().flowchart.htmlLabels)) {\\n    const div = text.children[0];\\n    const dv = select(text);\\n    bbox = div.getBoundingClientRect();\\n    dv.attr('width', bbox.width);\\n    dv.attr('height', bbox.height);\\n  }\\n  log.info('Text 2', text2);\\n  const textRows = text2.slice(1, text2.length);\\n  let titleBox = text.getBBox();\\n  const descr = label\\n    .node()\\n    .appendChild(\\n      createLabel(textRows.join ? textRows.join('&lt;br/&gt;') : textRows, node.labelStyle, true, true)\\n    );\\n\\n  if (evaluate(getConfig().flowchart.htmlLabels)) {\\n    const div = descr.children[0];\\n    const dv = select(descr);\\n    bbox = div.getBoundingClientRect();\\n    dv.attr('width', bbox.width);\\n    dv.attr('height', bbox.height);\\n  }\\n  // bbox = label.getBBox();\\n  // log.info(descr);\\n  const halfPadding = node.padding / 2;\\n  select(descr).attr(\\n    'transform',\\n    'translate( ' +\\n      // (titleBox.width - bbox.width) / 2 +\\n      (bbox.width &gt; titleBox.width ? 0 : (titleBox.width - bbox.width) / 2) +\\n      ', ' +\\n      (titleBox.height + halfPadding + 5) +\\n      ')'\\n  );\\n  select(text).attr(\\n    'transform',\\n    'translate( ' +\\n      // (titleBox.width - bbox.width) / 2 +\\n      (bbox.width &lt; titleBox.width ? 0 : -(titleBox.width - bbox.width) / 2) +\\n      ', ' +\\n      0 +\\n      ')'\\n  );\\n  // Get the size of the label\\n\\n  // Bounding box for title and text\\n  bbox = label.node().getBBox();\\n\\n  // Center the label\\n  label.attr(\\n    'transform',\\n    'translate(' + -bbox.width / 2 + ', ' + (-bbox.height / 2 - halfPadding + 3) + ')'\\n  );\\n\\n  rect\\n    .attr('class', 'outer title-state')\\n    .attr('x', -bbox.width / 2 - halfPadding)\\n    .attr('y', -bbox.height / 2 - halfPadding)\\n    .attr('width', bbox.width + node.padding)\\n    .attr('height', bbox.height + node.padding);\\n\\n  innerLine\\n    .attr('class', 'divider')\\n    .attr('x1', -bbox.width / 2 - halfPadding)\\n    .attr('x2', bbox.width / 2 + halfPadding)\\n    .attr('y1', -bbox.height / 2 - halfPadding + titleBox.height + halfPadding)\\n    .attr('y2', -bbox.height / 2 - halfPadding + titleBox.height + halfPadding);\\n\\n  updateNodeBounds(node, rect);\\n\\n  node.intersect = function (point) {\\n    return intersect.rect(node, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst stadium = (parent, node) =&gt; {\\n  const { shapeSvg, bbox } = labelHelper(parent, node, undefined, true);\\n\\n  const h = bbox.height + node.padding;\\n  const w = bbox.width + h / 4 + node.padding;\\n\\n  // add the rect\\n  const rect = shapeSvg\\n    .insert('rect', ':first-child')\\n    .attr('style', node.style)\\n    .attr('rx', h / 2)\\n    .attr('ry', h / 2)\\n    .attr('x', -w / 2)\\n    .attr('y', -h / 2)\\n    .attr('width', w)\\n    .attr('height', h);\\n\\n  updateNodeBounds(node, rect);\\n\\n  node.intersect = function (point) {\\n    return intersect.rect(node, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst circle = (parent, node) =&gt; {\\n  const { shapeSvg, bbox, halfPadding } = labelHelper(parent, node, undefined, true);\\n  const circle = shapeSvg.insert('circle', ':first-child');\\n\\n  // center the circle around its coordinate\\n  circle\\n    .attr('style', node.style)\\n    .attr('rx', node.rx)\\n    .attr('ry', node.ry)\\n    .attr('r', bbox.width / 2 + halfPadding)\\n    .attr('width', bbox.width + node.padding)\\n    .attr('height', bbox.height + node.padding);\\n\\n  log.info('Circle main');\\n\\n  updateNodeBounds(node, circle);\\n\\n  node.intersect = function (point) {\\n    log.info('Circle intersect', node, bbox.width / 2 + halfPadding, point);\\n    return intersect.circle(node, bbox.width / 2 + halfPadding, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst doublecircle = (parent, node) =&gt; {\\n  const { shapeSvg, bbox, halfPadding } = labelHelper(parent, node, undefined, true);\\n  const gap = 5;\\n  const circleGroup = shapeSvg.insert('g', ':first-child');\\n  const outerCircle = circleGroup.insert('circle');\\n  const innerCircle = circleGroup.insert('circle');\\n\\n  // center the circle around its coordinate\\n  outerCircle\\n    .attr('style', node.style)\\n    .attr('rx', node.rx)\\n    .attr('ry', node.ry)\\n    .attr('r', bbox.width / 2 + halfPadding + gap)\\n    .attr('width', bbox.width + node.padding + gap * 2)\\n    .attr('height', bbox.height + node.padding + gap * 2);\\n\\n  innerCircle\\n    .attr('style', node.style)\\n    .attr('rx', node.rx)\\n    .attr('ry', node.ry)\\n    .attr('r', bbox.width / 2 + halfPadding)\\n    .attr('width', bbox.width + node.padding)\\n    .attr('height', bbox.height + node.padding);\\n\\n  log.info('DoubleCircle main');\\n\\n  updateNodeBounds(node, outerCircle);\\n\\n  node.intersect = function (point) {\\n    log.info('DoubleCircle intersect', node, bbox.width / 2 + halfPadding + gap, point);\\n    return intersect.circle(node, bbox.width / 2 + halfPadding + gap, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst subroutine = (parent, node) =&gt; {\\n  const { shapeSvg, bbox } = labelHelper(parent, node, undefined, true);\\n\\n  const w = bbox.width + node.padding;\\n  const h = bbox.height + node.padding;\\n  const points = [\\n    { x: 0, y: 0 },\\n    { x: w, y: 0 },\\n    { x: w, y: -h },\\n    { x: 0, y: -h },\\n    { x: 0, y: 0 },\\n    { x: -8, y: 0 },\\n    { x: w + 8, y: 0 },\\n    { x: w + 8, y: -h },\\n    { x: -8, y: -h },\\n    { x: -8, y: 0 },\\n  ];\\n\\n  const el = insertPolygonShape(shapeSvg, w, h, points);\\n  el.attr('style', node.style);\\n  updateNodeBounds(node, el);\\n\\n  node.intersect = function (point) {\\n    return intersect.polygon(node, points, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst start = (parent, node) =&gt; {\\n  const shapeSvg = parent\\n    .insert('g')\\n    .attr('class', 'node default')\\n    .attr('id', node.domId || node.id);\\n  const circle = shapeSvg.insert('circle', ':first-child');\\n\\n  // center the circle around its coordinate\\n  circle.attr('class', 'state-start').attr('r', 7).attr('width', 14).attr('height', 14);\\n\\n  updateNodeBounds(node, circle);\\n\\n  node.intersect = function (point) {\\n    return intersect.circle(node, 7, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst forkJoin = (parent, node, dir) =&gt; {\\n  const shapeSvg = parent\\n    .insert('g')\\n    .attr('class', 'node default')\\n    .attr('id', node.domId || node.id);\\n\\n  let width = 70;\\n  let height = 10;\\n\\n  if (dir === 'LR') {\\n    width = 10;\\n    height = 70;\\n  }\\n\\n  const shape = shapeSvg\\n    .append('rect')\\n    .attr('x', (-1 * width) / 2)\\n    .attr('y', (-1 * height) / 2)\\n    .attr('width', width)\\n    .attr('height', height)\\n    .attr('class', 'fork-join');\\n\\n  updateNodeBounds(node, shape);\\n  node.height = node.height + node.padding / 2;\\n  node.width = node.width + node.padding / 2;\\n  node.intersect = function (point) {\\n    return intersect.rect(node, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst end = (parent, node) =&gt; {\\n  const shapeSvg = parent\\n    .insert('g')\\n    .attr('class', 'node default')\\n    .attr('id', node.domId || node.id);\\n  const innerCircle = shapeSvg.insert('circle', ':first-child');\\n  const circle = shapeSvg.insert('circle', ':first-child');\\n\\n  circle.attr('class', 'state-start').attr('r', 7).attr('width', 14).attr('height', 14);\\n\\n  innerCircle.attr('class', 'state-end').attr('r', 5).attr('width', 10).attr('height', 10);\\n\\n  updateNodeBounds(node, circle);\\n\\n  node.intersect = function (point) {\\n    return intersect.circle(node, 7, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst class_box = (parent, node) =&gt; {\\n  const halfPadding = node.padding / 2;\\n  const rowPadding = 4;\\n  const lineHeight = 8;\\n\\n  let classes;\\n  if (!node.classes) {\\n    classes = 'node default';\\n  } else {\\n    classes = 'node ' + node.classes;\\n  }\\n  // Add outer g element\\n  const shapeSvg = parent\\n    .insert('g')\\n    .attr('class', classes)\\n    .attr('id', node.domId || node.id);\\n\\n  // Create the title label and insert it after the rect\\n  const rect = shapeSvg.insert('rect', ':first-child');\\n  const topLine = shapeSvg.insert('line');\\n  const bottomLine = shapeSvg.insert('line');\\n  let maxWidth = 0;\\n  let maxHeight = rowPadding;\\n\\n  const labelContainer = shapeSvg.insert('g').attr('class', 'label');\\n  let verticalPos = 0;\\n  const hasInterface = node.classData.annotations &amp;&amp; node.classData.annotations[0];\\n\\n  // 1. Create the labels\\n  const interfaceLabelText = node.classData.annotations[0]\\n    ? '\u00AB' + node.classData.annotations[0] + '\u00BB'\\n    : '';\\n  const interfaceLabel = labelContainer\\n    .node()\\n    .appendChild(createLabel(interfaceLabelText, node.labelStyle, true, true));\\n  let interfaceBBox = interfaceLabel.getBBox();\\n  if (evaluate(getConfig().flowchart.htmlLabels)) {\\n    const div = interfaceLabel.children[0];\\n    const dv = select(interfaceLabel);\\n    interfaceBBox = div.getBoundingClientRect();\\n    dv.attr('width', interfaceBBox.width);\\n    dv.attr('height', interfaceBBox.height);\\n  }\\n  if (node.classData.annotations[0]) {\\n    maxHeight += interfaceBBox.height + rowPadding;\\n    maxWidth += interfaceBBox.width;\\n  }\\n\\n  let classTitleString = node.classData.id;\\n\\n  if (node.classData.type !== undefined &amp;&amp; node.classData.type !== '') {\\n    if (getConfig().flowchart.htmlLabels) {\\n      classTitleString += '&amp;lt;' + node.classData.type + '&amp;gt;';\\n    } else {\\n      classTitleString += '&lt;' + node.classData.type + '&gt;';\\n    }\\n  }\\n  const classTitleLabel = labelContainer\\n    .node()\\n    .appendChild(createLabel(classTitleString, node.labelStyle, true, true));\\n  select(classTitleLabel).attr('class', 'classTitle');\\n  let classTitleBBox = classTitleLabel.getBBox();\\n  if (evaluate(getConfig().flowchart.htmlLabels)) {\\n    const div = classTitleLabel.children[0];\\n    const dv = select(classTitleLabel);\\n    classTitleBBox = div.getBoundingClientRect();\\n    dv.attr('width', classTitleBBox.width);\\n    dv.attr('height', classTitleBBox.height);\\n  }\\n  maxHeight += classTitleBBox.height + rowPadding;\\n  if (classTitleBBox.width &gt; maxWidth) {\\n    maxWidth = classTitleBBox.width;\\n  }\\n  const classAttributes = [];\\n  node.classData.members.forEach((str) =&gt; {\\n    const parsedInfo = parseMember(str);\\n    let parsedText = parsedInfo.displayText;\\n    if (getConfig().flowchart.htmlLabels) {\\n      parsedText = parsedText.replace(/&lt;/g, '&amp;lt;').replace(/&gt;/g, '&amp;gt;');\\n    }\\n    const lbl = labelContainer\\n      .node()\\n      .appendChild(\\n        createLabel(\\n          parsedText,\\n          parsedInfo.cssStyle ? parsedInfo.cssStyle : node.labelStyle,\\n          true,\\n          true\\n        )\\n      );\\n    let bbox = lbl.getBBox();\\n    if (evaluate(getConfig().flowchart.htmlLabels)) {\\n      const div = lbl.children[0];\\n      const dv = select(lbl);\\n      bbox = div.getBoundingClientRect();\\n      dv.attr('width', bbox.width);\\n      dv.attr('height', bbox.height);\\n    }\\n    if (bbox.width &gt; maxWidth) {\\n      maxWidth = bbox.width;\\n    }\\n    maxHeight += bbox.height + rowPadding;\\n    classAttributes.push(lbl);\\n  });\\n\\n  maxHeight += lineHeight;\\n\\n  const classMethods = [];\\n  node.classData.methods.forEach((str) =&gt; {\\n    const parsedInfo = parseMember(str);\\n    let displayText = parsedInfo.displayText;\\n    if (getConfig().flowchart.htmlLabels) {\\n      displayText = displayText.replace(/&lt;/g, '&amp;lt;').replace(/&gt;/g, '&amp;gt;');\\n    }\\n    const lbl = labelContainer\\n      .node()\\n      .appendChild(\\n        createLabel(\\n          displayText,\\n          parsedInfo.cssStyle ? parsedInfo.cssStyle : node.labelStyle,\\n          true,\\n          true\\n        )\\n      );\\n    let bbox = lbl.getBBox();\\n    if (evaluate(getConfig().flowchart.htmlLabels)) {\\n      const div = lbl.children[0];\\n      const dv = select(lbl);\\n      bbox = div.getBoundingClientRect();\\n      dv.attr('width', bbox.width);\\n      dv.attr('height', bbox.height);\\n    }\\n    if (bbox.width &gt; maxWidth) {\\n      maxWidth = bbox.width;\\n    }\\n    maxHeight += bbox.height + rowPadding;\\n\\n    classMethods.push(lbl);\\n  });\\n\\n  maxHeight += lineHeight;\\n\\n  // 2. Position the labels\\n\\n  // position the interface label\\n  if (hasInterface) {\\n    let diffX = (maxWidth - interfaceBBox.width) / 2;\\n    select(interfaceLabel).attr(\\n      'transform',\\n      'translate( ' + ((-1 * maxWidth) / 2 + diffX) + ', ' + (-1 * maxHeight) / 2 + ')'\\n    );\\n    verticalPos = interfaceBBox.height + rowPadding;\\n  }\\n  // Positin the class title label\\n  let diffX = (maxWidth - classTitleBBox.width) / 2;\\n  select(classTitleLabel).attr(\\n    'transform',\\n    'translate( ' +\\n      ((-1 * maxWidth) / 2 + diffX) +\\n      ', ' +\\n      ((-1 * maxHeight) / 2 + verticalPos) +\\n      ')'\\n  );\\n  verticalPos += classTitleBBox.height + rowPadding;\\n\\n  topLine\\n    .attr('class', 'divider')\\n    .attr('x1', -maxWidth / 2 - halfPadding)\\n    .attr('x2', maxWidth / 2 + halfPadding)\\n    .attr('y1', -maxHeight / 2 - halfPadding + lineHeight + verticalPos)\\n    .attr('y2', -maxHeight / 2 - halfPadding + lineHeight + verticalPos);\\n\\n  verticalPos += lineHeight;\\n\\n  classAttributes.forEach((lbl) =&gt; {\\n    select(lbl).attr(\\n      'transform',\\n      'translate( ' +\\n        -maxWidth / 2 +\\n        ', ' +\\n        ((-1 * maxHeight) / 2 + verticalPos + lineHeight / 2) +\\n        ')'\\n    );\\n    verticalPos += classTitleBBox.height + rowPadding;\\n  });\\n\\n  verticalPos += lineHeight;\\n  bottomLine\\n    .attr('class', 'divider')\\n    .attr('x1', -maxWidth / 2 - halfPadding)\\n    .attr('x2', maxWidth / 2 + halfPadding)\\n    .attr('y1', -maxHeight / 2 - halfPadding + lineHeight + verticalPos)\\n    .attr('y2', -maxHeight / 2 - halfPadding + lineHeight + verticalPos);\\n\\n  verticalPos += lineHeight;\\n\\n  classMethods.forEach((lbl) =&gt; {\\n    select(lbl).attr(\\n      'transform',\\n      'translate( ' + -maxWidth / 2 + ', ' + ((-1 * maxHeight) / 2 + verticalPos) + ')'\\n    );\\n    verticalPos += classTitleBBox.height + rowPadding;\\n  });\\n  //\\n  // let bbox;\\n  // if (evaluate(getConfig().flowchart.htmlLabels)) {\\n  //   const div = interfaceLabel.children[0];\\n  //   const dv = select(interfaceLabel);\\n  //   bbox = div.getBoundingClientRect();\\n  //   dv.attr('width', bbox.width);\\n  //   dv.attr('height', bbox.height);\\n  // }\\n  // bbox = labelContainer.getBBox();\\n\\n  // log.info('Text 2', text2);\\n  // const textRows = text2.slice(1, text2.length);\\n  // let titleBox = text.getBBox();\\n  // const descr = label\\n  //   .node()\\n  //   .appendChild(createLabel(textRows.join('&lt;br/&gt;'), node.labelStyle, true, true));\\n\\n  // if (evaluate(getConfig().flowchart.htmlLabels)) {\\n  //   const div = descr.children[0];\\n  //   const dv = select(descr);\\n  //   bbox = div.getBoundingClientRect();\\n  //   dv.attr('width', bbox.width);\\n  //   dv.attr('height', bbox.height);\\n  // }\\n  // // bbox = label.getBBox();\\n  // // log.info(descr);\\n  // select(descr).attr(\\n  //   'transform',\\n  //   'translate( ' +\\n  //     // (titleBox.width - bbox.width) / 2 +\\n  //     (bbox.width &gt; titleBox.width ? 0 : (titleBox.width - bbox.width) / 2) +\\n  //     ', ' +\\n  //     (titleBox.height + halfPadding + 5) +\\n  //     ')'\\n  // );\\n  // select(text).attr(\\n  //   'transform',\\n  //   'translate( ' +\\n  //     // (titleBox.width - bbox.width) / 2 +\\n  //     (bbox.width &lt; titleBox.width ? 0 : -(titleBox.width - bbox.width) / 2) +\\n  //     ', ' +\\n  //     0 +\\n  //     ')'\\n  // );\\n  // // Get the size of the label\\n\\n  // // Bounding box for title and text\\n  // bbox = label.node().getBBox();\\n\\n  // // Center the label\\n  // label.attr(\\n  //   'transform',\\n  //   'translate(' + -bbox.width / 2 + ', ' + (-bbox.height / 2 - halfPadding + 3) + ')'\\n  // );\\n\\n  rect\\n    .attr('class', 'outer title-state')\\n    .attr('x', -maxWidth / 2 - halfPadding)\\n    .attr('y', -(maxHeight / 2) - halfPadding)\\n    .attr('width', maxWidth + node.padding)\\n    .attr('height', maxHeight + node.padding);\\n\\n  // innerLine\\n  //   .attr('class', 'divider')\\n  //   .attr('x1', -bbox.width / 2 - halfPadding)\\n  //   .attr('x2', bbox.width / 2 + halfPadding)\\n  //   .attr('y1', -bbox.height / 2 - halfPadding + titleBox.height + halfPadding)\\n  //   .attr('y2', -bbox.height / 2 - halfPadding + titleBox.height + halfPadding);\\n\\n  updateNodeBounds(node, rect);\\n\\n  node.intersect = function (point) {\\n    return intersect.rect(node, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst shapes = {\\n  question,\\n  rect,\\n  rectWithTitle,\\n  choice,\\n  circle,\\n  doublecircle,\\n  stadium,\\n  hexagon,\\n  rect_left_inv_arrow,\\n  lean_right,\\n  lean_left,\\n  trapezoid,\\n  inv_trapezoid,\\n  rect_right_inv_arrow,\\n  cylinder,\\n  start,\\n  end,\\n  note,\\n  subroutine,\\n  fork: forkJoin,\\n  join: forkJoin,\\n  class_box,\\n};\\n\\nlet nodeElems = {};\\n\\nexport const insertNode = (elem, node, dir) =&gt; {\\n  let newEl;\\n  let el;\\n\\n  // Add link when appropriate\\n  if (node.link) {\\n    let target;\\n    if (getConfig().securityLevel === 'sandbox') {\\n      target = '_top';\\n    } else if (node.linkTarget) {\\n      target = node.linkTarget || '_blank';\\n    }\\n    newEl = elem.insert('svg:a').attr('xlink:href', node.link).attr('target', target);\\n    el = shapes[node.shape](newEl, node, dir);\\n  } else {\\n    el = shapes[node.shape](elem, node, dir);\\n    newEl = el;\\n  }\\n  if (node.tooltip) {\\n    el.attr('title', node.tooltip);\\n  }\\n  if (node.class) {\\n    el.attr('class', 'node default ' + node.class);\\n  }\\n\\n  nodeElems[node.id] = newEl;\\n\\n  if (node.haveCallback) {\\n    nodeElems[node.id].attr('class', nodeElems[node.id].attr('class') + ' clickable');\\n  }\\n};\\nexport const setNodeElem = (elem, node) =&gt; {\\n  nodeElems[node.id] = elem;\\n};\\nexport const clear = () =&gt; {\\n  nodeElems = {};\\n};\\n\\nexport const positionNode = (node) =&gt; {\\n  const el = nodeElems[node.id];\\n  log.trace(\\n    'Transforming node',\\n    node.diff,\\n    node,\\n    'translate(' + (node.x - node.width / 2 - 5) + ', ' + node.width / 2 + ')'\\n  );\\n  const padding = 8;\\n  const diff = node.diff || 0;\\n  if (node.clusterNode) {\\n    el.attr(\\n      'transform',\\n      'translate(' +\\n        (node.x + diff - node.width / 2) +\\n        ', ' +\\n        (node.y - node.height / 2 - padding) +\\n        ')'\\n    );\\n  } else {\\n    el.attr('transform', 'translate(' + node.x + ', ' + node.y + ')');\\n  }\\n  return diff;\\n};\\n\"</span>,<span class=\"code-string\">\"import { updateNodeBounds, labelHelper } from './util';\\nimport { log } from '../../logger'; // eslint-disable-line\\nimport intersect from '../intersect/index.js';\\n\\nconst note = (parent, node) =&gt; {\\n  const { shapeSvg, bbox, halfPadding } = labelHelper(parent, node, 'node ' + node.classes, true);\\n\\n  log.info('Classes = ', node.classes);\\n  // add the rect\\n  const rect = shapeSvg.insert('rect', ':first-child');\\n\\n  rect\\n    .attr('rx', node.rx)\\n    .attr('ry', node.ry)\\n    .attr('x', -bbox.width / 2 - halfPadding)\\n    .attr('y', -bbox.height / 2 - halfPadding)\\n    .attr('width', bbox.width + node.padding)\\n    .attr('height', bbox.height + node.padding);\\n\\n  updateNodeBounds(node, rect);\\n\\n  node.intersect = function (point) {\\n    return intersect.rect(node, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nexport default note;\\n\"</span>,<span class=\"code-string\">\"import intersectRect from './intersect/intersect-rect';\\nimport { log } from '../logger';\\nimport createLabel from './createLabel';\\nimport { select } from 'd3';\\nimport { getConfig } from '../config';\\nimport { evaluate } from '../diagrams/common/common';\\n\\nconst rect = (parent, node) =&gt; {\\n  log.trace('Creating subgraph rect for ', node.id, node);\\n\\n  // Add outer g element\\n  const shapeSvg = parent\\n    .insert('g')\\n    .attr('class', 'cluster' + (node.class ? ' ' + node.class : ''))\\n    .attr('id', node.id);\\n\\n  // add the rect\\n  const rect = shapeSvg.insert('rect', ':first-child');\\n\\n  // Create the label and insert it after the rect\\n  const label = shapeSvg.insert('g').attr('class', 'cluster-label');\\n\\n  const text = label\\n    .node()\\n    .appendChild(createLabel(node.labelText, node.labelStyle, undefined, true));\\n\\n  // Get the size of the label\\n  let bbox = text.getBBox();\\n\\n  if (evaluate(getConfig().flowchart.htmlLabels)) {\\n    const div = text.children[0];\\n    const dv = select(text);\\n    bbox = div.getBoundingClientRect();\\n    dv.attr('width', bbox.width);\\n    dv.attr('height', bbox.height);\\n  }\\n\\n  const padding = 0 * node.padding;\\n  const halfPadding = padding / 2;\\n\\n  const width = node.width &lt;= bbox.width + padding ? bbox.width + padding : node.width;\\n  if (node.width &lt;= bbox.width + padding) {\\n    node.diff = (bbox.width - node.width) / 2;\\n  } else {\\n    node.diff = -node.padding / 2;\\n  }\\n\\n  log.trace('Data ', node, JSON.stringify(node));\\n  // center the rect around its coordinate\\n  rect\\n    .attr('style', node.style)\\n    .attr('rx', node.rx)\\n    .attr('ry', node.ry)\\n    .attr('x', node.x - width / 2)\\n    .attr('y', node.y - node.height / 2 - halfPadding)\\n    .attr('width', width)\\n    .attr('height', node.height + padding);\\n\\n  // Center the label\\n  label.attr(\\n    'transform',\\n    'translate(' +\\n      (node.x - bbox.width / 2) +\\n      ', ' +\\n      (node.y - node.height / 2 + node.padding / 3) +\\n      ')'\\n  );\\n\\n  const rectBox = rect.node().getBBox();\\n  node.width = rectBox.width;\\n  node.height = rectBox.height;\\n\\n  node.intersect = function (point) {\\n    return intersectRect(node, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\n/**\\n * Non visiable cluster where the note is group with its\\n *\\n * @param {any} parent\\n * @param {any} node\\n * @returns {any} ShapeSvg\\n */\\nconst noteGroup = (parent, node) =&gt; {\\n  // Add outer g element\\n  const shapeSvg = parent.insert('g').attr('class', 'note-cluster').attr('id', node.id);\\n\\n  // add the rect\\n  const rect = shapeSvg.insert('rect', ':first-child');\\n\\n  const padding = 0 * node.padding;\\n  const halfPadding = padding / 2;\\n\\n  // center the rect around its coordinate\\n  rect\\n    .attr('rx', node.rx)\\n    .attr('ry', node.ry)\\n    .attr('x', node.x - node.width / 2 - halfPadding)\\n    .attr('y', node.y - node.height / 2 - halfPadding)\\n    .attr('width', node.width + padding)\\n    .attr('height', node.height + padding)\\n    .attr('fill', 'none');\\n\\n  const rectBox = rect.node().getBBox();\\n  node.width = rectBox.width;\\n  node.height = rectBox.height;\\n\\n  node.intersect = function (point) {\\n    return intersectRect(node, point);\\n  };\\n\\n  return shapeSvg;\\n};\\nconst roundedWithTitle = (parent, node) =&gt; {\\n  // Add outer g element\\n  const shapeSvg = parent.insert('g').attr('class', node.classes).attr('id', node.id);\\n\\n  // add the rect\\n  const rect = shapeSvg.insert('rect', ':first-child');\\n\\n  // Create the label and insert it after the rect\\n  const label = shapeSvg.insert('g').attr('class', 'cluster-label');\\n  const innerRect = shapeSvg.append('rect');\\n\\n  const text = label\\n    .node()\\n    .appendChild(createLabel(node.labelText, node.labelStyle, undefined, true));\\n\\n  // Get the size of the label\\n  let bbox = text.getBBox();\\n  if (evaluate(getConfig().flowchart.htmlLabels)) {\\n    const div = text.children[0];\\n    const dv = select(text);\\n    bbox = div.getBoundingClientRect();\\n    dv.attr('width', bbox.width);\\n    dv.attr('height', bbox.height);\\n  }\\n  bbox = text.getBBox();\\n  const padding = 0 * node.padding;\\n  const halfPadding = padding / 2;\\n\\n  const width = node.width &lt;= bbox.width + node.padding ? bbox.width + node.padding : node.width;\\n  if (node.width &lt;= bbox.width + node.padding) {\\n    node.diff = (bbox.width + node.padding * 0 - node.width) / 2;\\n  } else {\\n    node.diff = -node.padding / 2;\\n  }\\n\\n  // center the rect around its coordinate\\n  rect\\n    .attr('class', 'outer')\\n    .attr('x', node.x - width / 2 - halfPadding)\\n    .attr('y', node.y - node.height / 2 - halfPadding)\\n    .attr('width', width + padding)\\n    .attr('height', node.height + padding);\\n  innerRect\\n    .attr('class', 'inner')\\n    .attr('x', node.x - width / 2 - halfPadding)\\n    .attr('y', node.y - node.height / 2 - halfPadding + bbox.height - 1)\\n    .attr('width', width + padding)\\n    .attr('height', node.height + padding - bbox.height - 3);\\n\\n  // Center the label\\n  label.attr(\\n    'transform',\\n    'translate(' +\\n      (node.x - bbox.width / 2) +\\n      ', ' +\\n      (node.y -\\n        node.height / 2 -\\n        node.padding / 3 +\\n        (evaluate(getConfig().flowchart.htmlLabels) ? 5 : 3)) +\\n      ')'\\n  );\\n\\n  const rectBox = rect.node().getBBox();\\n  node.height = rectBox.height;\\n\\n  node.intersect = function (point) {\\n    return intersectRect(node, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst divider = (parent, node) =&gt; {\\n  // Add outer g element\\n  const shapeSvg = parent.insert('g').attr('class', node.classes).attr('id', node.id);\\n\\n  // add the rect\\n  const rect = shapeSvg.insert('rect', ':first-child');\\n\\n  const padding = 0 * node.padding;\\n  const halfPadding = padding / 2;\\n\\n  // center the rect around its coordinate\\n  rect\\n    .attr('class', 'divider')\\n    .attr('x', node.x - node.width / 2 - halfPadding)\\n    .attr('y', node.y - node.height / 2)\\n    .attr('width', node.width + padding)\\n    .attr('height', node.height + padding);\\n\\n  const rectBox = rect.node().getBBox();\\n  node.width = rectBox.width;\\n  node.height = rectBox.height;\\n  node.diff = -node.padding / 2;\\n  node.intersect = function (point) {\\n    return intersectRect(node, point);\\n  };\\n\\n  return shapeSvg;\\n};\\n\\nconst shapes = { rect, roundedWithTitle, noteGroup, divider };\\n\\nlet clusterElems = {};\\n\\nexport const insertCluster = (elem, node) =&gt; {\\n  log.trace('Inserting cluster');\\n  const shape = node.shape || 'rect';\\n  clusterElems[node.id] = shapes[shape](elem, node);\\n};\\nexport const getClusterTitleWidth = (elem, node) =&gt; {\\n  const label = createLabel(node.labelText, node.labelStyle, undefined, true);\\n  elem.node().appendChild(label);\\n  const width = label.getBBox().width;\\n  elem.node().removeChild(label);\\n  return width;\\n};\\n\\nexport const clear = () =&gt; {\\n  clusterElems = {};\\n};\\n\\nexport const positionCluster = (node) =&gt; {\\n  log.info('Position cluster (' + node.id + ', ' + node.x + ', ' + node.y + ')');\\n  const el = clusterElems[node.id];\\n\\n  el.attr('transform', 'translate(' + node.x + ', ' + node.y + ')');\\n};\\n\"</span>,<span class=\"code-string\">\"import { log } from '../logger'; // eslint-disable-line\\nimport createLabel from './createLabel';\\nimport { line, curveBasis, select } from 'd3';\\nimport { getConfig } from '../config';\\nimport utils from '../utils';\\nimport { evaluate } from '../diagrams/common/common';\\n\\nlet edgeLabels = {};\\nlet terminalLabels = {};\\n\\nexport const clear = () =&gt; {\\n  edgeLabels = {};\\n  terminalLabels = {};\\n};\\n\\nexport const insertEdgeLabel = (elem, edge) =&gt; {\\n  // Create the actual text element\\n  const labelElement = createLabel(edge.label, edge.labelStyle);\\n\\n  // Create outer g, edgeLabel, this will be positioned after graph layout\\n  const edgeLabel = elem.insert('g').attr('class', 'edgeLabel');\\n\\n  // Create inner g, label, this will be positioned now for centering the text\\n  const label = edgeLabel.insert('g').attr('class', 'label');\\n  label.node().appendChild(labelElement);\\n\\n  // Center the label\\n  let bbox = labelElement.getBBox();\\n  if (evaluate(getConfig().flowchart.htmlLabels)) {\\n    const div = labelElement.children[0];\\n    const dv = select(labelElement);\\n    bbox = div.getBoundingClientRect();\\n    dv.attr('width', bbox.width);\\n    dv.attr('height', bbox.height);\\n  }\\n  label.attr('transform', 'translate(' + -bbox.width / 2 + ', ' + -bbox.height / 2 + ')');\\n\\n  // Make element accessible by id for positioning\\n  edgeLabels[edge.id] = edgeLabel;\\n\\n  // Update the abstract data of the edge with the new information about its width and height\\n  edge.width = bbox.width;\\n  edge.height = bbox.height;\\n\\n  let fo;\\n  if (edge.startLabelLeft) {\\n    // Create the actual text element\\n    const startLabelElement = createLabel(edge.startLabelLeft, edge.labelStyle);\\n    const startEdgeLabelLeft = elem.insert('g').attr('class', 'edgeTerminals');\\n    const inner = startEdgeLabelLeft.insert('g').attr('class', 'inner');\\n    fo = inner.node().appendChild(startLabelElement);\\n    const slBox = startLabelElement.getBBox();\\n    inner.attr('transform', 'translate(' + -slBox.width / 2 + ', ' + -slBox.height / 2 + ')');\\n    if (!terminalLabels[edge.id]) {\\n      terminalLabels[edge.id] = {};\\n    }\\n    terminalLabels[edge.id].startLeft = startEdgeLabelLeft;\\n    setTerminalWidth(fo, edge.startLabelLeft);\\n  }\\n  if (edge.startLabelRight) {\\n    // Create the actual text element\\n    const startLabelElement = createLabel(edge.startLabelRight, edge.labelStyle);\\n    const startEdgeLabelRight = elem.insert('g').attr('class', 'edgeTerminals');\\n    const inner = startEdgeLabelRight.insert('g').attr('class', 'inner');\\n    fo = startEdgeLabelRight.node().appendChild(startLabelElement);\\n    inner.node().appendChild(startLabelElement);\\n    const slBox = startLabelElement.getBBox();\\n    inner.attr('transform', 'translate(' + -slBox.width / 2 + ', ' + -slBox.height / 2 + ')');\\n\\n    if (!terminalLabels[edge.id]) {\\n      terminalLabels[edge.id] = {};\\n    }\\n    terminalLabels[edge.id].startRight = startEdgeLabelRight;\\n    setTerminalWidth(fo, edge.startLabelRight);\\n  }\\n  if (edge.endLabelLeft) {\\n    // Create the actual text element\\n    const endLabelElement = createLabel(edge.endLabelLeft, edge.labelStyle);\\n    const endEdgeLabelLeft = elem.insert('g').attr('class', 'edgeTerminals');\\n    const inner = endEdgeLabelLeft.insert('g').attr('class', 'inner');\\n    fo = inner.node().appendChild(endLabelElement);\\n    const slBox = endLabelElement.getBBox();\\n    inner.attr('transform', 'translate(' + -slBox.width / 2 + ', ' + -slBox.height / 2 + ')');\\n\\n    endEdgeLabelLeft.node().appendChild(endLabelElement);\\n\\n    if (!terminalLabels[edge.id]) {\\n      terminalLabels[edge.id] = {};\\n    }\\n    terminalLabels[edge.id].endLeft = endEdgeLabelLeft;\\n    setTerminalWidth(fo, edge.endLabelLeft);\\n  }\\n  if (edge.endLabelRight) {\\n    // Create the actual text element\\n    const endLabelElement = createLabel(edge.endLabelRight, edge.labelStyle);\\n    const endEdgeLabelRight = elem.insert('g').attr('class', 'edgeTerminals');\\n    const inner = endEdgeLabelRight.insert('g').attr('class', 'inner');\\n\\n    fo = inner.node().appendChild(endLabelElement);\\n    const slBox = endLabelElement.getBBox();\\n    inner.attr('transform', 'translate(' + -slBox.width / 2 + ', ' + -slBox.height / 2 + ')');\\n\\n    endEdgeLabelRight.node().appendChild(endLabelElement);\\n    if (!terminalLabels[edge.id]) {\\n      terminalLabels[edge.id] = {};\\n    }\\n    terminalLabels[edge.id].endRight = endEdgeLabelRight;\\n    setTerminalWidth(fo, edge.endLabelRight);\\n  }\\n};\\n\\n/**\\n * @param {any} fo\\n * @param {any} value\\n */\\nfunction setTerminalWidth(fo, value) {\\n  if (getConfig().flowchart.htmlLabels &amp;&amp; fo) {\\n    fo.style.width = value.length * 9 + 'px';\\n    fo.style.height = '12px';\\n  }\\n}\\n\\nexport const positionEdgeLabel = (edge, paths) =&gt; {\\n  log.info('Moving label abc78 ', edge.id, edge.label, edgeLabels[edge.id]);\\n  let path = paths.updatedPath ? paths.updatedPath : paths.originalPath;\\n  if (edge.label) {\\n    const el = edgeLabels[edge.id];\\n    let x = edge.x;\\n    let y = edge.y;\\n    if (path) {\\n      //   // debugger;\\n      const pos = utils.calcLabelPosition(path);\\n      log.info('Moving label from (', x, ',', y, ') to (', pos.x, ',', pos.y, ') abc78');\\n      // x = pos.x;\\n      // y = pos.y;\\n    }\\n    el.attr('transform', 'translate(' + x + ', ' + y + ')');\\n  }\\n\\n  //let path = paths.updatedPath ? paths.updatedPath : paths.originalPath;\\n  if (edge.startLabelLeft) {\\n    const el = terminalLabels[edge.id].startLeft;\\n    let x = edge.x;\\n    let y = edge.y;\\n    if (path) {\\n      // debugger;\\n      const pos = utils.calcTerminalLabelPosition(edge.arrowTypeStart ? 10 : 0, 'start_left', path);\\n      x = pos.x;\\n      y = pos.y;\\n    }\\n    el.attr('transform', 'translate(' + x + ', ' + y + ')');\\n  }\\n  if (edge.startLabelRight) {\\n    const el = terminalLabels[edge.id].startRight;\\n    let x = edge.x;\\n    let y = edge.y;\\n    if (path) {\\n      // debugger;\\n      const pos = utils.calcTerminalLabelPosition(\\n        edge.arrowTypeStart ? 10 : 0,\\n        'start_right',\\n        path\\n      );\\n      x = pos.x;\\n      y = pos.y;\\n    }\\n    el.attr('transform', 'translate(' + x + ', ' + y + ')');\\n  }\\n  if (edge.endLabelLeft) {\\n    const el = terminalLabels[edge.id].endLeft;\\n    let x = edge.x;\\n    let y = edge.y;\\n    if (path) {\\n      // debugger;\\n      const pos = utils.calcTerminalLabelPosition(edge.arrowTypeEnd ? 10 : 0, 'end_left', path);\\n      x = pos.x;\\n      y = pos.y;\\n    }\\n    el.attr('transform', 'translate(' + x + ', ' + y + ')');\\n  }\\n  if (edge.endLabelRight) {\\n    const el = terminalLabels[edge.id].endRight;\\n    let x = edge.x;\\n    let y = edge.y;\\n    if (path) {\\n      // debugger;\\n      const pos = utils.calcTerminalLabelPosition(edge.arrowTypeEnd ? 10 : 0, 'end_right', path);\\n      x = pos.x;\\n      y = pos.y;\\n    }\\n    el.attr('transform', 'translate(' + x + ', ' + y + ')');\\n  }\\n};\\n\\n// const getRelationType = function(type) {\\n//   switch (type) {\\n//     case stateDb.relationType.AGGREGATION:\\n//       return 'aggregation';\\n//     case stateDb.relationType.EXTENSION:\\n//       return 'extension';\\n//     case stateDb.relationType.COMPOSITION:\\n//       return 'composition';\\n//     case stateDb.relationType.DEPENDENCY:\\n//       return 'dependency';\\n//   }\\n// };\\n\\nconst outsideNode = (node, point) =&gt; {\\n  // log.warn('Checking bounds ', node, point);\\n  const x = node.x;\\n  const y = node.y;\\n  const dx = Math.abs(point.x - x);\\n  const dy = Math.abs(point.y - y);\\n  const w = node.width / 2;\\n  const h = node.height / 2;\\n  if (dx &gt;= w || dy &gt;= h) {\\n    return true;\\n  }\\n  return false;\\n};\\n\\nexport const intersection = (node, outsidePoint, insidePoint) =&gt; {\\n  log.warn(`intersection calc abc89:\\n  outsidePoint: ${JSON.stringify(outsidePoint)}\\n  insidePoint : ${JSON.stringify(insidePoint)}\\n  node        : x:${node.x} y:${node.y} w:${node.width} h:${node.height}`);\\n  const x = node.x;\\n  const y = node.y;\\n\\n  const dx = Math.abs(x - insidePoint.x);\\n  // const dy = Math.abs(y - insidePoint.y);\\n  const w = node.width / 2;\\n  let r = insidePoint.x &lt; outsidePoint.x ? w - dx : w + dx;\\n  const h = node.height / 2;\\n\\n  // const edges = {\\n  //   x1: x - w,\\n  //   x2: x + w,\\n  //   y1: y - h,\\n  //   y2: y + h\\n  // };\\n\\n  // if (\\n  //   outsidePoint.x === edges.x1 ||\\n  //   outsidePoint.x === edges.x2 ||\\n  //   outsidePoint.y === edges.y1 ||\\n  //   outsidePoint.y === edges.y2\\n  // ) {\\n  //   log.warn('abc89 calc equals on edge', outsidePoint, edges);\\n  //   return outsidePoint;\\n  // }\\n\\n  const Q = Math.abs(outsidePoint.y - insidePoint.y);\\n  const R = Math.abs(outsidePoint.x - insidePoint.x);\\n  // log.warn();\\n  if (Math.abs(y - outsidePoint.y) * w &gt; Math.abs(x - outsidePoint.x) * h) { // eslint-disable-line\\n    // Intersection is top or bottom of rect.\\n    // let q = insidePoint.y &lt; outsidePoint.y ? outsidePoint.y - h - y : y - h - outsidePoint.y;\\n    let q = insidePoint.y &lt; outsidePoint.y ? outsidePoint.y - h - y : y - h - outsidePoint.y;\\n    r = (R * q) / Q;\\n    const res = {\\n      x: insidePoint.x &lt; outsidePoint.x ? insidePoint.x + r : insidePoint.x - R + r,\\n      y: insidePoint.y &lt; outsidePoint.y ? insidePoint.y + Q - q : insidePoint.y - Q + q,\\n    };\\n\\n    if (r === 0) {\\n      res.x = outsidePoint.x;\\n      res.y = outsidePoint.y;\\n    }\\n    if (R === 0) {\\n      res.x = outsidePoint.x;\\n    }\\n    if (Q === 0) {\\n      res.y = outsidePoint.y;\\n    }\\n\\n    log.warn(`abc89 topp/bott calc, Q ${Q}, q ${q}, R ${R}, r ${r}`, res);\\n\\n    return res;\\n  } else {\\n    // Intersection onn sides of rect\\n    if (insidePoint.x &lt; outsidePoint.x) {\\n      r = outsidePoint.x - w - x;\\n    } else {\\n      // r = outsidePoint.x - w - x;\\n      r = x - w - outsidePoint.x;\\n    }\\n    let q = (Q * r) / R;\\n    //  OK let _x = insidePoint.x &lt; outsidePoint.x ? insidePoint.x + R - r : insidePoint.x + dx - w;\\n    // OK let _x = insidePoint.x &lt; outsidePoint.x ? insidePoint.x + R - r : outsidePoint.x + r;\\n    let _x = insidePoint.x &lt; outsidePoint.x ? insidePoint.x + R - r : insidePoint.x - R + r;\\n    // let _x = insidePoint.x &lt; outsidePoint.x ? insidePoint.x + R - r : outsidePoint.x + r;\\n    let _y = insidePoint.y &lt; outsidePoint.y ? insidePoint.y + q : insidePoint.y - q;\\n    log.warn(`sides calc abc89, Q ${Q}, q ${q}, R ${R}, r ${r}`, { _x, _y });\\n    if (r === 0) {\\n      _x = outsidePoint.x;\\n      _y = outsidePoint.y;\\n    }\\n    if (R === 0) {\\n      _x = outsidePoint.x;\\n    }\\n    if (Q === 0) {\\n      _y = outsidePoint.y;\\n    }\\n\\n    return { x: _x, y: _y };\\n  }\\n};\\n/**\\n * This function will page a path and node where the last point(s) in the path is inside the node\\n * and return an update path ending by the border of the node.\\n *\\n * @param {Array} _points\\n * @param {any} boundryNode\\n * @returns {Array} Points\\n */\\nconst cutPathAtIntersect = (_points, boundryNode) =&gt; {\\n  log.warn('abc88 cutPathAtIntersect', _points, boundryNode);\\n  let points = [];\\n  let lastPointOutside = _points[0];\\n  let isInside = false;\\n  _points.forEach((point) =&gt; {\\n    // const node = clusterDb[edge.toCluster].node;\\n    log.info('abc88 checking point', point, boundryNode);\\n\\n    // check if point is inside the boundry rect\\n    if (!outsideNode(boundryNode, point) &amp;&amp; !isInside) {\\n      // First point inside the rect found\\n      // Calc the intersection coord between the point anf the last opint ouside the rect\\n      const inter = intersection(boundryNode, lastPointOutside, point);\\n      log.warn('abc88 inside', point, lastPointOutside, inter);\\n      log.warn('abc88 intersection', inter);\\n\\n      // // Check case where the intersection is the same as the last point\\n      let pointPresent = false;\\n      points.forEach((p) =&gt; {\\n        pointPresent = pointPresent || (p.x === inter.x &amp;&amp; p.y === inter.y);\\n      });\\n      // // if (!pointPresent) {\\n      if (!points.find((e) =&gt; e.x === inter.x &amp;&amp; e.y === inter.y)) {\\n        points.push(inter);\\n      } else {\\n        log.warn('abc88 no intersect', inter, points);\\n      }\\n      // points.push(inter);\\n      isInside = true;\\n    } else {\\n      // Outside\\n      log.warn('abc88 outside', point, lastPointOutside);\\n      lastPointOutside = point;\\n      // points.push(point);\\n      if (!isInside) points.push(point);\\n    }\\n  });\\n  log.warn('abc88 returning points', points);\\n  return points;\\n};\\n\\n//(edgePaths, e, edge, clusterDb, diagramtype, graph)\\nexport const insertEdge = function (elem, e, edge, clusterDb, diagramType, graph) {\\n  let points = edge.points;\\n  let pointsHasChanged = false;\\n  const tail = graph.node(e.v);\\n  var head = graph.node(e.w);\\n\\n  log.info('abc88 InsertEdge: ', edge);\\n  if (head.intersect &amp;&amp; tail.intersect) {\\n    points = points.slice(1, edge.points.length - 1);\\n    points.unshift(tail.intersect(points[0]));\\n    log.info(\\n      'Last point',\\n      points[points.length - 1],\\n      head,\\n      head.intersect(points[points.length - 1])\\n    );\\n    points.push(head.intersect(points[points.length - 1]));\\n  }\\n  if (edge.toCluster) {\\n    log.info('to cluster abc88', clusterDb[edge.toCluster]);\\n    points = cutPathAtIntersect(edge.points, clusterDb[edge.toCluster].node);\\n    // log.trace('edge', edge);\\n    // points = [];\\n    // let lastPointOutside; // = edge.points[0];\\n    // let isInside = false;\\n    // edge.points.forEach(point =&gt; {\\n    //   const node = clusterDb[edge.toCluster].node;\\n    //   log.warn('checking from', edge.fromCluster, point, node);\\n\\n    //   if (!outsideNode(node, point) &amp;&amp; !isInside) {\\n    //     log.trace('inside', edge.toCluster, point, lastPointOutside);\\n\\n    //     // First point inside the rect\\n    //     const inter = intersection(node, lastPointOutside, point);\\n\\n    //     let pointPresent = false;\\n    //     points.forEach(p =&gt; {\\n    //       pointPresent = pointPresent || (p.x === inter.x &amp;&amp; p.y === inter.y);\\n    //     });\\n    //     // if (!pointPresent) {\\n    //     if (!points.find(e =&gt; e.x === inter.x &amp;&amp; e.y === inter.y)) {\\n    //       points.push(inter);\\n    //     } else {\\n    //       log.warn('no intersect', inter, points);\\n    //     }\\n    //     isInside = true;\\n    // } else {\\n    //   // outtside\\n    //   lastPointOutside = point;\\n    //   if (!isInside) points.push(point);\\n    // }\\n    // });\\n    pointsHasChanged = true;\\n  }\\n\\n  if (edge.fromCluster) {\\n    log.info('from cluster abc88', clusterDb[edge.fromCluster]);\\n    points = cutPathAtIntersect(points.reverse(), clusterDb[edge.fromCluster].node).reverse();\\n    // log.warn('edge', edge);\\n    // log.warn('from cluster', clusterDb[edge.fromCluster], points);\\n    // const updatedPoints = [];\\n    // let lastPointOutside = edge.points[edge.points.length - 1];\\n    // let isInside = false;\\n    // for (let i = points.length - 1; i &gt;= 0; i--) {\\n    //   const point = points[i];\\n    //   const node = clusterDb[edge.fromCluster].node;\\n    //   log.warn('checking to', edge.fromCluster, point, node);\\n\\n    //   if (!outsideNode(node, point) &amp;&amp; !isInside) {\\n    //     log.warn('inside', edge.fromCluster, point, node);\\n\\n    //     // First point inside the rect\\n    //     const inter = intersection(node, lastPointOutside, point);\\n    //     log.warn('intersect', intersection(node, lastPointOutside, point));\\n    //     let pointPresent = false;\\n    //     points.forEach(p =&gt; {\\n    //       pointPresent = pointPresent || (p.x === inter.x &amp;&amp; p.y === inter.y);\\n    //     });\\n    //     // if (!pointPresent) {\\n    //     if (!points.find(e =&gt; e.x === inter.x &amp;&amp; e.y === inter.y)) {\\n    //       updatedPoints.unshift(inter);\\n    //       log.warn('Adding point -updated = ', updatedPoints);\\n    //     } else {\\n    //       log.warn('no intersect', inter, points);\\n    //     }\\n    //     // points.push(insterection);\\n    //     isInside = true;\\n    //   } else {\\n    //     // at the outside\\n    //     // if (!isInside) updatedPoints.unshift(point);\\n    //     updatedPoints.unshift(point);\\n    //     log.warn('Outside point', point, updatedPoints);\\n    //   }\\n    //   lastPointOutside = point;\\n    // }\\n    // points = updatedPoints;\\n    // points = edge.points;\\n    pointsHasChanged = true;\\n  }\\n\\n  // The data for our line\\n  const lineData = points.filter((p) =&gt; !Number.isNaN(p.y));\\n\\n  // This is the accessor function we talked about above\\n  let curve;\\n  // Currently only flowcharts get the curve from the settings, perhaps this should\\n  // be expanded to a common setting? Restricting it for now in order not to cause side-effects that\\n  // have not been thought through\\n  if (diagramType === 'graph' || diagramType === 'flowchart') {\\n    curve = edge.curve || curveBasis;\\n  } else {\\n    curve = curveBasis;\\n  }\\n  // curve = curveLinear;\\n  const lineFunction = line()\\n    .x(function (d) {\\n      return d.x;\\n    })\\n    .y(function (d) {\\n      return d.y;\\n    })\\n    .curve(curve);\\n\\n  // Contruct stroke classes based on properties\\n  let strokeClasses;\\n  switch (edge.thickness) {\\n    case 'normal':\\n      strokeClasses = 'edge-thickness-normal';\\n      break;\\n    case 'thick':\\n      strokeClasses = 'edge-thickness-thick';\\n      break;\\n    default:\\n      strokeClasses = '';\\n  }\\n  switch (edge.pattern) {\\n    case 'solid':\\n      strokeClasses += ' edge-pattern-solid';\\n      break;\\n    case 'dotted':\\n      strokeClasses += ' edge-pattern-dotted';\\n      break;\\n    case 'dashed':\\n      strokeClasses += ' edge-pattern-dashed';\\n      break;\\n  }\\n\\n  const svgPath = elem\\n    .append('path')\\n    .attr('d', lineFunction(lineData))\\n    .attr('id', edge.id)\\n    .attr('class', ' ' + strokeClasses + (edge.classes ? ' ' + edge.classes : ''))\\n    .attr('style', edge.style);\\n\\n  // DEBUG code, adds a red circle at each edge coordinate\\n  // edge.points.forEach(point =&gt; {\\n  //   elem\\n  //     .append('circle')\\n  //     .style('stroke', 'red')\\n  //     .style('fill', 'red')\\n  //     .attr('r', 1)\\n  //     .attr('cx', point.x)\\n  //     .attr('cy', point.y);\\n  // });\\n\\n  let url = '';\\n  if (getConfig().state.arrowMarkerAbsolute) {\\n    url =\\n      window.location.protocol +\\n      '//' +\\n      window.location.host +\\n      window.location.pathname +\\n      window.location.search;\\n    url = url.replace(/\\\\(/g, '\\\\\\\\(');\\n    url = url.replace(/\\\\)/g, '\\\\\\\\)');\\n  }\\n  log.info('arrowTypeStart', edge.arrowTypeStart);\\n  log.info('arrowTypeEnd', edge.arrowTypeEnd);\\n\\n  switch (edge.arrowTypeStart) {\\n    case 'arrow_cross':\\n      svgPath.attr('marker-start', 'url(' + url + '#' + diagramType + '-crossStart' + ')');\\n      break;\\n    case 'arrow_point':\\n      svgPath.attr('marker-start', 'url(' + url + '#' + diagramType + '-pointStart' + ')');\\n      break;\\n    case 'arrow_barb':\\n      svgPath.attr('marker-start', 'url(' + url + '#' + diagramType + '-barbStart' + ')');\\n      break;\\n    case 'arrow_circle':\\n      svgPath.attr('marker-start', 'url(' + url + '#' + diagramType + '-circleStart' + ')');\\n      break;\\n    case 'aggregation':\\n      svgPath.attr('marker-start', 'url(' + url + '#' + diagramType + '-aggregationStart' + ')');\\n      break;\\n    case 'extension':\\n      svgPath.attr('marker-start', 'url(' + url + '#' + diagramType + '-extensionStart' + ')');\\n      break;\\n    case 'composition':\\n      svgPath.attr('marker-start', 'url(' + url + '#' + diagramType + '-compositionStart' + ')');\\n      break;\\n    case 'dependency':\\n      svgPath.attr('marker-start', 'url(' + url + '#' + diagramType + '-dependencyStart' + ')');\\n      break;\\n    default:\\n  }\\n  switch (edge.arrowTypeEnd) {\\n    case 'arrow_cross':\\n      svgPath.attr('marker-end', 'url(' + url + '#' + diagramType + '-crossEnd' + ')');\\n      break;\\n    case 'arrow_point':\\n      svgPath.attr('marker-end', 'url(' + url + '#' + diagramType + '-pointEnd' + ')');\\n      break;\\n    case 'arrow_barb':\\n      svgPath.attr('marker-end', 'url(' + url + '#' + diagramType + '-barbEnd' + ')');\\n      break;\\n    case 'arrow_circle':\\n      svgPath.attr('marker-end', 'url(' + url + '#' + diagramType + '-circleEnd' + ')');\\n      break;\\n    case 'aggregation':\\n      svgPath.attr('marker-end', 'url(' + url + '#' + diagramType + '-aggregationEnd' + ')');\\n      break;\\n    case 'extension':\\n      svgPath.attr('marker-end', 'url(' + url + '#' + diagramType + '-extensionEnd' + ')');\\n      break;\\n    case 'composition':\\n      svgPath.attr('marker-end', 'url(' + url + '#' + diagramType + '-compositionEnd' + ')');\\n      break;\\n    case 'dependency':\\n      svgPath.attr('marker-end', 'url(' + url + '#' + diagramType + '-dependencyEnd' + ')');\\n      break;\\n    default:\\n  }\\n  let paths = {};\\n  if (pointsHasChanged) {\\n    paths.updatedPath = points;\\n  }\\n  paths.originalPath = edge.points;\\n  return paths;\\n};\\n\"</span>,<span class=\"code-string\">\"import dagre from 'dagre';\\nimport graphlib from 'graphlib';\\nimport insertMarkers from './markers';\\nimport { updateNodeBounds } from './shapes/util';\\nimport {\\n  clear as clearGraphlib,\\n  clusterDb,\\n  adjustClustersAndEdges,\\n  findNonClusterChild,\\n  sortNodesByHierarchy,\\n} from './mermaid-graphlib';\\nimport { insertNode, positionNode, clear as clearNodes, setNodeElem } from './nodes';\\nimport { insertCluster, clear as clearClusters } from './clusters';\\nimport { insertEdgeLabel, positionEdgeLabel, insertEdge, clear as clearEdges } from './edges';\\nimport { log } from '../logger';\\n\\nconst recursiveRender = (_elem, graph, diagramtype, parentCluster) =&gt; {\\n  log.info('Graph in recursive render: XXX', graphlib.json.write(graph), parentCluster);\\n  const dir = graph.graph().rankdir;\\n  log.trace('Dir in recursive render - dir:', dir);\\n\\n  const elem = _elem.insert('g').attr('class', 'root'); // eslint-disable-line\\n  if (!graph.nodes()) {\\n    log.info('No nodes found for', graph);\\n  } else {\\n    log.info('Recursive render XXX', graph.nodes());\\n  }\\n  if (graph.edges().length &gt; 0) {\\n    log.trace('Recursive edges', graph.edge(graph.edges()[0]));\\n  }\\n  const clusters = elem.insert('g').attr('class', 'clusters'); // eslint-disable-line\\n  const edgePaths = elem.insert('g').attr('class', 'edgePaths');\\n  const edgeLabels = elem.insert('g').attr('class', 'edgeLabels');\\n  const nodes = elem.insert('g').attr('class', 'nodes');\\n\\n  // Insert nodes, this will insert them into the dom and each node will get a size. The size is updated\\n  // to the abstract node and is later used by dagre for the layout\\n  graph.nodes().forEach(function (v) {\\n    const node = graph.node(v);\\n    if (typeof parentCluster !== 'undefined') {\\n      const data = JSON.parse(JSON.stringify(parentCluster.clusterData));\\n      // data.clusterPositioning = true;\\n      log.info('Setting data for cluster XXX (', v, ') ', data, parentCluster);\\n      graph.setNode(parentCluster.id, data);\\n      if (!graph.parent(v)) {\\n        log.trace('Setting parent', v, parentCluster.id);\\n        graph.setParent(v, parentCluster.id, data);\\n      }\\n    }\\n    log.info('(Insert) Node XXX' + v + ': ' + JSON.stringify(graph.node(v)));\\n    if (node &amp;&amp; node.clusterNode) {\\n      // const children = graph.children(v);\\n      log.info('Cluster identified', v, node.width, graph.node(v));\\n      const o = recursiveRender(nodes, node.graph, diagramtype, graph.node(v));\\n      const newEl = o.elem;\\n      updateNodeBounds(node, newEl);\\n      node.diff = o.diff || 0;\\n      log.info('Node bounds (abc123)', v, node, node.width, node.x, node.y);\\n      setNodeElem(newEl, node);\\n\\n      log.warn('Recursive render complete ', newEl, node);\\n    } else {\\n      if (graph.children(v).length &gt; 0) {\\n        // This is a cluster but not to be rendered recusively\\n        // Render as before\\n        log.info('Cluster - the non recursive path XXX', v, node.id, node, graph);\\n        log.info(findNonClusterChild(node.id, graph));\\n        clusterDb[node.id] = { id: findNonClusterChild(node.id, graph), node };\\n        // insertCluster(clusters, graph.node(v));\\n      } else {\\n        log.info('Node - the non recursive path', v, node.id, node);\\n        insertNode(nodes, graph.node(v), dir);\\n      }\\n    }\\n  });\\n\\n  // Insert labels, this will insert them into the dom so that the width can be calculated\\n  // Also figure out which edges point to/from clusters and adjust them accordingly\\n  // Edges from/to clusters really points to the first child in the cluster.\\n  // TODO: pick optimal child in the cluster to us as link anchor\\n  graph.edges().forEach(function (e) {\\n    const edge = graph.edge(e.v, e.w, e.name);\\n    log.info('Edge ' + e.v + ' -&gt; ' + e.w + ': ' + JSON.stringify(e));\\n    log.info('Edge ' + e.v + ' -&gt; ' + e.w + ': ', e, ' ', JSON.stringify(graph.edge(e)));\\n\\n    // Check if link is either from or to a cluster\\n    log.info('Fix', clusterDb, 'ids:', e.v, e.w, 'Translateing: ', clusterDb[e.v], clusterDb[e.w]);\\n    insertEdgeLabel(edgeLabels, edge);\\n  });\\n\\n  graph.edges().forEach(function (e) {\\n    log.info('Edge ' + e.v + ' -&gt; ' + e.w + ': ' + JSON.stringify(e));\\n  });\\n  log.info('#############################################');\\n  log.info('###                Layout                 ###');\\n  log.info('#############################################');\\n  log.info(graph);\\n  dagre.layout(graph);\\n  log.info('Graph after layout:', graphlib.json.write(graph));\\n  // Move the nodes to the correct place\\n  let diff = 0;\\n  sortNodesByHierarchy(graph).forEach(function (v) {\\n    const node = graph.node(v);\\n    log.info('Position ' + v + ': ' + JSON.stringify(graph.node(v)));\\n    log.info(\\n      'Position ' + v + ': (' + node.x,\\n      ',' + node.y,\\n      ') width: ',\\n      node.width,\\n      ' height: ',\\n      node.height\\n    );\\n    if (node &amp;&amp; node.clusterNode) {\\n      // clusterDb[node.id].node = node;\\n\\n      positionNode(node);\\n    } else {\\n      // Non cluster node\\n      if (graph.children(v).length &gt; 0) {\\n        // A cluster in the non-recurive way\\n        // positionCluster(node);\\n        insertCluster(clusters, node);\\n        clusterDb[node.id].node = node;\\n      } else {\\n        positionNode(node);\\n      }\\n    }\\n  });\\n\\n  // Move the edge labels to the correct place after layout\\n  graph.edges().forEach(function (e) {\\n    const edge = graph.edge(e);\\n    log.info('Edge ' + e.v + ' -&gt; ' + e.w + ': ' + JSON.stringify(edge), edge);\\n\\n    const paths = insertEdge(edgePaths, e, edge, clusterDb, diagramtype, graph);\\n    positionEdgeLabel(edge, paths);\\n  });\\n\\n  graph.nodes().forEach(function (v) {\\n    const n = graph.node(v);\\n    log.info(v, n.type, n.diff);\\n    if (n.type === 'group') {\\n      diff = n.diff;\\n    }\\n  });\\n  return { elem, diff };\\n};\\n\\nexport const render = (elem, graph, markers, diagramtype, id) =&gt; {\\n  insertMarkers(elem, markers, diagramtype, id);\\n  clearNodes();\\n  clearEdges();\\n  clearClusters();\\n  clearGraphlib();\\n\\n  log.warn('Graph at first:', graphlib.json.write(graph));\\n  adjustClustersAndEdges(graph);\\n  log.warn('Graph after:', graphlib.json.write(graph));\\n  // log.warn('Graph ever  after:', graphlib.json.write(graph.node('A').graph));\\n  recursiveRender(elem, graph, diagramtype);\\n};\\n\\n// const shapeDefinitions = {};\\n// export const addShape = ({ shapeType: fun }) =&gt; {\\n//   shapeDefinitions[shapeType] = fun;\\n// };\\n\\n// const arrowDefinitions = {};\\n// export const addArrow = ({ arrowType: fun }) =&gt; {\\n//   arrowDefinitions[arrowType] = fun;\\n// };\\n\"</span>,<span class=\"code-string\">\"import { select } from 'd3';\\nimport dagre from 'dagre';\\nimport graphlib from 'graphlib';\\nimport { log } from '../../logger';\\nimport classDb, { lookUpDomId } from './classDb';\\nimport { parser } from './parser/classDiagram';\\nimport svgDraw from './svgDraw';\\nimport { getConfig } from '../../config';\\nimport { render } from '../../dagre-wrapper/index.js';\\n// import addHtmlLabel from 'dagre-d3/lib/label/add-html-label.js';\\nimport { curveLinear } from 'd3';\\nimport { interpolateToCurve, getStylesFromArray, configureSvgSize } from '../../utils';\\nimport common from '../common/common';\\n\\nparser.yy = classDb;\\n\\nlet idCache = {};\\nconst padding = 20;\\n\\nconst sanitizeText = (txt) =&gt; common.sanitizeText(txt, getConfig());\\n\\nconst conf = {\\n  dividerMargin: 10,\\n  padding: 5,\\n  textHeight: 10,\\n};\\n\\n/**\\n * Function that adds the vertices found during parsing to the graph to be rendered.\\n *\\n * @param {Object&lt;\\n *   string,\\n *   { cssClasses: string[]; text: string; id: string; type: string; domId: string }\\n * &gt;} classes\\n *   Object containing the vertices.\\n * @param {SVGGElement} g The graph that is to be drawn.\\n */\\nexport const addClasses = function (classes, g) {\\n  // const svg = select(`[id=\\\"${svgId}\\\"]`);\\n  const keys = Object.keys(classes);\\n  log.info('keys:', keys);\\n  log.info(classes);\\n\\n  // Iterate through each item in the vertex object (containing all the vertices found) in the graph definition\\n  keys.forEach(function (id) {\\n    const vertex = classes[id];\\n\\n    /**\\n     * Variable for storing the classes for the vertex\\n     *\\n     * @type {string}\\n     */\\n    let cssClassStr = '';\\n    if (vertex.cssClasses.length &gt; 0) {\\n      cssClassStr = cssClassStr + ' ' + vertex.cssClasses.join(' ');\\n    }\\n    // if (vertex.classes.length &gt; 0) {\\n    //   classStr = vertex.classes.join(' ');\\n    // }\\n\\n    const styles = { labelStyle: '' }; //getStylesFromArray(vertex.styles);\\n\\n    // Use vertex id as text in the box if no text is provided by the graph definition\\n    let vertexText = vertex.text !== undefined ? vertex.text : vertex.id;\\n\\n    // We create a SVG label, either by delegating to addHtmlLabel or manually\\n    // let vertexNode;\\n    // if (evaluate(getConfig().flowchart.htmlLabels)) {\\n    //   const node = {\\n    //     label: vertexText.replace(\\n    //       /fa[lrsb]?:fa-[\\\\w-]+/g,\\n    //       s =&gt; `&lt;i class='${s.replace(':', ' ')}'&gt;&lt;/i&gt;`\\n    //     )\\n    //   };\\n    //   vertexNode = addHtmlLabel(svg, node).node();\\n    //   vertexNode.parentNode.removeChild(vertexNode);\\n    // } else {\\n    //   const svgLabel = document.createElementNS('http://www.w3.org/2000/svg', 'text');\\n    //   svgLabel.setAttribute('style', styles.labelStyle.replace('color:', 'fill:'));\\n\\n    //   const rows = vertexText.split(common.lineBreakRegex);\\n\\n    //   for (let j = 0; j &lt; rows.length; j++) {\\n    //     const tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');\\n    //     tspan.setAttributeNS('http://www.w3.org/XML/1998/namespace', 'xml:space', 'preserve');\\n    //     tspan.setAttribute('dy', '1em');\\n    //     tspan.setAttribute('x', '1');\\n    //     tspan.textContent = rows[j];\\n    //     svgLabel.appendChild(tspan);\\n    //   }\\n    //   vertexNode = svgLabel;\\n    // }\\n\\n    let radious = 0;\\n    let _shape = '';\\n    // Set the shape based parameters\\n    switch (vertex.type) {\\n      case 'class':\\n        _shape = 'class_box';\\n        break;\\n      default:\\n        _shape = 'class_box';\\n    }\\n    // Add the node\\n    g.setNode(vertex.id, {\\n      labelStyle: styles.labelStyle,\\n      shape: _shape,\\n      labelText: sanitizeText(vertexText),\\n      classData: vertex,\\n      rx: radious,\\n      ry: radious,\\n      class: cssClassStr,\\n      style: styles.style,\\n      id: vertex.id,\\n      domId: vertex.domId,\\n      haveCallback: vertex.haveCallback,\\n      link: vertex.link,\\n      width: vertex.type === 'group' ? 500 : undefined,\\n      type: vertex.type,\\n      padding: getConfig().flowchart.padding,\\n    });\\n\\n    log.info('setNode', {\\n      labelStyle: styles.labelStyle,\\n      shape: _shape,\\n      labelText: vertexText,\\n      rx: radious,\\n      ry: radious,\\n      class: cssClassStr,\\n      style: styles.style,\\n      id: vertex.id,\\n      width: vertex.type === 'group' ? 500 : undefined,\\n      type: vertex.type,\\n      padding: getConfig().flowchart.padding,\\n    });\\n  });\\n};\\n\\n/**\\n * Add edges to graph based on parsed graph defninition\\n *\\n * @param relations\\n * @param {object} g The graph object\\n */\\nexport const addRelations = function (relations, g) {\\n  let cnt = 0;\\n\\n  let defaultStyle;\\n  let defaultLabelStyle;\\n\\n  // if (typeof relations.defaultStyle !== 'undefined') {\\n  //   const defaultStyles = getStylesFromArray(relations.defaultStyle);\\n  //   defaultStyle = defaultStyles.style;\\n  //   defaultLabelStyle = defaultStyles.labelStyle;\\n  // }\\n\\n  relations.forEach(function (edge) {\\n    cnt++;\\n    const edgeData = {};\\n    //Set relationship style and line type\\n    edgeData.classes = 'relation';\\n    edgeData.pattern = edge.relation.lineType == 1 ? 'dashed' : 'solid';\\n\\n    edgeData.id = 'id' + cnt;\\n    // Set link type for rendering\\n    if (edge.type === 'arrow_open') {\\n      edgeData.arrowhead = 'none';\\n    } else {\\n      edgeData.arrowhead = 'normal';\\n    }\\n\\n    log.info(edgeData, edge);\\n    //Set edge extra labels\\n    //edgeData.startLabelLeft = edge.relationTitle1;\\n    edgeData.startLabelRight = edge.relationTitle1 === 'none' ? '' : edge.relationTitle1;\\n    edgeData.endLabelLeft = edge.relationTitle2 === 'none' ? '' : edge.relationTitle2;\\n    //edgeData.endLabelRight = edge.relationTitle2;\\n\\n    //Set relation arrow types\\n    edgeData.arrowTypeStart = getArrowMarker(edge.relation.type1);\\n    edgeData.arrowTypeEnd = getArrowMarker(edge.relation.type2);\\n    let style = '';\\n    let labelStyle = '';\\n\\n    if (typeof edge.style !== 'undefined') {\\n      const styles = getStylesFromArray(edge.style);\\n      style = styles.style;\\n      labelStyle = styles.labelStyle;\\n    } else {\\n      style = 'fill:none';\\n      if (typeof defaultStyle !== 'undefined') {\\n        style = defaultStyle;\\n      }\\n      if (typeof defaultLabelStyle !== 'undefined') {\\n        labelStyle = defaultLabelStyle;\\n      }\\n    }\\n\\n    edgeData.style = style;\\n    edgeData.labelStyle = labelStyle;\\n\\n    if (typeof edge.interpolate !== 'undefined') {\\n      edgeData.curve = interpolateToCurve(edge.interpolate, curveLinear);\\n    } else if (typeof relations.defaultInterpolate !== 'undefined') {\\n      edgeData.curve = interpolateToCurve(relations.defaultInterpolate, curveLinear);\\n    } else {\\n      edgeData.curve = interpolateToCurve(conf.curve, curveLinear);\\n    }\\n\\n    edge.text = edge.title;\\n    if (typeof edge.text === 'undefined') {\\n      if (typeof edge.style !== 'undefined') {\\n        edgeData.arrowheadStyle = 'fill: #333';\\n      }\\n    } else {\\n      edgeData.arrowheadStyle = 'fill: #333';\\n      edgeData.labelpos = 'c';\\n\\n      if (getConfig().flowchart.htmlLabels) {\\n        // eslint-disable-line\\n        edgeData.labelType = 'html';\\n        edgeData.label = '&lt;span class=\\\"edgeLabel\\\"&gt;' + edge.text + '&lt;/span&gt;';\\n      } else {\\n        edgeData.labelType = 'text';\\n        edgeData.label = edge.text.replace(common.lineBreakRegex, '\\\\n');\\n\\n        if (typeof edge.style === 'undefined') {\\n          edgeData.style = edgeData.style || 'stroke: #333; stroke-width: 1.5px;fill:none';\\n        }\\n\\n        edgeData.labelStyle = edgeData.labelStyle.replace('color:', 'fill:');\\n      }\\n    }\\n    // Add the edge to the graph\\n    g.setEdge(edge.id1, edge.id2, edgeData, cnt);\\n  });\\n};\\n\\n/**\\n * Gets the ID with the same label as in the cache\\n *\\n * @param {string} label The label to look for\\n * @returns {string} The resulting ID\\n */\\nconst getGraphId = function (label) {\\n  const foundEntry = Object.entries(idCache).find((entry) =&gt; entry[1].label === label);\\n\\n  if (foundEntry) {\\n    return foundEntry[0];\\n  }\\n};\\n\\n/**\\n * Merges the value of `conf` with the passed `cnf`\\n *\\n * @param {object} cnf Config to merge\\n */\\nexport const setConf = function (cnf) {\\n  const keys = Object.keys(cnf);\\n\\n  keys.forEach(function (key) {\\n    conf[key] = cnf[key];\\n  });\\n};\\n\\n/**\\n * Draws a flowchart in the tag with id: id based on the graph definition in text.\\n *\\n * @param {string} text\\n * @param {string} id\\n */\\nexport const draw = function (text, id) {\\n  log.info('Drawing class - ', id);\\n  classDb.clear();\\n  // const parser = classDb.parser;\\n  // parser.yy = classDb;\\n\\n  // Parse the graph definition\\n  // try {\\n  parser.parse(text);\\n  // } catch (err) {\\n  // log.debug('Parsing failed');\\n  // }\\n\\n  // Fetch the default direction, use TD if none was found\\n  //let dir = 'TD';\\n\\n  const conf = getConfig().flowchart;\\n  const securityLevel = getConfig().securityLevel;\\n  log.info('config:', conf);\\n  const nodeSpacing = conf.nodeSpacing || 50;\\n  const rankSpacing = conf.rankSpacing || 50;\\n\\n  // Create the input mermaid.graph\\n  const g = new graphlib.Graph({\\n    multigraph: true,\\n    compound: true,\\n  })\\n    .setGraph({\\n      rankdir: classDb.getDirection(),\\n      nodesep: nodeSpacing,\\n      ranksep: rankSpacing,\\n      marginx: 8,\\n      marginy: 8,\\n    })\\n    .setDefaultEdgeLabel(function () {\\n      return {};\\n    });\\n\\n  // let subG;\\n  // const subGraphs = flowDb.getSubGraphs();\\n  // log.info('Subgraphs - ', subGraphs);\\n  // for (let i = subGraphs.length - 1; i &gt;= 0; i--) {\\n  //   subG = subGraphs[i];\\n  //   log.info('Subgraph - ', subG);\\n  //   flowDb.addVertex(subG.id, subG.title, 'group', undefined, subG.classes);\\n  // }\\n\\n  // Fetch the verices/nodes and edges/links from the parsed graph definition\\n  const classes = classDb.getClasses();\\n  const relations = classDb.getRelations();\\n\\n  log.info(relations);\\n  // let i = 0;\\n  // for (i = subGraphs.length - 1; i &gt;= 0; i--) {\\n  //   subG = subGraphs[i];\\n\\n  //   selectAll('cluster').append('text');\\n\\n  //   for (let j = 0; j &lt; subG.nodes.length; j++) {\\n  //     g.setParent(subG.nodes[j], subG.id);\\n  //   }\\n  // }\\n  addClasses(classes, g, id);\\n  addRelations(relations, g);\\n\\n  // Add custom shapes\\n  // flowChartShapes.addToRenderV2(addShape);\\n\\n  // Set up an SVG group so that we can translate the final graph.\\n  let sandboxElement;\\n  if (securityLevel === 'sandbox') {\\n    sandboxElement = select('#i' + id);\\n  }\\n  const root =\\n    securityLevel === 'sandbox'\\n      ? select(sandboxElement.nodes()[0].contentDocument.body)\\n      : select('body');\\n  const svg = root.select(`[id=\\\"${id}\\\"]`);\\n  svg.attr('xmlns:xlink', 'http://www.w3.org/1999/xlink');\\n\\n  // Run the renderer. This is what draws the final graph.\\n  const element = root.select('#' + id + ' g');\\n  render(element, g, ['aggregation', 'extension', 'composition', 'dependency'], 'classDiagram', id);\\n\\n  // element.selectAll('g.node').attr('title', function() {\\n  //   return flowDb.getTooltip(this.id);\\n  // });\\n\\n  const padding = 8;\\n  const svgBounds = svg.node().getBBox();\\n  const width = svgBounds.width + padding * 2;\\n  const height = svgBounds.height + padding * 2;\\n  log.debug(\\n    `new ViewBox 0 0 ${width} ${height}`,\\n    `translate(${padding - g._label.marginx}, ${padding - g._label.marginy})`\\n  );\\n\\n  configureSvgSize(svg, height, width, conf.useMaxWidth);\\n\\n  svg.attr('viewBox', `0 0 ${width} ${height}`);\\n  svg\\n    .select('g')\\n    .attr('transform', `translate(${padding - g._label.marginx}, ${padding - svgBounds.y})`);\\n\\n  // Index nodes\\n  // flowDb.indexNodes('subGraph' + i);\\n\\n  // Add label rects for non html labels\\n  if (!conf.htmlLabels) {\\n    const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n    const labels = doc.querySelectorAll('[id=\\\"' + id + '\\\"] .edgeLabel .label');\\n    for (let k = 0; k &lt; labels.length; k++) {\\n      const label = labels[k];\\n\\n      // Get dimensions of label\\n      const dim = label.getBBox();\\n\\n      const rect = doc.createElementNS('http://www.w3.org/2000/svg', 'rect');\\n      rect.setAttribute('rx', 0);\\n      rect.setAttribute('ry', 0);\\n      rect.setAttribute('width', dim.width);\\n      rect.setAttribute('height', dim.height);\\n      // rect.setAttribute('style', 'fill:#e8e8e8;');\\n\\n      label.insertBefore(rect, label.firstChild);\\n    }\\n  }\\n\\n  // If node has a link, wrap it in an anchor SVG object.\\n  // const keys = Object.keys(classes);\\n  // keys.forEach(function(key) {\\n  //   const vertex = classes[key];\\n\\n  //   if (vertex.link) {\\n  //     const node = select('#' + id + ' [id=\\\"' + key + '\\\"]');\\n  //     if (node) {\\n  //       const link = document.createElementNS('http://www.w3.org/2000/svg', 'a');\\n  //       link.setAttributeNS('http://www.w3.org/2000/svg', 'class', vertex.classes.join(' '));\\n  //       link.setAttributeNS('http://www.w3.org/2000/svg', 'href', vertex.link);\\n  //       link.setAttributeNS('http://www.w3.org/2000/svg', 'rel', 'noopener');\\n\\n  //       const linkNode = node.insert(function() {\\n  //         return link;\\n  //       }, ':first-child');\\n\\n  //       const shape = node.select('.label-container');\\n  //       if (shape) {\\n  //         linkNode.append(function() {\\n  //           return shape.node();\\n  //         });\\n  //       }\\n\\n  //       const label = node.select('.label');\\n  //       if (label) {\\n  //         linkNode.append(function() {\\n  //           return label.node();\\n  //         });\\n  //       }\\n  //     }\\n  //   }\\n  // });\\n};\\n\\n/**\\n * Gets the arrow marker for a type index\\n *\\n * @param {number} type The type to look for\\n * @returns {'aggregation' | 'extension' | 'composition' | 'dependency'} The arrow marker\\n */\\nfunction getArrowMarker(type) {\\n  let marker;\\n  switch (type) {\\n    case 0:\\n      marker = 'aggregation';\\n      break;\\n    case 1:\\n      marker = 'extension';\\n      break;\\n    case 2:\\n      marker = 'composition';\\n      break;\\n    case 3:\\n      marker = 'dependency';\\n      break;\\n    default:\\n      marker = 'none';\\n  }\\n  return marker;\\n}\\n\\nexport default {\\n  setConf,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import { log } from '../../logger';\\nimport mermaidAPI from '../../mermaidAPI';\\nimport * as configApi from '../../config';\\n\\nlet entities = {};\\nlet relationships = [];\\nlet title = '';\\nlet description = '';\\n\\nconst Cardinality = {\\n  ZERO_OR_ONE: 'ZERO_OR_ONE',\\n  ZERO_OR_MORE: 'ZERO_OR_MORE',\\n  ONE_OR_MORE: 'ONE_OR_MORE',\\n  ONLY_ONE: 'ONLY_ONE',\\n};\\n\\nconst Identification = {\\n  NON_IDENTIFYING: 'NON_IDENTIFYING',\\n  IDENTIFYING: 'IDENTIFYING',\\n};\\n\\nexport const parseDirective = function (statement, context, type) {\\n  mermaidAPI.parseDirective(this, statement, context, type);\\n};\\n\\nconst addEntity = function (name) {\\n  if (typeof entities[name] === 'undefined') {\\n    entities[name] = { attributes: [] };\\n    log.info('Added new entity :', name);\\n  }\\n\\n  return entities[name];\\n};\\n\\nconst getEntities = () =&gt; entities;\\n\\nconst addAttributes = function (entityName, attribs) {\\n  let entity = addEntity(entityName); // May do nothing (if entity has already been added)\\n\\n  // Process attribs in reverse order due to effect of recursive construction (last attribute is first)\\n  let i;\\n  for (i = attribs.length - 1; i &gt;= 0; i--) {\\n    entity.attributes.push(attribs[i]);\\n    log.debug('Added attribute ', attribs[i].attributeName);\\n  }\\n};\\n\\n/**\\n * Add a relationship\\n *\\n * @param entA The first entity in the relationship\\n * @param rolA The role played by the first entity in relation to the second\\n * @param entB The second entity in the relationship\\n * @param rSpec The details of the relationship between the two entities\\n */\\nconst addRelationship = function (entA, rolA, entB, rSpec) {\\n  let rel = {\\n    entityA: entA,\\n    roleA: rolA,\\n    entityB: entB,\\n    relSpec: rSpec,\\n  };\\n\\n  relationships.push(rel);\\n  log.debug('Added new relationship :', rel);\\n};\\n\\nconst getRelationships = () =&gt; relationships;\\n\\n// Keep this - TODO: revisit...allow the diagram to have a title\\nconst setTitle = function (txt) {\\n  title = txt;\\n};\\n\\nconst getTitle = function () {\\n  return title;\\n};\\n\\nconst setAccDescription = function (txt) {\\n  description = txt;\\n};\\n\\nconst getAccDescription = function () {\\n  return description;\\n};\\n\\nconst clear = function () {\\n  entities = {};\\n  relationships = [];\\n  title = '';\\n};\\n\\nexport default {\\n  Cardinality,\\n  Identification,\\n  parseDirective,\\n  getConfig: () =&gt; configApi.getConfig().er,\\n  addEntity,\\n  addAttributes,\\n  getEntities,\\n  addRelationship,\\n  getRelationships,\\n  clear,\\n  setTitle,\\n  getTitle,\\n  setAccDescription,\\n  getAccDescription,\\n};\\n\"</span>,<span class=\"code-string\">\"const ERMarkers = {\\n  ONLY_ONE_START: 'ONLY_ONE_START',\\n  ONLY_ONE_END: 'ONLY_ONE_END',\\n  ZERO_OR_ONE_START: 'ZERO_OR_ONE_START',\\n  ZERO_OR_ONE_END: 'ZERO_OR_ONE_END',\\n  ONE_OR_MORE_START: 'ONE_OR_MORE_START',\\n  ONE_OR_MORE_END: 'ONE_OR_MORE_END',\\n  ZERO_OR_MORE_START: 'ZERO_OR_MORE_START',\\n  ZERO_OR_MORE_END: 'ZERO_OR_MORE_END',\\n};\\n\\n/**\\n * Put the markers into the svg DOM for later use with edge paths\\n *\\n * @param elem\\n * @param conf\\n */\\nconst insertMarkers = function (elem, conf) {\\n  let marker;\\n\\n  elem\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', ERMarkers.ONLY_ONE_START)\\n    .attr('refX', 0)\\n    .attr('refY', 9)\\n    .attr('markerWidth', 18)\\n    .attr('markerHeight', 18)\\n    .attr('orient', 'auto')\\n    .append('path')\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'none')\\n    .attr('d', 'M9,0 L9,18 M15,0 L15,18');\\n\\n  elem\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', ERMarkers.ONLY_ONE_END)\\n    .attr('refX', 18)\\n    .attr('refY', 9)\\n    .attr('markerWidth', 18)\\n    .attr('markerHeight', 18)\\n    .attr('orient', 'auto')\\n    .append('path')\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'none')\\n    .attr('d', 'M3,0 L3,18 M9,0 L9,18');\\n\\n  marker = elem\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', ERMarkers.ZERO_OR_ONE_START)\\n    .attr('refX', 0)\\n    .attr('refY', 9)\\n    .attr('markerWidth', 30)\\n    .attr('markerHeight', 18)\\n    .attr('orient', 'auto');\\n  marker\\n    .append('circle')\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'white')\\n    .attr('cx', 21)\\n    .attr('cy', 9)\\n    .attr('r', 6);\\n  marker.append('path').attr('stroke', conf.stroke).attr('fill', 'none').attr('d', 'M9,0 L9,18');\\n\\n  marker = elem\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', ERMarkers.ZERO_OR_ONE_END)\\n    .attr('refX', 30)\\n    .attr('refY', 9)\\n    .attr('markerWidth', 30)\\n    .attr('markerHeight', 18)\\n    .attr('orient', 'auto');\\n  marker\\n    .append('circle')\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'white')\\n    .attr('cx', 9)\\n    .attr('cy', 9)\\n    .attr('r', 6);\\n  marker.append('path').attr('stroke', conf.stroke).attr('fill', 'none').attr('d', 'M21,0 L21,18');\\n\\n  elem\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', ERMarkers.ONE_OR_MORE_START)\\n    .attr('refX', 18)\\n    .attr('refY', 18)\\n    .attr('markerWidth', 45)\\n    .attr('markerHeight', 36)\\n    .attr('orient', 'auto')\\n    .append('path')\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'none')\\n    .attr('d', 'M0,18 Q 18,0 36,18 Q 18,36 0,18 M42,9 L42,27');\\n\\n  elem\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', ERMarkers.ONE_OR_MORE_END)\\n    .attr('refX', 27)\\n    .attr('refY', 18)\\n    .attr('markerWidth', 45)\\n    .attr('markerHeight', 36)\\n    .attr('orient', 'auto')\\n    .append('path')\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'none')\\n    .attr('d', 'M3,9 L3,27 M9,18 Q27,0 45,18 Q27,36 9,18');\\n\\n  marker = elem\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', ERMarkers.ZERO_OR_MORE_START)\\n    .attr('refX', 18)\\n    .attr('refY', 18)\\n    .attr('markerWidth', 57)\\n    .attr('markerHeight', 36)\\n    .attr('orient', 'auto');\\n  marker\\n    .append('circle')\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'white')\\n    .attr('cx', 48)\\n    .attr('cy', 18)\\n    .attr('r', 6);\\n  marker\\n    .append('path')\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'none')\\n    .attr('d', 'M0,18 Q18,0 36,18 Q18,36 0,18');\\n\\n  marker = elem\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', ERMarkers.ZERO_OR_MORE_END)\\n    .attr('refX', 39)\\n    .attr('refY', 18)\\n    .attr('markerWidth', 57)\\n    .attr('markerHeight', 36)\\n    .attr('orient', 'auto');\\n  marker\\n    .append('circle')\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'white')\\n    .attr('cx', 9)\\n    .attr('cy', 18)\\n    .attr('r', 6);\\n  marker\\n    .append('path')\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'none')\\n    .attr('d', 'M21,18 Q39,0 57,18 Q39,36 21,18');\\n\\n  return;\\n};\\n\\nexport default {\\n  ERMarkers,\\n  insertMarkers,\\n};\\n\"</span>,<span class=\"code-string\">\"/**\\n * This method will add a basic title and description element to a chart. The yy parser will need to\\n * respond to getTitle and getAccDescription, where the title is the title element on the chart,\\n * which is not displayed and the accDescription is the description element on the chart, which is\\n * also not displayed.\\n *\\n * @param yy_parser\\n * @param svg\\n * @param id\\n */\\nexport default function addSVGAccessibilityFields(yy_parser, svg, id) {\\n  if (typeof svg.insert == 'undefined') {\\n    return;\\n  }\\n  let title_string = yy_parser.getTitle();\\n  let description = yy_parser.getAccDescription();\\n  svg.attr('role', 'img').attr('aria-labelledby', 'chart-title-' + id + ' chart-desc-' + id);\\n  svg\\n    .insert('desc', ':first-child')\\n    .attr('id', 'chart-desc-' + id)\\n    .text(description);\\n  svg\\n    .insert('title', ':first-child')\\n    .attr('id', 'chart-title-' + id)\\n    .text(title_string);\\n}\\n\"</span>,<span class=\"code-string\">\"import graphlib from 'graphlib';\\nimport { line, curveBasis, select } from 'd3';\\nimport erDb from './erDb';\\nimport erParser from './parser/erDiagram';\\nimport dagre from 'dagre';\\nimport { getConfig } from '../../config';\\nimport { log } from '../../logger';\\nimport erMarkers from './erMarkers';\\nimport { configureSvgSize } from '../../utils';\\nimport addSVGAccessibilityFields from '../../accessibility';\\n\\nconst conf = {};\\n\\n/**\\n * Allows the top-level API module to inject config specific to this renderer, storing it in the\\n * local conf object. Note that generic config still needs to be retrieved using getConfig()\\n * imported from the config module\\n *\\n * @param cnf\\n */\\nexport const setConf = function (cnf) {\\n  const keys = Object.keys(cnf);\\n  for (let i = 0; i &lt; keys.length; i++) {\\n    conf[keys[i]] = cnf[keys[i]];\\n  }\\n};\\n\\n/**\\n * Draw attributes for an entity\\n *\\n * @param groupNode The svg group node for the entity\\n * @param entityTextNode The svg node for the entity label text\\n * @param attributes An array of attributes defined for the entity (each attribute has a type and a name)\\n * @returns The bounding box of the entity, after attributes have been added\\n */\\nconst drawAttributes = (groupNode, entityTextNode, attributes) =&gt; {\\n  const heightPadding = conf.entityPadding / 3; // Padding internal to attribute boxes\\n  const widthPadding = conf.entityPadding / 3; // Ditto\\n  const attrFontSize = conf.fontSize * 0.85;\\n  const labelBBox = entityTextNode.node().getBBox();\\n  const attributeNodes = []; // Intermediate storage for attribute nodes created so that we can do a second pass\\n  let hasKeyType = false;\\n  let hasComment = false;\\n  let maxTypeWidth = 0;\\n  let maxNameWidth = 0;\\n  let maxKeyWidth = 0;\\n  let maxCommentWidth = 0;\\n  let cumulativeHeight = labelBBox.height + heightPadding * 2;\\n  let attrNum = 1;\\n\\n  // Check to see if any of the attributes has a key or a comment\\n  attributes.forEach((item) =&gt; {\\n    if (item.attributeKeyType !== undefined) {\\n      hasKeyType = true;\\n    }\\n\\n    if (item.attributeComment !== undefined) {\\n      hasComment = true;\\n    }\\n  });\\n\\n  attributes.forEach((item) =&gt; {\\n    const attrPrefix = `${entityTextNode.node().id}-attr-${attrNum}`;\\n    let nodeHeight = 0;\\n\\n    // Add a text node for the attribute type\\n    const typeNode = groupNode\\n      .append('text')\\n      .attr('class', 'er entityLabel')\\n      .attr('id', `${attrPrefix}-type`)\\n      .attr('x', 0)\\n      .attr('y', 0)\\n      .attr('dominant-baseline', 'middle')\\n      .attr('text-anchor', 'left')\\n      .attr(\\n        'style',\\n        'font-family: ' + getConfig().fontFamily + '; font-size: ' + attrFontSize + 'px'\\n      )\\n      .text(item.attributeType);\\n\\n    // Add a text node for the attribute name\\n    const nameNode = groupNode\\n      .append('text')\\n      .attr('class', 'er entityLabel')\\n      .attr('id', `${attrPrefix}-name`)\\n      .attr('x', 0)\\n      .attr('y', 0)\\n      .attr('dominant-baseline', 'middle')\\n      .attr('text-anchor', 'left')\\n      .attr(\\n        'style',\\n        'font-family: ' + getConfig().fontFamily + '; font-size: ' + attrFontSize + 'px'\\n      )\\n      .text(item.attributeName);\\n\\n    const attributeNode = {};\\n    attributeNode.tn = typeNode;\\n    attributeNode.nn = nameNode;\\n\\n    const typeBBox = typeNode.node().getBBox();\\n    const nameBBox = nameNode.node().getBBox();\\n    maxTypeWidth = Math.max(maxTypeWidth, typeBBox.width);\\n    maxNameWidth = Math.max(maxNameWidth, nameBBox.width);\\n\\n    nodeHeight = Math.max(typeBBox.height, nameBBox.height);\\n\\n    if (hasKeyType) {\\n      const keyTypeNode = groupNode\\n        .append('text')\\n        .attr('class', 'er entityLabel')\\n        .attr('id', `${attrPrefix}-key`)\\n        .attr('x', 0)\\n        .attr('y', 0)\\n        .attr('dominant-baseline', 'middle')\\n        .attr('text-anchor', 'left')\\n        .attr(\\n          'style',\\n          'font-family: ' + getConfig().fontFamily + '; font-size: ' + attrFontSize + 'px'\\n        )\\n        .text(item.attributeKeyType || '');\\n\\n      attributeNode.kn = keyTypeNode;\\n      const keyTypeBBox = keyTypeNode.node().getBBox();\\n      maxKeyWidth = Math.max(maxKeyWidth, keyTypeBBox.width);\\n      nodeHeight = Math.max(nodeHeight, keyTypeBBox.height);\\n    }\\n\\n    if (hasComment) {\\n      const commentNode = groupNode\\n        .append('text')\\n        .attr('class', 'er entityLabel')\\n        .attr('id', `${attrPrefix}-comment`)\\n        .attr('x', 0)\\n        .attr('y', 0)\\n        .attr('dominant-baseline', 'middle')\\n        .attr('text-anchor', 'left')\\n        .attr(\\n          'style',\\n          'font-family: ' + getConfig().fontFamily + '; font-size: ' + attrFontSize + 'px'\\n        )\\n        .text(item.attributeComment || '');\\n\\n      attributeNode.cn = commentNode;\\n      const commentNodeBBox = commentNode.node().getBBox();\\n      maxCommentWidth = Math.max(maxCommentWidth, commentNodeBBox.width);\\n      nodeHeight = Math.max(nodeHeight, commentNodeBBox.height);\\n    }\\n\\n    attributeNode.height = nodeHeight;\\n    // Keep a reference to the nodes so that we can iterate through them later\\n    attributeNodes.push(attributeNode);\\n    cumulativeHeight += nodeHeight + heightPadding * 2;\\n    attrNum += 1;\\n  });\\n\\n  let widthPaddingFactor = 4;\\n  if (hasKeyType) {\\n    widthPaddingFactor += 2;\\n  }\\n  if (hasComment) {\\n    widthPaddingFactor += 2;\\n  }\\n\\n  const maxWidth = maxTypeWidth + maxNameWidth + maxKeyWidth + maxCommentWidth;\\n\\n  // Calculate the new bounding box of the overall entity, now that attributes have been added\\n  const bBox = {\\n    width: Math.max(\\n      conf.minEntityWidth,\\n      Math.max(\\n        labelBBox.width + conf.entityPadding * 2,\\n        maxWidth + widthPadding * widthPaddingFactor\\n      )\\n    ),\\n    height:\\n      attributes.length &gt; 0\\n        ? cumulativeHeight\\n        : Math.max(conf.minEntityHeight, labelBBox.height + conf.entityPadding * 2),\\n  };\\n\\n  if (attributes.length &gt; 0) {\\n    // There might be some spare width for padding out attributes if the entity name is very long\\n    const spareColumnWidth = Math.max(\\n      0,\\n      (bBox.width - maxWidth - widthPadding * widthPaddingFactor) / (widthPaddingFactor / 2)\\n    );\\n\\n    // Position the entity label near the top of the entity bounding box\\n    entityTextNode.attr(\\n      'transform',\\n      'translate(' + bBox.width / 2 + ',' + (heightPadding + labelBBox.height / 2) + ')'\\n    );\\n\\n    // Add rectangular boxes for the attribute types/names\\n    let heightOffset = labelBBox.height + heightPadding * 2; // Start at the bottom of the entity label\\n    let attribStyle = 'attributeBoxOdd'; // We will flip the style on alternate rows to achieve a banded effect\\n\\n    attributeNodes.forEach((attributeNode) =&gt; {\\n      // Calculate the alignment y co-ordinate for the type/name of the attribute\\n      const alignY = heightOffset + heightPadding + attributeNode.height / 2;\\n\\n      // Position the type attribute\\n      attributeNode.tn.attr('transform', 'translate(' + widthPadding + ',' + alignY + ')');\\n\\n      // TODO Handle spareWidth in attr('width')\\n      // Insert a rectangle for the type\\n      const typeRect = groupNode\\n        .insert('rect', '#' + attributeNode.tn.node().id)\\n        .attr('class', `er ${attribStyle}`)\\n        .attr('fill', conf.fill)\\n        .attr('fill-opacity', '100%')\\n        .attr('stroke', conf.stroke)\\n        .attr('x', 0)\\n        .attr('y', heightOffset)\\n        .attr('width', maxTypeWidth + widthPadding * 2 + spareColumnWidth)\\n        .attr('height', attributeNode.height + heightPadding * 2);\\n\\n      const nameXOffset = parseFloat(typeRect.attr('x')) + parseFloat(typeRect.attr('width'));\\n\\n      // Position the name attribute\\n      attributeNode.nn.attr(\\n        'transform',\\n        'translate(' + (nameXOffset + widthPadding) + ',' + alignY + ')'\\n      );\\n\\n      // Insert a rectangle for the name\\n      const nameRect = groupNode\\n        .insert('rect', '#' + attributeNode.nn.node().id)\\n        .attr('class', `er ${attribStyle}`)\\n        .attr('fill', conf.fill)\\n        .attr('fill-opacity', '100%')\\n        .attr('stroke', conf.stroke)\\n        .attr('x', nameXOffset)\\n        .attr('y', heightOffset)\\n        .attr('width', maxNameWidth + widthPadding * 2 + spareColumnWidth)\\n        .attr('height', attributeNode.height + heightPadding * 2);\\n\\n      let keyTypeAndCommentXOffset =\\n        parseFloat(nameRect.attr('x')) + parseFloat(nameRect.attr('width'));\\n\\n      if (hasKeyType) {\\n        // Position the key type attribute\\n        attributeNode.kn.attr(\\n          'transform',\\n          'translate(' + (keyTypeAndCommentXOffset + widthPadding) + ',' + alignY + ')'\\n        );\\n\\n        // Insert a rectangle for the key type\\n        const keyTypeRect = groupNode\\n          .insert('rect', '#' + attributeNode.kn.node().id)\\n          .attr('class', `er ${attribStyle}`)\\n          .attr('fill', conf.fill)\\n          .attr('fill-opacity', '100%')\\n          .attr('stroke', conf.stroke)\\n          .attr('x', keyTypeAndCommentXOffset)\\n          .attr('y', heightOffset)\\n          .attr('width', maxKeyWidth + widthPadding * 2 + spareColumnWidth)\\n          .attr('height', attributeNode.height + heightPadding * 2);\\n\\n        keyTypeAndCommentXOffset =\\n          parseFloat(keyTypeRect.attr('x')) + parseFloat(keyTypeRect.attr('width'));\\n      }\\n\\n      if (hasComment) {\\n        // Position the comment attribute\\n        attributeNode.cn.attr(\\n          'transform',\\n          'translate(' + (keyTypeAndCommentXOffset + widthPadding) + ',' + alignY + ')'\\n        );\\n\\n        // Insert a rectangle for the comment\\n        groupNode\\n          .insert('rect', '#' + attributeNode.cn.node().id)\\n          .attr('class', `er ${attribStyle}`)\\n          .attr('fill', conf.fill)\\n          .attr('fill-opacity', '100%')\\n          .attr('stroke', conf.stroke)\\n          .attr('x', keyTypeAndCommentXOffset)\\n          .attr('y', heightOffset)\\n          .attr('width', maxCommentWidth + widthPadding * 2 + spareColumnWidth)\\n          .attr('height', attributeNode.height + heightPadding * 2);\\n      }\\n\\n      // Increment the height offset to move to the next row\\n      heightOffset += attributeNode.height + heightPadding * 2;\\n\\n      // Flip the attribute style for row banding\\n      attribStyle = attribStyle == 'attributeBoxOdd' ? 'attributeBoxEven' : 'attributeBoxOdd';\\n    });\\n  } else {\\n    // Ensure the entity box is a decent size without any attributes\\n    bBox.height = Math.max(conf.minEntityHeight, cumulativeHeight);\\n\\n    // Position the entity label in the middle of the box\\n    entityTextNode.attr('transform', 'translate(' + bBox.width / 2 + ',' + bBox.height / 2 + ')');\\n  }\\n\\n  return bBox;\\n};\\n\\n/**\\n * Use D3 to construct the svg elements for the entities\\n *\\n * @param svgNode The svg node that contains the diagram\\n * @param entities The entities to be drawn\\n * @param graph The graph that contains the vertex and edge definitions post-layout\\n * @returns The first entity that was inserted\\n */\\nconst drawEntities = function (svgNode, entities, graph) {\\n  const keys = Object.keys(entities);\\n  let firstOne;\\n\\n  keys.forEach(function (id) {\\n    // Create a group for each entity\\n    const groupNode = svgNode.append('g').attr('id', id);\\n\\n    firstOne = firstOne === undefined ? id : firstOne;\\n\\n    // Label the entity - this is done first so that we can get the bounding box\\n    // which then determines the size of the rectangle\\n    const textId = 'entity-' + id;\\n    const textNode = groupNode\\n      .append('text')\\n      .attr('class', 'er entityLabel')\\n      .attr('id', textId)\\n      .attr('x', 0)\\n      .attr('y', 0)\\n      .attr('dominant-baseline', 'middle')\\n      .attr('text-anchor', 'middle')\\n      .attr(\\n        'style',\\n        'font-family: ' + getConfig().fontFamily + '; font-size: ' + conf.fontSize + 'px'\\n      )\\n      .text(id);\\n\\n    const { width: entityWidth, height: entityHeight } = drawAttributes(\\n      groupNode,\\n      textNode,\\n      entities[id].attributes\\n    );\\n\\n    // Draw the rectangle - insert it before the text so that the text is not obscured\\n    const rectNode = groupNode\\n      .insert('rect', '#' + textId)\\n      .attr('class', 'er entityBox')\\n      .attr('fill', conf.fill)\\n      .attr('fill-opacity', '100%')\\n      .attr('stroke', conf.stroke)\\n      .attr('x', 0)\\n      .attr('y', 0)\\n      .attr('width', entityWidth)\\n      .attr('height', entityHeight);\\n\\n    const rectBBox = rectNode.node().getBBox();\\n\\n    // Add the entity to the graph\\n    graph.setNode(id, {\\n      width: rectBBox.width,\\n      height: rectBBox.height,\\n      shape: 'rect',\\n      id: id,\\n    });\\n  });\\n  return firstOne;\\n}; // drawEntities\\n\\nconst adjustEntities = function (svgNode, graph) {\\n  graph.nodes().forEach(function (v) {\\n    if (typeof v !== 'undefined' &amp;&amp; typeof graph.node(v) !== 'undefined') {\\n      svgNode\\n        .select('#' + v)\\n        .attr(\\n          'transform',\\n          'translate(' +\\n            (graph.node(v).x - graph.node(v).width / 2) +\\n            ',' +\\n            (graph.node(v).y - graph.node(v).height / 2) +\\n            ' )'\\n        );\\n    }\\n  });\\n  return;\\n};\\n\\nconst getEdgeName = function (rel) {\\n  return (rel.entityA + rel.roleA + rel.entityB).replace(/\\\\s/g, '');\\n};\\n\\n/**\\n * Add each relationship to the graph\\n *\\n * @param relationships The relationships to be added\\n * @param g The graph\\n * @returns {Array} The array of relationships\\n */\\nconst addRelationships = function (relationships, g) {\\n  relationships.forEach(function (r) {\\n    g.setEdge(r.entityA, r.entityB, { relationship: r }, getEdgeName(r));\\n  });\\n  return relationships;\\n}; // addRelationships\\n\\nlet relCnt = 0;\\n/**\\n * Draw a relationship using edge information from the graph\\n *\\n * @param svg The svg node\\n * @param rel The relationship to draw in the svg\\n * @param g The graph containing the edge information\\n * @param insert The insertion point in the svg DOM (because relationships have markers that need to\\n *   sit 'behind' opaque entity boxes)\\n */\\nconst drawRelationshipFromLayout = function (svg, rel, g, insert) {\\n  relCnt++;\\n\\n  // Find the edge relating to this relationship\\n  const edge = g.edge(rel.entityA, rel.entityB, getEdgeName(rel));\\n\\n  // Get a function that will generate the line path\\n  const lineFunction = line()\\n    .x(function (d) {\\n      return d.x;\\n    })\\n    .y(function (d) {\\n      return d.y;\\n    })\\n    .curve(curveBasis);\\n\\n  // Insert the line at the right place\\n  const svgPath = svg\\n    .insert('path', '#' + insert)\\n    .attr('class', 'er relationshipLine')\\n    .attr('d', lineFunction(edge.points))\\n    .attr('stroke', conf.stroke)\\n    .attr('fill', 'none');\\n\\n  // ...and with dashes if necessary\\n  if (rel.relSpec.relType === erDb.Identification.NON_IDENTIFYING) {\\n    svgPath.attr('stroke-dasharray', '8,8');\\n  }\\n\\n  // TODO: Understand this better\\n  let url = '';\\n  if (conf.arrowMarkerAbsolute) {\\n    url =\\n      window.location.protocol +\\n      '//' +\\n      window.location.host +\\n      window.location.pathname +\\n      window.location.search;\\n    url = url.replace(/\\\\(/g, '\\\\\\\\(');\\n    url = url.replace(/\\\\)/g, '\\\\\\\\)');\\n  }\\n\\n  // Decide which start and end markers it needs. It may be possible to be more concise here\\n  // by reversing a start marker to make an end marker...but this will do for now\\n\\n  // Note that the 'A' entity's marker is at the end of the relationship and the 'B' entity's marker is at the start\\n  switch (rel.relSpec.cardA) {\\n    case erDb.Cardinality.ZERO_OR_ONE:\\n      svgPath.attr('marker-end', 'url(' + url + '#' + erMarkers.ERMarkers.ZERO_OR_ONE_END + ')');\\n      break;\\n    case erDb.Cardinality.ZERO_OR_MORE:\\n      svgPath.attr('marker-end', 'url(' + url + '#' + erMarkers.ERMarkers.ZERO_OR_MORE_END + ')');\\n      break;\\n    case erDb.Cardinality.ONE_OR_MORE:\\n      svgPath.attr('marker-end', 'url(' + url + '#' + erMarkers.ERMarkers.ONE_OR_MORE_END + ')');\\n      break;\\n    case erDb.Cardinality.ONLY_ONE:\\n      svgPath.attr('marker-end', 'url(' + url + '#' + erMarkers.ERMarkers.ONLY_ONE_END + ')');\\n      break;\\n  }\\n\\n  switch (rel.relSpec.cardB) {\\n    case erDb.Cardinality.ZERO_OR_ONE:\\n      svgPath.attr(\\n        'marker-start',\\n        'url(' + url + '#' + erMarkers.ERMarkers.ZERO_OR_ONE_START + ')'\\n      );\\n      break;\\n    case erDb.Cardinality.ZERO_OR_MORE:\\n      svgPath.attr(\\n        'marker-start',\\n        'url(' + url + '#' + erMarkers.ERMarkers.ZERO_OR_MORE_START + ')'\\n      );\\n      break;\\n    case erDb.Cardinality.ONE_OR_MORE:\\n      svgPath.attr(\\n        'marker-start',\\n        'url(' + url + '#' + erMarkers.ERMarkers.ONE_OR_MORE_START + ')'\\n      );\\n      break;\\n    case erDb.Cardinality.ONLY_ONE:\\n      svgPath.attr('marker-start', 'url(' + url + '#' + erMarkers.ERMarkers.ONLY_ONE_START + ')');\\n      break;\\n  }\\n\\n  // Now label the relationship\\n\\n  // Find the half-way point\\n  const len = svgPath.node().getTotalLength();\\n  const labelPoint = svgPath.node().getPointAtLength(len * 0.5);\\n\\n  // Append a text node containing the label\\n  const labelId = 'rel' + relCnt;\\n\\n  const labelNode = svg\\n    .append('text')\\n    .attr('class', 'er relationshipLabel')\\n    .attr('id', labelId)\\n    .attr('x', labelPoint.x)\\n    .attr('y', labelPoint.y)\\n    .attr('text-anchor', 'middle')\\n    .attr('dominant-baseline', 'middle')\\n    .attr(\\n      'style',\\n      'font-family: ' + getConfig().fontFamily + '; font-size: ' + conf.fontSize + 'px'\\n    )\\n    .text(rel.roleA);\\n\\n  // Figure out how big the opaque 'container' rectangle needs to be\\n  const labelBBox = labelNode.node().getBBox();\\n\\n  // Insert the opaque rectangle before the text label\\n  svg\\n    .insert('rect', '#' + labelId)\\n    .attr('class', 'er relationshipLabelBox')\\n    .attr('x', labelPoint.x - labelBBox.width / 2)\\n    .attr('y', labelPoint.y - labelBBox.height / 2)\\n    .attr('width', labelBBox.width)\\n    .attr('height', labelBBox.height)\\n    .attr('fill', 'white')\\n    .attr('fill-opacity', '85%');\\n\\n  return;\\n};\\n\\n/**\\n * Draw en E-R diagram in the tag with id: id based on the text definition of the diagram\\n *\\n * @param text The text of the diagram\\n * @param id The unique id of the DOM node that contains the diagram\\n */\\nexport const draw = function (text, id) {\\n  log.info('Drawing ER diagram');\\n  erDb.clear();\\n  const parser = erParser.parser;\\n  parser.yy = erDb;\\n  const securityLevel = getConfig().securityLevel;\\n  // Handle root and ocument for when rendering in sanbox mode\\n  let sandboxElement;\\n  if (securityLevel === 'sandbox') {\\n    sandboxElement = select('#i' + id);\\n  }\\n  const root =\\n    securityLevel === 'sandbox'\\n      ? select(sandboxElement.nodes()[0].contentDocument.body)\\n      : select('body');\\n  const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n\\n  // Parse the text to populate erDb\\n  try {\\n    parser.parse(text);\\n  } catch (err) {\\n    log.debug('Parsing failed');\\n  }\\n\\n  // Get a reference to the svg node that contains the text\\n  const svg = root.select(`[id='${id}']`);\\n\\n  // Add cardinality marker definitions to the svg\\n  erMarkers.insertMarkers(svg, conf);\\n\\n  // Now we have to construct the diagram in a specific way:\\n  // ---\\n  // 1. Create all the entities in the svg node at 0,0, but with the correct dimensions (allowing for text content)\\n  // 2. Make sure they are all added to the graph\\n  // 3. Add all the edges (relationships) to the graph aswell\\n  // 4. Let dagre do its magic to layout the graph.  This assigns:\\n  //    - the centre co-ordinates for each node, bearing in mind the dimensions and edge relationships\\n  //    - the path co-ordinates for each edge\\n  //    But it has no impact on the svg child nodes - the diagram remains with every entity rooted at 0,0\\n  // 5. Now assign a transform to each entity in the svg node so that it gets drawn in the correct place, as determined by\\n  //    its centre point, which is obtained from the graph, and it's width and height\\n  // 6. And finally, create all the edges in the svg node using information from the graph\\n  // ---\\n\\n  // Create the graph\\n  let g;\\n\\n  // TODO: Explore directed vs undirected graphs, and how the layout is affected\\n  // An E-R diagram could be said to be undirected, but there is merit in setting\\n  // the direction from parent to child in a one-to-many as this influences graphlib to\\n  // put the parent above the child (does it?), which is intuitive.  Most relationships\\n  // in ER diagrams are one-to-many.\\n  g = new graphlib.Graph({\\n    multigraph: true,\\n    directed: true,\\n    compound: false,\\n  })\\n    .setGraph({\\n      rankdir: conf.layoutDirection,\\n      marginx: 20,\\n      marginy: 20,\\n      nodesep: 100,\\n      edgesep: 100,\\n      ranksep: 100,\\n    })\\n    .setDefaultEdgeLabel(function () {\\n      return {};\\n    });\\n\\n  // Draw the entities (at 0,0), returning the first svg node that got\\n  // inserted - this represents the insertion point for relationship paths\\n  const firstEntity = drawEntities(svg, erDb.getEntities(), g);\\n\\n  // TODO: externalise the addition of entities to the graph - it's a bit 'buried' in the above\\n\\n  // Add all the relationships to the graph\\n  const relationships = addRelationships(erDb.getRelationships(), g);\\n\\n  dagre.layout(g); // Node and edge positions will be updated\\n\\n  // Adjust the positions of the entities so that they adhere to the layout\\n  adjustEntities(svg, g);\\n\\n  // Draw the relationships\\n  relationships.forEach(function (rel) {\\n    drawRelationshipFromLayout(svg, rel, g, firstEntity);\\n  });\\n\\n  const padding = conf.diagramPadding;\\n\\n  const svgBounds = svg.node().getBBox();\\n  const width = svgBounds.width + padding * 2;\\n  const height = svgBounds.height + padding * 2;\\n\\n  configureSvgSize(svg, height, width, conf.useMaxWidth);\\n\\n  svg.attr('viewBox', `${svgBounds.x - padding} ${svgBounds.y - padding} ${width} ${height}`);\\n\\n  addSVGAccessibilityFields(parser.yy, svg, id);\\n}; // draw\\n\\nexport default {\\n  setConf,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import { select } from 'd3';\\nimport utils from '../../utils';\\nimport * as configApi from '../../config';\\nimport common from '../common/common';\\nimport mermaidAPI from '../../mermaidAPI';\\nimport { log } from '../../logger';\\n\\nconst MERMAID_DOM_ID_PREFIX = 'flowchart-';\\nlet vertexCounter = 0;\\nlet config = configApi.getConfig();\\nlet vertices = {};\\nlet edges = [];\\nlet classes = [];\\nlet subGraphs = [];\\nlet subGraphLookup = {};\\nlet tooltips = {};\\nlet subCount = 0;\\nlet firstGraphFlag = true;\\nlet direction;\\n\\nlet version; // As in graph\\n\\n// Functions to be run after graph rendering\\nlet funs = [];\\n\\nexport const parseDirective = function (statement, context, type) {\\n  mermaidAPI.parseDirective(this, statement, context, type);\\n};\\n\\n/**\\n * Function to lookup domId from id in the graph definition.\\n *\\n * @param id\\n * @public\\n */\\nexport const lookUpDomId = function (id) {\\n  const veritceKeys = Object.keys(vertices);\\n  for (let i = 0; i &lt; veritceKeys.length; i++) {\\n    if (vertices[veritceKeys[i]].id === id) {\\n      return vertices[veritceKeys[i]].domId;\\n    }\\n  }\\n  return id;\\n};\\n\\n/**\\n * Function called by parser when a node definition has been found\\n *\\n * @param _id\\n * @param text\\n * @param type\\n * @param style\\n * @param classes\\n * @param dir\\n * @param props\\n */\\nexport const addVertex = function (_id, text, type, style, classes, dir, props = {}) {\\n  let txt;\\n  let id = _id;\\n  if (typeof id === 'undefined') {\\n    return;\\n  }\\n  if (id.trim().length === 0) {\\n    return;\\n  }\\n\\n  // if (id[0].match(/\\\\d/)) id = MERMAID_DOM_ID_PREFIX + id;\\n\\n  if (typeof vertices[id] === 'undefined') {\\n    vertices[id] = {\\n      id: id,\\n      domId: MERMAID_DOM_ID_PREFIX + id + '-' + vertexCounter,\\n      styles: [],\\n      classes: [],\\n    };\\n  }\\n  vertexCounter++;\\n  if (typeof text !== 'undefined') {\\n    config = configApi.getConfig();\\n    txt = common.sanitizeText(text.trim(), config);\\n\\n    // strip quotes if string starts and ends with a quote\\n    if (txt[0] === '\\\"' &amp;&amp; txt[txt.length - 1] === '\\\"') {\\n      txt = txt.substring(1, txt.length - 1);\\n    }\\n\\n    vertices[id].text = txt;\\n  } else {\\n    if (typeof vertices[id].text === 'undefined') {\\n      vertices[id].text = _id;\\n    }\\n  }\\n  if (typeof type !== 'undefined') {\\n    vertices[id].type = type;\\n  }\\n  if (typeof style !== 'undefined') {\\n    if (style !== null) {\\n      style.forEach(function (s) {\\n        vertices[id].styles.push(s);\\n      });\\n    }\\n  }\\n  if (typeof classes !== 'undefined') {\\n    if (classes !== null) {\\n      classes.forEach(function (s) {\\n        vertices[id].classes.push(s);\\n      });\\n    }\\n  }\\n  if (typeof dir !== 'undefined') {\\n    vertices[id].dir = dir;\\n  }\\n  vertices[id].props = props;\\n};\\n\\n/**\\n * Function called by parser when a link/edge definition has been found\\n *\\n * @param _start\\n * @param _end\\n * @param type\\n * @param linktext\\n */\\nexport const addSingleLink = function (_start, _end, type, linktext) {\\n  let start = _start;\\n  let end = _end;\\n  // if (start[0].match(/\\\\d/)) start = MERMAID_DOM_ID_PREFIX + start;\\n  // if (end[0].match(/\\\\d/)) end = MERMAID_DOM_ID_PREFIX + end;\\n  // log.info('Got edge...', start, end);\\n\\n  const edge = { start: start, end: end, type: undefined, text: '' };\\n  linktext = type.text;\\n\\n  if (typeof linktext !== 'undefined') {\\n    edge.text = common.sanitizeText(linktext.trim(), config);\\n\\n    // strip quotes if string starts and exnds with a quote\\n    if (edge.text[0] === '\\\"' &amp;&amp; edge.text[edge.text.length - 1] === '\\\"') {\\n      edge.text = edge.text.substring(1, edge.text.length - 1);\\n    }\\n  }\\n\\n  if (typeof type !== 'undefined') {\\n    edge.type = type.type;\\n    edge.stroke = type.stroke;\\n    edge.length = type.length;\\n  }\\n  edges.push(edge);\\n};\\nexport const addLink = function (_start, _end, type, linktext) {\\n  let i, j;\\n  for (i = 0; i &lt; _start.length; i++) {\\n    for (j = 0; j &lt; _end.length; j++) {\\n      addSingleLink(_start[i], _end[j], type, linktext);\\n    }\\n  }\\n};\\n\\n/**\\n * Updates a link's line interpolation algorithm\\n *\\n * @param positions\\n * @param interp\\n */\\nexport const updateLinkInterpolate = function (positions, interp) {\\n  positions.forEach(function (pos) {\\n    if (pos === 'default') {\\n      edges.defaultInterpolate = interp;\\n    } else {\\n      edges[pos].interpolate = interp;\\n    }\\n  });\\n};\\n\\n/**\\n * Updates a link with a style\\n *\\n * @param positions\\n * @param style\\n */\\nexport const updateLink = function (positions, style) {\\n  positions.forEach(function (pos) {\\n    if (pos === 'default') {\\n      edges.defaultStyle = style;\\n    } else {\\n      if (utils.isSubstringInArray('fill', style) === -1) {\\n        style.push('fill:none');\\n      }\\n      edges[pos].style = style;\\n    }\\n  });\\n};\\n\\nexport const addClass = function (id, style) {\\n  if (typeof classes[id] === 'undefined') {\\n    classes[id] = { id: id, styles: [], textStyles: [] };\\n  }\\n\\n  if (typeof style !== 'undefined') {\\n    if (style !== null) {\\n      style.forEach(function (s) {\\n        if (s.match('color')) {\\n          const newStyle1 = s.replace('fill', 'bgFill');\\n          const newStyle2 = newStyle1.replace('color', 'fill');\\n          classes[id].textStyles.push(newStyle2);\\n        }\\n        classes[id].styles.push(s);\\n      });\\n    }\\n  }\\n};\\n\\n/**\\n * Called by parser when a graph definition is found, stores the direction of the chart.\\n *\\n * @param dir\\n */\\nexport const setDirection = function (dir) {\\n  direction = dir;\\n  if (direction.match(/.*&lt;/)) {\\n    direction = 'RL';\\n  }\\n  if (direction.match(/.*\\\\^/)) {\\n    direction = 'BT';\\n  }\\n  if (direction.match(/.*&gt;/)) {\\n    direction = 'LR';\\n  }\\n  if (direction.match(/.*v/)) {\\n    direction = 'TB';\\n  }\\n};\\n\\n/**\\n * Called by parser when a special node is found, e.g. a clickable element.\\n *\\n * @param ids Comma separated list of ids\\n * @param className Class to add\\n */\\nexport const setClass = function (ids, className) {\\n  ids.split(',').forEach(function (_id) {\\n    // let id = version === 'gen-2' ? lookUpDomId(_id) : _id;\\n    let id = _id;\\n    // if (_id[0].match(/\\\\d/)) id = MERMAID_DOM_ID_PREFIX + id;\\n    if (typeof vertices[id] !== 'undefined') {\\n      vertices[id].classes.push(className);\\n    }\\n\\n    if (typeof subGraphLookup[id] !== 'undefined') {\\n      subGraphLookup[id].classes.push(className);\\n    }\\n  });\\n};\\n\\nconst setTooltip = function (ids, tooltip) {\\n  ids.split(',').forEach(function (id) {\\n    if (typeof tooltip !== 'undefined') {\\n      tooltips[version === 'gen-1' ? lookUpDomId(id) : id] = common.sanitizeText(tooltip, config);\\n    }\\n  });\\n};\\n\\nconst setClickFun = function (id, functionName, functionArgs) {\\n  let domId = lookUpDomId(id);\\n  // if (_id[0].match(/\\\\d/)) id = MERMAID_DOM_ID_PREFIX + id;\\n  if (configApi.getConfig().securityLevel !== 'loose') {\\n    return;\\n  }\\n  if (typeof functionName === 'undefined') {\\n    return;\\n  }\\n  let argList = [];\\n  if (typeof functionArgs === 'string') {\\n    /* Splits functionArgs by ',', ignoring all ',' in double quoted strings */\\n    argList = functionArgs.split(/,(?=(?:(?:[^\\\"]*\\\"){2})*[^\\\"]*$)/);\\n    for (let i = 0; i &lt; argList.length; i++) {\\n      let item = argList[i].trim();\\n      /* Removes all double quotes at the start and end of an argument */\\n      /* This preserves all starting and ending whitespace inside */\\n      if (item.charAt(0) === '\\\"' &amp;&amp; item.charAt(item.length - 1) === '\\\"') {\\n        item = item.substr(1, item.length - 2);\\n      }\\n      argList[i] = item;\\n    }\\n  }\\n\\n  /* if no arguments passed into callback, default to passing in id */\\n  if (argList.length === 0) {\\n    argList.push(id);\\n  }\\n\\n  if (typeof vertices[id] !== 'undefined') {\\n    vertices[id].haveCallback = true;\\n    funs.push(function () {\\n      const elem = document.querySelector(`[id=\\\"${domId}\\\"]`);\\n      if (elem !== null) {\\n        elem.addEventListener(\\n          'click',\\n          function () {\\n            utils.runFunc(functionName, ...argList);\\n          },\\n          false\\n        );\\n      }\\n    });\\n  }\\n};\\n\\n/**\\n * Called by parser when a link is found. Adds the URL to the vertex data.\\n *\\n * @param ids Comma separated list of ids\\n * @param linkStr URL to create a link for\\n * @param target\\n */\\nexport const setLink = function (ids, linkStr, target) {\\n  ids.split(',').forEach(function (id) {\\n    if (typeof vertices[id] !== 'undefined') {\\n      vertices[id].link = utils.formatUrl(linkStr, config);\\n      vertices[id].linkTarget = target;\\n    }\\n  });\\n  setClass(ids, 'clickable');\\n};\\nexport const getTooltip = function (id) {\\n  return tooltips[id];\\n};\\n\\n/**\\n * Called by parser when a click definition is found. Registers an event handler.\\n *\\n * @param ids Comma separated list of ids\\n * @param functionName Function to be called on click\\n * @param functionArgs\\n */\\nexport const setClickEvent = function (ids, functionName, functionArgs) {\\n  ids.split(',').forEach(function (id) {\\n    setClickFun(id, functionName, functionArgs);\\n  });\\n  setClass(ids, 'clickable');\\n};\\n\\nexport const bindFunctions = function (element) {\\n  funs.forEach(function (fun) {\\n    fun(element);\\n  });\\n};\\nexport const getDirection = function () {\\n  return direction.trim();\\n};\\n/**\\n * Retrieval function for fetching the found nodes after parsing has completed.\\n *\\n * @returns {{} | any | vertices}\\n */\\nexport const getVertices = function () {\\n  return vertices;\\n};\\n\\n/**\\n * Retrieval function for fetching the found links after parsing has completed.\\n *\\n * @returns {{} | any | edges}\\n */\\nexport const getEdges = function () {\\n  return edges;\\n};\\n\\n/**\\n * Retrieval function for fetching the found class definitions after parsing has completed.\\n *\\n * @returns {{} | any | classes}\\n */\\nexport const getClasses = function () {\\n  return classes;\\n};\\n\\nconst setupToolTips = function (element) {\\n  let tooltipElem = select('.mermaidTooltip');\\n  if ((tooltipElem._groups || tooltipElem)[0][0] === null) {\\n    tooltipElem = select('body').append('div').attr('class', 'mermaidTooltip').style('opacity', 0);\\n  }\\n\\n  const svg = select(element).select('svg');\\n\\n  const nodes = svg.selectAll('g.node');\\n  nodes\\n    .on('mouseover', function () {\\n      const el = select(this);\\n      const title = el.attr('title');\\n\\n      // Dont try to draw a tooltip if no data is provided\\n      if (title === null) {\\n        return;\\n      }\\n      const rect = this.getBoundingClientRect();\\n\\n      tooltipElem.transition().duration(200).style('opacity', '.9');\\n      tooltipElem\\n        .html(el.attr('title'))\\n        .style('left', window.scrollX + rect.left + (rect.right - rect.left) / 2 + 'px')\\n        .style('top', window.scrollY + rect.top - 14 + document.body.scrollTop + 'px');\\n      el.classed('hover', true);\\n    })\\n    .on('mouseout', function () {\\n      tooltipElem.transition().duration(500).style('opacity', 0);\\n      const el = select(this);\\n      el.classed('hover', false);\\n    });\\n};\\nfuns.push(setupToolTips);\\n\\n/**\\n * Clears the internal graph db so that a new graph can be parsed.\\n *\\n * @param ver\\n */\\nexport const clear = function (ver) {\\n  vertices = {};\\n  classes = {};\\n  edges = [];\\n  funs = [];\\n  funs.push(setupToolTips);\\n  subGraphs = [];\\n  subGraphLookup = {};\\n  subCount = 0;\\n  tooltips = [];\\n  firstGraphFlag = true;\\n  version = ver || 'gen-1';\\n};\\nexport const setGen = (ver) =&gt; {\\n  version = ver || 'gen-1';\\n};\\n/** @returns {string} */\\nexport const defaultStyle = function () {\\n  return 'fill:#ffa;stroke: #f66; stroke-width: 3px; stroke-dasharray: 5, 5;fill:#ffa;stroke: #666;';\\n};\\n\\n/**\\n * Clears the internal graph db so that a new graph can be parsed.\\n *\\n * @param _id\\n * @param list\\n * @param _title\\n */\\nexport const addSubGraph = function (_id, list, _title) {\\n  // console.log('addSubGraph', _id, list, _title);\\n  let id = _id.trim();\\n  let title = _title;\\n  if (_id === _title &amp;&amp; _title.match(/\\\\s/)) {\\n    id = undefined;\\n  }\\n  /** @param a */\\n  function uniq(a) {\\n    const prims = { boolean: {}, number: {}, string: {} };\\n    const objs = [];\\n\\n    let dir; //  = unbdefined; direction.trim();\\n    const nodeList = a.filter(function (item) {\\n      const type = typeof item;\\n      if (item.stmt &amp;&amp; item.stmt === 'dir') {\\n        dir = item.value;\\n        return false;\\n      }\\n      if (item.trim() === '') {\\n        return false;\\n      }\\n      if (type in prims) {\\n        return prims[type].hasOwnProperty(item) ? false : (prims[type][item] = true); // eslint-disable-line\\n      } else {\\n        return objs.indexOf(item) &gt;= 0 ? false : objs.push(item);\\n      }\\n    });\\n    return { nodeList, dir };\\n  }\\n\\n  let nodeList = [];\\n\\n  const { nodeList: nl, dir } = uniq(nodeList.concat.apply(nodeList, list));\\n  nodeList = nl;\\n  if (version === 'gen-1') {\\n    log.warn('LOOKING UP');\\n    for (let i = 0; i &lt; nodeList.length; i++) {\\n      nodeList[i] = lookUpDomId(nodeList[i]);\\n    }\\n  }\\n\\n  id = id || 'subGraph' + subCount;\\n  // if (id[0].match(/\\\\d/)) id = lookUpDomId(id);\\n  title = title || '';\\n  title = common.sanitizeText(title, config);\\n  subCount = subCount + 1;\\n  const subGraph = { id: id, nodes: nodeList, title: title.trim(), classes: [], dir };\\n\\n  log.info('Adding', subGraph.id, subGraph.nodes, subGraph.dir);\\n\\n  /** Deletes an id from all subgraphs */\\n  // const del = _id =&gt; {\\n  //   subGraphs.forEach(sg =&gt; {\\n  //     const pos = sg.nodes.indexOf(_id);\\n  //     if (pos &gt;= 0) {\\n  //       sg.nodes.splice(pos, 1);\\n  //     }\\n  //   });\\n  // };\\n\\n  // // Removes the members of this subgraph from any other subgraphs, a node only belong to one subgraph\\n  // subGraph.nodes.forEach(_id =&gt; del(_id));\\n\\n  // Remove the members in the new subgraph if they already belong to another subgraph\\n  subGraph.nodes = makeUniq(subGraph, subGraphs).nodes;\\n  subGraphs.push(subGraph);\\n  subGraphLookup[id] = subGraph;\\n  return id;\\n};\\n\\nconst getPosForId = function (id) {\\n  for (let i = 0; i &lt; subGraphs.length; i++) {\\n    if (subGraphs[i].id === id) {\\n      return i;\\n    }\\n  }\\n  return -1;\\n};\\nlet secCount = -1;\\nconst posCrossRef = [];\\nconst indexNodes2 = function (id, pos) {\\n  const nodes = subGraphs[pos].nodes;\\n  secCount = secCount + 1;\\n  if (secCount &gt; 2000) {\\n    return;\\n  }\\n  posCrossRef[secCount] = pos;\\n  // Check if match\\n  if (subGraphs[pos].id === id) {\\n    return {\\n      result: true,\\n      count: 0,\\n    };\\n  }\\n\\n  let count = 0;\\n  let posCount = 1;\\n  while (count &lt; nodes.length) {\\n    const childPos = getPosForId(nodes[count]);\\n    // Ignore regular nodes (pos will be -1)\\n    if (childPos &gt;= 0) {\\n      const res = indexNodes2(id, childPos);\\n      if (res.result) {\\n        return {\\n          result: true,\\n          count: posCount + res.count,\\n        };\\n      } else {\\n        posCount = posCount + res.count;\\n      }\\n    }\\n    count = count + 1;\\n  }\\n\\n  return {\\n    result: false,\\n    count: posCount,\\n  };\\n};\\n\\nexport const getDepthFirstPos = function (pos) {\\n  return posCrossRef[pos];\\n};\\nexport const indexNodes = function () {\\n  secCount = -1;\\n  if (subGraphs.length &gt; 0) {\\n    indexNodes2('none', subGraphs.length - 1, 0);\\n  }\\n};\\n\\nexport const getSubGraphs = function () {\\n  return subGraphs;\\n};\\n\\nexport const firstGraph = () =&gt; {\\n  if (firstGraphFlag) {\\n    firstGraphFlag = false;\\n    return true;\\n  }\\n  return false;\\n};\\n\\nconst destructStartLink = (_str) =&gt; {\\n  let str = _str.trim();\\n  let type = 'arrow_open';\\n\\n  switch (str[0]) {\\n    case '&lt;':\\n      type = 'arrow_point';\\n      str = str.slice(1);\\n      break;\\n    case 'x':\\n      type = 'arrow_cross';\\n      str = str.slice(1);\\n      break;\\n    case 'o':\\n      type = 'arrow_circle';\\n      str = str.slice(1);\\n      break;\\n  }\\n\\n  let stroke = 'normal';\\n\\n  if (str.indexOf('=') !== -1) {\\n    stroke = 'thick';\\n  }\\n\\n  if (str.indexOf('.') !== -1) {\\n    stroke = 'dotted';\\n  }\\n\\n  return { type, stroke };\\n};\\n\\nconst countChar = (char, str) =&gt; {\\n  const length = str.length;\\n  let count = 0;\\n  for (let i = 0; i &lt; length; ++i) {\\n    if (str[i] === char) {\\n      ++count;\\n    }\\n  }\\n  return count;\\n};\\n\\nconst destructEndLink = (_str) =&gt; {\\n  const str = _str.trim();\\n  let line = str.slice(0, -1);\\n  let type = 'arrow_open';\\n\\n  switch (str.slice(-1)) {\\n    case 'x':\\n      type = 'arrow_cross';\\n      if (str[0] === 'x') {\\n        type = 'double_' + type;\\n        line = line.slice(1);\\n      }\\n      break;\\n    case '&gt;':\\n      type = 'arrow_point';\\n      if (str[0] === '&lt;') {\\n        type = 'double_' + type;\\n        line = line.slice(1);\\n      }\\n      break;\\n    case 'o':\\n      type = 'arrow_circle';\\n      if (str[0] === 'o') {\\n        type = 'double_' + type;\\n        line = line.slice(1);\\n      }\\n      break;\\n  }\\n\\n  let stroke = 'normal';\\n  let length = line.length - 1;\\n\\n  if (line[0] === '=') {\\n    stroke = 'thick';\\n  }\\n\\n  let dots = countChar('.', line);\\n\\n  if (dots) {\\n    stroke = 'dotted';\\n    length = dots;\\n  }\\n\\n  return { type, stroke, length };\\n};\\n\\nconst destructLink = (_str, _startStr) =&gt; {\\n  const info = destructEndLink(_str);\\n  let startInfo;\\n  if (_startStr) {\\n    startInfo = destructStartLink(_startStr);\\n\\n    if (startInfo.stroke !== info.stroke) {\\n      return { type: 'INVALID', stroke: 'INVALID' };\\n    }\\n\\n    if (startInfo.type === 'arrow_open') {\\n      // -- xyz --&gt;  - take arrow type from ending\\n      startInfo.type = info.type;\\n    } else {\\n      // x-- xyz --&gt;  - not supported\\n      if (startInfo.type !== info.type) return { type: 'INVALID', stroke: 'INVALID' };\\n\\n      startInfo.type = 'double_' + startInfo.type;\\n    }\\n\\n    if (startInfo.type === 'double_arrow') {\\n      startInfo.type = 'double_arrow_point';\\n    }\\n\\n    startInfo.length = info.length;\\n    return startInfo;\\n  }\\n\\n  return info;\\n};\\n\\n// Todo optimizer this by caching existing nodes\\nconst exists = (allSgs, _id) =&gt; {\\n  let res = false;\\n  allSgs.forEach((sg) =&gt; {\\n    const pos = sg.nodes.indexOf(_id);\\n    if (pos &gt;= 0) {\\n      res = true;\\n    }\\n  });\\n  return res;\\n};\\n/**\\n * Deletes an id from all subgraphs\\n *\\n * @param sg\\n * @param allSubgraphs\\n */\\nconst makeUniq = (sg, allSubgraphs) =&gt; {\\n  const res = [];\\n  sg.nodes.forEach((_id, pos) =&gt; {\\n    if (!exists(allSubgraphs, _id)) {\\n      res.push(sg.nodes[pos]);\\n    }\\n  });\\n  return { nodes: res };\\n};\\n\\nexport default {\\n  parseDirective,\\n  defaultConfig: () =&gt; configApi.defaultConfig.flowchart,\\n  addVertex,\\n  lookUpDomId,\\n  addLink,\\n  updateLinkInterpolate,\\n  updateLink,\\n  addClass,\\n  setDirection,\\n  setClass,\\n  setTooltip,\\n  getTooltip,\\n  setClickEvent,\\n  setLink,\\n  bindFunctions,\\n  getDirection,\\n  getVertices,\\n  getEdges,\\n  getClasses,\\n  clear,\\n  setGen,\\n  defaultStyle,\\n  addSubGraph,\\n  getDepthFirstPos,\\n  indexNodes,\\n  getSubGraphs,\\n  destructLink,\\n  lex: {\\n    firstGraph,\\n  },\\n  exists,\\n  makeUniq,\\n};\\n\"</span>,<span class=\"code-string\">\"import dagreD3 from 'dagre-d3';\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction question(parent, bbox, node) {\\n  const w = bbox.width;\\n  const h = bbox.height;\\n  const s = (w + h) * 0.9;\\n  const points = [\\n    { x: s / 2, y: 0 },\\n    { x: s, y: -s / 2 },\\n    { x: s / 2, y: -s },\\n    { x: 0, y: -s / 2 },\\n  ];\\n  const shapeSvg = insertPolygonShape(parent, s, s, points);\\n  node.intersect = function (point) {\\n    return dagreD3.intersect.polygon(node, points, point);\\n  };\\n  return shapeSvg;\\n}\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction hexagon(parent, bbox, node) {\\n  const f = 4;\\n  const h = bbox.height;\\n  const m = h / f;\\n  const w = bbox.width + 2 * m;\\n  const points = [\\n    { x: m, y: 0 },\\n    { x: w - m, y: 0 },\\n    { x: w, y: -h / 2 },\\n    { x: w - m, y: -h },\\n    { x: m, y: -h },\\n    { x: 0, y: -h / 2 },\\n  ];\\n  const shapeSvg = insertPolygonShape(parent, w, h, points);\\n  node.intersect = function (point) {\\n    return dagreD3.intersect.polygon(node, points, point);\\n  };\\n  return shapeSvg;\\n}\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction rect_left_inv_arrow(parent, bbox, node) {\\n  const w = bbox.width;\\n  const h = bbox.height;\\n  const points = [\\n    { x: -h / 2, y: 0 },\\n    { x: w, y: 0 },\\n    { x: w, y: -h },\\n    { x: -h / 2, y: -h },\\n    { x: 0, y: -h / 2 },\\n  ];\\n  const shapeSvg = insertPolygonShape(parent, w, h, points);\\n  node.intersect = function (point) {\\n    return dagreD3.intersect.polygon(node, points, point);\\n  };\\n  return shapeSvg;\\n}\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction lean_right(parent, bbox, node) {\\n  const w = bbox.width;\\n  const h = bbox.height;\\n  const points = [\\n    { x: (-2 * h) / 6, y: 0 },\\n    { x: w - h / 6, y: 0 },\\n    { x: w + (2 * h) / 6, y: -h },\\n    { x: h / 6, y: -h },\\n  ];\\n  const shapeSvg = insertPolygonShape(parent, w, h, points);\\n  node.intersect = function (point) {\\n    return dagreD3.intersect.polygon(node, points, point);\\n  };\\n  return shapeSvg;\\n}\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction lean_left(parent, bbox, node) {\\n  const w = bbox.width;\\n  const h = bbox.height;\\n  const points = [\\n    { x: (2 * h) / 6, y: 0 },\\n    { x: w + h / 6, y: 0 },\\n    { x: w - (2 * h) / 6, y: -h },\\n    { x: -h / 6, y: -h },\\n  ];\\n  const shapeSvg = insertPolygonShape(parent, w, h, points);\\n  node.intersect = function (point) {\\n    return dagreD3.intersect.polygon(node, points, point);\\n  };\\n  return shapeSvg;\\n}\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction trapezoid(parent, bbox, node) {\\n  const w = bbox.width;\\n  const h = bbox.height;\\n  const points = [\\n    { x: (-2 * h) / 6, y: 0 },\\n    { x: w + (2 * h) / 6, y: 0 },\\n    { x: w - h / 6, y: -h },\\n    { x: h / 6, y: -h },\\n  ];\\n  const shapeSvg = insertPolygonShape(parent, w, h, points);\\n  node.intersect = function (point) {\\n    return dagreD3.intersect.polygon(node, points, point);\\n  };\\n  return shapeSvg;\\n}\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction inv_trapezoid(parent, bbox, node) {\\n  const w = bbox.width;\\n  const h = bbox.height;\\n  const points = [\\n    { x: h / 6, y: 0 },\\n    { x: w - h / 6, y: 0 },\\n    { x: w + (2 * h) / 6, y: -h },\\n    { x: (-2 * h) / 6, y: -h },\\n  ];\\n  const shapeSvg = insertPolygonShape(parent, w, h, points);\\n  node.intersect = function (point) {\\n    return dagreD3.intersect.polygon(node, points, point);\\n  };\\n  return shapeSvg;\\n}\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction rect_right_inv_arrow(parent, bbox, node) {\\n  const w = bbox.width;\\n  const h = bbox.height;\\n  const points = [\\n    { x: 0, y: 0 },\\n    { x: w + h / 2, y: 0 },\\n    { x: w, y: -h / 2 },\\n    { x: w + h / 2, y: -h },\\n    { x: 0, y: -h },\\n  ];\\n  const shapeSvg = insertPolygonShape(parent, w, h, points);\\n  node.intersect = function (point) {\\n    return dagreD3.intersect.polygon(node, points, point);\\n  };\\n  return shapeSvg;\\n}\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction stadium(parent, bbox, node) {\\n  const h = bbox.height;\\n  const w = bbox.width + h / 4;\\n\\n  const shapeSvg = parent\\n    .insert('rect', ':first-child')\\n    .attr('rx', h / 2)\\n    .attr('ry', h / 2)\\n    .attr('x', -w / 2)\\n    .attr('y', -h / 2)\\n    .attr('width', w)\\n    .attr('height', h);\\n\\n  node.intersect = function (point) {\\n    return dagreD3.intersect.rect(node, point);\\n  };\\n  return shapeSvg;\\n}\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction subroutine(parent, bbox, node) {\\n  const w = bbox.width;\\n  const h = bbox.height;\\n  const points = [\\n    { x: 0, y: 0 },\\n    { x: w, y: 0 },\\n    { x: w, y: -h },\\n    { x: 0, y: -h },\\n    { x: 0, y: 0 },\\n    { x: -8, y: 0 },\\n    { x: w + 8, y: 0 },\\n    { x: w + 8, y: -h },\\n    { x: -8, y: -h },\\n    { x: -8, y: 0 },\\n  ];\\n  const shapeSvg = insertPolygonShape(parent, w, h, points);\\n  node.intersect = function (point) {\\n    return dagreD3.intersect.polygon(node, points, point);\\n  };\\n  return shapeSvg;\\n}\\n\\n/**\\n * @param parent\\n * @param bbox\\n * @param node\\n */\\nfunction cylinder(parent, bbox, node) {\\n  const w = bbox.width;\\n  const rx = w / 2;\\n  const ry = rx / (2.5 + w / 50);\\n  const h = bbox.height + ry;\\n\\n  const shape =\\n    'M 0,' +\\n    ry +\\n    ' a ' +\\n    rx +\\n    ',' +\\n    ry +\\n    ' 0,0,0 ' +\\n    w +\\n    ' 0 a ' +\\n    rx +\\n    ',' +\\n    ry +\\n    ' 0,0,0 ' +\\n    -w +\\n    ' 0 l 0,' +\\n    h +\\n    ' a ' +\\n    rx +\\n    ',' +\\n    ry +\\n    ' 0,0,0 ' +\\n    w +\\n    ' 0 l 0,' +\\n    -h;\\n\\n  const shapeSvg = parent\\n    .attr('label-offset-y', ry)\\n    .insert('path', ':first-child')\\n    .attr('d', shape)\\n    .attr('transform', 'translate(' + -w / 2 + ',' + -(h / 2 + ry) + ')');\\n\\n  node.intersect = function (point) {\\n    const pos = dagreD3.intersect.rect(node, point);\\n    const x = pos.x - node.x;\\n\\n    if (\\n      rx != 0 &amp;&amp;\\n      (Math.abs(x) &lt; node.width / 2 ||\\n        (Math.abs(x) == node.width / 2 &amp;&amp; Math.abs(pos.y - node.y) &gt; node.height / 2 - ry))\\n    ) {\\n      // ellipsis equation: x*x / a*a + y*y / b*b = 1\\n      // solve for y to get adjustion value for pos.y\\n      let y = ry * ry * (1 - (x * x) / (rx * rx));\\n      if (y != 0) y = Math.sqrt(y);\\n      y = ry - y;\\n      if (point.y - node.y &gt; 0) y = -y;\\n\\n      pos.y += y;\\n    }\\n\\n    return pos;\\n  };\\n\\n  return shapeSvg;\\n}\\n\\n/** @param render */\\nexport function addToRender(render) {\\n  render.shapes().question = question;\\n  render.shapes().hexagon = hexagon;\\n  render.shapes().stadium = stadium;\\n  render.shapes().subroutine = subroutine;\\n  render.shapes().cylinder = cylinder;\\n\\n  // Add custom shape for box with inverted arrow on left side\\n  render.shapes().rect_left_inv_arrow = rect_left_inv_arrow;\\n\\n  // Add custom shape for box with inverted arrow on left side\\n  render.shapes().lean_right = lean_right;\\n\\n  // Add custom shape for box with inverted arrow on left side\\n  render.shapes().lean_left = lean_left;\\n\\n  // Add custom shape for box with inverted arrow on left side\\n  render.shapes().trapezoid = trapezoid;\\n\\n  // Add custom shape for box with inverted arrow on left side\\n  render.shapes().inv_trapezoid = inv_trapezoid;\\n\\n  // Add custom shape for box with inverted arrow on right side\\n  render.shapes().rect_right_inv_arrow = rect_right_inv_arrow;\\n}\\n\\n/** @param addShape */\\nexport function addToRenderV2(addShape) {\\n  addShape({ question });\\n  addShape({ hexagon });\\n  addShape({ stadium });\\n  addShape({ subroutine });\\n  addShape({ cylinder });\\n\\n  // Add custom shape for box with inverted arrow on left side\\n  addShape({ rect_left_inv_arrow });\\n\\n  // Add custom shape for box with inverted arrow on left side\\n  addShape({ lean_right });\\n\\n  // Add custom shape for box with inverted arrow on left side\\n  addShape({ lean_left });\\n\\n  // Add custom shape for box with inverted arrow on left side\\n  addShape({ trapezoid });\\n\\n  // Add custom shape for box with inverted arrow on left side\\n  addShape({ inv_trapezoid });\\n\\n  // Add custom shape for box with inverted arrow on right side\\n  addShape({ rect_right_inv_arrow });\\n}\\n\\n/**\\n * @param parent\\n * @param w\\n * @param h\\n * @param points\\n */\\nfunction insertPolygonShape(parent, w, h, points) {\\n  return parent\\n    .insert('polygon', ':first-child')\\n    .attr(\\n      'points',\\n      points\\n        .map(function (d) {\\n          return d.x + ',' + d.y;\\n        })\\n        .join(' ')\\n    )\\n    .attr('transform', 'translate(' + -w / 2 + ',' + h / 2 + ')');\\n}\\n\\nexport default {\\n  addToRender,\\n  addToRenderV2,\\n};\\n\"</span>,<span class=\"code-string\">\"import graphlib from 'graphlib';\\nimport { select, curveLinear, selectAll } from 'd3';\\n\\nimport flowDb from './flowDb';\\nimport flow from './parser/flow';\\nimport { getConfig } from '../../config';\\n\\nimport dagreD3 from 'dagre-d3';\\nimport addHtmlLabel from 'dagre-d3/lib/label/add-html-label.js';\\nimport { log } from '../../logger';\\nimport common, { evaluate } from '../common/common';\\nimport { interpolateToCurve, getStylesFromArray, configureSvgSize } from '../../utils';\\nimport flowChartShapes from './flowChartShapes';\\n\\nconst conf = {};\\nexport const setConf = function (cnf) {\\n  const keys = Object.keys(cnf);\\n  for (let i = 0; i &lt; keys.length; i++) {\\n    conf[keys[i]] = cnf[keys[i]];\\n  }\\n};\\n\\n/**\\n * Function that adds the vertices found in the graph definition to the graph to be rendered.\\n *\\n * @param vert Object containing the vertices.\\n * @param g The graph that is to be drawn.\\n * @param svgId\\n * @param root\\n * @param doc\\n * @param _doc\\n */\\nexport const addVertices = function (vert, g, svgId, root, _doc) {\\n  const securityLevel = getConfig().securityLevel;\\n\\n  const svg = !root ? select(`[id=\\\"${svgId}\\\"]`) : root.select(`[id=\\\"${svgId}\\\"]`);\\n  const doc = !_doc ? document : _doc;\\n  const keys = Object.keys(vert);\\n\\n  // Iterate through each item in the vertex object (containing all the vertices found) in the graph definition\\n  keys.forEach(function (id) {\\n    const vertex = vert[id];\\n\\n    /**\\n     * Variable for storing the classes for the vertex\\n     *\\n     * @type {string}\\n     */\\n    let classStr = 'default';\\n    if (vertex.classes.length &gt; 0) {\\n      classStr = vertex.classes.join(' ');\\n    }\\n\\n    const styles = getStylesFromArray(vertex.styles);\\n\\n    // Use vertex id as text in the box if no text is provided by the graph definition\\n    let vertexText = vertex.text !== undefined ? vertex.text : vertex.id;\\n\\n    // We create a SVG label, either by delegating to addHtmlLabel or manually\\n    let vertexNode;\\n    if (evaluate(getConfig().flowchart.htmlLabels)) {\\n      // TODO: addHtmlLabel accepts a labelStyle. Do we possibly have that?\\n      const node = {\\n        label: vertexText.replace(\\n          /fa[lrsb]?:fa-[\\\\w-]+/g,\\n          (s) =&gt; `&lt;i class='${s.replace(':', ' ')}'&gt;&lt;/i&gt;`\\n        ),\\n      };\\n      vertexNode = addHtmlLabel(svg, node).node();\\n      vertexNode.parentNode.removeChild(vertexNode);\\n    } else {\\n      const svgLabel = doc.createElementNS('http://www.w3.org/2000/svg', 'text');\\n      svgLabel.setAttribute('style', styles.labelStyle.replace('color:', 'fill:'));\\n\\n      const rows = vertexText.split(common.lineBreakRegex);\\n\\n      for (let j = 0; j &lt; rows.length; j++) {\\n        const tspan = doc.createElementNS('http://www.w3.org/2000/svg', 'tspan');\\n        tspan.setAttributeNS('http://www.w3.org/XML/1998/namespace', 'xml:space', 'preserve');\\n        tspan.setAttribute('dy', '1em');\\n        tspan.setAttribute('x', '1');\\n        tspan.textContent = rows[j];\\n        svgLabel.appendChild(tspan);\\n      }\\n      vertexNode = svgLabel;\\n    }\\n\\n    let radious = 0;\\n    let _shape = '';\\n    // Set the shape based parameters\\n    switch (vertex.type) {\\n      case 'round':\\n        radious = 5;\\n        _shape = 'rect';\\n        break;\\n      case 'square':\\n        _shape = 'rect';\\n        break;\\n      case 'diamond':\\n        _shape = 'question';\\n        break;\\n      case 'hexagon':\\n        _shape = 'hexagon';\\n        break;\\n      case 'odd':\\n        _shape = 'rect_left_inv_arrow';\\n        break;\\n      case 'lean_right':\\n        _shape = 'lean_right';\\n        break;\\n      case 'lean_left':\\n        _shape = 'lean_left';\\n        break;\\n      case 'trapezoid':\\n        _shape = 'trapezoid';\\n        break;\\n      case 'inv_trapezoid':\\n        _shape = 'inv_trapezoid';\\n        break;\\n      case 'odd_right':\\n        _shape = 'rect_left_inv_arrow';\\n        break;\\n      case 'circle':\\n        _shape = 'circle';\\n        break;\\n      case 'ellipse':\\n        _shape = 'ellipse';\\n        break;\\n      case 'stadium':\\n        _shape = 'stadium';\\n        break;\\n      case 'subroutine':\\n        _shape = 'subroutine';\\n        break;\\n      case 'cylinder':\\n        _shape = 'cylinder';\\n        break;\\n      case 'group':\\n        _shape = 'rect';\\n        break;\\n      default:\\n        _shape = 'rect';\\n    }\\n    // Add the node\\n    log.warn('Adding node', vertex.id, vertex.domId);\\n    g.setNode(flowDb.lookUpDomId(vertex.id), {\\n      labelType: 'svg',\\n      labelStyle: styles.labelStyle,\\n      shape: _shape,\\n      label: vertexNode,\\n      rx: radious,\\n      ry: radious,\\n      class: classStr,\\n      style: styles.style,\\n      id: flowDb.lookUpDomId(vertex.id),\\n    });\\n  });\\n};\\n\\n/**\\n * Add edges to graph based on parsed graph defninition\\n *\\n * @param {object} edges The edges to add to the graph\\n * @param {object} g The graph object\\n */\\nexport const addEdges = function (edges, g) {\\n  let cnt = 0;\\n\\n  let defaultStyle;\\n  let defaultLabelStyle;\\n\\n  if (typeof edges.defaultStyle !== 'undefined') {\\n    const defaultStyles = getStylesFromArray(edges.defaultStyle);\\n    defaultStyle = defaultStyles.style;\\n    defaultLabelStyle = defaultStyles.labelStyle;\\n  }\\n\\n  edges.forEach(function (edge) {\\n    cnt++;\\n\\n    // Identify Link\\n    var linkId = 'L-' + edge.start + '-' + edge.end;\\n    var linkNameStart = 'LS-' + edge.start;\\n    var linkNameEnd = 'LE-' + edge.end;\\n\\n    const edgeData = {};\\n\\n    // Set link type for rendering\\n    if (edge.type === 'arrow_open') {\\n      edgeData.arrowhead = 'none';\\n    } else {\\n      edgeData.arrowhead = 'normal';\\n    }\\n\\n    let style = '';\\n    let labelStyle = '';\\n\\n    if (typeof edge.style !== 'undefined') {\\n      const styles = getStylesFromArray(edge.style);\\n      style = styles.style;\\n      labelStyle = styles.labelStyle;\\n    } else {\\n      switch (edge.stroke) {\\n        case 'normal':\\n          style = 'fill:none';\\n          if (typeof defaultStyle !== 'undefined') {\\n            style = defaultStyle;\\n          }\\n          if (typeof defaultLabelStyle !== 'undefined') {\\n            labelStyle = defaultLabelStyle;\\n          }\\n          break;\\n        case 'dotted':\\n          style = 'fill:none;stroke-width:2px;stroke-dasharray:3;';\\n          break;\\n        case 'thick':\\n          style = ' stroke-width: 3.5px;fill:none';\\n          break;\\n      }\\n    }\\n\\n    edgeData.style = style;\\n    edgeData.labelStyle = labelStyle;\\n\\n    if (typeof edge.interpolate !== 'undefined') {\\n      edgeData.curve = interpolateToCurve(edge.interpolate, curveLinear);\\n    } else if (typeof edges.defaultInterpolate !== 'undefined') {\\n      edgeData.curve = interpolateToCurve(edges.defaultInterpolate, curveLinear);\\n    } else {\\n      edgeData.curve = interpolateToCurve(conf.curve, curveLinear);\\n    }\\n\\n    if (typeof edge.text === 'undefined') {\\n      if (typeof edge.style !== 'undefined') {\\n        edgeData.arrowheadStyle = 'fill: #333';\\n      }\\n    } else {\\n      edgeData.arrowheadStyle = 'fill: #333';\\n      edgeData.labelpos = 'c';\\n\\n      if (evaluate(getConfig().flowchart.htmlLabels)) {\\n        edgeData.labelType = 'html';\\n        edgeData.label = `&lt;span id=\\\"L-${linkId}\\\" class=\\\"edgeLabel L-${linkNameStart}' L-${linkNameEnd}\\\"&gt;${edge.text.replace(\\n          /fa[lrsb]?:fa-[\\\\w-]+/g,\\n          (s) =&gt; `&lt;i class='${s.replace(':', ' ')}'&gt;&lt;/i&gt;`\\n        )}&lt;/span&gt;`;\\n      } else {\\n        edgeData.labelType = 'text';\\n        edgeData.label = edge.text.replace(common.lineBreakRegex, '\\\\n');\\n\\n        if (typeof edge.style === 'undefined') {\\n          edgeData.style = edgeData.style || 'stroke: #333; stroke-width: 1.5px;fill:none';\\n        }\\n\\n        edgeData.labelStyle = edgeData.labelStyle.replace('color:', 'fill:');\\n      }\\n    }\\n\\n    edgeData.id = linkId;\\n    edgeData.class = linkNameStart + ' ' + linkNameEnd;\\n    edgeData.minlen = edge.length || 1;\\n\\n    // Add the edge to the graph\\n    g.setEdge(flowDb.lookUpDomId(edge.start), flowDb.lookUpDomId(edge.end), edgeData, cnt);\\n  });\\n};\\n\\n/**\\n * Returns the all the styles from classDef statements in the graph definition.\\n *\\n * @param text\\n * @returns {object} ClassDef styles\\n */\\nexport const getClasses = function (text) {\\n  log.info('Extracting classes');\\n  flowDb.clear();\\n  try {\\n    const parser = flow.parser;\\n    parser.yy = flowDb;\\n\\n    // Parse the graph definition\\n    parser.parse(text);\\n    return flowDb.getClasses();\\n  } catch (e) {\\n    return;\\n  }\\n};\\n\\n/**\\n * Draws a flowchart in the tag with id: id based on the graph definition in text.\\n *\\n * @param text\\n * @param id\\n */\\nexport const draw = function (text, id) {\\n  log.info('Drawing flowchart');\\n  flowDb.clear();\\n  flowDb.setGen('gen-1');\\n  const parser = flow.parser;\\n  parser.yy = flowDb;\\n\\n  const securityLevel = getConfig().securityLevel;\\n  let sandboxElement;\\n  if (securityLevel === 'sandbox') {\\n    sandboxElement = select('#i' + id);\\n  }\\n  const root =\\n    securityLevel === 'sandbox'\\n      ? select(sandboxElement.nodes()[0].contentDocument.body)\\n      : select('body');\\n  const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n\\n  // Parse the graph definition\\n  // try {\\n  parser.parse(text);\\n  // } catch (err) {\\n  // log.debug('Parsing failed');\\n  // }\\n\\n  // Fetch the default direction, use TD if none was found\\n  let dir = flowDb.getDirection();\\n  if (typeof dir === 'undefined') {\\n    dir = 'TD';\\n  }\\n\\n  const conf = getConfig().flowchart;\\n  const nodeSpacing = conf.nodeSpacing || 50;\\n  const rankSpacing = conf.rankSpacing || 50;\\n\\n  // Create the input mermaid.graph\\n  const g = new graphlib.Graph({\\n    multigraph: true,\\n    compound: true,\\n  })\\n    .setGraph({\\n      rankdir: dir,\\n      nodesep: nodeSpacing,\\n      ranksep: rankSpacing,\\n      marginx: 8,\\n      marginy: 8,\\n    })\\n    .setDefaultEdgeLabel(function () {\\n      return {};\\n    });\\n\\n  let subG;\\n  const subGraphs = flowDb.getSubGraphs();\\n  for (let i = subGraphs.length - 1; i &gt;= 0; i--) {\\n    subG = subGraphs[i];\\n    flowDb.addVertex(subG.id, subG.title, 'group', undefined, subG.classes);\\n  }\\n\\n  // Fetch the verices/nodes and edges/links from the parsed graph definition\\n  const vert = flowDb.getVertices();\\n  log.warn('Get vertices', vert);\\n\\n  const edges = flowDb.getEdges();\\n\\n  let i = 0;\\n  for (i = subGraphs.length - 1; i &gt;= 0; i--) {\\n    subG = subGraphs[i];\\n\\n    selectAll('cluster').append('text');\\n\\n    for (let j = 0; j &lt; subG.nodes.length; j++) {\\n      log.warn(\\n        'Setting subgraph',\\n        subG.nodes[j],\\n        flowDb.lookUpDomId(subG.nodes[j]),\\n        flowDb.lookUpDomId(subG.id)\\n      );\\n      g.setParent(flowDb.lookUpDomId(subG.nodes[j]), flowDb.lookUpDomId(subG.id));\\n    }\\n  }\\n  addVertices(vert, g, id, root, doc);\\n  addEdges(edges, g);\\n\\n  // Create the renderer\\n  const Render = dagreD3.render;\\n  const render = new Render();\\n\\n  // Add custom shapes\\n  flowChartShapes.addToRender(render);\\n\\n  // Add our custom arrow - an empty arrowhead\\n  render.arrows().none = function normal(parent, id, edge, type) {\\n    const marker = parent\\n      .append('marker')\\n      .attr('id', id)\\n      .attr('viewBox', '0 0 10 10')\\n      .attr('refX', 9)\\n      .attr('refY', 5)\\n      .attr('markerUnits', 'strokeWidth')\\n      .attr('markerWidth', 8)\\n      .attr('markerHeight', 6)\\n      .attr('orient', 'auto');\\n\\n    const path = marker.append('path').attr('d', 'M 0 0 L 0 0 L 0 0 z');\\n    dagreD3.util.applyStyle(path, edge[type + 'Style']);\\n  };\\n\\n  // Override normal arrowhead defined in d3. Remove style &amp; add class to allow css styling.\\n  render.arrows().normal = function normal(parent, id) {\\n    const marker = parent\\n      .append('marker')\\n      .attr('id', id)\\n      .attr('viewBox', '0 0 10 10')\\n      .attr('refX', 9)\\n      .attr('refY', 5)\\n      .attr('markerUnits', 'strokeWidth')\\n      .attr('markerWidth', 8)\\n      .attr('markerHeight', 6)\\n      .attr('orient', 'auto');\\n\\n    marker\\n      .append('path')\\n      .attr('d', 'M 0 0 L 10 5 L 0 10 z')\\n      .attr('class', 'arrowheadPath')\\n      .style('stroke-width', 1)\\n      .style('stroke-dasharray', '1,0');\\n  };\\n\\n  // Set up an SVG group so that we can translate the final graph.\\n  const svg = root.select(`[id=\\\"${id}\\\"]`);\\n  svg.attr('xmlns:xlink', 'http://www.w3.org/1999/xlink');\\n\\n  log.warn(g);\\n\\n  // Run the renderer. This is what draws the final graph.\\n  const element = root.select('#' + id + ' g');\\n  render(element, g);\\n\\n  element.selectAll('g.node').attr('title', function () {\\n    return flowDb.getTooltip(this.id);\\n  });\\n\\n  const padding = conf.diagramPadding;\\n  const svgBounds = svg.node().getBBox();\\n  const width = svgBounds.width + padding * 2;\\n  const height = svgBounds.height + padding * 2;\\n\\n  configureSvgSize(svg, height, width, conf.useMaxWidth);\\n\\n  // Ensure the viewBox includes the whole svgBounds area with extra space for padding\\n  const vBox = `${svgBounds.x - padding} ${svgBounds.y - padding} ${width} ${height}`;\\n  log.debug(`viewBox ${vBox}`);\\n  svg.attr('viewBox', vBox);\\n\\n  // Index nodes\\n  flowDb.indexNodes('subGraph' + i);\\n\\n  // reposition labels\\n  for (i = 0; i &lt; subGraphs.length; i++) {\\n    subG = subGraphs[i];\\n    if (subG.title !== 'undefined') {\\n      const clusterRects = doc.querySelectorAll(\\n        '#' + id + ' [id=\\\"' + flowDb.lookUpDomId(subG.id) + '\\\"] rect'\\n      );\\n      const clusterEl = doc.querySelectorAll(\\n        '#' + id + ' [id=\\\"' + flowDb.lookUpDomId(subG.id) + '\\\"]'\\n      );\\n\\n      const xPos = clusterRects[0].x.baseVal.value;\\n      const yPos = clusterRects[0].y.baseVal.value;\\n      const width = clusterRects[0].width.baseVal.value;\\n      const cluster = select(clusterEl[0]);\\n      const te = cluster.select('.label');\\n      te.attr('transform', `translate(${xPos + width / 2}, ${yPos + 14})`);\\n      te.attr('id', id + 'Text');\\n\\n      for (let j = 0; j &lt; subG.classes.length; j++) {\\n        clusterEl[0].classList.add(subG.classes[j]);\\n      }\\n    }\\n  }\\n\\n  // Add label rects for non html labels\\n  if (!evaluate(conf.htmlLabels) || true) { // eslint-disable-line\\n    const labels = doc.querySelectorAll('[id=\\\"' + id + '\\\"] .edgeLabel .label');\\n    for (let k = 0; k &lt; labels.length; k++) {\\n      const label = labels[k];\\n\\n      // Get dimensions of label\\n      const dim = label.getBBox();\\n\\n      const rect = doc.createElementNS('http://www.w3.org/2000/svg', 'rect');\\n      rect.setAttribute('rx', 0);\\n      rect.setAttribute('ry', 0);\\n      rect.setAttribute('width', dim.width);\\n      rect.setAttribute('height', dim.height);\\n      // rect.setAttribute('style', 'fill:#e8e8e8;');\\n\\n      label.insertBefore(rect, label.firstChild);\\n    }\\n  }\\n\\n  // If node has a link, wrap it in an anchor SVG object.\\n  const keys = Object.keys(vert);\\n  keys.forEach(function (key) {\\n    const vertex = vert[key];\\n\\n    if (vertex.link) {\\n      const node = root.select('#' + id + ' [id=\\\"' + flowDb.lookUpDomId(key) + '\\\"]');\\n      if (node) {\\n        const link = doc.createElementNS('http://www.w3.org/2000/svg', 'a');\\n        link.setAttributeNS('http://www.w3.org/2000/svg', 'class', vertex.classes.join(' '));\\n        link.setAttributeNS('http://www.w3.org/2000/svg', 'href', vertex.link);\\n        link.setAttributeNS('http://www.w3.org/2000/svg', 'rel', 'noopener');\\n        if (securityLevel === 'sandbox') {\\n          link.setAttributeNS('http://www.w3.org/2000/svg', 'target', '_top');\\n        } else if (vertex.linkTarget) {\\n          link.setAttributeNS('http://www.w3.org/2000/svg', 'target', vertex.linkTarget);\\n        }\\n\\n        const linkNode = node.insert(function () {\\n          return link;\\n        }, ':first-child');\\n\\n        const shape = node.select('.label-container');\\n        if (shape) {\\n          linkNode.append(function () {\\n            return shape.node();\\n          });\\n        }\\n\\n        const label = node.select('.label');\\n        if (label) {\\n          linkNode.append(function () {\\n            return label.node();\\n          });\\n        }\\n      }\\n    }\\n  });\\n};\\n\\nexport default {\\n  setConf,\\n  addVertices,\\n  addEdges,\\n  getClasses,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import graphlib from 'graphlib';\\nimport { select, curveLinear, selectAll } from 'd3';\\n\\nimport flowDb from './flowDb';\\nimport flow from './parser/flow';\\nimport { getConfig } from '../../config';\\n\\nimport { render } from '../../dagre-wrapper/index.js';\\nimport addHtmlLabel from 'dagre-d3/lib/label/add-html-label.js';\\nimport { log } from '../../logger';\\nimport common, { evaluate } from '../common/common';\\nimport { interpolateToCurve, getStylesFromArray, configureSvgSize } from '../../utils';\\n\\nconst conf = {};\\nexport const setConf = function (cnf) {\\n  const keys = Object.keys(cnf);\\n  for (let i = 0; i &lt; keys.length; i++) {\\n    conf[keys[i]] = cnf[keys[i]];\\n  }\\n};\\n\\n/**\\n * Function that adds the vertices found during parsing to the graph to be rendered.\\n *\\n * @param vert Object containing the vertices.\\n * @param g The graph that is to be drawn.\\n * @param svgId\\n * @param root\\n * @param doc\\n */\\nexport const addVertices = function (vert, g, svgId, root, doc) {\\n  const svg = root.select(`[id=\\\"${svgId}\\\"]`);\\n  const keys = Object.keys(vert);\\n\\n  // Iterate through each item in the vertex object (containing all the vertices found) in the graph definition\\n  keys.forEach(function (id) {\\n    const vertex = vert[id];\\n\\n    /**\\n     * Variable for storing the classes for the vertex\\n     *\\n     * @type {string}\\n     */\\n    let classStr = 'default';\\n    if (vertex.classes.length &gt; 0) {\\n      classStr = vertex.classes.join(' ');\\n    }\\n\\n    const styles = getStylesFromArray(vertex.styles);\\n\\n    // Use vertex id as text in the box if no text is provided by the graph definition\\n    let vertexText = vertex.text !== undefined ? vertex.text : vertex.id;\\n\\n    // We create a SVG label, either by delegating to addHtmlLabel or manually\\n    let vertexNode;\\n    if (evaluate(getConfig().flowchart.htmlLabels)) {\\n      // TODO: addHtmlLabel accepts a labelStyle. Do we possibly have that?\\n      const node = {\\n        label: vertexText.replace(\\n          /fa[lrsb]?:fa-[\\\\w-]+/g,\\n          (s) =&gt; `&lt;i class='${s.replace(':', ' ')}'&gt;&lt;/i&gt;`\\n        ),\\n      };\\n      vertexNode = addHtmlLabel(svg, node).node();\\n      vertexNode.parentNode.removeChild(vertexNode);\\n    } else {\\n      const svgLabel = doc.createElementNS('http://www.w3.org/2000/svg', 'text');\\n      svgLabel.setAttribute('style', styles.labelStyle.replace('color:', 'fill:'));\\n\\n      const rows = vertexText.split(common.lineBreakRegex);\\n\\n      for (let j = 0; j &lt; rows.length; j++) {\\n        const tspan = doc.createElementNS('http://www.w3.org/2000/svg', 'tspan');\\n        tspan.setAttributeNS('http://www.w3.org/XML/1998/namespace', 'xml:space', 'preserve');\\n        tspan.setAttribute('dy', '1em');\\n        tspan.setAttribute('x', '1');\\n        tspan.textContent = rows[j];\\n        svgLabel.appendChild(tspan);\\n      }\\n      vertexNode = svgLabel;\\n    }\\n\\n    let radious = 0;\\n    let _shape = '';\\n    // Set the shape based parameters\\n    switch (vertex.type) {\\n      case 'round':\\n        radious = 5;\\n        _shape = 'rect';\\n        break;\\n      case 'square':\\n        _shape = 'rect';\\n        break;\\n      case 'diamond':\\n        _shape = 'question';\\n        break;\\n      case 'hexagon':\\n        _shape = 'hexagon';\\n        break;\\n      case 'odd':\\n        _shape = 'rect_left_inv_arrow';\\n        break;\\n      case 'lean_right':\\n        _shape = 'lean_right';\\n        break;\\n      case 'lean_left':\\n        _shape = 'lean_left';\\n        break;\\n      case 'trapezoid':\\n        _shape = 'trapezoid';\\n        break;\\n      case 'inv_trapezoid':\\n        _shape = 'inv_trapezoid';\\n        break;\\n      case 'odd_right':\\n        _shape = 'rect_left_inv_arrow';\\n        break;\\n      case 'circle':\\n        _shape = 'circle';\\n        break;\\n      case 'ellipse':\\n        _shape = 'ellipse';\\n        break;\\n      case 'stadium':\\n        _shape = 'stadium';\\n        break;\\n      case 'subroutine':\\n        _shape = 'subroutine';\\n        break;\\n      case 'cylinder':\\n        _shape = 'cylinder';\\n        break;\\n      case 'group':\\n        _shape = 'rect';\\n        break;\\n      case 'doublecircle':\\n        _shape = 'doublecircle';\\n        break;\\n      default:\\n        _shape = 'rect';\\n    }\\n    // Add the node\\n    g.setNode(vertex.id, {\\n      labelStyle: styles.labelStyle,\\n      shape: _shape,\\n      labelText: vertexText,\\n      rx: radious,\\n      ry: radious,\\n      class: classStr,\\n      style: styles.style,\\n      id: vertex.id,\\n      link: vertex.link,\\n      linkTarget: vertex.linkTarget,\\n      tooltip: flowDb.getTooltip(vertex.id) || '',\\n      domId: flowDb.lookUpDomId(vertex.id),\\n      haveCallback: vertex.haveCallback,\\n      width: vertex.type === 'group' ? 500 : undefined,\\n      dir: vertex.dir,\\n      type: vertex.type,\\n      props: vertex.props,\\n      padding: getConfig().flowchart.padding,\\n    });\\n\\n    log.info('setNode', {\\n      labelStyle: styles.labelStyle,\\n      shape: _shape,\\n      labelText: vertexText,\\n      rx: radious,\\n      ry: radious,\\n      class: classStr,\\n      style: styles.style,\\n      id: vertex.id,\\n      domId: flowDb.lookUpDomId(vertex.id),\\n      width: vertex.type === 'group' ? 500 : undefined,\\n      type: vertex.type,\\n      dir: vertex.dir,\\n      props: vertex.props,\\n      padding: getConfig().flowchart.padding,\\n    });\\n  });\\n};\\n\\n/**\\n * Add edges to graph based on parsed graph defninition\\n *\\n * @param {object} edges The edges to add to the graph\\n * @param {object} g The graph object\\n */\\nexport const addEdges = function (edges, g) {\\n  log.info('abc78 edges = ', edges);\\n  let cnt = 0;\\n  let linkIdCnt = {};\\n\\n  let defaultStyle;\\n  let defaultLabelStyle;\\n\\n  if (typeof edges.defaultStyle !== 'undefined') {\\n    const defaultStyles = getStylesFromArray(edges.defaultStyle);\\n    defaultStyle = defaultStyles.style;\\n    defaultLabelStyle = defaultStyles.labelStyle;\\n  }\\n\\n  edges.forEach(function (edge) {\\n    cnt++;\\n\\n    // Identify Link\\n    var linkIdBase = 'L-' + edge.start + '-' + edge.end;\\n    // count the links from+to the same node to give unique id\\n    if (typeof linkIdCnt[linkIdBase] === 'undefined') {\\n      linkIdCnt[linkIdBase] = 0;\\n      log.info('abc78 new entry', linkIdBase, linkIdCnt[linkIdBase]);\\n    } else {\\n      linkIdCnt[linkIdBase]++;\\n      log.info('abc78 new entry', linkIdBase, linkIdCnt[linkIdBase]);\\n    }\\n    let linkId = linkIdBase + '-' + linkIdCnt[linkIdBase];\\n    log.info('abc78 new link id to be used is', linkIdBase, linkId, linkIdCnt[linkIdBase]);\\n    var linkNameStart = 'LS-' + edge.start;\\n    var linkNameEnd = 'LE-' + edge.end;\\n\\n    const edgeData = { style: '', labelStyle: '' };\\n    edgeData.minlen = edge.length || 1;\\n    //edgeData.id = 'id' + cnt;\\n\\n    // Set link type for rendering\\n    if (edge.type === 'arrow_open') {\\n      edgeData.arrowhead = 'none';\\n    } else {\\n      edgeData.arrowhead = 'normal';\\n    }\\n\\n    // Check of arrow types, placed here in order not to break old rendering\\n    edgeData.arrowTypeStart = 'arrow_open';\\n    edgeData.arrowTypeEnd = 'arrow_open';\\n\\n    /* eslint-disable no-fallthrough */\\n    switch (edge.type) {\\n      case 'double_arrow_cross':\\n        edgeData.arrowTypeStart = 'arrow_cross';\\n      case 'arrow_cross':\\n        edgeData.arrowTypeEnd = 'arrow_cross';\\n        break;\\n      case 'double_arrow_point':\\n        edgeData.arrowTypeStart = 'arrow_point';\\n      case 'arrow_point':\\n        edgeData.arrowTypeEnd = 'arrow_point';\\n        break;\\n      case 'double_arrow_circle':\\n        edgeData.arrowTypeStart = 'arrow_circle';\\n      case 'arrow_circle':\\n        edgeData.arrowTypeEnd = 'arrow_circle';\\n        break;\\n    }\\n\\n    let style = '';\\n    let labelStyle = '';\\n\\n    switch (edge.stroke) {\\n      case 'normal':\\n        style = 'fill:none;';\\n        if (typeof defaultStyle !== 'undefined') {\\n          style = defaultStyle;\\n        }\\n        if (typeof defaultLabelStyle !== 'undefined') {\\n          labelStyle = defaultLabelStyle;\\n        }\\n        edgeData.thickness = 'normal';\\n        edgeData.pattern = 'solid';\\n        break;\\n      case 'dotted':\\n        edgeData.thickness = 'normal';\\n        edgeData.pattern = 'dotted';\\n        edgeData.style = 'fill:none;stroke-width:2px;stroke-dasharray:3;';\\n        break;\\n      case 'thick':\\n        edgeData.thickness = 'thick';\\n        edgeData.pattern = 'solid';\\n        edgeData.style = 'stroke-width: 3.5px;fill:none;';\\n        break;\\n    }\\n    if (typeof edge.style !== 'undefined') {\\n      const styles = getStylesFromArray(edge.style);\\n      style = styles.style;\\n      labelStyle = styles.labelStyle;\\n    }\\n\\n    edgeData.style = edgeData.style += style;\\n    edgeData.labelStyle = edgeData.labelStyle += labelStyle;\\n\\n    if (typeof edge.interpolate !== 'undefined') {\\n      edgeData.curve = interpolateToCurve(edge.interpolate, curveLinear);\\n    } else if (typeof edges.defaultInterpolate !== 'undefined') {\\n      edgeData.curve = interpolateToCurve(edges.defaultInterpolate, curveLinear);\\n    } else {\\n      edgeData.curve = interpolateToCurve(conf.curve, curveLinear);\\n    }\\n\\n    if (typeof edge.text === 'undefined') {\\n      if (typeof edge.style !== 'undefined') {\\n        edgeData.arrowheadStyle = 'fill: #333';\\n      }\\n    } else {\\n      edgeData.arrowheadStyle = 'fill: #333';\\n      edgeData.labelpos = 'c';\\n    }\\n    // if (evaluate(getConfig().flowchart.htmlLabels) &amp;&amp; false) {\\n    //   // eslint-disable-line\\n    //   edgeData.labelType = 'html';\\n    //   edgeData.label = `&lt;span id=\\\"L-${linkId}\\\" class=\\\"edgeLabel L-${linkNameStart}' L-${linkNameEnd}\\\"&gt;${edge.text}&lt;/span&gt;`;\\n    // } else {\\n    edgeData.labelType = 'text';\\n    edgeData.label = edge.text.replace(common.lineBreakRegex, '\\\\n');\\n\\n    if (typeof edge.style === 'undefined') {\\n      edgeData.style = edgeData.style || 'stroke: #333; stroke-width: 1.5px;fill:none;';\\n    }\\n\\n    edgeData.labelStyle = edgeData.labelStyle.replace('color:', 'fill:');\\n    // }\\n\\n    edgeData.id = linkId;\\n    edgeData.classes = 'flowchart-link ' + linkNameStart + ' ' + linkNameEnd;\\n\\n    // Add the edge to the graph\\n    g.setEdge(edge.start, edge.end, edgeData, cnt);\\n  });\\n};\\n\\n/**\\n * Returns the all the styles from classDef statements in the graph definition.\\n *\\n * @param text\\n * @returns {object} ClassDef styles\\n */\\nexport const getClasses = function (text) {\\n  log.info('Extracting classes');\\n  flowDb.clear();\\n  const parser = flow.parser;\\n  parser.yy = flowDb;\\n\\n  try {\\n    // Parse the graph definition\\n    parser.parse(text);\\n  } catch (e) {\\n    return;\\n  }\\n\\n  return flowDb.getClasses();\\n};\\n\\n/**\\n * Draws a flowchart in the tag with id: id based on the graph definition in text.\\n *\\n * @param text\\n * @param id\\n */\\n\\nexport const draw = function (text, id) {\\n  log.info('Drawing flowchart');\\n  flowDb.clear();\\n  flowDb.setGen('gen-2');\\n  const parser = flow.parser;\\n  parser.yy = flowDb;\\n\\n  // Parse the graph definition\\n  // try {\\n  parser.parse(text);\\n  // } catch (err) {\\n  // log.debug('Parsing failed');\\n  // }\\n\\n  // Fetch the default direction, use TD if none was found\\n  let dir = flowDb.getDirection();\\n  if (typeof dir === 'undefined') {\\n    dir = 'TD';\\n  }\\n\\n  const conf = getConfig().flowchart;\\n  const nodeSpacing = conf.nodeSpacing || 50;\\n  const rankSpacing = conf.rankSpacing || 50;\\n\\n  const securityLevel = getConfig().securityLevel;\\n  // Handle root and ocument for when rendering in sanbox mode\\n  let sandboxElement;\\n  if (securityLevel === 'sandbox') {\\n    sandboxElement = select('#i' + id);\\n  }\\n  const root =\\n    securityLevel === 'sandbox'\\n      ? select(sandboxElement.nodes()[0].contentDocument.body)\\n      : select('body');\\n  const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n\\n  // Create the input mermaid.graph\\n  const g = new graphlib.Graph({\\n    multigraph: true,\\n    compound: true,\\n  })\\n    .setGraph({\\n      rankdir: dir,\\n      nodesep: nodeSpacing,\\n      ranksep: rankSpacing,\\n      marginx: 8,\\n      marginy: 8,\\n    })\\n    .setDefaultEdgeLabel(function () {\\n      return {};\\n    });\\n\\n  let subG;\\n  const subGraphs = flowDb.getSubGraphs();\\n  log.info('Subgraphs - ', subGraphs);\\n  for (let i = subGraphs.length - 1; i &gt;= 0; i--) {\\n    subG = subGraphs[i];\\n    log.info('Subgraph - ', subG);\\n    flowDb.addVertex(subG.id, subG.title, 'group', undefined, subG.classes, subG.dir);\\n  }\\n\\n  // Fetch the verices/nodes and edges/links from the parsed graph definition\\n  const vert = flowDb.getVertices();\\n\\n  const edges = flowDb.getEdges();\\n\\n  log.info(edges);\\n  let i = 0;\\n  for (i = subGraphs.length - 1; i &gt;= 0; i--) {\\n    // for (let i = 0; i &lt; subGraphs.length; i++) {\\n    subG = subGraphs[i];\\n\\n    selectAll('cluster').append('text');\\n\\n    for (let j = 0; j &lt; subG.nodes.length; j++) {\\n      log.info('Setting up subgraphs', subG.nodes[j], subG.id);\\n      g.setParent(subG.nodes[j], subG.id);\\n    }\\n  }\\n  addVertices(vert, g, id, root, doc);\\n  addEdges(edges, g);\\n\\n  // Add custom shapes\\n  // flowChartShapes.addToRenderV2(addShape);\\n\\n  // Set up an SVG group so that we can translate the final graph.\\n  const svg = root.select(`[id=\\\"${id}\\\"]`);\\n  svg.attr('xmlns:xlink', 'http://www.w3.org/1999/xlink');\\n\\n  // Run the renderer. This is what draws the final graph.\\n  const element = root.select('#' + id + ' g');\\n  render(element, g, ['point', 'circle', 'cross'], 'flowchart', id);\\n\\n  const padding = conf.diagramPadding;\\n  const svgBounds = svg.node().getBBox();\\n  const width = svgBounds.width + padding * 2;\\n  const height = svgBounds.height + padding * 2;\\n  log.debug(\\n    `new ViewBox 0 0 ${width} ${height}`,\\n    `translate(${padding - g._label.marginx}, ${padding - g._label.marginy})`\\n  );\\n\\n  configureSvgSize(svg, height, width, conf.useMaxWidth);\\n\\n  svg.attr('viewBox', `0 0 ${width} ${height}`);\\n  svg\\n    .select('g')\\n    .attr('transform', `translate(${padding - g._label.marginx}, ${padding - svgBounds.y})`);\\n\\n  // Index nodes\\n  flowDb.indexNodes('subGraph' + i);\\n\\n  // Add label rects for non html labels\\n  if (!conf.htmlLabels) {\\n    const labels = doc.querySelectorAll('[id=\\\"' + id + '\\\"] .edgeLabel .label');\\n    for (let k = 0; k &lt; labels.length; k++) {\\n      const label = labels[k];\\n\\n      // Get dimensions of label\\n      const dim = label.getBBox();\\n\\n      const rect = doc.createElementNS('http://www.w3.org/2000/svg', 'rect');\\n      rect.setAttribute('rx', 0);\\n      rect.setAttribute('ry', 0);\\n      rect.setAttribute('width', dim.width);\\n      rect.setAttribute('height', dim.height);\\n      // rect.setAttribute('style', 'fill:#e8e8e8;');\\n\\n      label.insertBefore(rect, label.firstChild);\\n    }\\n  }\\n\\n  // If node has a link, wrap it in an anchor SVG object.\\n  const keys = Object.keys(vert);\\n  keys.forEach(function (key) {\\n    const vertex = vert[key];\\n\\n    if (vertex.link) {\\n      const node = select('#' + id + ' [id=\\\"' + key + '\\\"]');\\n      if (node) {\\n        const link = doc.createElementNS('http://www.w3.org/2000/svg', 'a');\\n        link.setAttributeNS('http://www.w3.org/2000/svg', 'class', vertex.classes.join(' '));\\n        link.setAttributeNS('http://www.w3.org/2000/svg', 'href', vertex.link);\\n        link.setAttributeNS('http://www.w3.org/2000/svg', 'rel', 'noopener');\\n        if (securityLevel === 'sandbox') {\\n          link.setAttributeNS('http://www.w3.org/2000/svg', 'target', '_top');\\n        } else if (vertex.linkTarget) {\\n          link.setAttributeNS('http://www.w3.org/2000/svg', 'target', vertex.linkTarget);\\n        }\\n\\n        const linkNode = node.insert(function () {\\n          return link;\\n        }, ':first-child');\\n\\n        const shape = node.select('.label-container');\\n        if (shape) {\\n          linkNode.append(function () {\\n            return shape.node();\\n          });\\n        }\\n\\n        const label = node.select('.label');\\n        if (label) {\\n          linkNode.append(function () {\\n            return label.node();\\n          });\\n        }\\n      }\\n    }\\n  });\\n};\\n\\nexport default {\\n  setConf,\\n  addVertices,\\n  addEdges,\\n  getClasses,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import moment from 'moment-mini';\\nimport { sanitizeUrl } from '@braintree/sanitize-url';\\nimport { log } from '../../logger';\\nimport * as configApi from '../../config';\\nimport utils from '../../utils';\\nimport mermaidAPI from '../../mermaidAPI';\\n\\nlet dateFormat = '';\\nlet axisFormat = '';\\nlet todayMarker = '';\\nlet includes = [];\\nlet excludes = [];\\nlet links = {};\\nlet title = '';\\nlet sections = [];\\nlet tasks = [];\\nlet currentSection = '';\\nconst tags = ['active', 'done', 'crit', 'milestone'];\\nlet funs = [];\\nlet inclusiveEndDates = false;\\nlet topAxis = false;\\n\\n// The serial order of the task in the script\\nlet lastOrder = 0;\\n\\nexport const parseDirective = function (statement, context, type) {\\n  mermaidAPI.parseDirective(this, statement, context, type);\\n};\\n\\nexport const clear = function () {\\n  sections = [];\\n  tasks = [];\\n  currentSection = '';\\n  funs = [];\\n  title = '';\\n  taskCnt = 0;\\n  lastTask = undefined;\\n  lastTaskID = undefined;\\n  rawTasks = [];\\n  dateFormat = '';\\n  axisFormat = '';\\n  todayMarker = '';\\n  includes = [];\\n  excludes = [];\\n  inclusiveEndDates = false;\\n  topAxis = false;\\n  lastOrder = 0;\\n  links = {};\\n};\\n\\nexport const setAxisFormat = function (txt) {\\n  axisFormat = txt;\\n};\\n\\nexport const getAxisFormat = function () {\\n  return axisFormat;\\n};\\n\\nexport const setTodayMarker = function (txt) {\\n  todayMarker = txt;\\n};\\n\\nexport const getTodayMarker = function () {\\n  return todayMarker;\\n};\\n\\nexport const setDateFormat = function (txt) {\\n  dateFormat = txt;\\n};\\n\\nexport const enableInclusiveEndDates = function () {\\n  inclusiveEndDates = true;\\n};\\n\\nexport const endDatesAreInclusive = function () {\\n  return inclusiveEndDates;\\n};\\n\\nexport const enableTopAxis = function () {\\n  topAxis = true;\\n};\\n\\nexport const topAxisEnabled = function () {\\n  return topAxis;\\n};\\n\\nexport const getDateFormat = function () {\\n  return dateFormat;\\n};\\n\\nexport const setIncludes = function (txt) {\\n  includes = txt.toLowerCase().split(/[\\\\s,]+/);\\n};\\n\\nexport const getIncludes = function () {\\n  return includes;\\n};\\nexport const setExcludes = function (txt) {\\n  excludes = txt.toLowerCase().split(/[\\\\s,]+/);\\n};\\n\\nexport const getExcludes = function () {\\n  return excludes;\\n};\\n\\nexport const getLinks = function () {\\n  return links;\\n};\\n\\nexport const setTitle = function (txt) {\\n  title = txt;\\n};\\n\\nexport const getTitle = function () {\\n  return title;\\n};\\n\\nexport const addSection = function (txt) {\\n  currentSection = txt;\\n  sections.push(txt);\\n};\\n\\nexport const getSections = function () {\\n  return sections;\\n};\\n\\nexport const getTasks = function () {\\n  let allItemsPricessed = compileTasks();\\n  const maxDepth = 10;\\n  let iterationCount = 0;\\n  while (!allItemsPricessed &amp;&amp; iterationCount &lt; maxDepth) {\\n    allItemsPricessed = compileTasks();\\n    iterationCount++;\\n  }\\n\\n  tasks = rawTasks;\\n\\n  return tasks;\\n};\\n\\nexport const isInvalidDate = function (date, dateFormat, excludes, includes) {\\n  if (includes.indexOf(date.format(dateFormat.trim())) &gt;= 0) {\\n    return false;\\n  }\\n  if (date.isoWeekday() &gt;= 6 &amp;&amp; excludes.indexOf('weekends') &gt;= 0) {\\n    return true;\\n  }\\n  if (excludes.indexOf(date.format('dddd').toLowerCase()) &gt;= 0) {\\n    return true;\\n  }\\n  return excludes.indexOf(date.format(dateFormat.trim())) &gt;= 0;\\n};\\n\\nconst checkTaskDates = function (task, dateFormat, excludes, includes) {\\n  if (!excludes.length || task.manualEndTime) return;\\n  let startTime = moment(task.startTime, dateFormat, true);\\n  startTime.add(1, 'd');\\n  let endTime = moment(task.endTime, dateFormat, true);\\n  let renderEndTime = fixTaskDates(startTime, endTime, dateFormat, excludes, includes);\\n  task.endTime = endTime.toDate();\\n  task.renderEndTime = renderEndTime;\\n};\\n\\nconst fixTaskDates = function (startTime, endTime, dateFormat, excludes, includes) {\\n  let invalid = false;\\n  let renderEndTime = null;\\n  while (startTime &lt;= endTime) {\\n    if (!invalid) {\\n      renderEndTime = endTime.toDate();\\n    }\\n    invalid = isInvalidDate(startTime, dateFormat, excludes, includes);\\n    if (invalid) {\\n      endTime.add(1, 'd');\\n    }\\n    startTime.add(1, 'd');\\n  }\\n  return renderEndTime;\\n};\\n\\nconst getStartDate = function (prevTime, dateFormat, str) {\\n  str = str.trim();\\n\\n  // Test for after\\n  const re = /^after\\\\s+([\\\\d\\\\w- ]+)/;\\n  const afterStatement = re.exec(str.trim());\\n\\n  if (afterStatement !== null) {\\n    // check all after ids and take the latest\\n    let latestEndingTask = null;\\n    afterStatement[1].split(' ').forEach(function (id) {\\n      let task = findTaskById(id);\\n      if (typeof task !== 'undefined') {\\n        if (!latestEndingTask) {\\n          latestEndingTask = task;\\n        } else {\\n          if (task.endTime &gt; latestEndingTask.endTime) {\\n            latestEndingTask = task;\\n          }\\n        }\\n      }\\n    });\\n\\n    if (!latestEndingTask) {\\n      const dt = new Date();\\n      dt.setHours(0, 0, 0, 0);\\n      return dt;\\n    } else {\\n      return latestEndingTask.endTime;\\n    }\\n  }\\n\\n  // Check for actual date set\\n  let mDate = moment(str, dateFormat.trim(), true);\\n  if (mDate.isValid()) {\\n    return mDate.toDate();\\n  } else {\\n    log.debug('Invalid date:' + str);\\n    log.debug('With date format:' + dateFormat.trim());\\n  }\\n\\n  // Default date - now\\n  return new Date();\\n};\\n\\nconst durationToDate = function (durationStatement, relativeTime) {\\n  if (durationStatement !== null) {\\n    switch (durationStatement[2]) {\\n      case 's':\\n        relativeTime.add(durationStatement[1], 'seconds');\\n        break;\\n      case 'm':\\n        relativeTime.add(durationStatement[1], 'minutes');\\n        break;\\n      case 'h':\\n        relativeTime.add(durationStatement[1], 'hours');\\n        break;\\n      case 'd':\\n        relativeTime.add(durationStatement[1], 'days');\\n        break;\\n      case 'w':\\n        relativeTime.add(durationStatement[1], 'weeks');\\n        break;\\n    }\\n  }\\n  // Default date - now\\n  return relativeTime.toDate();\\n};\\n\\nconst getEndDate = function (prevTime, dateFormat, str, inclusive) {\\n  inclusive = inclusive || false;\\n  str = str.trim();\\n\\n  // Check for actual date\\n  let mDate = moment(str, dateFormat.trim(), true);\\n  if (mDate.isValid()) {\\n    if (inclusive) {\\n      mDate.add(1, 'd');\\n    }\\n    return mDate.toDate();\\n  }\\n\\n  return durationToDate(/^([\\\\d]+)([wdhms])/.exec(str.trim()), moment(prevTime));\\n};\\n\\nlet taskCnt = 0;\\nconst parseId = function (idStr) {\\n  if (typeof idStr === 'undefined') {\\n    taskCnt = taskCnt + 1;\\n    return 'task' + taskCnt;\\n  }\\n  return idStr;\\n};\\n// id, startDate, endDate\\n// id, startDate, length\\n// id, after x, endDate\\n// id, after x, length\\n// startDate, endDate\\n// startDate, length\\n// after x, endDate\\n// after x, length\\n// endDate\\n// length\\n\\nconst compileData = function (prevTask, dataStr) {\\n  let ds;\\n\\n  if (dataStr.substr(0, 1) === ':') {\\n    ds = dataStr.substr(1, dataStr.length);\\n  } else {\\n    ds = dataStr;\\n  }\\n\\n  const data = ds.split(',');\\n\\n  const task = {};\\n\\n  // Get tags like active, done, crit and milestone\\n  getTaskTags(data, task, tags);\\n\\n  for (let i = 0; i &lt; data.length; i++) {\\n    data[i] = data[i].trim();\\n  }\\n\\n  let endTimeData = '';\\n  switch (data.length) {\\n    case 1:\\n      task.id = parseId();\\n      task.startTime = prevTask.endTime;\\n      endTimeData = data[0];\\n      break;\\n    case 2:\\n      task.id = parseId();\\n      task.startTime = getStartDate(undefined, dateFormat, data[0]);\\n      endTimeData = data[1];\\n      break;\\n    case 3:\\n      task.id = parseId(data[0]);\\n      task.startTime = getStartDate(undefined, dateFormat, data[1]);\\n      endTimeData = data[2];\\n      break;\\n    default:\\n  }\\n\\n  if (endTimeData) {\\n    task.endTime = getEndDate(task.startTime, dateFormat, endTimeData, inclusiveEndDates);\\n    task.manualEndTime = moment(endTimeData, 'YYYY-MM-DD', true).isValid();\\n    checkTaskDates(task, dateFormat, excludes, includes);\\n  }\\n\\n  return task;\\n};\\n\\nconst parseData = function (prevTaskId, dataStr) {\\n  let ds;\\n  if (dataStr.substr(0, 1) === ':') {\\n    ds = dataStr.substr(1, dataStr.length);\\n  } else {\\n    ds = dataStr;\\n  }\\n\\n  const data = ds.split(',');\\n\\n  const task = {};\\n\\n  // Get tags like active, done, crit and milestone\\n  getTaskTags(data, task, tags);\\n\\n  for (let i = 0; i &lt; data.length; i++) {\\n    data[i] = data[i].trim();\\n  }\\n\\n  switch (data.length) {\\n    case 1:\\n      task.id = parseId();\\n      task.startTime = {\\n        type: 'prevTaskEnd',\\n        id: prevTaskId,\\n      };\\n      task.endTime = {\\n        data: data[0],\\n      };\\n      break;\\n    case 2:\\n      task.id = parseId();\\n      task.startTime = {\\n        type: 'getStartDate',\\n        startData: data[0],\\n      };\\n      task.endTime = {\\n        data: data[1],\\n      };\\n      break;\\n    case 3:\\n      task.id = parseId(data[0]);\\n      task.startTime = {\\n        type: 'getStartDate',\\n        startData: data[1],\\n      };\\n      task.endTime = {\\n        data: data[2],\\n      };\\n      break;\\n    default:\\n  }\\n\\n  return task;\\n};\\n\\nlet lastTask;\\nlet lastTaskID;\\nlet rawTasks = [];\\nconst taskDb = {};\\nexport const addTask = function (descr, data) {\\n  const rawTask = {\\n    section: currentSection,\\n    type: currentSection,\\n    processed: false,\\n    manualEndTime: false,\\n    renderEndTime: null,\\n    raw: { data: data },\\n    task: descr,\\n    classes: [],\\n  };\\n  const taskInfo = parseData(lastTaskID, data);\\n  rawTask.raw.startTime = taskInfo.startTime;\\n  rawTask.raw.endTime = taskInfo.endTime;\\n  rawTask.id = taskInfo.id;\\n  rawTask.prevTaskId = lastTaskID;\\n  rawTask.active = taskInfo.active;\\n  rawTask.done = taskInfo.done;\\n  rawTask.crit = taskInfo.crit;\\n  rawTask.milestone = taskInfo.milestone;\\n  rawTask.order = lastOrder;\\n\\n  lastOrder++;\\n\\n  const pos = rawTasks.push(rawTask);\\n\\n  lastTaskID = rawTask.id;\\n  // Store cross ref\\n  taskDb[rawTask.id] = pos - 1;\\n};\\n\\nexport const findTaskById = function (id) {\\n  const pos = taskDb[id];\\n  return rawTasks[pos];\\n};\\n\\nexport const addTaskOrg = function (descr, data) {\\n  const newTask = {\\n    section: currentSection,\\n    type: currentSection,\\n    description: descr,\\n    task: descr,\\n    classes: [],\\n  };\\n  const taskInfo = compileData(lastTask, data);\\n  newTask.startTime = taskInfo.startTime;\\n  newTask.endTime = taskInfo.endTime;\\n  newTask.id = taskInfo.id;\\n  newTask.active = taskInfo.active;\\n  newTask.done = taskInfo.done;\\n  newTask.crit = taskInfo.crit;\\n  newTask.milestone = taskInfo.milestone;\\n  lastTask = newTask;\\n  tasks.push(newTask);\\n};\\n\\nconst compileTasks = function () {\\n  const compileTask = function (pos) {\\n    const task = rawTasks[pos];\\n    let startTime = '';\\n    switch (rawTasks[pos].raw.startTime.type) {\\n      case 'prevTaskEnd': {\\n        const prevTask = findTaskById(task.prevTaskId);\\n        task.startTime = prevTask.endTime;\\n        break;\\n      }\\n      case 'getStartDate':\\n        startTime = getStartDate(undefined, dateFormat, rawTasks[pos].raw.startTime.startData);\\n        if (startTime) {\\n          rawTasks[pos].startTime = startTime;\\n        }\\n        break;\\n    }\\n\\n    if (rawTasks[pos].startTime) {\\n      rawTasks[pos].endTime = getEndDate(\\n        rawTasks[pos].startTime,\\n        dateFormat,\\n        rawTasks[pos].raw.endTime.data,\\n        inclusiveEndDates\\n      );\\n      if (rawTasks[pos].endTime) {\\n        rawTasks[pos].processed = true;\\n        rawTasks[pos].manualEndTime = moment(\\n          rawTasks[pos].raw.endTime.data,\\n          'YYYY-MM-DD',\\n          true\\n        ).isValid();\\n        checkTaskDates(rawTasks[pos], dateFormat, excludes, includes);\\n      }\\n    }\\n\\n    return rawTasks[pos].processed;\\n  };\\n\\n  let allProcessed = true;\\n  for (let i = 0; i &lt; rawTasks.length; i++) {\\n    compileTask(i);\\n\\n    allProcessed = allProcessed &amp;&amp; rawTasks[i].processed;\\n  }\\n  return allProcessed;\\n};\\n\\n/**\\n * Called by parser when a link is found. Adds the URL to the vertex data.\\n *\\n * @param ids Comma separated list of ids\\n * @param _linkStr URL to create a link for\\n */\\nexport const setLink = function (ids, _linkStr) {\\n  let linkStr = _linkStr;\\n  if (configApi.getConfig().securityLevel !== 'loose') {\\n    linkStr = sanitizeUrl(_linkStr);\\n  }\\n  ids.split(',').forEach(function (id) {\\n    let rawTask = findTaskById(id);\\n    if (typeof rawTask !== 'undefined') {\\n      pushFun(id, () =&gt; {\\n        window.open(linkStr, '_self');\\n      });\\n      links[id] = linkStr;\\n    }\\n  });\\n  setClass(ids, 'clickable');\\n};\\n\\n/**\\n * Called by parser when a special node is found, e.g. a clickable element.\\n *\\n * @param ids Comma separated list of ids\\n * @param className Class to add\\n */\\nexport const setClass = function (ids, className) {\\n  ids.split(',').forEach(function (id) {\\n    let rawTask = findTaskById(id);\\n    if (typeof rawTask !== 'undefined') {\\n      rawTask.classes.push(className);\\n    }\\n  });\\n};\\n\\nconst setClickFun = function (id, functionName, functionArgs) {\\n  if (configApi.getConfig().securityLevel !== 'loose') {\\n    return;\\n  }\\n  if (typeof functionName === 'undefined') {\\n    return;\\n  }\\n\\n  let argList = [];\\n  if (typeof functionArgs === 'string') {\\n    /* Splits functionArgs by ',', ignoring all ',' in double quoted strings */\\n    argList = functionArgs.split(/,(?=(?:(?:[^\\\"]*\\\"){2})*[^\\\"]*$)/);\\n    for (let i = 0; i &lt; argList.length; i++) {\\n      let item = argList[i].trim();\\n      /* Removes all double quotes at the start and end of an argument */\\n      /* This preserves all starting and ending whitespace inside */\\n      if (item.charAt(0) === '\\\"' &amp;&amp; item.charAt(item.length - 1) === '\\\"') {\\n        item = item.substr(1, item.length - 2);\\n      }\\n      argList[i] = item;\\n    }\\n  }\\n\\n  /* if no arguments passed into callback, default to passing in id */\\n  if (argList.length === 0) {\\n    argList.push(id);\\n  }\\n\\n  let rawTask = findTaskById(id);\\n  if (typeof rawTask !== 'undefined') {\\n    pushFun(id, () =&gt; {\\n      utils.runFunc(functionName, ...argList);\\n    });\\n  }\\n};\\n\\n/**\\n * The callbackFunction is executed in a click event bound to the task with the specified id or the\\n * task's assigned text\\n *\\n * @param id The task's id\\n * @param callbackFunction A function to be executed when clicked on the task or the task's text\\n */\\nconst pushFun = function (id, callbackFunction) {\\n  funs.push(function () {\\n    // const elem = d3.select(element).select(`[id=\\\"${id}\\\"]`)\\n    const elem = document.querySelector(`[id=\\\"${id}\\\"]`);\\n    if (elem !== null) {\\n      elem.addEventListener('click', function () {\\n        callbackFunction();\\n      });\\n    }\\n  });\\n  funs.push(function () {\\n    // const elem = d3.select(element).select(`[id=\\\"${id}-text\\\"]`)\\n    const elem = document.querySelector(`[id=\\\"${id}-text\\\"]`);\\n    if (elem !== null) {\\n      elem.addEventListener('click', function () {\\n        callbackFunction();\\n      });\\n    }\\n  });\\n};\\n\\n/**\\n * Called by parser when a click definition is found. Registers an event handler.\\n *\\n * @param ids Comma separated list of ids\\n * @param functionName Function to be called on click\\n * @param functionArgs Function args the function should be called with\\n */\\nexport const setClickEvent = function (ids, functionName, functionArgs) {\\n  ids.split(',').forEach(function (id) {\\n    setClickFun(id, functionName, functionArgs);\\n  });\\n  setClass(ids, 'clickable');\\n};\\n\\n/**\\n * Binds all functions previously added to fun (specified through click) to the element\\n *\\n * @param element\\n */\\nexport const bindFunctions = function (element) {\\n  funs.forEach(function (fun) {\\n    fun(element);\\n  });\\n};\\n\\nexport default {\\n  parseDirective,\\n  getConfig: () =&gt; configApi.getConfig().gantt,\\n  clear,\\n  setDateFormat,\\n  getDateFormat,\\n  enableInclusiveEndDates,\\n  endDatesAreInclusive,\\n  enableTopAxis,\\n  topAxisEnabled,\\n  setAxisFormat,\\n  getAxisFormat,\\n  setTodayMarker,\\n  getTodayMarker,\\n  setTitle,\\n  getTitle,\\n  addSection,\\n  getSections,\\n  getTasks,\\n  addTask,\\n  findTaskById,\\n  addTaskOrg,\\n  setIncludes,\\n  getIncludes,\\n  setExcludes,\\n  getExcludes,\\n  setClickEvent,\\n  setLink,\\n  getLinks,\\n  bindFunctions,\\n  durationToDate,\\n  isInvalidDate,\\n};\\n\\n/**\\n * @param data\\n * @param task\\n * @param tags\\n */\\nfunction getTaskTags(data, task, tags) {\\n  let matchFound = true;\\n  while (matchFound) {\\n    matchFound = false;\\n    tags.forEach(function (t) {\\n      const pattern = '^\\\\\\\\s*' + t + '\\\\\\\\s*$';\\n      const regex = new RegExp(pattern);\\n      if (data[0].match(regex)) {\\n        task[t] = true;\\n        data.shift(1);\\n        matchFound = true;\\n      }\\n    });\\n  }\\n}\\n\"</span>,<span class=\"code-string\">\"import moment from 'moment-mini';\\nimport {\\n  select,\\n  scaleTime,\\n  min,\\n  max,\\n  scaleLinear,\\n  interpolateHcl,\\n  axisBottom,\\n  axisTop,\\n  timeFormat,\\n} from 'd3';\\nimport { parser } from './parser/gantt';\\nimport common from '../common/common';\\nimport ganttDb from './ganttDb';\\nimport { getConfig } from '../../config';\\nimport { configureSvgSize } from '../../utils';\\n\\nparser.yy = ganttDb;\\nexport const setConf = function () {\\n  // const keys = Object.keys(cnf);\\n  // keys.forEach(function(key) {\\n  //   conf[key] = cnf[key];\\n  // });\\n};\\nlet w;\\nexport const draw = function (text, id) {\\n  const conf = getConfig().gantt;\\n  parser.yy.clear();\\n  parser.parse(text);\\n\\n  const securityLevel = getConfig().securityLevel;\\n  // Handle root and ocument for when rendering in sanbox mode\\n  let sandboxElement;\\n  if (securityLevel === 'sandbox') {\\n    sandboxElement = select('#i' + id);\\n  }\\n  const root =\\n    securityLevel === 'sandbox'\\n      ? select(sandboxElement.nodes()[0].contentDocument.body)\\n      : select('body');\\n  const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n\\n  const elem = doc.getElementById(id);\\n  w = elem.parentElement.offsetWidth;\\n\\n  if (typeof w === 'undefined') {\\n    w = 1200;\\n  }\\n\\n  if (typeof conf.useWidth !== 'undefined') {\\n    w = conf.useWidth;\\n  }\\n\\n  const taskArray = parser.yy.getTasks();\\n\\n  // Set height based on number of tasks\\n  const h = taskArray.length * (conf.barHeight + conf.barGap) + 2 * conf.topPadding;\\n\\n  // Set viewBox\\n  elem.setAttribute('viewBox', '0 0 ' + w + ' ' + h);\\n  const svg = root.select(`[id=\\\"${id}\\\"]`);\\n\\n  // Set timescale\\n  const timeScale = scaleTime()\\n    .domain([\\n      min(taskArray, function (d) {\\n        return d.startTime;\\n      }),\\n      max(taskArray, function (d) {\\n        return d.endTime;\\n      }),\\n    ])\\n    .rangeRound([0, w - conf.leftPadding - conf.rightPadding]);\\n\\n  let categories = [];\\n\\n  for (let i = 0; i &lt; taskArray.length; i++) {\\n    categories.push(taskArray[i].type);\\n  }\\n\\n  const catsUnfiltered = categories; // for vert labels\\n\\n  categories = checkUnique(categories);\\n\\n  /**\\n   * @param a\\n   * @param b\\n   */\\n  function taskCompare(a, b) {\\n    const taskA = a.startTime;\\n    const taskB = b.startTime;\\n    let result = 0;\\n    if (taskA &gt; taskB) {\\n      result = 1;\\n    } else if (taskA &lt; taskB) {\\n      result = -1;\\n    }\\n    return result;\\n  }\\n\\n  // Sort the task array using the above taskCompare() so that\\n  // tasks are created based on their order of startTime\\n  taskArray.sort(taskCompare);\\n\\n  makeGant(taskArray, w, h);\\n\\n  configureSvgSize(svg, h, w, conf.useMaxWidth);\\n\\n  svg\\n    .append('text')\\n    .text(parser.yy.getTitle())\\n    .attr('x', w / 2)\\n    .attr('y', conf.titleTopMargin)\\n    .attr('class', 'titleText');\\n\\n  /**\\n   * @param tasks\\n   * @param pageWidth\\n   * @param pageHeight\\n   */\\n  function makeGant(tasks, pageWidth, pageHeight) {\\n    const barHeight = conf.barHeight;\\n    const gap = barHeight + conf.barGap;\\n    const topPadding = conf.topPadding;\\n    const leftPadding = conf.leftPadding;\\n\\n    const colorScale = scaleLinear()\\n      .domain([0, categories.length])\\n      .range(['#00B9FA', '#F95002'])\\n      .interpolate(interpolateHcl);\\n\\n    drawExcludeDays(\\n      gap,\\n      topPadding,\\n      leftPadding,\\n      pageWidth,\\n      pageHeight,\\n      tasks,\\n      parser.yy.getExcludes(),\\n      parser.yy.getIncludes()\\n    );\\n    makeGrid(leftPadding, topPadding, pageWidth, pageHeight);\\n    drawRects(tasks, gap, topPadding, leftPadding, barHeight, colorScale, pageWidth, pageHeight);\\n    vertLabels(gap, topPadding, leftPadding, barHeight, colorScale);\\n    drawToday(leftPadding, topPadding, pageWidth, pageHeight);\\n  }\\n\\n  /**\\n   * @param theArray\\n   * @param theGap\\n   * @param theTopPad\\n   * @param theSidePad\\n   * @param theBarHeight\\n   * @param theColorScale\\n   * @param w\\n   */\\n  function drawRects(theArray, theGap, theTopPad, theSidePad, theBarHeight, theColorScale, w) {\\n    // Draw background rects covering the entire width of the graph, these form the section rows.\\n    svg\\n      .append('g')\\n      .selectAll('rect')\\n      .data(theArray)\\n      .enter()\\n      .append('rect')\\n      .attr('x', 0)\\n      .attr('y', function (d, i) {\\n        // Ignore the incoming i value and use our order instead\\n        i = d.order;\\n        return i * theGap + theTopPad - 2;\\n      })\\n      .attr('width', function () {\\n        return w - conf.rightPadding / 2;\\n      })\\n      .attr('height', theGap)\\n      .attr('class', function (d) {\\n        for (let i = 0; i &lt; categories.length; i++) {\\n          if (d.type === categories[i]) {\\n            return 'section section' + (i % conf.numberSectionStyles);\\n          }\\n        }\\n        return 'section section0';\\n      });\\n\\n    // Draw the rects representing the tasks\\n    const rectangles = svg.append('g').selectAll('rect').data(theArray).enter();\\n\\n    const links = ganttDb.getLinks();\\n\\n    // Render the tasks with links\\n    // Render the other tasks\\n    rectangles\\n      .append('rect')\\n      .attr('id', function (d) {\\n        return d.id;\\n      })\\n      .attr('rx', 3)\\n      .attr('ry', 3)\\n      .attr('x', function (d) {\\n        if (d.milestone) {\\n          return (\\n            timeScale(d.startTime) +\\n            theSidePad +\\n            0.5 * (timeScale(d.endTime) - timeScale(d.startTime)) -\\n            0.5 * theBarHeight\\n          );\\n        }\\n        return timeScale(d.startTime) + theSidePad;\\n      })\\n      .attr('y', function (d, i) {\\n        // Ignore the incoming i value and use our order instead\\n        i = d.order;\\n        return i * theGap + theTopPad;\\n      })\\n      .attr('width', function (d) {\\n        if (d.milestone) {\\n          return theBarHeight;\\n        }\\n        return timeScale(d.renderEndTime || d.endTime) - timeScale(d.startTime);\\n      })\\n      .attr('height', theBarHeight)\\n      .attr('transform-origin', function (d, i) {\\n        // Ignore the incoming i value and use our order instead\\n        i = d.order;\\n\\n        return (\\n          (\\n            timeScale(d.startTime) +\\n            theSidePad +\\n            0.5 * (timeScale(d.endTime) - timeScale(d.startTime))\\n          ).toString() +\\n          'px ' +\\n          (i * theGap + theTopPad + 0.5 * theBarHeight).toString() +\\n          'px'\\n        );\\n      })\\n      .attr('class', function (d) {\\n        const res = 'task';\\n\\n        let classStr = '';\\n        if (d.classes.length &gt; 0) {\\n          classStr = d.classes.join(' ');\\n        }\\n\\n        let secNum = 0;\\n        for (let i = 0; i &lt; categories.length; i++) {\\n          if (d.type === categories[i]) {\\n            secNum = i % conf.numberSectionStyles;\\n          }\\n        }\\n\\n        let taskClass = '';\\n        if (d.active) {\\n          if (d.crit) {\\n            taskClass += ' activeCrit';\\n          } else {\\n            taskClass = ' active';\\n          }\\n        } else if (d.done) {\\n          if (d.crit) {\\n            taskClass = ' doneCrit';\\n          } else {\\n            taskClass = ' done';\\n          }\\n        } else {\\n          if (d.crit) {\\n            taskClass += ' crit';\\n          }\\n        }\\n\\n        if (taskClass.length === 0) {\\n          taskClass = ' task';\\n        }\\n\\n        if (d.milestone) {\\n          taskClass = ' milestone ' + taskClass;\\n        }\\n\\n        taskClass += secNum;\\n\\n        taskClass += ' ' + classStr;\\n\\n        return res + taskClass;\\n      });\\n\\n    // Append task labels\\n    rectangles\\n      .append('text')\\n      .attr('id', function (d) {\\n        return d.id + '-text';\\n      })\\n      .text(function (d) {\\n        return d.task;\\n      })\\n      .attr('font-size', conf.fontSize)\\n      .attr('x', function (d) {\\n        let startX = timeScale(d.startTime);\\n        let endX = timeScale(d.renderEndTime || d.endTime);\\n        if (d.milestone) {\\n          startX += 0.5 * (timeScale(d.endTime) - timeScale(d.startTime)) - 0.5 * theBarHeight;\\n        }\\n        if (d.milestone) {\\n          endX = startX + theBarHeight;\\n        }\\n        const textWidth = this.getBBox().width;\\n\\n        // Check id text width &gt; width of rectangle\\n        if (textWidth &gt; endX - startX) {\\n          if (endX + textWidth + 1.5 * conf.leftPadding &gt; w) {\\n            return startX + theSidePad - 5;\\n          } else {\\n            return endX + theSidePad + 5;\\n          }\\n        } else {\\n          return (endX - startX) / 2 + startX + theSidePad;\\n        }\\n      })\\n      .attr('y', function (d, i) {\\n        // Ignore the incoming i value and use our order instead\\n        i = d.order;\\n        return i * theGap + conf.barHeight / 2 + (conf.fontSize / 2 - 2) + theTopPad;\\n      })\\n      .attr('text-height', theBarHeight)\\n      .attr('class', function (d) {\\n        const startX = timeScale(d.startTime);\\n        let endX = timeScale(d.endTime);\\n        if (d.milestone) {\\n          endX = startX + theBarHeight;\\n        }\\n        const textWidth = this.getBBox().width;\\n\\n        let classStr = '';\\n        if (d.classes.length &gt; 0) {\\n          classStr = d.classes.join(' ');\\n        }\\n\\n        let secNum = 0;\\n        for (let i = 0; i &lt; categories.length; i++) {\\n          if (d.type === categories[i]) {\\n            secNum = i % conf.numberSectionStyles;\\n          }\\n        }\\n\\n        let taskType = '';\\n        if (d.active) {\\n          if (d.crit) {\\n            taskType = 'activeCritText' + secNum;\\n          } else {\\n            taskType = 'activeText' + secNum;\\n          }\\n        }\\n\\n        if (d.done) {\\n          if (d.crit) {\\n            taskType = taskType + ' doneCritText' + secNum;\\n          } else {\\n            taskType = taskType + ' doneText' + secNum;\\n          }\\n        } else {\\n          if (d.crit) {\\n            taskType = taskType + ' critText' + secNum;\\n          }\\n        }\\n\\n        if (d.milestone) {\\n          taskType += ' milestoneText';\\n        }\\n\\n        // Check id text width &gt; width of rectangle\\n        if (textWidth &gt; endX - startX) {\\n          if (endX + textWidth + 1.5 * conf.leftPadding &gt; w) {\\n            return classStr + ' taskTextOutsideLeft taskTextOutside' + secNum + ' ' + taskType;\\n          } else {\\n            return (\\n              classStr +\\n              ' taskTextOutsideRight taskTextOutside' +\\n              secNum +\\n              ' ' +\\n              taskType +\\n              ' width-' +\\n              textWidth\\n            );\\n          }\\n        } else {\\n          return classStr + ' taskText taskText' + secNum + ' ' + taskType + ' width-' + textWidth;\\n        }\\n      });\\n\\n    const securityLevel = getConfig().securityLevel;\\n\\n    // Wrap the tasks in an a tag for working links without javascript\\n    if (securityLevel === 'sandbox') {\\n      let sandboxElement;\\n      sandboxElement = select('#i' + id);\\n      const root = select(sandboxElement.nodes()[0].contentDocument.body);\\n      const doc = sandboxElement.nodes()[0].contentDocument;\\n\\n      rectangles\\n        .filter(function (d) {\\n          return typeof links[d.id] !== 'undefined';\\n        })\\n        .each(function (o) {\\n          var taskRect = doc.querySelector('#' + o.id);\\n          var taskText = doc.querySelector('#' + o.id + '-text');\\n          const oldParent = taskRect.parentNode;\\n          var Link = doc.createElement('a');\\n          Link.setAttribute('xlink:href', links[o.id]);\\n          Link.setAttribute('target', '_top');\\n          oldParent.appendChild(Link);\\n          Link.appendChild(taskRect);\\n          Link.appendChild(taskText);\\n        });\\n    }\\n  }\\n  /**\\n   * @param theGap\\n   * @param theTopPad\\n   * @param theSidePad\\n   * @param w\\n   * @param h\\n   * @param tasks\\n   * @param excludes\\n   * @param includes\\n   */\\n  function drawExcludeDays(theGap, theTopPad, theSidePad, w, h, tasks, excludes, includes) {\\n    const minTime = tasks.reduce(\\n      (min, { startTime }) =&gt; (min ? Math.min(min, startTime) : startTime),\\n      0\\n    );\\n    const maxTime = tasks.reduce((max, { endTime }) =&gt; (max ? Math.max(max, endTime) : endTime), 0);\\n    const dateFormat = parser.yy.getDateFormat();\\n    if (!minTime || !maxTime) return;\\n\\n    const excludeRanges = [];\\n    let range = null;\\n    let d = moment(minTime);\\n    while (d.valueOf() &lt;= maxTime) {\\n      if (parser.yy.isInvalidDate(d, dateFormat, excludes, includes)) {\\n        if (!range) {\\n          range = {\\n            start: d.clone(),\\n            end: d.clone(),\\n          };\\n        } else {\\n          range.end = d.clone();\\n        }\\n      } else {\\n        if (range) {\\n          excludeRanges.push(range);\\n          range = null;\\n        }\\n      }\\n      d.add(1, 'd');\\n    }\\n\\n    const rectangles = svg.append('g').selectAll('rect').data(excludeRanges).enter();\\n\\n    rectangles\\n      .append('rect')\\n      .attr('id', function (d) {\\n        return 'exclude-' + d.start.format('YYYY-MM-DD');\\n      })\\n      .attr('x', function (d) {\\n        return timeScale(d.start) + theSidePad;\\n      })\\n      .attr('y', conf.gridLineStartPadding)\\n      .attr('width', function (d) {\\n        const renderEnd = d.end.clone().add(1, 'day');\\n        return timeScale(renderEnd) - timeScale(d.start);\\n      })\\n      .attr('height', h - theTopPad - conf.gridLineStartPadding)\\n      .attr('transform-origin', function (d, i) {\\n        return (\\n          (\\n            timeScale(d.start) +\\n            theSidePad +\\n            0.5 * (timeScale(d.end) - timeScale(d.start))\\n          ).toString() +\\n          'px ' +\\n          (i * theGap + 0.5 * h).toString() +\\n          'px'\\n        );\\n      })\\n      .attr('class', 'exclude-range');\\n  }\\n\\n  /**\\n   * @param theSidePad\\n   * @param theTopPad\\n   * @param w\\n   * @param h\\n   */\\n  function makeGrid(theSidePad, theTopPad, w, h) {\\n    let bottomXAxis = axisBottom(timeScale)\\n      .tickSize(-h + theTopPad + conf.gridLineStartPadding)\\n      .tickFormat(timeFormat(parser.yy.getAxisFormat() || conf.axisFormat || '%Y-%m-%d'));\\n\\n    svg\\n      .append('g')\\n      .attr('class', 'grid')\\n      .attr('transform', 'translate(' + theSidePad + ', ' + (h - 50) + ')')\\n      .call(bottomXAxis)\\n      .selectAll('text')\\n      .style('text-anchor', 'middle')\\n      .attr('fill', '#000')\\n      .attr('stroke', 'none')\\n      .attr('font-size', 10)\\n      .attr('dy', '1em');\\n\\n    if (ganttDb.topAxisEnabled() || conf.topAxis) {\\n      let topXAxis = axisTop(timeScale)\\n        .tickSize(-h + theTopPad + conf.gridLineStartPadding)\\n        .tickFormat(timeFormat(parser.yy.getAxisFormat() || conf.axisFormat || '%Y-%m-%d'));\\n\\n      svg\\n        .append('g')\\n        .attr('class', 'grid')\\n        .attr('transform', 'translate(' + theSidePad + ', ' + theTopPad + ')')\\n        .call(topXAxis)\\n        .selectAll('text')\\n        .style('text-anchor', 'middle')\\n        .attr('fill', '#000')\\n        .attr('stroke', 'none')\\n        .attr('font-size', 10);\\n      // .attr('dy', '1em');\\n    }\\n  }\\n\\n  /**\\n   * @param theGap\\n   * @param theTopPad\\n   */\\n  function vertLabels(theGap, theTopPad) {\\n    const numOccurances = [];\\n    let prevGap = 0;\\n\\n    for (let i = 0; i &lt; categories.length; i++) {\\n      numOccurances[i] = [categories[i], getCount(categories[i], catsUnfiltered)];\\n    }\\n\\n    svg\\n      .append('g') // without doing this, impossible to put grid lines behind text\\n      .selectAll('text')\\n      .data(numOccurances)\\n      .enter()\\n      .append(function (d) {\\n        const rows = d[0].split(common.lineBreakRegex);\\n        const dy = -(rows.length - 1) / 2;\\n\\n        const svgLabel = doc.createElementNS('http://www.w3.org/2000/svg', 'text');\\n        svgLabel.setAttribute('dy', dy + 'em');\\n\\n        for (let j = 0; j &lt; rows.length; j++) {\\n          const tspan = doc.createElementNS('http://www.w3.org/2000/svg', 'tspan');\\n          tspan.setAttribute('alignment-baseline', 'central');\\n          tspan.setAttribute('x', '10');\\n          if (j &gt; 0) tspan.setAttribute('dy', '1em');\\n          tspan.textContent = rows[j];\\n          svgLabel.appendChild(tspan);\\n        }\\n        return svgLabel;\\n      })\\n      .attr('x', 10)\\n      .attr('y', function (d, i) {\\n        if (i &gt; 0) {\\n          for (let j = 0; j &lt; i; j++) {\\n            prevGap += numOccurances[i - 1][1];\\n            return (d[1] * theGap) / 2 + prevGap * theGap + theTopPad;\\n          }\\n        } else {\\n          return (d[1] * theGap) / 2 + theTopPad;\\n        }\\n      })\\n      .attr('font-size', conf.sectionFontSize)\\n      .attr('font-size', conf.sectionFontSize)\\n      .attr('class', function (d) {\\n        for (let i = 0; i &lt; categories.length; i++) {\\n          if (d[0] === categories[i]) {\\n            return 'sectionTitle sectionTitle' + (i % conf.numberSectionStyles);\\n          }\\n        }\\n        return 'sectionTitle';\\n      });\\n  }\\n\\n  /**\\n   * @param theSidePad\\n   * @param theTopPad\\n   * @param w\\n   * @param h\\n   */\\n  function drawToday(theSidePad, theTopPad, w, h) {\\n    const todayMarker = ganttDb.getTodayMarker();\\n    if (todayMarker === 'off') {\\n      return;\\n    }\\n\\n    const todayG = svg.append('g').attr('class', 'today');\\n    const today = new Date();\\n    const todayLine = todayG.append('line');\\n\\n    todayLine\\n      .attr('x1', timeScale(today) + theSidePad)\\n      .attr('x2', timeScale(today) + theSidePad)\\n      .attr('y1', conf.titleTopMargin)\\n      .attr('y2', h - conf.titleTopMargin)\\n      .attr('class', 'today');\\n\\n    if (todayMarker !== '') {\\n      todayLine.attr('style', todayMarker.replace(/,/g, ';'));\\n    }\\n  }\\n\\n  /**\\n   * From this stackexchange question:\\n   * http://stackoverflow.com/questions/1890203/unique-for-arrays-in-javascript\\n   *\\n   * @param arr\\n   */\\n  function checkUnique(arr) {\\n    const hash = {};\\n    const result = [];\\n    for (let i = 0, l = arr.length; i &lt; l; ++i) {\\n      if (!Object.prototype.hasOwnProperty.call(hash, arr[i])) {\\n        // eslint-disable-line\\n        // it works with objects! in FF, at least\\n        hash[arr[i]] = true;\\n        result.push(arr[i]);\\n      }\\n    }\\n    return result;\\n  }\\n\\n  /**\\n   * From this stackexchange question:\\n   * http://stackoverflow.com/questions/14227981/count-how-many-strings-in-an-array-have-duplicates-in-the-same-array\\n   *\\n   * @param arr\\n   */\\n  function getCounts(arr) {\\n    let i = arr.length; // const to loop over\\n    const obj = {}; // obj to store results\\n    while (i) {\\n      obj[arr[--i]] = (obj[arr[i]] || 0) + 1; // count occurrences\\n    }\\n    return obj;\\n  }\\n\\n  /**\\n   * Get specific from everything\\n   *\\n   * @param word\\n   * @param arr\\n   */\\n  function getCount(word, arr) {\\n    return getCounts(arr)[word] || 0;\\n  }\\n};\\n\\nexport default {\\n  setConf,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import { log } from '../../logger';\\nimport { random } from '../../utils';\\nimport mermaidAPI from '../../mermaidAPI';\\nimport * as configApi from '../../config';\\nimport { getConfig } from '../../config';\\nimport common from '../common/common';\\n\\nlet mainBranchName = getConfig().gitGraph.mainBranchName;\\nlet commits = {};\\nlet head = null;\\nlet branches = {};\\nbranches[mainBranchName] = head;\\nlet curBranch = mainBranchName;\\nlet direction = 'LR';\\nlet seq = 0;\\n\\nfunction getId() {\\n  return random({ length: 7 });\\n}\\n\\nexport const parseDirective = function (statement, context, type) {\\n  mermaidAPI.parseDirective(this, statement, context, type);\\n};\\n\\n// /**\\n//  * @param currentCommit\\n//  * @param otherCommit\\n//  */\\n// function isfastforwardable(currentCommit, otherCommit) {\\n//   log.debug('Entering isfastforwardable:', currentCommit.id, otherCommit.id);\\n//   let cnt = 0;\\n//   while (currentCommit.seq &lt;= otherCommit.seq &amp;&amp; currentCommit !== otherCommit &amp;&amp; cnt &lt; 1000) {\\n//     cnt++;\\n//     // only if other branch has more commits\\n//     if (otherCommit.parent == null) break;\\n//     if (Array.isArray(otherCommit.parent)) {\\n//       log.debug('In merge commit:', otherCommit.parent);\\n//       return (\\n//         isfastforwardable(currentCommit, commits[otherCommit.parent[0]]) ||\\n//         isfastforwardable(currentCommit, commits[otherCommit.parent[1]])\\n//       );\\n//     } else {\\n//       otherCommit = commits[otherCommit.parent];\\n//     }\\n//   }\\n//   log.debug(currentCommit.id, otherCommit.id);\\n//   return currentCommit.id === otherCommit.id;\\n// }\\n\\n/**\\n * @param currentCommit\\n * @param otherCommit\\n */\\n// function isReachableFrom(currentCommit, otherCommit) {\\n//   const currentSeq = currentCommit.seq;\\n//   const otherSeq = otherCommit.seq;\\n//   if (currentSeq &gt; otherSeq) return isfastforwardable(otherCommit, currentCommit);\\n//   return false;\\n// }\\n\\n/**\\n * @param list\\n * @param fn\\n */\\nfunction uniqBy(list, fn) {\\n  const recordMap = Object.create(null);\\n  return list.reduce((out, item) =&gt; {\\n    const key = fn(item);\\n    if (!recordMap[key]) {\\n      recordMap[key] = true;\\n      out.push(item);\\n    }\\n    return out;\\n  }, []);\\n}\\n\\nexport const setDirection = function (dir) {\\n  direction = dir;\\n};\\nlet options = {};\\nexport const setOptions = function (rawOptString) {\\n  log.debug('options str', rawOptString);\\n  rawOptString = rawOptString &amp;&amp; rawOptString.trim();\\n  rawOptString = rawOptString || '{}';\\n  try {\\n    options = JSON.parse(rawOptString);\\n  } catch (e) {\\n    log.error('error while parsing gitGraph options', e.message);\\n  }\\n};\\n\\nexport const getOptions = function () {\\n  return options;\\n};\\n\\nexport const commit = function (msg, id, type, tag) {\\n  log.debug('Entering commit:', msg, id, type, tag);\\n  id = common.sanitizeText(id, configApi.getConfig());\\n  msg = common.sanitizeText(msg, configApi.getConfig());\\n  tag = common.sanitizeText(tag, configApi.getConfig());\\n  const commit = {\\n    id: id ? id : seq + '-' + getId(),\\n    message: msg,\\n    seq: seq++,\\n    type: type ? type : commitType.NORMAL,\\n    tag: tag ? tag : '',\\n    parents: head == null ? [] : [head.id],\\n    branch: curBranch,\\n  };\\n  head = commit;\\n  commits[commit.id] = commit;\\n  branches[curBranch] = commit.id;\\n  log.debug('in pushCommit ' + commit.id);\\n};\\n\\nexport const branch = function (name) {\\n  name = common.sanitizeText(name, configApi.getConfig());\\n  if (typeof branches[name] === 'undefined') {\\n    branches[name] = head != null ? head.id : null;\\n    checkout(name);\\n    log.debug('in createBranch');\\n  } else {\\n    let error = new Error(\\n      'Trying to create an existing branch. (Help: Either use a new name if you want create a new branch or try using \\\"checkout ' +\\n        name +\\n        '\\\")'\\n    );\\n    error.hash = {\\n      text: 'branch ' + name,\\n      token: 'branch ' + name,\\n      line: '1',\\n      loc: { first_line: 1, last_line: 1, first_column: 1, last_column: 1 },\\n      expected: ['\\\"checkout ' + name + '\\\"'],\\n    };\\n    throw error;\\n  }\\n};\\n\\nexport const merge = function (otherBranch) {\\n  otherBranch = common.sanitizeText(otherBranch, configApi.getConfig());\\n  const currentCommit = commits[branches[curBranch]];\\n  const otherCommit = commits[branches[otherBranch]];\\n  if (curBranch === otherBranch) {\\n    let error = new Error('Incorrect usage of \\\"merge\\\". Cannot merge a branch to itself');\\n    error.hash = {\\n      text: 'merge ' + otherBranch,\\n      token: 'merge ' + otherBranch,\\n      line: '1',\\n      loc: { first_line: 1, last_line: 1, first_column: 1, last_column: 1 },\\n      expected: ['branch abc'],\\n    };\\n    throw error;\\n  } else if (typeof currentCommit === 'undefined' || !currentCommit) {\\n    let error = new Error(\\n      'Incorrect usage of \\\"merge\\\". Current branch (' + curBranch + ')has no commits'\\n    );\\n    error.hash = {\\n      text: 'merge ' + otherBranch,\\n      token: 'merge ' + otherBranch,\\n      line: '1',\\n      loc: { first_line: 1, last_line: 1, first_column: 1, last_column: 1 },\\n      expected: ['commit'],\\n    };\\n    throw error;\\n  } else if (typeof branches[otherBranch] === 'undefined') {\\n    let error = new Error(\\n      'Incorrect usage of \\\"merge\\\". Branch to be merged (' + otherBranch + ') does not exist'\\n    );\\n    error.hash = {\\n      text: 'merge ' + otherBranch,\\n      token: 'merge ' + otherBranch,\\n      line: '1',\\n      loc: { first_line: 1, last_line: 1, first_column: 1, last_column: 1 },\\n      expected: ['branch ' + otherBranch],\\n    };\\n    throw error;\\n  } else if (typeof otherCommit === 'undefined' || !otherCommit) {\\n    let error = new Error(\\n      'Incorrect usage of \\\"merge\\\". Branch to be merged (' + otherBranch + ') has no commits'\\n    );\\n    error.hash = {\\n      text: 'merge ' + otherBranch,\\n      token: 'merge ' + otherBranch,\\n      line: '1',\\n      loc: { first_line: 1, last_line: 1, first_column: 1, last_column: 1 },\\n      expected: ['\\\"commit\\\"'],\\n    };\\n    throw error;\\n  } else if (currentCommit === otherCommit) {\\n    let error = new Error('Incorrect usage of \\\"merge\\\". Both branches have same head');\\n    error.hash = {\\n      text: 'merge ' + otherBranch,\\n      token: 'merge ' + otherBranch,\\n      line: '1',\\n      loc: { first_line: 1, last_line: 1, first_column: 1, last_column: 1 },\\n      expected: ['branch abc'],\\n    };\\n    throw error;\\n  }\\n  // if (isReachableFrom(currentCommit, otherCommit)) {\\n  //   log.debug('Already merged');\\n  //   return;\\n  // }\\n  // if (isfastforwardable(currentCommit, otherCommit)) {\\n  //   branches[curBranch] = branches[otherBranch];\\n  //   head = commits[branches[curBranch]];\\n  // } else {\\n  // create merge commit\\n  const commit = {\\n    id: seq + '-' + getId(),\\n    message: 'merged branch ' + otherBranch + ' into ' + curBranch,\\n    seq: seq++,\\n    parents: [head == null ? null : head.id, branches[otherBranch]],\\n    branch: curBranch,\\n    type: commitType.MERGE,\\n  };\\n  head = commit;\\n  commits[commit.id] = commit;\\n  branches[curBranch] = commit.id;\\n  // }\\n  log.debug(branches);\\n  log.debug('in mergeBranch');\\n};\\n\\nexport const checkout = function (branch) {\\n  branch = common.sanitizeText(branch, configApi.getConfig());\\n  if (typeof branches[branch] === 'undefined') {\\n    let error = new Error(\\n      'Trying to checkout branch which is not yet created. (Help try using \\\"branch ' + branch + '\\\")'\\n    );\\n    error.hash = {\\n      text: 'checkout ' + branch,\\n      token: 'checkout ' + branch,\\n      line: '1',\\n      loc: { first_line: 1, last_line: 1, first_column: 1, last_column: 1 },\\n      expected: ['\\\"branch ' + branch + '\\\"'],\\n    };\\n    throw error;\\n    //branches[branch] = head != null ? head.id : null;\\n    //log.debug('in createBranch');\\n  } else {\\n    curBranch = branch;\\n    const id = branches[curBranch];\\n    head = commits[id];\\n  }\\n};\\n\\n// export const reset = function (commitRef) {\\n//   log.debug('in reset', commitRef);\\n//   const ref = commitRef.split(':')[0];\\n//   let parentCount = parseInt(commitRef.split(':')[1]);\\n//   let commit = ref === 'HEAD' ? head : commits[branches[ref]];\\n//   log.debug(commit, parentCount);\\n//   while (parentCount &gt; 0) {\\n//     commit = commits[commit.parent];\\n//     parentCount--;\\n//     if (!commit) {\\n//       const err = 'Critical error - unique parent commit not found during reset';\\n//       log.error(err);\\n//       throw err;\\n//     }\\n//   }\\n//   head = commit;\\n//   branches[curBranch] = commit.id;\\n// };\\n\\n/**\\n * @param arr\\n * @param key\\n * @param newval\\n */\\nfunction upsert(arr, key, newval) {\\n  const index = arr.indexOf(key);\\n  if (index === -1) {\\n    arr.push(newval);\\n  } else {\\n    arr.splice(index, 1, newval);\\n  }\\n}\\n\\n/** @param commitArr */\\nfunction prettyPrintCommitHistory(commitArr) {\\n  const commit = commitArr.reduce((out, commit) =&gt; {\\n    if (out.seq &gt; commit.seq) return out;\\n    return commit;\\n  }, commitArr[0]);\\n  let line = '';\\n  commitArr.forEach(function (c) {\\n    if (c === commit) {\\n      line += '\\\\t*';\\n    } else {\\n      line += '\\\\t|';\\n    }\\n  });\\n  const label = [line, commit.id, commit.seq];\\n  for (let branch in branches) {\\n    if (branches[branch] === commit.id) label.push(branch);\\n  }\\n  log.debug(label.join(' '));\\n  if (commit.parents &amp;&amp; commit.parents.length == 2) {\\n    const newCommit = commits[commit.parents[0]];\\n    upsert(commitArr, commit, newCommit);\\n    commitArr.push(commits[commit.parents[1]]);\\n  } else if (commit.parents.length == 0) {\\n    return;\\n  } else {\\n    const nextCommit = commits[commit.parents];\\n    upsert(commitArr, commit, nextCommit);\\n  }\\n  commitArr = uniqBy(commitArr, (c) =&gt; c.id);\\n  prettyPrintCommitHistory(commitArr);\\n}\\n\\nexport const prettyPrint = function () {\\n  log.debug(commits);\\n  const node = getCommitsArray()[0];\\n  prettyPrintCommitHistory([node]);\\n};\\n\\nexport const clear = function () {\\n  commits = {};\\n  head = null;\\n  let mainBranch = getConfig().gitGraph.mainBranchName;\\n  branches = {};\\n  branches[mainBranch] = null;\\n  curBranch = mainBranch;\\n  seq = 0;\\n};\\n\\nexport const getBranchesAsObjArray = function () {\\n  const branchArr = [];\\n  for (let branch in branches) {\\n    // branchArr.push({ name: branch, commit: commits[branches[branch]] });\\n    branchArr.push({ name: branch });\\n  }\\n  return branchArr;\\n};\\n\\nexport const getBranches = function () {\\n  return branches;\\n};\\nexport const getCommits = function () {\\n  return commits;\\n};\\nexport const getCommitsArray = function () {\\n  const commitArr = Object.keys(commits).map(function (key) {\\n    return commits[key];\\n  });\\n  commitArr.forEach(function (o) {\\n    log.debug(o.id);\\n  });\\n  commitArr.sort((a, b) =&gt; a.seq - b.seq);\\n  return commitArr;\\n};\\nexport const getCurrentBranch = function () {\\n  return curBranch;\\n};\\nexport const getDirection = function () {\\n  return direction;\\n};\\nexport const getHead = function () {\\n  return head;\\n};\\n\\nexport const commitType = {\\n  NORMAL: 0,\\n  REVERSE: 1,\\n  HIGHLIGHT: 2,\\n  MERGE: 3,\\n};\\n\\nexport default {\\n  parseDirective,\\n  getConfig: () =&gt; configApi.getConfig().gitGraph,\\n  setDirection,\\n  setOptions,\\n  getOptions,\\n  commit,\\n  branch,\\n  merge,\\n  checkout,\\n  //reset,\\n  prettyPrint,\\n  clear,\\n  getBranchesAsObjArray,\\n  getBranches,\\n  getCommits,\\n  getCommitsArray,\\n  getCurrentBranch,\\n  getDirection,\\n  getHead,\\n  commitType,\\n};\\n\"</span>,<span class=\"code-string\">\"import { curveBasis, line, select } from 'd3';\\nimport { interpolateToCurve, getStylesFromArray, configureSvgSize } from '../../utils';\\nimport db from './gitGraphAst';\\nimport gitGraphParser from './parser/gitGraph';\\nimport { log } from '../../logger';\\nimport { getConfig } from '../../config';\\nlet allCommitsDict = {};\\nlet branchNum;\\n\\nconst commitType = {\\n  NORMAL: 0,\\n  REVERSE: 1,\\n  HIGHLIGHT: 2,\\n  MERGE: 3,\\n};\\n\\nlet branchPos = {};\\nlet commitPos = {};\\nlet lanes = [];\\nlet maxPos = 0;\\nconst clear = () =&gt; {\\n  branchPos = {};\\n  commitPos = {};\\n  allCommitsDict = {};\\n  maxPos = 0;\\n  lanes = [];\\n};\\n\\n/**\\n * Draws a text, used for labels of the branches\\n *\\n * @param {string} txt The text\\n * @returns {SVGElement}\\n */\\nconst drawText = (txt) =&gt; {\\n  const svgLabel = document.createElementNS('http://www.w3.org/2000/svg', 'text');\\n  let rows = [];\\n\\n  // Handling of new lines in the label\\n  if (typeof txt === 'string') {\\n    rows = txt.split(/\\\\\\\\n|\\\\n|&lt;br\\\\s*\\\\/?&gt;/gi);\\n  } else if (Array.isArray(txt)) {\\n    rows = txt;\\n  } else {\\n    rows = [];\\n  }\\n\\n  for (let j = 0; j &lt; rows.length; j++) {\\n    const tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');\\n    tspan.setAttributeNS('http://www.w3.org/XML/1998/namespace', 'xml:space', 'preserve');\\n    tspan.setAttribute('dy', '1em');\\n    tspan.setAttribute('x', '0');\\n    tspan.setAttribute('class', 'row');\\n    tspan.textContent = rows[j].trim();\\n    svgLabel.appendChild(tspan);\\n  }\\n  /**\\n   * @param svg\\n   * @param selector\\n   */\\n  return svgLabel;\\n};\\n\\n/**\\n * Draws the commits with its symbol and labels. The function has tywo modes, one which only\\n * calculates the positions and one that does the actual drawing. This for a simple way getting the\\n * vertical leyering rcorrect in the graph.\\n *\\n * @param {any} svg\\n * @param {any} commits\\n * @param {any} modifyGraph\\n */\\nconst drawCommits = (svg, commits, modifyGraph) =&gt; {\\n  const gitGraphConfig = getConfig().gitGraph;\\n  const gBullets = svg.append('g').attr('class', 'commit-bullets');\\n  const gLabels = svg.append('g').attr('class', 'commit-labels');\\n  let pos = 0;\\n\\n  const keys = Object.keys(commits);\\n  const sortedKeys = keys.sort((a, b) =&gt; {\\n    return commits[a].seq - commits[b].seq;\\n  });\\n  sortedKeys.forEach((key, index) =&gt; {\\n    const commit = commits[key];\\n\\n    const y = branchPos[commit.branch].pos;\\n    const x = pos + 10;\\n    // Don't draw the commits now but calculate the positioning which is used by the branch lines etc.\\n    if (modifyGraph) {\\n      let typeClass;\\n      switch (commit.type) {\\n        case commitType.NORMAL:\\n          typeClass = 'commit-normal';\\n          break;\\n        case commitType.REVERSE:\\n          typeClass = 'commit-reverse';\\n          break;\\n        case commitType.HIGHLIGHT:\\n          typeClass = 'commit-highlight';\\n          break;\\n        case commitType.MERGE:\\n          typeClass = 'commit-merge';\\n          break;\\n        default:\\n          typeClass = 'commit-normal';\\n      }\\n\\n      if (commit.type === commitType.HIGHLIGHT) {\\n        const circle = gBullets.append('rect');\\n        circle.attr('x', x - 10);\\n        circle.attr('y', y - 10);\\n        circle.attr('height', 20);\\n        circle.attr('width', 20);\\n        circle.attr(\\n          'class',\\n          'commit ' +\\n            commit.id +\\n            ' commit-highlight' +\\n            branchPos[commit.branch].index +\\n            ' ' +\\n            typeClass +\\n            '-outer'\\n        );\\n        gBullets\\n          .append('rect')\\n          .attr('x', x - 6)\\n          .attr('y', y - 6)\\n          .attr('height', 12)\\n          .attr('width', 12)\\n          .attr(\\n            'class',\\n            'commit ' +\\n              commit.id +\\n              ' commit' +\\n              branchPos[commit.branch].index +\\n              ' ' +\\n              typeClass +\\n              '-inner'\\n          );\\n      } else {\\n        const circle = gBullets.append('circle');\\n        circle.attr('cx', x);\\n        circle.attr('cy', y);\\n        circle.attr('r', commit.type === commitType.MERGE ? 9 : 10);\\n        circle.attr('class', 'commit ' + commit.id + ' commit' + branchPos[commit.branch].index);\\n        if (commit.type === commitType.MERGE) {\\n          const circle2 = gBullets.append('circle');\\n          circle2.attr('cx', x);\\n          circle2.attr('cy', y);\\n          circle2.attr('r', 6);\\n          circle2.attr(\\n            'class',\\n            'commit ' + typeClass + ' ' + commit.id + ' commit' + branchPos[commit.branch].index\\n          );\\n        }\\n        if (commit.type === commitType.REVERSE) {\\n          const cross = gBullets.append('path');\\n          cross\\n            .attr('d', `M ${x - 5},${y - 5}L${x + 5},${y + 5}M${x - 5},${y + 5}L${x + 5},${y - 5}`)\\n            .attr(\\n              'class',\\n              'commit ' + typeClass + ' ' + commit.id + ' commit' + branchPos[commit.branch].index\\n            );\\n        }\\n      }\\n    }\\n    commitPos[commit.id] = { x: pos + 10, y: y };\\n\\n    // The first iteration over the commits are for positioning purposes, this\\n    // is required for drawing the lines. The circles and labels is drawn after the labels\\n    // placing them on top of the lines.\\n    if (modifyGraph) {\\n      const px = 4;\\n      const py = 2;\\n      // Draw the commit label\\n      if (commit.type !== commitType.MERGE &amp;&amp; gitGraphConfig.showCommitLabel) {\\n        const labelBkg = gLabels.insert('rect').attr('class', 'commit-label-bkg');\\n\\n        const text = gLabels\\n          .append('text')\\n          .attr('x', pos)\\n          .attr('y', y + 25)\\n          .attr('class', 'commit-label')\\n          .text(commit.id);\\n        let bbox = text.node().getBBox();\\n\\n        // Now we have the label, lets position the background\\n        labelBkg\\n          .attr('x', pos + 10 - bbox.width / 2 - py)\\n          .attr('y', y + 13.5)\\n          .attr('width', bbox.width + 2 * py)\\n          .attr('height', bbox.height + 2 * py);\\n        text.attr('x', pos + 10 - bbox.width / 2);\\n      }\\n      if (commit.tag) {\\n        const rect = gLabels.insert('polygon');\\n        const hole = gLabels.append('circle');\\n        const tag = gLabels\\n          .append('text')\\n          // Note that we are delaying setting the x position until we know the width of the text\\n          .attr('y', y - 16)\\n          .attr('class', 'tag-label')\\n          .text(commit.tag);\\n        let tagBbox = tag.node().getBBox();\\n        tag.attr('x', pos + 10 - tagBbox.width / 2);\\n\\n        const h2 = tagBbox.height / 2;\\n        const ly = y - 19.2;\\n        rect.attr('class', 'tag-label-bkg').attr(\\n          'points',\\n          `\\n          ${pos - tagBbox.width / 2 - px / 2},${ly + py}\\n          ${pos - tagBbox.width / 2 - px / 2},${ly - py}\\n          ${pos + 10 - tagBbox.width / 2 - px},${ly - h2 - py}\\n          ${pos + 10 + tagBbox.width / 2 + px},${ly - h2 - py}\\n          ${pos + 10 + tagBbox.width / 2 + px},${ly + h2 + py}\\n          ${pos + 10 - tagBbox.width / 2 - px},${ly + h2 + py}`\\n        );\\n\\n        hole\\n          .attr('cx', pos - tagBbox.width / 2 + px / 2)\\n          .attr('cy', ly)\\n          .attr('r', 1.5)\\n          .attr('class', 'tag-hole');\\n      }\\n    }\\n    pos += 50;\\n    if (pos &gt; maxPos) {\\n      maxPos = pos;\\n    }\\n  });\\n};\\n\\n/**\\n * Detect if there are other commits between commit1s x-position and commit2s x-position on the same\\n * branch as commit2.\\n *\\n * @param {any} commit1\\n * @param {any} commit2\\n * @param allCommits\\n * @returns\\n */\\nconst hasOverlappingCommits = (commit1, commit2, allCommits) =&gt; {\\n  const commit1Pos = commitPos[commit2.id];\\n  const commit2Pos = commitPos[commit1.id];\\n\\n  // Find commits on the same branch as commit2\\n  const keys = Object.keys(allCommits);\\n  const overlappingComits = keys.filter((key) =&gt; {\\n    return (\\n      allCommits[key].branch === commit2.branch &amp;&amp;\\n      allCommits[key].seq &gt; commit1.seq &amp;&amp;\\n      allCommits[key].seq &lt; commit2.seq\\n    );\\n  });\\n\\n  return overlappingComits.length &gt; 0;\\n};\\n\\n/**\\n * This function find a lane in the y-axis that is not overlapping with any other lanes. This is\\n * used for drawing the lines between commits.\\n *\\n * @param {any} y1\\n * @param {any} y2\\n * @param {any} _depth\\n * @returns\\n */\\nconst findLane = (y1, y2, _depth) =&gt; {\\n  const depth = _depth || 0;\\n\\n  const candidate = y1 + Math.abs(y1 - y2) / 2;\\n  if (depth &gt; 5) {\\n    return candidate;\\n  }\\n\\n  let ok = true;\\n  for (let i = 0; i &lt; lanes.length; i++) {\\n    if (Math.abs(lanes[i] - candidate) &lt; 10) {\\n      ok = false;\\n    }\\n  }\\n  if (ok) {\\n    lanes.push(candidate);\\n    return candidate;\\n  }\\n  const diff = Math.abs(y1 - y2);\\n  return findLane(y1, y2 - diff / 5, depth);\\n};\\n\\n/**\\n * This function draw trhe lines between the commits. They were arrows initially.\\n *\\n * @param {any} svg\\n * @param {any} commit1\\n * @param {any} commit2\\n * @param {any} allCommits\\n */\\nconst drawArrow = (svg, commit1, commit2, allCommits) =&gt; {\\n  const conf = getConfig();\\n\\n  const p1 = commitPos[commit1.id];\\n  const p2 = commitPos[commit2.id];\\n  const overlappingCommits = hasOverlappingCommits(commit1, commit2, allCommits);\\n  // log.debug('drawArrow', p1, p2, overlappingCommits, commit1.id, commit2.id);\\n\\n  let url = '';\\n  if (conf.arrowMarkerAbsolute) {\\n    url =\\n      window.location.protocol +\\n      '//' +\\n      window.location.host +\\n      window.location.pathname +\\n      window.location.search;\\n    url = url.replace(/\\\\(/g, '\\\\\\\\(');\\n    url = url.replace(/\\\\)/g, '\\\\\\\\)');\\n  }\\n\\n  let arc = '';\\n  let arc2 = '';\\n  let radius = 0;\\n  let offset = 0;\\n  let colorClassNum = branchPos[commit2.branch].index;\\n  let lineDef;\\n  if (overlappingCommits) {\\n    arc = 'A 10 10, 0, 0, 0,';\\n    arc2 = 'A 10 10, 0, 0, 1,';\\n    radius = 10;\\n    offset = 10;\\n    // Figure out the color of the arrow,arrows going down take the color from the destination branch\\n    colorClassNum = branchPos[commit2.branch].index;\\n\\n    const lineY = p1.y &lt; p2.y ? findLane(p1.y, p2.y) : findLane(p2.y, p1.y);\\n\\n    if (p1.y &lt; p2.y) {\\n      lineDef = `M ${p1.x} ${p1.y} L ${p1.x} ${lineY - radius} ${arc} ${p1.x + offset} ${lineY} L ${\\n        p2.x - radius\\n      } ${lineY} ${arc2} ${p2.x} ${lineY + offset} L ${p2.x} ${p2.y}`;\\n    } else {\\n      lineDef = `M ${p1.x} ${p1.y} L ${p1.x} ${lineY + radius} ${arc2} ${\\n        p1.x + offset\\n      } ${lineY} L ${p2.x - radius} ${lineY} ${arc} ${p2.x} ${lineY - offset} L ${p2.x} ${p2.y}`;\\n    }\\n  } else {\\n    if (p1.y &lt; p2.y) {\\n      arc = 'A 20 20, 0, 0, 0,';\\n      radius = 20;\\n      offset = 20;\\n\\n      // Figure out the color of the arrow,arrows going down take the color from the destination branch\\n      colorClassNum = branchPos[commit2.branch].index;\\n\\n      lineDef = `M ${p1.x} ${p1.y} L ${p1.x} ${p2.y - radius} ${arc} ${p1.x + offset} ${p2.y} L ${\\n        p2.x\\n      } ${p2.y}`;\\n    }\\n    if (p1.y &gt; p2.y) {\\n      arc = 'A 20 20, 0, 0, 0,';\\n      radius = 20;\\n      offset = 20;\\n\\n      // Arrows going up take the color from the source branch\\n      colorClassNum = branchPos[commit1.branch].index;\\n      lineDef = `M ${p1.x} ${p1.y} L ${p2.x - radius} ${p1.y} ${arc} ${p2.x} ${p1.y - offset} L ${\\n        p2.x\\n      } ${p2.y}`;\\n    }\\n\\n    if (p1.y === p2.y) {\\n      colorClassNum = branchPos[commit1.branch].index;\\n      lineDef = `M ${p1.x} ${p1.y} L ${p1.x} ${p2.y - radius} ${arc} ${p1.x + offset} ${p2.y} L ${\\n        p2.x\\n      } ${p2.y}`;\\n    }\\n  }\\n  const arrow = svg\\n    .append('path')\\n    .attr('d', lineDef)\\n    .attr('class', 'arrow arrow' + colorClassNum);\\n};\\n\\nconst drawArrows = (svg, commits) =&gt; {\\n  const gArrows = svg.append('g').attr('class', 'commit-arrows');\\n  let pos = 0;\\n\\n  const k = Object.keys(commits);\\n  k.forEach((key, index) =&gt; {\\n    const commit = commits[key];\\n    if (commit.parents &amp;&amp; commit.parents.length &gt; 0) {\\n      commit.parents.forEach((parent) =&gt; {\\n        drawArrow(gArrows, commits[parent], commit, commits);\\n      });\\n    }\\n  });\\n};\\n\\n/**\\n * This function adds the branches and the branches' labels to the svg.\\n *\\n * @param svg\\n * @param commitid\\n * @param branches\\n * @param direction\\n */\\nconst drawBranches = (svg, branches) =&gt; {\\n  const gitGraphConfig = getConfig().gitGraph;\\n  const g = svg.append('g');\\n  branches.forEach((branch, index) =&gt; {\\n    const pos = branchPos[branch.name].pos;\\n    const line = g.append('line');\\n    line.attr('x1', 0);\\n    line.attr('y1', pos);\\n    line.attr('x2', maxPos);\\n    line.attr('y2', pos);\\n    line.attr('class', 'branch branch' + index);\\n\\n    lanes.push(pos);\\n\\n    let name = index === 0 ? gitGraphConfig.mainBranchName : branch.name;\\n\\n    // Create the actual text element\\n    const labelElement = drawText(name);\\n    // Create outer g, edgeLabel, this will be positioned after graph layout\\n    const bkg = g.insert('rect');\\n    const branchLabel = g.insert('g').attr('class', 'branchLabel');\\n\\n    // Create inner g, label, this will be positioned now for centering the text\\n    const label = branchLabel.insert('g').attr('class', 'label branch-label' + index);\\n    label.node().appendChild(labelElement);\\n    let bbox = labelElement.getBBox();\\n    bkg\\n      .attr('class', 'branchLabelBkg label' + index)\\n      .attr('rx', 4)\\n      .attr('ry', 4)\\n      .attr('x', -bbox.width - 4)\\n      .attr('y', -bbox.height / 2 + 8)\\n      .attr('width', bbox.width + 18)\\n      .attr('height', bbox.height + 4);\\n\\n    label.attr(\\n      'transform',\\n      'translate(' + (-bbox.width - 14) + ', ' + (pos - bbox.height / 2 - 1) + ')'\\n    );\\n    bkg.attr('transform', 'translate(' + -19 + ', ' + (pos - bbox.height / 2) + ')');\\n  });\\n};\\n\\n/**\\n * @param svg\\n * @param commit\\n * @param direction\\n * @param branchColor\\n * @param txt\\n * @param id\\n * @param ver\\n */\\nexport const draw = function (txt, id, ver) {\\n  clear();\\n  const conf = getConfig();\\n  const gitGraphConfig = getConfig().gitGraph;\\n  // try {\\n  const parser = gitGraphParser.parser;\\n  parser.yy = db;\\n  parser.yy.clear();\\n\\n  log.debug('in gitgraph renderer', txt + '\\\\n', 'id:', id, ver);\\n  // // Parse the graph definition\\n  parser.parse(txt + '\\\\n');\\n\\n  const direction = db.getDirection();\\n  allCommitsDict = db.getCommits();\\n  const branches = db.getBranchesAsObjArray();\\n\\n  // Position branches vertically\\n  let pos = 0;\\n  branches.forEach((branch, index) =&gt; {\\n    branchPos[branch.name] = { pos, index };\\n    pos += 50;\\n  });\\n\\n  const diagram = select(`[id=\\\"${id}\\\"]`);\\n\\n  drawCommits(diagram, allCommitsDict, false);\\n  if (gitGraphConfig.showBranches) {\\n    drawBranches(diagram, branches);\\n  }\\n  drawArrows(diagram, allCommitsDict);\\n  drawCommits(diagram, allCommitsDict, true);\\n\\n  const padding = gitGraphConfig.diagramPadding;\\n  const svgBounds = diagram.node().getBBox();\\n  const width = svgBounds.width + padding * 2;\\n  const height = svgBounds.height + padding * 2;\\n\\n  configureSvgSize(diagram, height, width, conf.useMaxWidth);\\n  const vBox = `${svgBounds.x - padding} ${svgBounds.y - padding} ${width} ${height}`;\\n  diagram.attr('viewBox', vBox);\\n};\\n\\nexport default {\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"/** Created by knut on 15-01-14. */\\nimport { log } from '../../logger';\\n\\nvar message = '';\\nvar info = false;\\n\\nexport const setMessage = (txt) =&gt; {\\n  log.debug('Setting message to: ' + txt);\\n  message = txt;\\n};\\n\\nexport const getMessage = () =&gt; {\\n  return message;\\n};\\n\\nexport const setInfo = (inf) =&gt; {\\n  info = inf;\\n};\\n\\nexport const getInfo = () =&gt; {\\n  return info;\\n};\\n\\n// export const parseError = (err, hash) =&gt; {\\n//   global.mermaidAPI.parseError(err, hash)\\n// }\\n\\nexport default {\\n  setMessage,\\n  getMessage,\\n  setInfo,\\n  getInfo,\\n  // parseError\\n};\\n\"</span>,<span class=\"code-string\">\"/** Created by knut on 14-12-11. */\\nimport { select } from 'd3';\\nimport db from './infoDb';\\nimport infoParser from './parser/info';\\nimport { log } from '../../logger';\\nimport { getConfig } from '../../config';\\n\\nconst conf = {};\\nexport const setConf = function (cnf) {\\n  const keys = Object.keys(cnf);\\n\\n  keys.forEach(function (key) {\\n    conf[key] = cnf[key];\\n  });\\n};\\n\\n/**\\n * Draws a an info picture in the tag with id: id based on the graph definition in text.\\n *\\n * @param {any} text\\n * @param {any} id\\n * @param {any} version\\n */\\nexport const draw = (text, id, version) =&gt; {\\n  try {\\n    const parser = infoParser.parser;\\n    parser.yy = db;\\n    log.debug('Renering info diagram\\\\n' + text);\\n\\n    const securityLevel = getConfig().securityLevel;\\n    // Handle root and ocument for when rendering in sanbox mode\\n    let sandboxElement;\\n    if (securityLevel === 'sandbox') {\\n      sandboxElement = select('#i' + id);\\n    }\\n    const root =\\n      securityLevel === 'sandbox'\\n        ? select(sandboxElement.nodes()[0].contentDocument.body)\\n        : select('body');\\n    const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n\\n    // Parse the graph definition\\n    parser.parse(text);\\n    log.debug('Parsed info diagram');\\n    // Fetch the default direction, use TD if none was found\\n    const svg = root.select('#' + id);\\n\\n    const g = svg.append('g');\\n\\n    g.append('text') // text label for the x axis\\n      .attr('x', 100)\\n      .attr('y', 40)\\n      .attr('class', 'version')\\n      .attr('font-size', '32px')\\n      .style('text-anchor', 'middle')\\n      .text('v ' + version);\\n\\n    svg.attr('height', 100);\\n    svg.attr('width', 400);\\n    // svg.attr('viewBox', '0 0 300 150');\\n  } catch (e) {\\n    log.error('Error while rendering info diagram');\\n    log.error(e.message);\\n  }\\n};\\n\\nexport default {\\n  setConf,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import { log } from '../../logger';\\nimport mermaidAPI from '../../mermaidAPI';\\nimport * as configApi from '../../config';\\nimport common from '../common/common';\\nconst sanitizeText = (txt) =&gt; common.sanitizeText(txt, configApi.getConfig());\\n\\nlet sections = {};\\nlet title = '';\\nlet description = '';\\nlet showData = false;\\n\\nexport const parseDirective = function (statement, context, type) {\\n  mermaidAPI.parseDirective(this, statement, context, type);\\n};\\n\\nconst addSection = function (id, value) {\\n  id = common.sanitizeText(id, configApi.getConfig());\\n  if (typeof sections[id] === 'undefined') {\\n    sections[id] = value;\\n    log.debug('Added new section :', id);\\n  }\\n};\\nconst getSections = () =&gt; sections;\\n\\nconst setTitle = function (txt) {\\n  title = common.sanitizeText(txt, configApi.getConfig());\\n};\\n\\nconst setShowData = function (toggle) {\\n  showData = toggle;\\n};\\n\\nconst getShowData = function () {\\n  return showData;\\n};\\n\\nconst getTitle = function () {\\n  return title;\\n};\\n\\nconst setAccDescription = function (txt) {\\n  description = common.sanitizeText(txt, configApi.getConfig());\\n};\\n\\nconst getAccDescription = function () {\\n  return description;\\n};\\n\\nconst cleanupValue = function (value) {\\n  if (value.substring(0, 1) === ':') {\\n    value = value.substring(1).trim();\\n    return Number(value.trim());\\n  } else {\\n    return Number(value.trim());\\n  }\\n};\\n\\nconst clear = function () {\\n  sections = {};\\n  title = '';\\n  showData = false;\\n};\\n// export const parseError = (err, hash) =&gt; {\\n//   global.mermaidAPI.parseError(err, hash)\\n// }\\n\\nexport default {\\n  parseDirective,\\n  getConfig: () =&gt; configApi.getConfig().pie,\\n  addSection,\\n  getSections,\\n  cleanupValue,\\n  clear,\\n  setTitle,\\n  getTitle,\\n  setShowData,\\n  getShowData,\\n  getAccDescription,\\n  setAccDescription,\\n  // parseError\\n};\\n\"</span>,<span class=\"code-string\">\"/** Created by AshishJ on 11-09-2019. */\\nimport { select, scaleOrdinal, pie as d3pie, arc } from 'd3';\\nimport pieData from './pieDb';\\nimport pieParser from './parser/pie';\\nimport { log } from '../../logger';\\nimport { configureSvgSize } from '../../utils';\\nimport * as configApi from '../../config';\\nimport addSVGAccessibilityFields from '../../accessibility';\\n\\nlet conf = configApi.getConfig();\\n\\n/**\\n * Draws a Pie Chart with the data given in text.\\n *\\n * @param text\\n * @param id\\n */\\nlet width;\\nconst height = 450;\\nexport const draw = (txt, id) =&gt; {\\n  try {\\n    conf = configApi.getConfig();\\n    const parser = pieParser.parser;\\n    parser.yy = pieData;\\n    log.debug('Rendering info diagram\\\\n' + txt);\\n\\n    const securityLevel = configApi.getConfig().securityLevel;\\n    // Handle root and ocument for when rendering in sanbox mode\\n    let sandboxElement;\\n    if (securityLevel === 'sandbox') {\\n      sandboxElement = select('#i' + id);\\n    }\\n    const root =\\n      securityLevel === 'sandbox'\\n        ? select(sandboxElement.nodes()[0].contentDocument.body)\\n        : select('body');\\n    const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n\\n    // Parse the Pie Chart definition\\n    parser.yy.clear();\\n    parser.parse(txt);\\n    log.debug('Parsed info diagram');\\n    const elem = doc.getElementById(id);\\n    width = elem.parentElement.offsetWidth;\\n\\n    if (typeof width === 'undefined') {\\n      width = 1200;\\n    }\\n\\n    if (typeof conf.useWidth !== 'undefined') {\\n      width = conf.useWidth;\\n    }\\n    if (typeof conf.pie.useWidth !== 'undefined') {\\n      width = conf.pie.useWidth;\\n    }\\n\\n    const diagram = root.select('#' + id);\\n    configureSvgSize(diagram, height, width, conf.pie.useMaxWidth);\\n\\n    addSVGAccessibilityFields(parser.yy, diagram, id);\\n    // Set viewBox\\n    elem.setAttribute('viewBox', '0 0 ' + width + ' ' + height);\\n\\n    // Fetch the default direction, use TD if none was found\\n    var margin = 40;\\n    var legendRectSize = 18;\\n    var legendSpacing = 4;\\n\\n    var radius = Math.min(width, height) / 2 - margin;\\n\\n    var svg = diagram\\n      .append('g')\\n      .attr('transform', 'translate(' + width / 2 + ',' + height / 2 + ')');\\n\\n    var data = pieData.getSections();\\n    var sum = 0;\\n    Object.keys(data).forEach(function (key) {\\n      sum += data[key];\\n    });\\n\\n    const themeVariables = conf.themeVariables;\\n    var myGeneratedColors = [\\n      themeVariables.pie1,\\n      themeVariables.pie2,\\n      themeVariables.pie3,\\n      themeVariables.pie4,\\n      themeVariables.pie5,\\n      themeVariables.pie6,\\n      themeVariables.pie7,\\n      themeVariables.pie8,\\n      themeVariables.pie9,\\n      themeVariables.pie10,\\n      themeVariables.pie11,\\n      themeVariables.pie12,\\n    ];\\n\\n    // Set the color scale\\n    var color = scaleOrdinal().range(myGeneratedColors);\\n\\n    // Compute the position of each group on the pie:\\n    var pie = d3pie().value(function (d) {\\n      return d[1];\\n    });\\n    var dataReady = pie(Object.entries(data));\\n\\n    // Shape helper to build arcs:\\n    var arcGenerator = arc().innerRadius(0).outerRadius(radius);\\n\\n    // Build the pie chart: each part of the pie is a path that we build using the arc function.\\n    svg\\n      .selectAll('mySlices')\\n      .data(dataReady)\\n      .enter()\\n      .append('path')\\n      .attr('d', arcGenerator)\\n      .attr('fill', function (d) {\\n        return color(d.data[0]);\\n      })\\n      .attr('class', 'pieCircle');\\n\\n    // Now add the percentage.\\n    // Use the centroid method to get the best coordinates.\\n    svg\\n      .selectAll('mySlices')\\n      .data(dataReady)\\n      .enter()\\n      .append('text')\\n      .text(function (d) {\\n        return ((d.data[1] / sum) * 100).toFixed(0) + '%';\\n      })\\n      .attr('transform', function (d) {\\n        return 'translate(' + arcGenerator.centroid(d) + ')';\\n      })\\n      .style('text-anchor', 'middle')\\n      .attr('class', 'slice');\\n\\n    svg\\n      .append('text')\\n      .text(parser.yy.getTitle())\\n      .attr('x', 0)\\n      .attr('y', -(height - 50) / 2)\\n      .attr('class', 'pieTitleText');\\n\\n    // Add the legends/annotations for each section\\n    var legend = svg\\n      .selectAll('.legend')\\n      .data(color.domain())\\n      .enter()\\n      .append('g')\\n      .attr('class', 'legend')\\n      .attr('transform', function (d, i) {\\n        var height = legendRectSize + legendSpacing;\\n        var offset = (height * color.domain().length) / 2;\\n        var horz = 12 * legendRectSize;\\n        var vert = i * height - offset;\\n        return 'translate(' + horz + ',' + vert + ')';\\n      });\\n\\n    legend\\n      .append('rect')\\n      .attr('width', legendRectSize)\\n      .attr('height', legendRectSize)\\n      .style('fill', color)\\n      .style('stroke', color);\\n\\n    legend\\n      .data(dataReady)\\n      .append('text')\\n      .attr('x', legendRectSize + legendSpacing)\\n      .attr('y', legendRectSize - legendSpacing)\\n      .text(function (d) {\\n        if (parser.yy.getShowData() || conf.showData || conf.pie.showData) {\\n          return d.data[0] + ' [' + d.data[1] + ']';\\n        } else {\\n          return d.data[0];\\n        }\\n      });\\n  } catch (e) {\\n    log.error('Error while rendering info diagram');\\n    log.error(e);\\n  }\\n};\\n\\nexport default {\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import array from \\\"./array.js\\\";\\nimport constant from \\\"./constant.js\\\";\\nimport descending from \\\"./descending.js\\\";\\nimport identity from \\\"./identity.js\\\";\\nimport {tau} from \\\"./math.js\\\";\\n\\nexport default function() {\\n  var value = identity,\\n      sortValues = descending,\\n      sort = null,\\n      startAngle = constant(0),\\n      endAngle = constant(tau),\\n      padAngle = constant(0);\\n\\n  function pie(data) {\\n    var i,\\n        n = (data = array(data)).length,\\n        j,\\n        k,\\n        sum = 0,\\n        index = new Array(n),\\n        arcs = new Array(n),\\n        a0 = +startAngle.apply(this, arguments),\\n        da = Math.min(tau, Math.max(-tau, endAngle.apply(this, arguments) - a0)),\\n        a1,\\n        p = Math.min(Math.abs(da) / n, padAngle.apply(this, arguments)),\\n        pa = p * (da &lt; 0 ? -1 : 1),\\n        v;\\n\\n    for (i = 0; i &lt; n; ++i) {\\n      if ((v = arcs[index[i] = i] = +value(data[i], i, data)) &gt; 0) {\\n        sum += v;\\n      }\\n    }\\n\\n    // Optionally sort the arcs by previously-computed values or by data.\\n    if (sortValues != null) index.sort(function(i, j) { return sortValues(arcs[i], arcs[j]); });\\n    else if (sort != null) index.sort(function(i, j) { return sort(data[i], data[j]); });\\n\\n    // Compute the arcs! They are stored in the original data's order.\\n    for (i = 0, k = sum ? (da - n * pa) / sum : 0; i &lt; n; ++i, a0 = a1) {\\n      j = index[i], v = arcs[j], a1 = a0 + (v &gt; 0 ? v * k : 0) + pa, arcs[j] = {\\n        data: data[j],\\n        index: i,\\n        value: v,\\n        startAngle: a0,\\n        endAngle: a1,\\n        padAngle: p\\n      };\\n    }\\n\\n    return arcs;\\n  }\\n\\n  pie.value = function(_) {\\n    return arguments.length ? (value = typeof _ === \\\"function\\\" ? _ : constant(+_), pie) : value;\\n  };\\n\\n  pie.sortValues = function(_) {\\n    return arguments.length ? (sortValues = _, sort = null, pie) : sortValues;\\n  };\\n\\n  pie.sort = function(_) {\\n    return arguments.length ? (sort = _, sortValues = null, pie) : sort;\\n  };\\n\\n  pie.startAngle = function(_) {\\n    return arguments.length ? (startAngle = typeof _ === \\\"function\\\" ? _ : constant(+_), pie) : startAngle;\\n  };\\n\\n  pie.endAngle = function(_) {\\n    return arguments.length ? (endAngle = typeof _ === \\\"function\\\" ? _ : constant(+_), pie) : endAngle;\\n  };\\n\\n  pie.padAngle = function(_) {\\n    return arguments.length ? (padAngle = typeof _ === \\\"function\\\" ? _ : constant(+_), pie) : padAngle;\\n  };\\n\\n  return pie;\\n}\\n\"</span>,<span class=\"code-string\">\"import * as configApi from '../../config';\\nimport { log } from '../../logger';\\nimport mermaidAPI from '../../mermaidAPI';\\n\\nlet relations = [];\\nlet latestRequirement = {};\\nlet requirements = {};\\nlet latestElement = {};\\nlet elements = {};\\n\\nconst RequirementType = {\\n  REQUIREMENT: 'Requirement',\\n  FUNCTIONAL_REQUIREMENT: 'Functional Requirement',\\n  INTERFACE_REQUIREMENT: 'Interface Requirement',\\n  PERFORMANCE_REQUIREMENT: 'Performance Requirement',\\n  PHYSICAL_REQUIREMENT: 'Physical Requirement',\\n  DESIGN_CONSTRAINT: 'Design Constraint',\\n};\\n\\nconst RiskLevel = {\\n  LOW_RISK: 'Low',\\n  MED_RISK: 'Medium',\\n  HIGH_RISK: 'High',\\n};\\n\\nconst VerifyType = {\\n  VERIFY_ANALYSIS: 'Analysis',\\n  VERIFY_DEMONSTRATION: 'Demonstration',\\n  VERIFY_INSPECTION: 'Inspection',\\n  VERIFY_TEST: 'Test',\\n};\\n\\nconst Relationships = {\\n  CONTAINS: 'contains',\\n  COPIES: 'copies',\\n  DERIVES: 'derives',\\n  SATISFIES: 'satisfies',\\n  VERIFIES: 'verifies',\\n  REFINES: 'refines',\\n  TRACES: 'traces',\\n};\\n\\nexport const parseDirective = function (statement, context, type) {\\n  mermaidAPI.parseDirective(this, statement, context, type);\\n};\\n\\nconst addRequirement = (name, type) =&gt; {\\n  if (typeof requirements[name] === 'undefined') {\\n    requirements[name] = {\\n      name,\\n      type,\\n\\n      id: latestRequirement.id,\\n      text: latestRequirement.text,\\n      risk: latestRequirement.risk,\\n      verifyMethod: latestRequirement.verifyMethod,\\n    };\\n  }\\n  latestRequirement = {};\\n\\n  return requirements[name];\\n};\\n\\nconst getRequirements = () =&gt; requirements;\\n\\nconst setNewReqId = (id) =&gt; {\\n  if (typeof latestRequirement != 'undefined') {\\n    latestRequirement.id = id;\\n  }\\n};\\n\\nconst setNewReqText = (text) =&gt; {\\n  if (typeof latestRequirement != 'undefined') {\\n    latestRequirement.text = text;\\n  }\\n};\\n\\nconst setNewReqRisk = (risk) =&gt; {\\n  if (typeof latestRequirement != 'undefined') {\\n    latestRequirement.risk = risk;\\n  }\\n};\\n\\nconst setNewReqVerifyMethod = (verifyMethod) =&gt; {\\n  if (typeof latestRequirement != 'undefined') {\\n    latestRequirement.verifyMethod = verifyMethod;\\n  }\\n};\\n\\nconst addElement = (name) =&gt; {\\n  if (typeof elements[name] === 'undefined') {\\n    elements[name] = {\\n      name,\\n\\n      type: latestElement.type,\\n      docRef: latestElement.docRef,\\n    };\\n    log.info('Added new requirement: ', name);\\n  }\\n  latestElement = {};\\n\\n  return elements[name];\\n};\\n\\nconst getElements = () =&gt; elements;\\n\\nconst setNewElementType = (type) =&gt; {\\n  if (typeof latestElement != 'undefined') {\\n    latestElement.type = type;\\n  }\\n};\\n\\nconst setNewElementDocRef = (docRef) =&gt; {\\n  if (typeof latestElement != 'undefined') {\\n    latestElement.docRef = docRef;\\n  }\\n};\\n\\nconst addRelationship = (type, src, dst) =&gt; {\\n  relations.push({\\n    type,\\n    src,\\n    dst,\\n  });\\n};\\n\\nconst getRelationships = () =&gt; relations;\\n\\nconst clear = () =&gt; {\\n  relations = [];\\n  latestRequirement = {};\\n  requirements = {};\\n  latestElement = {};\\n  elements = {};\\n};\\n\\nexport default {\\n  RequirementType,\\n  RiskLevel,\\n  VerifyType,\\n  Relationships,\\n\\n  parseDirective,\\n  getConfig: () =&gt; configApi.getConfig().req,\\n\\n  addRequirement,\\n  getRequirements,\\n  setNewReqId,\\n  setNewReqText,\\n  setNewReqRisk,\\n  setNewReqVerifyMethod,\\n\\n  addElement,\\n  getElements,\\n  setNewElementType,\\n  setNewElementDocRef,\\n\\n  addRelationship,\\n  getRelationships,\\n\\n  clear,\\n};\\n\"</span>,<span class=\"code-string\">\"const ReqMarkers = {\\n  CONTAINS: 'contains',\\n  ARROW: 'arrow',\\n};\\n\\nconst insertLineEndings = (parentNode, conf) =&gt; {\\n  let containsNode = parentNode\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', ReqMarkers.CONTAINS + '_line_ending')\\n    .attr('refX', 0)\\n    .attr('refY', conf.line_height / 2)\\n    .attr('markerWidth', conf.line_height)\\n    .attr('markerHeight', conf.line_height)\\n    .attr('orient', 'auto')\\n    .append('g');\\n\\n  containsNode\\n    .append('circle')\\n    .attr('cx', conf.line_height / 2)\\n    .attr('cy', conf.line_height / 2)\\n    .attr('r', conf.line_height / 2)\\n    // .attr('stroke', conf.rect_border_color)\\n    // .attr('stroke-width', 1)\\n    .attr('fill', 'none');\\n\\n  containsNode\\n    .append('line')\\n    .attr('x1', 0)\\n    .attr('x2', conf.line_height)\\n    .attr('y1', conf.line_height / 2)\\n    .attr('y2', conf.line_height / 2)\\n    // .attr('stroke', conf.rect_border_color)\\n    .attr('stroke-width', 1);\\n\\n  containsNode\\n    .append('line')\\n    .attr('y1', 0)\\n    .attr('y2', conf.line_height)\\n    .attr('x1', conf.line_height / 2)\\n    .attr('x2', conf.line_height / 2)\\n    // .attr('stroke', conf.rect_border_color)\\n    .attr('stroke-width', 1);\\n\\n  parentNode\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', ReqMarkers.ARROW + '_line_ending')\\n    .attr('refX', conf.line_height)\\n    .attr('refY', 0.5 * conf.line_height)\\n    .attr('markerWidth', conf.line_height)\\n    .attr('markerHeight', conf.line_height)\\n    .attr('orient', 'auto')\\n    .append('path')\\n    .attr(\\n      'd',\\n      `M0,0\\n      L${conf.line_height},${conf.line_height / 2}\\n      M${conf.line_height},${conf.line_height / 2}\\n      L0,${conf.line_height}`\\n    )\\n    .attr('stroke-width', 1);\\n  // .attr('stroke', conf.rect_border_color);\\n};\\n\\nexport default {\\n  ReqMarkers,\\n  insertLineEndings,\\n};\\n\"</span>,<span class=\"code-string\">\"import { line, select } from 'd3';\\nimport dagre from 'dagre';\\nimport graphlib from 'graphlib';\\n// import * as configApi from '../../config';\\nimport { log } from '../../logger';\\nimport { configureSvgSize } from '../../utils';\\nimport common from '../common/common';\\nimport { parser } from './parser/requirementDiagram';\\nimport requirementDb from './requirementDb';\\nimport markers from './requirementMarkers';\\nimport { getConfig } from '../../config';\\n\\nconst conf = {};\\nlet relCnt = 0;\\n\\nexport const setConf = function (cnf) {\\n  if (typeof cnf === 'undefined') {\\n    return;\\n  }\\n  const keys = Object.keys(cnf);\\n  for (let i = 0; i &lt; keys.length; i++) {\\n    conf[keys[i]] = cnf[keys[i]];\\n  }\\n};\\n\\nconst newRectNode = (parentNode, id) =&gt; {\\n  return parentNode\\n    .insert('rect', '#' + id)\\n    .attr('class', 'req reqBox')\\n    .attr('x', 0)\\n    .attr('y', 0)\\n    .attr('width', conf.rect_min_width + 'px')\\n    .attr('height', conf.rect_min_height + 'px');\\n};\\n\\nconst newTitleNode = (parentNode, id, txts) =&gt; {\\n  let x = conf.rect_min_width / 2;\\n\\n  let title = parentNode\\n    .append('text')\\n    .attr('class', 'req reqLabel reqTitle')\\n    .attr('id', id)\\n    .attr('x', x)\\n    .attr('y', conf.rect_padding)\\n    .attr('dominant-baseline', 'hanging');\\n  // .attr(\\n  //   'style',\\n  //   'font-family: ' + configApi.getConfig().fontFamily + '; font-size: ' + conf.fontSize + 'px'\\n  // )\\n  let i = 0;\\n  txts.forEach((textStr) =&gt; {\\n    if (i == 0) {\\n      title\\n        .append('tspan')\\n        .attr('text-anchor', 'middle')\\n        .attr('x', conf.rect_min_width / 2)\\n        .attr('dy', 0)\\n        .text(textStr);\\n    } else {\\n      title\\n        .append('tspan')\\n        .attr('text-anchor', 'middle')\\n        .attr('x', conf.rect_min_width / 2)\\n        .attr('dy', conf.line_height * 0.75)\\n        .text(textStr);\\n    }\\n    i++;\\n  });\\n\\n  let yPadding = 1.5 * conf.rect_padding;\\n  let linePadding = i * conf.line_height * 0.75;\\n  let totalY = yPadding + linePadding;\\n\\n  parentNode\\n    .append('line')\\n    .attr('class', 'req-title-line')\\n    .attr('x1', '0')\\n    .attr('x2', conf.rect_min_width)\\n    .attr('y1', totalY)\\n    .attr('y2', totalY);\\n\\n  return {\\n    titleNode: title,\\n    y: totalY,\\n  };\\n};\\n\\nconst newBodyNode = (parentNode, id, txts, yStart) =&gt; {\\n  let body = parentNode\\n    .append('text')\\n    .attr('class', 'req reqLabel')\\n    .attr('id', id)\\n    .attr('x', conf.rect_padding)\\n    .attr('y', yStart)\\n    .attr('dominant-baseline', 'hanging');\\n  // .attr(\\n  //   'style',\\n  //   'font-family: ' + configApi.getConfig().fontFamily + '; font-size: ' + conf.fontSize + 'px'\\n  // );\\n\\n  let currentRow = 0;\\n  const charLimit = 30;\\n  let wrappedTxts = [];\\n  txts.forEach((textStr) =&gt; {\\n    let currentTextLen = textStr.length;\\n    while (currentTextLen &gt; charLimit &amp;&amp; currentRow &lt; 3) {\\n      let firstPart = textStr.substring(0, charLimit);\\n      textStr = textStr.substring(charLimit, textStr.length);\\n      currentTextLen = textStr.length;\\n      wrappedTxts[wrappedTxts.length] = firstPart;\\n      currentRow++;\\n    }\\n    if (currentRow == 3) {\\n      let lastStr = wrappedTxts[wrappedTxts.length - 1];\\n      wrappedTxts[wrappedTxts.length - 1] = lastStr.substring(0, lastStr.length - 4) + '...';\\n    } else {\\n      wrappedTxts[wrappedTxts.length] = textStr;\\n    }\\n    currentRow = 0;\\n  });\\n\\n  wrappedTxts.forEach((textStr) =&gt; {\\n    body.append('tspan').attr('x', conf.rect_padding).attr('dy', conf.line_height).text(textStr);\\n  });\\n\\n  return body;\\n};\\n\\nconst addEdgeLabel = (parentNode, svgPath, conf, txt) =&gt; {\\n  // Find the half-way point\\n  const len = svgPath.node().getTotalLength();\\n  const labelPoint = svgPath.node().getPointAtLength(len * 0.5);\\n\\n  // Append a text node containing the label\\n  const labelId = 'rel' + relCnt;\\n  relCnt++;\\n\\n  const labelNode = parentNode\\n    .append('text')\\n    .attr('class', 'req relationshipLabel')\\n    .attr('id', labelId)\\n    .attr('x', labelPoint.x)\\n    .attr('y', labelPoint.y)\\n    .attr('text-anchor', 'middle')\\n    .attr('dominant-baseline', 'middle')\\n    // .attr('style', 'font-family: ' + conf.fontFamily + '; font-size: ' + conf.fontSize + 'px')\\n    .text(txt);\\n\\n  // Figure out how big the opaque 'container' rectangle needs to be\\n  const labelBBox = labelNode.node().getBBox();\\n\\n  // Insert the opaque rectangle before the text label\\n  parentNode\\n    .insert('rect', '#' + labelId)\\n    .attr('class', 'req reqLabelBox')\\n    .attr('x', labelPoint.x - labelBBox.width / 2)\\n    .attr('y', labelPoint.y - labelBBox.height / 2)\\n    .attr('width', labelBBox.width)\\n    .attr('height', labelBBox.height)\\n    .attr('fill', 'white')\\n    .attr('fill-opacity', '85%');\\n};\\n\\nconst drawRelationshipFromLayout = function (svg, rel, g, insert) {\\n  // Find the edge relating to this relationship\\n  const edge = g.edge(elementString(rel.src), elementString(rel.dst));\\n\\n  // Get a function that will generate the line path\\n  const lineFunction = line()\\n    .x(function (d) {\\n      return d.x;\\n    })\\n    .y(function (d) {\\n      return d.y;\\n    });\\n\\n  // Insert the line at the right place\\n  const svgPath = svg\\n    .insert('path', '#' + insert)\\n    .attr('class', 'er relationshipLine')\\n    .attr('d', lineFunction(edge.points))\\n    .attr('fill', 'none');\\n\\n  if (rel.type == requirementDb.Relationships.CONTAINS) {\\n    svgPath.attr(\\n      'marker-start',\\n      'url(' + common.getUrl(conf.arrowMarkerAbsolute) + '#' + rel.type + '_line_ending' + ')'\\n    );\\n  } else {\\n    svgPath.attr('stroke-dasharray', '10,7');\\n    svgPath.attr(\\n      'marker-end',\\n      'url(' +\\n        common.getUrl(conf.arrowMarkerAbsolute) +\\n        '#' +\\n        markers.ReqMarkers.ARROW +\\n        '_line_ending' +\\n        ')'\\n    );\\n  }\\n\\n  addEdgeLabel(svg, svgPath, conf, `&lt;&lt;${rel.type}&gt;&gt;`);\\n\\n  return;\\n};\\n\\nexport const drawReqs = (reqs, graph, svgNode) =&gt; {\\n  Object.keys(reqs).forEach((reqName) =&gt; {\\n    let req = reqs[reqName];\\n    reqName = elementString(reqName);\\n    log.info('Added new requirement: ', reqName);\\n\\n    const groupNode = svgNode.append('g').attr('id', reqName);\\n    const textId = 'req-' + reqName;\\n    const rectNode = newRectNode(groupNode, textId);\\n\\n    let nodes = [];\\n\\n    let titleNodeInfo = newTitleNode(groupNode, reqName + '_title', [\\n      `&lt;&lt;${req.type}&gt;&gt;`,\\n      `${req.name}`,\\n    ]);\\n\\n    nodes.push(titleNodeInfo.titleNode);\\n\\n    let bodyNode = newBodyNode(\\n      groupNode,\\n      reqName + '_body',\\n      [\\n        `Id: ${req.id}`,\\n        `Text: ${req.text}`,\\n        `Risk: ${req.risk}`,\\n        `Verification: ${req.verifyMethod}`,\\n      ],\\n      titleNodeInfo.y\\n    );\\n\\n    nodes.push(bodyNode);\\n\\n    const rectBBox = rectNode.node().getBBox();\\n\\n    // Add the entity to the graph\\n    graph.setNode(reqName, {\\n      width: rectBBox.width,\\n      height: rectBBox.height,\\n      shape: 'rect',\\n      id: reqName,\\n    });\\n  });\\n};\\n\\nexport const drawElements = (els, graph, svgNode) =&gt; {\\n  Object.keys(els).forEach((elName) =&gt; {\\n    let el = els[elName];\\n    const id = elementString(elName);\\n\\n    const groupNode = svgNode.append('g').attr('id', id);\\n    const textId = 'element-' + id;\\n    const rectNode = newRectNode(groupNode, textId);\\n\\n    let nodes = [];\\n\\n    let titleNodeInfo = newTitleNode(groupNode, textId + '_title', [`&lt;&lt;Element&gt;&gt;`, `${elName}`]);\\n\\n    nodes.push(titleNodeInfo.titleNode);\\n\\n    let bodyNode = newBodyNode(\\n      groupNode,\\n      textId + '_body',\\n      [`Type: ${el.type || 'Not Specified'}`, `Doc Ref: ${el.docRef || 'None'}`],\\n      titleNodeInfo.y\\n    );\\n\\n    nodes.push(bodyNode);\\n\\n    const rectBBox = rectNode.node().getBBox();\\n\\n    // Add the entity to the graph\\n    graph.setNode(id, {\\n      width: rectBBox.width,\\n      height: rectBBox.height,\\n      shape: 'rect',\\n      id: id,\\n    });\\n  });\\n};\\n\\nconst addRelationships = (relationships, g) =&gt; {\\n  relationships.forEach(function (r) {\\n    let src = elementString(r.src);\\n    let dst = elementString(r.dst);\\n    g.setEdge(src, dst, { relationship: r });\\n  });\\n  return relationships;\\n};\\n\\nconst adjustEntities = function (svgNode, graph) {\\n  graph.nodes().forEach(function (v) {\\n    if (typeof v !== 'undefined' &amp;&amp; typeof graph.node(v) !== 'undefined') {\\n      svgNode.select('#' + v);\\n      svgNode\\n        .select('#' + v)\\n        .attr(\\n          'transform',\\n          'translate(' +\\n            (graph.node(v).x - graph.node(v).width / 2) +\\n            ',' +\\n            (graph.node(v).y - graph.node(v).height / 2) +\\n            ' )'\\n        );\\n    }\\n  });\\n  return;\\n};\\n\\nconst elementString = (str) =&gt; {\\n  return str.replace(/\\\\s/g, '').replace(/\\\\./g, '_');\\n};\\n\\nexport const draw = (text, id) =&gt; {\\n  parser.yy = requirementDb;\\n  parser.yy.clear();\\n  parser.parse(text);\\n\\n  const securityLevel = getConfig().securityLevel;\\n  // Handle root and ocument for when rendering in sanbox mode\\n  let sandboxElement;\\n  if (securityLevel === 'sandbox') {\\n    sandboxElement = select('#i' + id);\\n  }\\n  const root =\\n    securityLevel === 'sandbox'\\n      ? select(sandboxElement.nodes()[0].contentDocument.body)\\n      : select('body');\\n  const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n\\n  const svg = root.select(`[id='${id}']`);\\n  markers.insertLineEndings(svg, conf);\\n\\n  const g = new graphlib.Graph({\\n    multigraph: false,\\n    compound: false,\\n    directed: true,\\n  })\\n    .setGraph({\\n      rankdir: conf.layoutDirection,\\n      marginx: 20,\\n      marginy: 20,\\n      nodesep: 100,\\n      edgesep: 100,\\n      ranksep: 100,\\n    })\\n    .setDefaultEdgeLabel(function () {\\n      return {};\\n    });\\n\\n  let requirements = requirementDb.getRequirements();\\n  let elements = requirementDb.getElements();\\n  let relationships = requirementDb.getRelationships();\\n\\n  drawReqs(requirements, g, svg);\\n  drawElements(elements, g, svg);\\n  addRelationships(relationships, g);\\n  dagre.layout(g);\\n  adjustEntities(svg, g);\\n\\n  relationships.forEach(function (rel) {\\n    drawRelationshipFromLayout(svg, rel, g, id);\\n  });\\n\\n  // svg.attr('height', '500px');\\n  const padding = conf.rect_padding;\\n  const svgBounds = svg.node().getBBox();\\n  const width = svgBounds.width + padding * 2;\\n  const height = svgBounds.height + padding * 2;\\n\\n  configureSvgSize(svg, height, width, conf.useMaxWidth);\\n\\n  svg.attr('viewBox', `${svgBounds.x - padding} ${svgBounds.y - padding} ${width} ${height}`);\\n};\\n\\nexport default {\\n  setConf,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import mermaidAPI from '../../mermaidAPI';\\nimport * as configApi from '../../config';\\nimport { log } from '../../logger';\\nimport { sanitizeText } from '../common/common';\\n\\nlet prevActor = undefined;\\nlet actors = {};\\nlet messages = [];\\nconst notes = [];\\nlet title = '';\\nlet description = '';\\nlet sequenceNumbersEnabled = false;\\nlet wrapEnabled = false;\\n\\nexport const parseDirective = function (statement, context, type) {\\n  mermaidAPI.parseDirective(this, statement, context, type);\\n};\\n\\nexport const addActor = function (id, name, description, type) {\\n  // Don't allow description nulling\\n  const old = actors[id];\\n  if (old &amp;&amp; name === old.name &amp;&amp; description == null) return;\\n\\n  // Don't allow null descriptions, either\\n  if (description == null || description.text == null) {\\n    description = { text: name, wrap: null, type };\\n  }\\n  if (type == null || description.text == null) {\\n    description = { text: name, wrap: null, type };\\n  }\\n\\n  actors[id] = {\\n    name: name,\\n    description: description.text,\\n    wrap: (description.wrap === undefined &amp;&amp; autoWrap()) || !!description.wrap,\\n    prevActor: prevActor,\\n    links: {},\\n    properties: {},\\n    actorCnt: null,\\n    rectData: null,\\n    type: type || 'participant',\\n  };\\n  if (prevActor &amp;&amp; actors[prevActor]) {\\n    actors[prevActor].nextActor = id;\\n  }\\n\\n  prevActor = id;\\n};\\n\\nconst activationCount = (part) =&gt; {\\n  let i;\\n  let count = 0;\\n  for (i = 0; i &lt; messages.length; i++) {\\n    if (messages[i].type === LINETYPE.ACTIVE_START) {\\n      if (messages[i].from.actor === part) {\\n        count++;\\n      }\\n    }\\n    if (messages[i].type === LINETYPE.ACTIVE_END) {\\n      if (messages[i].from.actor === part) {\\n        count--;\\n      }\\n    }\\n  }\\n  return count;\\n};\\n\\nexport const addMessage = function (idFrom, idTo, message, answer) {\\n  messages.push({\\n    from: idFrom,\\n    to: idTo,\\n    message: message.text,\\n    wrap: (message.wrap === undefined &amp;&amp; autoWrap()) || !!message.wrap,\\n    answer: answer,\\n  });\\n};\\n\\nexport const addSignal = function (\\n  idFrom,\\n  idTo,\\n  message = { text: undefined, wrap: undefined },\\n  messageType\\n) {\\n  if (messageType === LINETYPE.ACTIVE_END) {\\n    const cnt = activationCount(idFrom.actor);\\n    if (cnt &lt; 1) {\\n      // Bail out as there is an activation signal from an inactive participant\\n      let error = new Error('Trying to inactivate an inactive participant (' + idFrom.actor + ')');\\n      error.hash = {\\n        text: '-&gt;&gt;-',\\n        token: '-&gt;&gt;-',\\n        line: '1',\\n        loc: { first_line: 1, last_line: 1, first_column: 1, last_column: 1 },\\n        expected: [\\\"'ACTIVE_PARTICIPANT'\\\"],\\n      };\\n      throw error;\\n    }\\n  }\\n  messages.push({\\n    from: idFrom,\\n    to: idTo,\\n    message: message.text,\\n    wrap: (message.wrap === undefined &amp;&amp; autoWrap()) || !!message.wrap,\\n    type: messageType,\\n  });\\n  return true;\\n};\\n\\nexport const getMessages = function () {\\n  return messages;\\n};\\n\\nexport const getActors = function () {\\n  return actors;\\n};\\nexport const getActor = function (id) {\\n  return actors[id];\\n};\\nexport const getActorKeys = function () {\\n  return Object.keys(actors);\\n};\\nexport const getTitle = function () {\\n  return title;\\n};\\nexport const enableSequenceNumbers = function () {\\n  sequenceNumbersEnabled = true;\\n};\\nexport const showSequenceNumbers = () =&gt; sequenceNumbersEnabled;\\n\\nexport const setWrap = function (wrapSetting) {\\n  wrapEnabled = wrapSetting;\\n};\\n\\nexport const autoWrap = () =&gt; wrapEnabled;\\n\\nexport const clear = function () {\\n  actors = {};\\n  messages = [];\\n  sequenceNumbersEnabled = false;\\n};\\n\\nexport const parseMessage = function (str) {\\n  const _str = str.trim();\\n  const message = {\\n    text: _str.replace(/^[:]?(?:no)?wrap:/, '').trim(),\\n    wrap:\\n      _str.match(/^[:]?wrap:/) !== null\\n        ? true\\n        : _str.match(/^[:]?nowrap:/) !== null\\n        ? false\\n        : undefined,\\n  };\\n  log.debug('parseMessage:', message);\\n  return message;\\n};\\n\\nexport const LINETYPE = {\\n  SOLID: 0,\\n  DOTTED: 1,\\n  NOTE: 2,\\n  SOLID_CROSS: 3,\\n  DOTTED_CROSS: 4,\\n  SOLID_OPEN: 5,\\n  DOTTED_OPEN: 6,\\n  LOOP_START: 10,\\n  LOOP_END: 11,\\n  ALT_START: 12,\\n  ALT_ELSE: 13,\\n  ALT_END: 14,\\n  OPT_START: 15,\\n  OPT_END: 16,\\n  ACTIVE_START: 17,\\n  ACTIVE_END: 18,\\n  PAR_START: 19,\\n  PAR_AND: 20,\\n  PAR_END: 21,\\n  RECT_START: 22,\\n  RECT_END: 23,\\n  SOLID_POINT: 24,\\n  DOTTED_POINT: 25,\\n};\\n\\nexport const ARROWTYPE = {\\n  FILLED: 0,\\n  OPEN: 1,\\n};\\n\\nexport const PLACEMENT = {\\n  LEFTOF: 0,\\n  RIGHTOF: 1,\\n  OVER: 2,\\n};\\n\\nexport const addNote = function (actor, placement, message) {\\n  const note = {\\n    actor: actor,\\n    placement: placement,\\n    message: message.text,\\n    wrap: (message.wrap === undefined &amp;&amp; autoWrap()) || !!message.wrap,\\n  };\\n\\n  // Coerce actor into a [to, from, ...] array\\n  const actors = [].concat(actor, actor);\\n\\n  notes.push(note);\\n  messages.push({\\n    from: actors[0],\\n    to: actors[1],\\n    message: message.text,\\n    wrap: (message.wrap === undefined &amp;&amp; autoWrap()) || !!message.wrap,\\n    type: LINETYPE.NOTE,\\n    placement: placement,\\n  });\\n};\\n\\nexport const addLinks = function (actorId, text) {\\n  // find the actor\\n  const actor = getActor(actorId);\\n  // JSON.parse the text\\n  try {\\n    let sanitizedText = sanitizeText(text.text, configApi.getConfig());\\n    sanitizedText = sanitizedText.replace(/&amp;amp;/g, '&amp;');\\n    sanitizedText = sanitizedText.replace(/&amp;equals;/g, '=');\\n    const links = JSON.parse(sanitizedText);\\n    // add the deserialized text to the actor's links field.\\n    insertLinks(actor, links);\\n  } catch (e) {\\n    log.error('error while parsing actor link text', e);\\n  }\\n};\\n\\nexport const addALink = function (actorId, text) {\\n  // find the actor\\n  const actor = getActor(actorId);\\n  try {\\n    const links = {};\\n    let sanitizedText = sanitizeText(text.text, configApi.getConfig());\\n    var sep = sanitizedText.indexOf('@');\\n    sanitizedText = sanitizedText.replace(/&amp;amp;/g, '&amp;');\\n    sanitizedText = sanitizedText.replace(/&amp;equals;/g, '=');\\n    var label = sanitizedText.slice(0, sep - 1).trim();\\n    var link = sanitizedText.slice(sep + 1).trim();\\n\\n    links[label] = link;\\n    // add the deserialized text to the actor's links field.\\n    insertLinks(actor, links);\\n  } catch (e) {\\n    log.error('error while parsing actor link text', e);\\n  }\\n};\\n\\n/**\\n * @param {any} actor\\n * @param {any} links\\n */\\nfunction insertLinks(actor, links) {\\n  if (actor.links == null) {\\n    actor.links = links;\\n  } else {\\n    for (let key in links) {\\n      actor.links[key] = links[key];\\n    }\\n  }\\n}\\n\\nexport const addProperties = function (actorId, text) {\\n  // find the actor\\n  const actor = getActor(actorId);\\n  // JSON.parse the text\\n  try {\\n    let sanitizedText = sanitizeText(text.text, configApi.getConfig());\\n    const properties = JSON.parse(sanitizedText);\\n    // add the deserialized text to the actor's property field.\\n    insertProperties(actor, properties);\\n  } catch (e) {\\n    log.error('error while parsing actor properties text', e);\\n  }\\n};\\n\\n/**\\n * @param {any} actor\\n * @param {any} properties\\n */\\nfunction insertProperties(actor, properties) {\\n  if (actor.properties == null) {\\n    actor.properties = properties;\\n  } else {\\n    for (let key in properties) {\\n      actor.properties[key] = properties[key];\\n    }\\n  }\\n}\\n\\nexport const addDetails = function (actorId, text) {\\n  // find the actor\\n  const actor = getActor(actorId);\\n  const elem = document.getElementById(text.text);\\n\\n  // JSON.parse the text\\n  try {\\n    const text = elem.innerHTML;\\n    const details = JSON.parse(text);\\n    // add the deserialized text to the actor's property field.\\n    if (details['properties']) {\\n      insertProperties(actor, details['properties']);\\n    }\\n\\n    if (details['links']) {\\n      insertLinks(actor, details['links']);\\n    }\\n  } catch (e) {\\n    log.error('error while parsing actor details text', e);\\n  }\\n};\\n\\nexport const getActorProperty = function (actor, key) {\\n  if (typeof actor !== 'undefined' &amp;&amp; typeof actor.properties !== 'undefined') {\\n    return actor.properties[key];\\n  }\\n\\n  return undefined;\\n};\\n\\nexport const setTitle = function (txt) {\\n  let sanitizedText = sanitizeText(txt, configApi.getConfig());\\n  title = sanitizedText;\\n};\\n\\nexport const apply = function (param) {\\n  if (param instanceof Array) {\\n    param.forEach(function (item) {\\n      apply(item);\\n    });\\n  } else {\\n    switch (param.type) {\\n      case 'addParticipant':\\n        addActor(param.actor, param.actor, param.description, 'participant');\\n        break;\\n      case 'addActor':\\n        addActor(param.actor, param.actor, param.description, 'actor');\\n        break;\\n      case 'activeStart':\\n        addSignal(param.actor, undefined, undefined, param.signalType);\\n        break;\\n      case 'activeEnd':\\n        addSignal(param.actor, undefined, undefined, param.signalType);\\n        break;\\n      case 'addNote':\\n        addNote(param.actor, param.placement, param.text);\\n        break;\\n      case 'addLinks':\\n        addLinks(param.actor, param.text);\\n        break;\\n      case 'addALink':\\n        addALink(param.actor, param.text);\\n        break;\\n      case 'addProperties':\\n        addProperties(param.actor, param.text);\\n        break;\\n      case 'addDetails':\\n        addDetails(param.actor, param.text);\\n        break;\\n      case 'addMessage':\\n        addSignal(param.from, param.to, param.msg, param.signalType);\\n        break;\\n      case 'loopStart':\\n        addSignal(undefined, undefined, param.loopText, param.signalType);\\n        break;\\n      case 'loopEnd':\\n        addSignal(undefined, undefined, undefined, param.signalType);\\n        break;\\n      case 'rectStart':\\n        addSignal(undefined, undefined, param.color, param.signalType);\\n        break;\\n      case 'rectEnd':\\n        addSignal(undefined, undefined, undefined, param.signalType);\\n        break;\\n      case 'optStart':\\n        addSignal(undefined, undefined, param.optText, param.signalType);\\n        break;\\n      case 'optEnd':\\n        addSignal(undefined, undefined, undefined, param.signalType);\\n        break;\\n      case 'altStart':\\n        addSignal(undefined, undefined, param.altText, param.signalType);\\n        break;\\n      case 'else':\\n        addSignal(undefined, undefined, param.altText, param.signalType);\\n        break;\\n      case 'altEnd':\\n        addSignal(undefined, undefined, undefined, param.signalType);\\n        break;\\n      case 'setTitle':\\n        setTitle(param.text);\\n        break;\\n      case 'parStart':\\n        addSignal(undefined, undefined, param.parText, param.signalType);\\n        break;\\n      case 'and':\\n        addSignal(undefined, undefined, param.parText, param.signalType);\\n        break;\\n      case 'parEnd':\\n        addSignal(undefined, undefined, undefined, param.signalType);\\n        break;\\n    }\\n  }\\n};\\n\\nconst setAccDescription = function (description_lex) {\\n  let sanitizedText = sanitizeText(description_lex, configApi.getConfig());\\n  description = sanitizedText;\\n};\\n\\nconst getAccDescription = function () {\\n  return description;\\n};\\n\\nexport default {\\n  addActor,\\n  addMessage,\\n  addSignal,\\n  addLinks,\\n  addDetails,\\n  addProperties,\\n  autoWrap,\\n  setWrap,\\n  enableSequenceNumbers,\\n  showSequenceNumbers,\\n  getMessages,\\n  getActors,\\n  getActor,\\n  getActorKeys,\\n  getActorProperty,\\n  getTitle,\\n  parseDirective,\\n  getConfig: () =&gt; configApi.getConfig().sequence,\\n  clear,\\n  parseMessage,\\n  LINETYPE,\\n  ARROWTYPE,\\n  PLACEMENT,\\n  addNote,\\n  setTitle,\\n  apply,\\n  setAccDescription,\\n  getAccDescription,\\n};\\n\"</span>,<span class=\"code-string\">\"let interactionFunctions = [];\\nexport const addFunction = (func) =&gt; {\\n  interactionFunctions.push(func);\\n};\\nexport const attachFunctions = () =&gt; {\\n  interactionFunctions.forEach((f) =&gt; {\\n    f();\\n  });\\n  interactionFunctions = [];\\n};\\n\"</span>,<span class=\"code-string\">\"import common from '../common/common';\\nimport { addFunction } from '../../interactionDb';\\nimport { sanitizeUrl } from '@braintree/sanitize-url';\\n\\nexport const drawRect = function (elem, rectData) {\\n  const rectElem = elem.append('rect');\\n  rectElem.attr('x', rectData.x);\\n  rectElem.attr('y', rectData.y);\\n  rectElem.attr('fill', rectData.fill);\\n  rectElem.attr('stroke', rectData.stroke);\\n  rectElem.attr('width', rectData.width);\\n  rectElem.attr('height', rectData.height);\\n  rectElem.attr('rx', rectData.rx);\\n  rectElem.attr('ry', rectData.ry);\\n\\n  if (typeof rectData.class !== 'undefined') {\\n    rectElem.attr('class', rectData.class);\\n  }\\n\\n  return rectElem;\\n};\\n\\n// const sanitizeUrl = function (s) {\\n//   return s\\n//     .replace(/&amp;/g, '&amp;amp;')\\n//     .replace(/&lt;/g, '&amp;lt;')\\n//     .replace(/javascript:/g, '');\\n// };\\n\\nconst addPopupInteraction = (id, actorCnt) =&gt; {\\n  addFunction(() =&gt; {\\n    const arr = document.querySelectorAll(id);\\n    // This will be the case when running in sandboxed mode\\n    if (arr.length === 0) return;\\n    arr[0].addEventListener('mouseover', function () {\\n      popupMenuUpFunc('actor' + actorCnt + '_popup');\\n    });\\n    arr[0].addEventListener('mouseout', function () {\\n      popupMenuDownFunc('actor' + actorCnt + '_popup');\\n    });\\n  });\\n};\\nexport const drawPopup = function (elem, actor, minMenuWidth, textAttrs, forceMenus) {\\n  if (actor.links === undefined || actor.links === null || Object.keys(actor.links).length === 0) {\\n    return { height: 0, width: 0 };\\n  }\\n\\n  const links = actor.links;\\n  const actorCnt = actor.actorCnt;\\n  const rectData = actor.rectData;\\n\\n  var displayValue = 'none';\\n  if (forceMenus) {\\n    displayValue = 'block !important';\\n  }\\n\\n  const g = elem.append('g');\\n  g.attr('id', 'actor' + actorCnt + '_popup');\\n  g.attr('class', 'actorPopupMenu');\\n  g.attr('display', displayValue);\\n  addPopupInteraction('#actor' + actorCnt + '_popup', actorCnt);\\n  var actorClass = '';\\n  if (typeof rectData.class !== 'undefined') {\\n    actorClass = ' ' + rectData.class;\\n  }\\n\\n  let menuWidth = rectData.width &gt; minMenuWidth ? rectData.width : minMenuWidth;\\n\\n  const rectElem = g.append('rect');\\n  rectElem.attr('class', 'actorPopupMenuPanel' + actorClass);\\n  rectElem.attr('x', rectData.x);\\n  rectElem.attr('y', rectData.height);\\n  rectElem.attr('fill', rectData.fill);\\n  rectElem.attr('stroke', rectData.stroke);\\n  rectElem.attr('width', menuWidth);\\n  rectElem.attr('height', rectData.height);\\n  rectElem.attr('rx', rectData.rx);\\n  rectElem.attr('ry', rectData.ry);\\n  if (links != null) {\\n    var linkY = 20;\\n    for (let key in links) {\\n      var linkElem = g.append('a');\\n      var sanitizedLink = sanitizeUrl(links[key]);\\n      linkElem.attr('xlink:href', sanitizedLink);\\n      linkElem.attr('target', '_blank');\\n\\n      _drawMenuItemTextCandidateFunc(textAttrs)(\\n        key,\\n        linkElem,\\n        rectData.x + 10,\\n        rectData.height + linkY,\\n        menuWidth,\\n        20,\\n        { class: 'actor' },\\n        textAttrs\\n      );\\n\\n      linkY += 30;\\n    }\\n  }\\n\\n  rectElem.attr('height', linkY);\\n\\n  return { height: rectData.height + linkY, width: menuWidth };\\n};\\n\\nexport const drawImage = function (elem, x, y, link) {\\n  const imageElem = elem.append('image');\\n  imageElem.attr('x', x);\\n  imageElem.attr('y', y);\\n  var sanitizedLink = sanitizeUrl(link);\\n  imageElem.attr('xlink:href', sanitizedLink);\\n};\\n\\nexport const drawEmbeddedImage = function (elem, x, y, link) {\\n  const imageElem = elem.append('use');\\n  imageElem.attr('x', x);\\n  imageElem.attr('y', y);\\n  var sanitizedLink = sanitizeUrl(link);\\n  imageElem.attr('xlink:href', '#' + sanitizedLink);\\n};\\n\\nexport const popupMenu = function (popid) {\\n  return (\\n    \\\"var pu = document.getElementById('\\\" +\\n    popid +\\n    \\\"'); if (pu != null) { pu.style.display = 'block'; }\\\"\\n  );\\n};\\n\\nexport const popdownMenu = function (popid) {\\n  return (\\n    \\\"var pu = document.getElementById('\\\" +\\n    popid +\\n    \\\"'); if (pu != null) { pu.style.display = 'none'; }\\\"\\n  );\\n};\\n\\nconst popupMenuUpFunc = function (popupId) {\\n  var pu = document.getElementById(popupId);\\n  if (pu != null) {\\n    pu.style.display = 'block';\\n  }\\n};\\n\\nconst popupMenuDownFunc = function (popupId) {\\n  var pu = document.getElementById(popupId);\\n  if (pu != null) {\\n    pu.style.display = 'none';\\n  }\\n};\\nexport const drawText = function (elem, textData) {\\n  let prevTextHeight = 0,\\n    textHeight = 0;\\n  const lines = textData.text.split(common.lineBreakRegex);\\n\\n  let textElems = [];\\n  let dy = 0;\\n  let yfunc = () =&gt; textData.y;\\n  if (\\n    typeof textData.valign !== 'undefined' &amp;&amp;\\n    typeof textData.textMargin !== 'undefined' &amp;&amp;\\n    textData.textMargin &gt; 0\\n  ) {\\n    switch (textData.valign) {\\n      case 'top':\\n      case 'start':\\n        yfunc = () =&gt; Math.round(textData.y + textData.textMargin);\\n        break;\\n      case 'middle':\\n      case 'center':\\n        yfunc = () =&gt;\\n          Math.round(textData.y + (prevTextHeight + textHeight + textData.textMargin) / 2);\\n        break;\\n      case 'bottom':\\n      case 'end':\\n        yfunc = () =&gt;\\n          Math.round(\\n            textData.y +\\n              (prevTextHeight + textHeight + 2 * textData.textMargin) -\\n              textData.textMargin\\n          );\\n        break;\\n    }\\n  }\\n  if (\\n    typeof textData.anchor !== 'undefined' &amp;&amp;\\n    typeof textData.textMargin !== 'undefined' &amp;&amp;\\n    typeof textData.width !== 'undefined'\\n  ) {\\n    switch (textData.anchor) {\\n      case 'left':\\n      case 'start':\\n        textData.x = Math.round(textData.x + textData.textMargin);\\n        textData.anchor = 'start';\\n        textData.dominantBaseline = 'text-after-edge';\\n        textData.alignmentBaseline = 'middle';\\n        break;\\n      case 'middle':\\n      case 'center':\\n        textData.x = Math.round(textData.x + textData.width / 2);\\n        textData.anchor = 'middle';\\n        textData.dominantBaseline = 'middle';\\n        textData.alignmentBaseline = 'middle';\\n        break;\\n      case 'right':\\n      case 'end':\\n        textData.x = Math.round(textData.x + textData.width - textData.textMargin);\\n        textData.anchor = 'end';\\n        textData.dominantBaseline = 'text-before-edge';\\n        textData.alignmentBaseline = 'middle';\\n        break;\\n    }\\n  }\\n  for (let i = 0; i &lt; lines.length; i++) {\\n    let line = lines[i];\\n    if (\\n      typeof textData.textMargin !== 'undefined' &amp;&amp;\\n      textData.textMargin === 0 &amp;&amp;\\n      typeof textData.fontSize !== 'undefined'\\n    ) {\\n      dy = i * textData.fontSize;\\n    }\\n\\n    const textElem = elem.append('text');\\n    textElem.attr('x', textData.x);\\n    textElem.attr('y', yfunc());\\n    if (typeof textData.anchor !== 'undefined') {\\n      textElem\\n        .attr('text-anchor', textData.anchor)\\n        .attr('dominant-baseline', textData.dominantBaseline)\\n        .attr('alignment-baseline', textData.alignmentBaseline);\\n    }\\n    if (typeof textData.fontFamily !== 'undefined') {\\n      textElem.style('font-family', textData.fontFamily);\\n    }\\n    if (typeof textData.fontSize !== 'undefined') {\\n      textElem.style('font-size', textData.fontSize);\\n    }\\n    if (typeof textData.fontWeight !== 'undefined') {\\n      textElem.style('font-weight', textData.fontWeight);\\n    }\\n    if (typeof textData.fill !== 'undefined') {\\n      textElem.attr('fill', textData.fill);\\n    }\\n    if (typeof textData.class !== 'undefined') {\\n      textElem.attr('class', textData.class);\\n    }\\n    if (typeof textData.dy !== 'undefined') {\\n      textElem.attr('dy', textData.dy);\\n    } else if (dy !== 0) {\\n      textElem.attr('dy', dy);\\n    }\\n\\n    if (textData.tspan) {\\n      const span = textElem.append('tspan');\\n      span.attr('x', textData.x);\\n      if (typeof textData.fill !== 'undefined') {\\n        span.attr('fill', textData.fill);\\n      }\\n      span.text(line);\\n    } else {\\n      textElem.text(line);\\n    }\\n    if (\\n      typeof textData.valign !== 'undefined' &amp;&amp;\\n      typeof textData.textMargin !== 'undefined' &amp;&amp;\\n      textData.textMargin &gt; 0\\n    ) {\\n      textHeight += (textElem._groups || textElem)[0][0].getBBox().height;\\n      prevTextHeight = textHeight;\\n    }\\n\\n    textElems.push(textElem);\\n  }\\n\\n  return textElems;\\n};\\n\\nexport const drawLabel = function (elem, txtObject) {\\n  /**\\n   * @param {any} x\\n   * @param {any} y\\n   * @param {any} width\\n   * @param {any} height\\n   * @param {any} cut\\n   * @returns {any}\\n   */\\n  function genPoints(x, y, width, height, cut) {\\n    return (\\n      x +\\n      ',' +\\n      y +\\n      ' ' +\\n      (x + width) +\\n      ',' +\\n      y +\\n      ' ' +\\n      (x + width) +\\n      ',' +\\n      (y + height - cut) +\\n      ' ' +\\n      (x + width - cut * 1.2) +\\n      ',' +\\n      (y + height) +\\n      ' ' +\\n      x +\\n      ',' +\\n      (y + height)\\n    );\\n  }\\n  const polygon = elem.append('polygon');\\n  polygon.attr('points', genPoints(txtObject.x, txtObject.y, txtObject.width, txtObject.height, 7));\\n  polygon.attr('class', 'labelBox');\\n\\n  txtObject.y = txtObject.y + txtObject.height / 2;\\n\\n  drawText(elem, txtObject);\\n  return polygon;\\n};\\n\\nlet actorCnt = -1;\\n\\nexport const fixLifeLineHeights = (diagram, bounds) =&gt; {\\n  if (!diagram.selectAll) return;\\n  diagram\\n    .selectAll('.actor-line')\\n    .attr('class', '200')\\n    .attr('y2', bounds - 55);\\n};\\n\\n/**\\n * Draws an actor in the diagram with the attached line\\n *\\n * @param {any} elem - The diagram we'll draw to.\\n * @param {any} actor - The actor to draw.\\n * @param {any} conf - DrawText implementation discriminator object\\n */\\nconst drawActorTypeParticipant = function (elem, actor, conf) {\\n  const center = actor.x + actor.width / 2;\\n\\n  const boxpluslineGroup = elem.append('g');\\n  var g = boxpluslineGroup;\\n\\n  if (actor.y === 0) {\\n    actorCnt++;\\n    g.append('line')\\n      .attr('id', 'actor' + actorCnt)\\n      .attr('x1', center)\\n      .attr('y1', 5)\\n      .attr('x2', center)\\n      .attr('y2', 2000)\\n      .attr('class', 'actor-line')\\n      .attr('stroke-width', '0.5px')\\n      .attr('stroke', '#999');\\n\\n    g = boxpluslineGroup.append('g');\\n    actor.actorCnt = actorCnt;\\n\\n    if (actor.links != null) {\\n      g.attr('id', 'root-' + actorCnt);\\n      addPopupInteraction('#root-' + actorCnt, actorCnt);\\n    }\\n  }\\n\\n  const rect = getNoteRect();\\n  var cssclass = 'actor';\\n  if (actor.properties != null &amp;&amp; actor.properties['class']) {\\n    cssclass = actor.properties['class'];\\n  } else {\\n    rect.fill = '#eaeaea';\\n  }\\n  rect.x = actor.x;\\n  rect.y = actor.y;\\n  rect.width = actor.width;\\n  rect.height = actor.height;\\n  rect.class = cssclass;\\n  rect.rx = 3;\\n  rect.ry = 3;\\n  const rectElem = drawRect(g, rect);\\n  actor.rectData = rect;\\n\\n  if (actor.properties != null &amp;&amp; actor.properties['icon']) {\\n    const iconSrc = actor.properties['icon'].trim();\\n    if (iconSrc.charAt(0) === '@') {\\n      drawEmbeddedImage(g, rect.x + rect.width - 20, rect.y + 10, iconSrc.substr(1));\\n    } else {\\n      drawImage(g, rect.x + rect.width - 20, rect.y + 10, iconSrc);\\n    }\\n  }\\n\\n  _drawTextCandidateFunc(conf)(\\n    actor.description,\\n    g,\\n    rect.x,\\n    rect.y,\\n    rect.widt