  function byFo(content, g, x, y, width, height, textAttrs, conf) {\\n    const s = g.append('switch');\\n    const f = s\\n      .append('foreignObject')\\n      .attr('x', x)\\n      .attr('y', y)\\n      .attr('width', width)\\n      .attr('height', height);\\n\\n    const text = f\\n      .append('xhtml:div')\\n      .style('display', 'table')\\n      .style('height', '100%')\\n      .style('width', '100%');\\n\\n    text\\n      .append('div')\\n      .style('display', 'table-cell')\\n      .style('text-align', 'center')\\n      .style('vertical-align', 'middle')\\n      .text(content);\\n\\n    byTspan(content, s, x, y, width, height, textAttrs, conf);\\n    _setTextAttrs(text, textAttrs);\\n  }\\n\\n  /**\\n   * @param {any} toText\\n   * @param {any} fromTextAttrsDict\\n   */\\n  function _setTextAttrs(toText, fromTextAttrsDict) {\\n    for (const key in fromTextAttrsDict) {\\n      if (fromTextAttrsDict.hasOwnProperty(key)) { // eslint-disable-line\\n        toText.attr(key, fromTextAttrsDict[key]);\\n      }\\n    }\\n  }\\n\\n  return function (conf) {\\n    return conf.textPlacement === 'fo' ? byFo : conf.textPlacement === 'old' ? byText : byTspan;\\n  };\\n})();\\n\\nexport default {\\n  drawRect,\\n  drawText,\\n  drawLabel,\\n  drawActor,\\n  drawPopup,\\n  drawImage,\\n  drawEmbeddedImage,\\n  anchorElement,\\n  drawActivation,\\n  drawLoop,\\n  drawBackgroundRect,\\n  insertArrowHead,\\n  insertArrowFilledHead,\\n  insertSequenceNumber,\\n  insertArrowCrossHead,\\n  insertDatabaseIcon,\\n  insertComputerIcon,\\n  insertClockIcon,\\n  getTextObj,\\n  getNoteRect,\\n  popupMenu,\\n  popdownMenu,\\n  fixLifeLineHeights,\\n  sanitizeUrl,\\n};\\n\"</span>,<span class=\"code-string\">\"import { select, selectAll } from 'd3';\\nimport svgDraw, { drawText, fixLifeLineHeights } from './svgDraw';\\nimport { log } from '../../logger';\\nimport { parser } from './parser/sequenceDiagram';\\nimport common from '../common/common';\\nimport sequenceDb from './sequenceDb';\\nimport * as configApi from '../../config';\\nimport utils, { assignWithDepth, configureSvgSize } from '../../utils';\\nimport addSVGAccessibilityFields from '../../accessibility';\\n\\nparser.yy = sequenceDb;\\n\\nlet conf = {};\\n\\nexport const bounds = {\\n  data: {\\n    startx: undefined,\\n    stopx: undefined,\\n    starty: undefined,\\n    stopy: undefined,\\n  },\\n  verticalPos: 0,\\n  sequenceItems: [],\\n  activations: [],\\n  models: {\\n    getHeight: function () {\\n      return (\\n        Math.max.apply(\\n          null,\\n          this.actors.length === 0 ? [0] : this.actors.map((actor) =&gt; actor.height || 0)\\n        ) +\\n        (this.loops.length === 0\\n          ? 0\\n          : this.loops.map((it) =&gt; it.height || 0).reduce((acc, h) =&gt; acc + h)) +\\n        (this.messages.length === 0\\n          ? 0\\n          : this.messages.map((it) =&gt; it.height || 0).reduce((acc, h) =&gt; acc + h)) +\\n        (this.notes.length === 0\\n          ? 0\\n          : this.notes.map((it) =&gt; it.height || 0).reduce((acc, h) =&gt; acc + h))\\n      );\\n    },\\n    clear: function () {\\n      this.actors = [];\\n      this.loops = [];\\n      this.messages = [];\\n      this.notes = [];\\n    },\\n    addActor: function (actorModel) {\\n      this.actors.push(actorModel);\\n    },\\n    addLoop: function (loopModel) {\\n      this.loops.push(loopModel);\\n    },\\n    addMessage: function (msgModel) {\\n      this.messages.push(msgModel);\\n    },\\n    addNote: function (noteModel) {\\n      this.notes.push(noteModel);\\n    },\\n    lastActor: function () {\\n      return this.actors[this.actors.length - 1];\\n    },\\n    lastLoop: function () {\\n      return this.loops[this.loops.length - 1];\\n    },\\n    lastMessage: function () {\\n      return this.messages[this.messages.length - 1];\\n    },\\n    lastNote: function () {\\n      return this.notes[this.notes.length - 1];\\n    },\\n    actors: [],\\n    loops: [],\\n    messages: [],\\n    notes: [],\\n  },\\n  init: function () {\\n    this.sequenceItems = [];\\n    this.activations = [];\\n    this.models.clear();\\n    this.data = {\\n      startx: undefined,\\n      stopx: undefined,\\n      starty: undefined,\\n      stopy: undefined,\\n    };\\n    this.verticalPos = 0;\\n    setConf(parser.yy.getConfig());\\n  },\\n  updateVal: function (obj, key, val, fun) {\\n    if (typeof obj[key] === 'undefined') {\\n      obj[key] = val;\\n    } else {\\n      obj[key] = fun(val, obj[key]);\\n    }\\n  },\\n  updateBounds: function (startx, starty, stopx, stopy) {\\n    const _self = this;\\n    let cnt = 0;\\n    /** @param {any} type */\\n    function updateFn(type) {\\n      return function updateItemBounds(item) {\\n        cnt++;\\n        // The loop sequenceItems is a stack so the biggest margins in the beginning of the sequenceItems\\n        const n = _self.sequenceItems.length - cnt + 1;\\n\\n        _self.updateVal(item, 'starty', starty - n * conf.boxMargin, Math.min);\\n        _self.updateVal(item, 'stopy', stopy + n * conf.boxMargin, Math.max);\\n\\n        _self.updateVal(bounds.data, 'startx', startx - n * conf.boxMargin, Math.min);\\n        _self.updateVal(bounds.data, 'stopx', stopx + n * conf.boxMargin, Math.max);\\n\\n        if (!(type === 'activation')) {\\n          _self.updateVal(item, 'startx', startx - n * conf.boxMargin, Math.min);\\n          _self.updateVal(item, 'stopx', stopx + n * conf.boxMargin, Math.max);\\n\\n          _self.updateVal(bounds.data, 'starty', starty - n * conf.boxMargin, Math.min);\\n          _self.updateVal(bounds.data, 'stopy', stopy + n * conf.boxMargin, Math.max);\\n        }\\n      };\\n    }\\n\\n    this.sequenceItems.forEach(updateFn());\\n    this.activations.forEach(updateFn('activation'));\\n  },\\n  insert: function (startx, starty, stopx, stopy) {\\n    const _startx = Math.min(startx, stopx);\\n    const _stopx = Math.max(startx, stopx);\\n    const _starty = Math.min(starty, stopy);\\n    const _stopy = Math.max(starty, stopy);\\n\\n    this.updateVal(bounds.data, 'startx', _startx, Math.min);\\n    this.updateVal(bounds.data, 'starty', _starty, Math.min);\\n    this.updateVal(bounds.data, 'stopx', _stopx, Math.max);\\n    this.updateVal(bounds.data, 'stopy', _stopy, Math.max);\\n\\n    this.updateBounds(_startx, _starty, _stopx, _stopy);\\n  },\\n  newActivation: function (message, diagram, actors) {\\n    const actorRect = actors[message.from.actor];\\n    const stackedSize = actorActivations(message.from.actor).length || 0;\\n    const x = actorRect.x + actorRect.width / 2 + ((stackedSize - 1) * conf.activationWidth) / 2;\\n    this.activations.push({\\n      startx: x,\\n      starty: this.verticalPos + 2,\\n      stopx: x + conf.activationWidth,\\n      stopy: undefined,\\n      actor: message.from.actor,\\n      anchored: svgDraw.anchorElement(diagram),\\n    });\\n  },\\n  endActivation: function (message) {\\n    // find most recent activation for given actor\\n    const lastActorActivationIdx = this.activations\\n      .map(function (activation) {\\n        return activation.actor;\\n      })\\n      .lastIndexOf(message.from.actor);\\n    return this.activations.splice(lastActorActivationIdx, 1)[0];\\n  },\\n  createLoop: function (title = { message: undefined, wrap: false, width: undefined }, fill) {\\n    return {\\n      startx: undefined,\\n      starty: this.verticalPos,\\n      stopx: undefined,\\n      stopy: undefined,\\n      title: title.message,\\n      wrap: title.wrap,\\n      width: title.width,\\n      height: 0,\\n      fill: fill,\\n    };\\n  },\\n  newLoop: function (title = { message: undefined, wrap: false, width: undefined }, fill) {\\n    this.sequenceItems.push(this.createLoop(title, fill));\\n  },\\n  endLoop: function () {\\n    return this.sequenceItems.pop();\\n  },\\n  addSectionToLoop: function (message) {\\n    const loop = this.sequenceItems.pop();\\n    loop.sections = loop.sections || [];\\n    loop.sectionTitles = loop.sectionTitles || [];\\n    loop.sections.push({ y: bounds.getVerticalPos(), height: 0 });\\n    loop.sectionTitles.push(message);\\n    this.sequenceItems.push(loop);\\n  },\\n  bumpVerticalPos: function (bump) {\\n    this.verticalPos = this.verticalPos + bump;\\n    this.data.stopy = this.verticalPos;\\n  },\\n  getVerticalPos: function () {\\n    return this.verticalPos;\\n  },\\n  getBounds: function () {\\n    return { bounds: this.data, models: this.models };\\n  },\\n};\\n\\n/**\\n * Draws an note in the diagram with the attached line\\n *\\n * @param {any} elem - The diagram to draw to.\\n * @param {{ x: number; y: number; message: string; width: number }} noteModel - Startx: x axis\\n *   start position, verticalPos: y axis position, messsage: the message to be shown, width: Set\\n *   this with a custom width to override the default configured width.\\n */\\nconst drawNote = function (elem, noteModel) {\\n  bounds.bumpVerticalPos(conf.boxMargin);\\n  noteModel.height = conf.boxMargin;\\n  noteModel.starty = bounds.getVerticalPos();\\n  const rect = svgDraw.getNoteRect();\\n  rect.x = noteModel.startx;\\n  rect.y = noteModel.starty;\\n  rect.width = noteModel.width || conf.width;\\n  rect.class = 'note';\\n\\n  let g = elem.append('g');\\n  const rectElem = svgDraw.drawRect(g, rect);\\n  const textObj = svgDraw.getTextObj();\\n  textObj.x = noteModel.startx;\\n  textObj.y = noteModel.starty;\\n  textObj.width = rect.width;\\n  textObj.dy = '1em';\\n  textObj.text = noteModel.message;\\n  textObj.class = 'noteText';\\n  textObj.fontFamily = conf.noteFontFamily;\\n  textObj.fontSize = conf.noteFontSize;\\n  textObj.fontWeight = conf.noteFontWeight;\\n  textObj.anchor = conf.noteAlign;\\n  textObj.textMargin = conf.noteMargin;\\n  textObj.valign = conf.noteAlign;\\n\\n  let textElem = drawText(g, textObj);\\n\\n  let textHeight = Math.round(\\n    textElem\\n      .map((te) =&gt; (te._groups || te)[0][0].getBBox().height)\\n      .reduce((acc, curr) =&gt; acc + curr)\\n  );\\n\\n  rectElem.attr('height', textHeight + 2 * conf.noteMargin);\\n  noteModel.height += textHeight + 2 * conf.noteMargin;\\n  bounds.bumpVerticalPos(textHeight + 2 * conf.noteMargin);\\n  noteModel.stopy = noteModel.starty + textHeight + 2 * conf.noteMargin;\\n  noteModel.stopx = noteModel.startx + rect.width;\\n  bounds.insert(noteModel.startx, noteModel.starty, noteModel.stopx, noteModel.stopy);\\n  bounds.models.addNote(noteModel);\\n};\\n\\nconst messageFont = (cnf) =&gt; {\\n  return {\\n    fontFamily: cnf.messageFontFamily,\\n    fontSize: cnf.messageFontSize,\\n    fontWeight: cnf.messageFontWeight,\\n  };\\n};\\nconst noteFont = (cnf) =&gt; {\\n  return {\\n    fontFamily: cnf.noteFontFamily,\\n    fontSize: cnf.noteFontSize,\\n    fontWeight: cnf.noteFontWeight,\\n  };\\n};\\nconst actorFont = (cnf) =&gt; {\\n  return {\\n    fontFamily: cnf.actorFontFamily,\\n    fontSize: cnf.actorFontSize,\\n    fontWeight: cnf.actorFontWeight,\\n  };\\n};\\n\\n/**\\n * Draws a message\\n *\\n * @param {any} g - The parent of the message element\\n * @param {any} msgModel - The model containing fields describing a message\\n */\\nconst drawMessage = function (g, msgModel) {\\n  bounds.bumpVerticalPos(10);\\n  const { startx, stopx, starty, message, type, sequenceIndex } = msgModel;\\n  const lines = common.splitBreaks(message).length;\\n  let textDims = utils.calculateTextDimensions(message, messageFont(conf));\\n  const lineHeight = textDims.height / lines;\\n  msgModel.height += lineHeight;\\n\\n  bounds.bumpVerticalPos(lineHeight);\\n  const textObj = svgDraw.getTextObj();\\n  textObj.x = startx;\\n  textObj.y = starty + 10;\\n  textObj.width = stopx - startx;\\n  textObj.class = 'messageText';\\n  textObj.dy = '1em';\\n  textObj.text = message;\\n  textObj.fontFamily = conf.messageFontFamily;\\n  textObj.fontSize = conf.messageFontSize;\\n  textObj.fontWeight = conf.messageFontWeight;\\n  textObj.anchor = conf.messageAlign;\\n  textObj.valign = conf.messageAlign;\\n  textObj.textMargin = conf.wrapPadding;\\n  textObj.tspan = false;\\n\\n  drawText(g, textObj);\\n\\n  let totalOffset = textDims.height - 10;\\n\\n  let textWidth = textDims.width;\\n\\n  let line, lineStarty;\\n  if (startx === stopx) {\\n    lineStarty = bounds.getVerticalPos() + totalOffset;\\n    if (conf.rightAngles) {\\n      line = g\\n        .append('path')\\n        .attr(\\n          'd',\\n          `M  ${startx},${lineStarty} H ${startx + Math.max(conf.width / 2, textWidth / 2)} V ${\\n            lineStarty + 25\\n          } H ${startx}`\\n        );\\n    } else {\\n      totalOffset += conf.boxMargin;\\n\\n      lineStarty = bounds.getVerticalPos() + totalOffset;\\n      line = g\\n        .append('path')\\n        .attr(\\n          'd',\\n          'M ' +\\n            startx +\\n            ',' +\\n            lineStarty +\\n            ' C ' +\\n            (startx + 60) +\\n            ',' +\\n            (lineStarty - 10) +\\n            ' ' +\\n            (startx + 60) +\\n            ',' +\\n            (lineStarty + 30) +\\n            ' ' +\\n            startx +\\n            ',' +\\n            (lineStarty + 20)\\n        );\\n    }\\n\\n    totalOffset += 30;\\n    const dx = Math.max(textWidth / 2, conf.width / 2);\\n    bounds.insert(\\n      startx - dx,\\n      bounds.getVerticalPos() - 10 + totalOffset,\\n      stopx + dx,\\n      bounds.getVerticalPos() + 30 + totalOffset\\n    );\\n  } else {\\n    totalOffset += conf.boxMargin;\\n    lineStarty = bounds.getVerticalPos() + totalOffset;\\n    line = g.append('line');\\n    line.attr('x1', startx);\\n    line.attr('y1', lineStarty);\\n    line.attr('x2', stopx);\\n    line.attr('y2', lineStarty);\\n    bounds.insert(startx, lineStarty - 10, stopx, lineStarty);\\n  }\\n  // Make an SVG Container\\n  // Draw the line\\n  if (\\n    type === parser.yy.LINETYPE.DOTTED ||\\n    type === parser.yy.LINETYPE.DOTTED_CROSS ||\\n    type === parser.yy.LINETYPE.DOTTED_POINT ||\\n    type === parser.yy.LINETYPE.DOTTED_OPEN\\n  ) {\\n    line.style('stroke-dasharray', '3, 3');\\n    line.attr('class', 'messageLine1');\\n  } else {\\n    line.attr('class', 'messageLine0');\\n  }\\n\\n  let url = '';\\n  if (conf.arrowMarkerAbsolute) {\\n    url =\\n      window.location.protocol +\\n      '//' +\\n      window.location.host +\\n      window.location.pathname +\\n      window.location.search;\\n    url = url.replace(/\\\\(/g, '\\\\\\\\(');\\n    url = url.replace(/\\\\)/g, '\\\\\\\\)');\\n  }\\n\\n  line.attr('stroke-width', 2);\\n  line.attr('stroke', 'none'); // handled by theme/css anyway\\n  line.style('fill', 'none'); // remove any fill colour\\n  if (type === parser.yy.LINETYPE.SOLID || type === parser.yy.LINETYPE.DOTTED) {\\n    line.attr('marker-end', 'url(' + url + '#arrowhead)');\\n  }\\n  if (type === parser.yy.LINETYPE.SOLID_POINT || type === parser.yy.LINETYPE.DOTTED_POINT) {\\n    line.attr('marker-end', 'url(' + url + '#filled-head)');\\n  }\\n\\n  if (type === parser.yy.LINETYPE.SOLID_CROSS || type === parser.yy.LINETYPE.DOTTED_CROSS) {\\n    line.attr('marker-end', 'url(' + url + '#crosshead)');\\n  }\\n\\n  // add node number\\n  if (sequenceDb.showSequenceNumbers() || conf.showSequenceNumbers) {\\n    line.attr('marker-start', 'url(' + url + '#sequencenumber)');\\n    g.append('text')\\n      .attr('x', startx)\\n      .attr('y', lineStarty + 4)\\n      .attr('font-family', 'sans-serif')\\n      .attr('font-size', '12px')\\n      .attr('text-anchor', 'middle')\\n      .attr('textLength', '16px')\\n      .attr('class', 'sequenceNumber')\\n      .text(sequenceIndex);\\n  }\\n  bounds.bumpVerticalPos(totalOffset);\\n  msgModel.height += totalOffset;\\n  msgModel.stopy = msgModel.starty + msgModel.height;\\n  bounds.insert(msgModel.fromBounds, msgModel.starty, msgModel.toBounds, msgModel.stopy);\\n};\\n\\nexport const drawActors = function (diagram, actors, actorKeys, verticalPos) {\\n  // Draw the actors\\n  let prevWidth = 0;\\n  let prevMargin = 0;\\n  let maxHeight = 0;\\n  for (let i = 0; i &lt; actorKeys.length; i++) {\\n    const actor = actors[actorKeys[i]];\\n\\n    // Add some rendering data to the object\\n    actor.width = actor.width || conf.width;\\n    actor.height = Math.max(actor.height || conf.height, conf.height);\\n    actor.margin = actor.margin || conf.actorMargin;\\n\\n    actor.x = prevWidth + prevMargin;\\n    actor.y = verticalPos;\\n\\n    // Draw the box with the attached line\\n    const height = svgDraw.drawActor(diagram, actor, conf);\\n    maxHeight = Math.max(maxHeight, height);\\n    bounds.insert(actor.x, verticalPos, actor.x + actor.width, actor.height);\\n\\n    prevWidth += actor.width;\\n    prevMargin += actor.margin;\\n    bounds.models.addActor(actor);\\n  }\\n\\n  // Add a margin between the actor boxes and the first arrow\\n  bounds.bumpVerticalPos(maxHeight);\\n};\\n\\nexport const drawActorsPopup = function (diagram, actors, actorKeys, doc) {\\n  var maxHeight = 0;\\n  var maxWidth = 0;\\n  for (let i = 0; i &lt; actorKeys.length; i++) {\\n    const actor = actors[actorKeys[i]];\\n    const minMenuWidth = getRequiredPopupWidth(actor);\\n    var menuDimensions = svgDraw.drawPopup(\\n      diagram,\\n      actor,\\n      minMenuWidth,\\n      conf,\\n      conf.forceMenus,\\n      doc\\n    );\\n    if (menuDimensions.height &gt; maxHeight) {\\n      maxHeight = menuDimensions.height;\\n    }\\n    if (menuDimensions.width + actor.x &gt; maxWidth) {\\n      maxWidth = menuDimensions.width + actor.x;\\n    }\\n  }\\n\\n  return { maxHeight: maxHeight, maxWidth: maxWidth };\\n};\\n\\nexport const setConf = function (cnf) {\\n  assignWithDepth(conf, cnf);\\n\\n  if (cnf.fontFamily) {\\n    conf.actorFontFamily = conf.noteFontFamily = conf.messageFontFamily = cnf.fontFamily;\\n  }\\n  if (cnf.fontSize) {\\n    conf.actorFontSize = conf.noteFontSize = conf.messageFontSize = cnf.fontSize;\\n  }\\n  if (cnf.fontWeight) {\\n    conf.actorFontWeight = conf.noteFontWeight = conf.messageFontWeight = cnf.fontWeight;\\n  }\\n};\\n\\nconst actorActivations = function (actor) {\\n  return bounds.activations.filter(function (activation) {\\n    return activation.actor === actor;\\n  });\\n};\\n\\nconst activationBounds = function (actor, actors) {\\n  // handle multiple stacked activations for same actor\\n  const actorObj = actors[actor];\\n  const activations = actorActivations(actor);\\n\\n  const left = activations.reduce(function (acc, activation) {\\n    return Math.min(acc, activation.startx);\\n  }, actorObj.x + actorObj.width / 2);\\n  const right = activations.reduce(function (acc, activation) {\\n    return Math.max(acc, activation.stopx);\\n  }, actorObj.x + actorObj.width / 2);\\n  return [left, right];\\n};\\n\\n/**\\n * @param {any} loopWidths\\n * @param {any} msg\\n * @param {any} preMargin\\n * @param {any} postMargin\\n * @param {any} addLoopFn\\n */\\nfunction adjustLoopHeightForWrap(loopWidths, msg, preMargin, postMargin, addLoopFn) {\\n  bounds.bumpVerticalPos(preMargin);\\n  let heightAdjust = postMargin;\\n  if (msg.id &amp;&amp; msg.message &amp;&amp; loopWidths[msg.id]) {\\n    let loopWidth = loopWidths[msg.id].width;\\n    let textConf = messageFont(conf);\\n    msg.message = utils.wrapLabel(`[${msg.message}]`, loopWidth - 2 * conf.wrapPadding, textConf);\\n    msg.width = loopWidth;\\n    msg.wrap = true;\\n\\n    // const lines = common.splitBreaks(msg.message).length;\\n    const textDims = utils.calculateTextDimensions(msg.message, textConf);\\n    const totalOffset = Math.max(textDims.height, conf.labelBoxHeight);\\n    heightAdjust = postMargin + totalOffset;\\n    log.debug(`${totalOffset} - ${msg.message}`);\\n  }\\n  addLoopFn(msg);\\n  bounds.bumpVerticalPos(heightAdjust);\\n}\\n\\n/**\\n * Draws a sequenceDiagram in the tag with id: id based on the graph definition in text.\\n *\\n * @param {any} text\\n * @param {any} id\\n */\\nexport const draw = function (text, id) {\\n  conf = configApi.getConfig().sequence;\\n  const securityLevel = configApi.getConfig().securityLevel;\\n  // Handle root and ocument for when rendering in sanbox mode\\n  let sandboxElement;\\n  if (securityLevel === 'sandbox') {\\n    sandboxElement = select('#i' + id);\\n  }\\n  const root =\\n    securityLevel === 'sandbox'\\n      ? select(sandboxElement.nodes()[0].contentDocument.body)\\n      : select('body');\\n  const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n\\n  parser.yy.clear();\\n  parser.yy.setWrap(conf.wrap);\\n  parser.parse(text + '\\\\n');\\n  bounds.init();\\n  log.debug(`C:${JSON.stringify(conf, null, 2)}`);\\n\\n  const diagram =\\n    securityLevel === 'sandbox' ? root.select(`[id=\\\"${id}\\\"]`) : select(`[id=\\\"${id}\\\"]`);\\n\\n  // Fetch data from the parsing\\n  const actors = parser.yy.getActors();\\n  const actorKeys = parser.yy.getActorKeys();\\n  const messages = parser.yy.getMessages();\\n  const title = parser.yy.getTitle();\\n\\n  const maxMessageWidthPerActor = getMaxMessageWidthPerActor(actors, messages);\\n  conf.height = calculateActorMargins(actors, maxMessageWidthPerActor);\\n\\n  svgDraw.insertComputerIcon(diagram);\\n  svgDraw.insertDatabaseIcon(diagram);\\n  svgDraw.insertClockIcon(diagram);\\n\\n  drawActors(diagram, actors, actorKeys, 0);\\n  const loopWidths = calculateLoopBounds(messages, actors, maxMessageWidthPerActor);\\n\\n  // The arrow head definition is attached to the svg once\\n  svgDraw.insertArrowHead(diagram);\\n  svgDraw.insertArrowCrossHead(diagram);\\n  svgDraw.insertArrowFilledHead(diagram);\\n  svgDraw.insertSequenceNumber(diagram);\\n\\n  /**\\n   * @param {any} msg\\n   * @param {any} verticalPos\\n   */\\n  function activeEnd(msg, verticalPos) {\\n    const activationData = bounds.endActivation(msg);\\n    if (activationData.starty + 18 &gt; verticalPos) {\\n      activationData.starty = verticalPos - 6;\\n      verticalPos += 12;\\n    }\\n    svgDraw.drawActivation(\\n      diagram,\\n      activationData,\\n      verticalPos,\\n      conf,\\n      actorActivations(msg.from.actor).length\\n    );\\n\\n    bounds.insert(activationData.startx, verticalPos - 10, activationData.stopx, verticalPos);\\n  }\\n\\n  // Draw the messages/signals\\n  let sequenceIndex = 1;\\n  messages.forEach(function (msg) {\\n    let loopModel, noteModel, msgModel;\\n\\n    switch (msg.type) {\\n      case parser.yy.LINETYPE.NOTE:\\n        noteModel = msg.noteModel;\\n        drawNote(diagram, noteModel);\\n        break;\\n      case parser.yy.LINETYPE.ACTIVE_START:\\n        bounds.newActivation(msg, diagram, actors);\\n        break;\\n      case parser.yy.LINETYPE.ACTIVE_END:\\n        activeEnd(msg, bounds.getVerticalPos());\\n        break;\\n      case parser.yy.LINETYPE.LOOP_START:\\n        adjustLoopHeightForWrap(\\n          loopWidths,\\n          msg,\\n          conf.boxMargin,\\n          conf.boxMargin + conf.boxTextMargin,\\n          (message) =&gt; bounds.newLoop(message)\\n        );\\n        break;\\n      case parser.yy.LINETYPE.LOOP_END:\\n        loopModel = bounds.endLoop();\\n        svgDraw.drawLoop(diagram, loopModel, 'loop', conf);\\n        bounds.bumpVerticalPos(loopModel.stopy - bounds.getVerticalPos());\\n        bounds.models.addLoop(loopModel);\\n        break;\\n      case parser.yy.LINETYPE.RECT_START:\\n        adjustLoopHeightForWrap(loopWidths, msg, conf.boxMargin, conf.boxMargin, (message) =&gt;\\n          bounds.newLoop(undefined, message.message)\\n        );\\n        break;\\n      case parser.yy.LINETYPE.RECT_END:\\n        loopModel = bounds.endLoop();\\n        svgDraw.drawBackgroundRect(diagram, loopModel);\\n        bounds.models.addLoop(loopModel);\\n        bounds.bumpVerticalPos(loopModel.stopy - bounds.getVerticalPos());\\n        break;\\n      case parser.yy.LINETYPE.OPT_START:\\n        adjustLoopHeightForWrap(\\n          loopWidths,\\n          msg,\\n          conf.boxMargin,\\n          conf.boxMargin + conf.boxTextMargin,\\n          (message) =&gt; bounds.newLoop(message)\\n        );\\n        break;\\n      case parser.yy.LINETYPE.OPT_END:\\n        loopModel = bounds.endLoop();\\n        svgDraw.drawLoop(diagram, loopModel, 'opt', conf);\\n        bounds.bumpVerticalPos(loopModel.stopy - bounds.getVerticalPos());\\n        bounds.models.addLoop(loopModel);\\n        break;\\n      case parser.yy.LINETYPE.ALT_START:\\n        adjustLoopHeightForWrap(\\n          loopWidths,\\n          msg,\\n          conf.boxMargin,\\n          conf.boxMargin + conf.boxTextMargin,\\n          (message) =&gt; bounds.newLoop(message)\\n        );\\n        break;\\n      case parser.yy.LINETYPE.ALT_ELSE:\\n        adjustLoopHeightForWrap(\\n          loopWidths,\\n          msg,\\n          conf.boxMargin + conf.boxTextMargin,\\n          conf.boxMargin,\\n          (message) =&gt; bounds.addSectionToLoop(message)\\n        );\\n        break;\\n      case parser.yy.LINETYPE.ALT_END:\\n        loopModel = bounds.endLoop();\\n        svgDraw.drawLoop(diagram, loopModel, 'alt', conf);\\n        bounds.bumpVerticalPos(loopModel.stopy - bounds.getVerticalPos());\\n        bounds.models.addLoop(loopModel);\\n        break;\\n      case parser.yy.LINETYPE.PAR_START:\\n        adjustLoopHeightForWrap(\\n          loopWidths,\\n          msg,\\n          conf.boxMargin,\\n          conf.boxMargin + conf.boxTextMargin,\\n          (message) =&gt; bounds.newLoop(message)\\n        );\\n        break;\\n      case parser.yy.LINETYPE.PAR_AND:\\n        adjustLoopHeightForWrap(\\n          loopWidths,\\n          msg,\\n          conf.boxMargin + conf.boxTextMargin,\\n          conf.boxMargin,\\n          (message) =&gt; bounds.addSectionToLoop(message)\\n        );\\n        break;\\n      case parser.yy.LINETYPE.PAR_END:\\n        loopModel = bounds.endLoop();\\n        svgDraw.drawLoop(diagram, loopModel, 'par', conf);\\n        bounds.bumpVerticalPos(loopModel.stopy - bounds.getVerticalPos());\\n        bounds.models.addLoop(loopModel);\\n        break;\\n      default:\\n        try {\\n          // lastMsg = msg\\n          msgModel = msg.msgModel;\\n          msgModel.starty = bounds.getVerticalPos();\\n          msgModel.sequenceIndex = sequenceIndex;\\n          drawMessage(diagram, msgModel);\\n          bounds.models.addMessage(msgModel);\\n        } catch (e) {\\n          log.error('error while drawing message', e);\\n        }\\n    }\\n\\n    // Increment sequence counter if msg.type is a line (and not another event like activation or note, etc)\\n    if (\\n      [\\n        parser.yy.LINETYPE.SOLID_OPEN,\\n        parser.yy.LINETYPE.DOTTED_OPEN,\\n        parser.yy.LINETYPE.SOLID,\\n        parser.yy.LINETYPE.DOTTED,\\n        parser.yy.LINETYPE.SOLID_CROSS,\\n        parser.yy.LINETYPE.DOTTED_CROSS,\\n        parser.yy.LINETYPE.SOLID_POINT,\\n        parser.yy.LINETYPE.DOTTED_POINT,\\n      ].includes(msg.type)\\n    ) {\\n      sequenceIndex++;\\n    }\\n  });\\n\\n  if (conf.mirrorActors) {\\n    // Draw actors below diagram\\n    bounds.bumpVerticalPos(conf.boxMargin * 2);\\n    drawActors(diagram, actors, actorKeys, bounds.getVerticalPos());\\n    bounds.bumpVerticalPos(conf.boxMargin);\\n    fixLifeLineHeights(diagram, bounds.getVerticalPos());\\n  }\\n\\n  // only draw popups for the top row of actors.\\n  var requiredBoxSize = drawActorsPopup(diagram, actors, actorKeys, doc);\\n\\n  const { bounds: box } = bounds.getBounds();\\n\\n  // Adjust line height of actor lines now that the height of the diagram is known\\n  log.debug('For line height fix Querying: #' + id + ' .actor-line');\\n  const actorLines = selectAll('#' + id + ' .actor-line');\\n  actorLines.attr('y2', box.stopy);\\n\\n  // Make sure the height of the diagram supports long menus.\\n  let boxHeight = box.stopy - box.starty;\\n  if (boxHeight &lt; requiredBoxSize.maxHeight) {\\n    boxHeight = requiredBoxSize.maxHeight;\\n  }\\n\\n  let height = boxHeight + 2 * conf.diagramMarginY;\\n  if (conf.mirrorActors) {\\n    height = height - conf.boxMargin + conf.bottomMarginAdj;\\n  }\\n\\n  // Make sure the width of the diagram supports wide menus.\\n  let boxWidth = box.stopx - box.startx;\\n  if (boxWidth &lt; requiredBoxSize.maxWidth) {\\n    boxWidth = requiredBoxSize.maxWidth;\\n  }\\n  const width = boxWidth + 2 * conf.diagramMarginX;\\n\\n  if (title) {\\n    diagram\\n      .append('text')\\n      .text(title)\\n      .attr('x', (box.stopx - box.startx) / 2 - 2 * conf.diagramMarginX)\\n      .attr('y', -25);\\n  }\\n\\n  configureSvgSize(diagram, height, width, conf.useMaxWidth);\\n\\n  const extraVertForTitle = title ? 40 : 0;\\n  diagram.attr(\\n    'viewBox',\\n    box.startx -\\n      conf.diagramMarginX +\\n      ' -' +\\n      (conf.diagramMarginY + extraVertForTitle) +\\n      ' ' +\\n      width +\\n      ' ' +\\n      (height + extraVertForTitle)\\n  );\\n\\n  addSVGAccessibilityFields(parser.yy, diagram, id);\\n  log.debug(`models:`, bounds.models);\\n};\\n\\n/**\\n * Retrieves the max message width of each actor, supports signals (messages, loops) and notes.\\n *\\n * It will enumerate each given message, and will determine its text width, in relation to the actor\\n * it originates from, and destined to.\\n *\\n * @param {any} actors - The actors map\\n * @param {Array} messages - A list of message objects to iterate\\n * @returns {any}\\n */\\nconst getMaxMessageWidthPerActor = function (actors, messages) {\\n  const maxMessageWidthPerActor = {};\\n\\n  messages.forEach(function (msg) {\\n    if (actors[msg.to] &amp;&amp; actors[msg.from]) {\\n      const actor = actors[msg.to];\\n\\n      // If this is the first actor, and the message is left of it, no need to calculate the margin\\n      if (msg.placement === parser.yy.PLACEMENT.LEFTOF &amp;&amp; !actor.prevActor) {\\n        return;\\n      }\\n\\n      // If this is the last actor, and the message is right of it, no need to calculate the margin\\n      if (msg.placement === parser.yy.PLACEMENT.RIGHTOF &amp;&amp; !actor.nextActor) {\\n        return;\\n      }\\n\\n      const isNote = msg.placement !== undefined;\\n      const isMessage = !isNote;\\n\\n      const textFont = isNote ? noteFont(conf) : messageFont(conf);\\n      let wrappedMessage = msg.wrap\\n        ? utils.wrapLabel(msg.message, conf.width - 2 * conf.wrapPadding, textFont)\\n        : msg.message;\\n      const messageDimensions = utils.calculateTextDimensions(wrappedMessage, textFont);\\n      const messageWidth = messageDimensions.width + 2 * conf.wrapPadding;\\n\\n      /*\\n       * The following scenarios should be supported:\\n       *\\n       * - There's a message (non-note) between fromActor and toActor\\n       *   - If fromActor is on the right and toActor is on the left, we should\\n       *     define the toActor's margin\\n       *   - If fromActor is on the left and toActor is on the right, we should\\n       *     define the fromActor's margin\\n       * - There's a note, in which case fromActor == toActor\\n       *   - If the note is to the left of the actor, we should define the previous actor\\n       *     margin\\n       *   - If the note is on the actor, we should define both the previous and next actor\\n       *     margins, each being the half of the note size\\n       *   - If the note is on the right of the actor, we should define the current actor\\n       *     margin\\n       */\\n      if (isMessage &amp;&amp; msg.from === actor.nextActor) {\\n        maxMessageWidthPerActor[msg.to] = Math.max(\\n          maxMessageWidthPerActor[msg.to] || 0,\\n          messageWidth\\n        );\\n      } else if (isMessage &amp;&amp; msg.from === actor.prevActor) {\\n        maxMessageWidthPerActor[msg.from] = Math.max(\\n          maxMessageWidthPerActor[msg.from] || 0,\\n          messageWidth\\n        );\\n      } else if (isMessage &amp;&amp; msg.from === msg.to) {\\n        maxMessageWidthPerActor[msg.from] = Math.max(\\n          maxMessageWidthPerActor[msg.from] || 0,\\n          messageWidth / 2\\n        );\\n\\n        maxMessageWidthPerActor[msg.to] = Math.max(\\n          maxMessageWidthPerActor[msg.to] || 0,\\n          messageWidth / 2\\n        );\\n      } else if (msg.placement === parser.yy.PLACEMENT.RIGHTOF) {\\n        maxMessageWidthPerActor[msg.from] = Math.max(\\n          maxMessageWidthPerActor[msg.from] || 0,\\n          messageWidth\\n        );\\n      } else if (msg.placement === parser.yy.PLACEMENT.LEFTOF) {\\n        maxMessageWidthPerActor[actor.prevActor] = Math.max(\\n          maxMessageWidthPerActor[actor.prevActor] || 0,\\n          messageWidth\\n        );\\n      } else if (msg.placement === parser.yy.PLACEMENT.OVER) {\\n        if (actor.prevActor) {\\n          maxMessageWidthPerActor[actor.prevActor] = Math.max(\\n            maxMessageWidthPerActor[actor.prevActor] || 0,\\n            messageWidth / 2\\n          );\\n        }\\n\\n        if (actor.nextActor) {\\n          maxMessageWidthPerActor[msg.from] = Math.max(\\n            maxMessageWidthPerActor[msg.from] || 0,\\n            messageWidth / 2\\n          );\\n        }\\n      }\\n    }\\n  });\\n\\n  log.debug('maxMessageWidthPerActor:', maxMessageWidthPerActor);\\n  return maxMessageWidthPerActor;\\n};\\n\\nconst getRequiredPopupWidth = function (actor) {\\n  let requiredPopupWidth = 0;\\n  const textFont = actorFont(conf);\\n  for (let key in actor.links) {\\n    let labelDimensions = utils.calculateTextDimensions(key, textFont);\\n    let labelWidth = labelDimensions.width + 2 * conf.wrapPadding + 2 * conf.boxMargin;\\n    if (requiredPopupWidth &lt; labelWidth) {\\n      requiredPopupWidth = labelWidth;\\n    }\\n  }\\n\\n  return requiredPopupWidth;\\n};\\n\\n/**\\n * This will calculate the optimal margin for each given actor, for a given actor-&gt;messageWidth map.\\n *\\n * An actor's margin is determined by the width of the actor, the width of the largest message that\\n * originates from it, and the configured conf.actorMargin.\\n *\\n * @param {any} actors - The actors map to calculate margins for\\n * @param {any} actorToMessageWidth - A map of actor key -&gt; max message width it holds\\n */\\nconst calculateActorMargins = function (actors, actorToMessageWidth) {\\n  let maxHeight = 0;\\n  Object.keys(actors).forEach((prop) =&gt; {\\n    const actor = actors[prop];\\n    if (actor.wrap) {\\n      actor.description = utils.wrapLabel(\\n        actor.description,\\n        conf.width - 2 * conf.wrapPadding,\\n        actorFont(conf)\\n      );\\n    }\\n    const actDims = utils.calculateTextDimensions(actor.description, actorFont(conf));\\n    actor.width = actor.wrap\\n      ? conf.width\\n      : Math.max(conf.width, actDims.width + 2 * conf.wrapPadding);\\n\\n    actor.height = actor.wrap ? Math.max(actDims.height, conf.height) : conf.height;\\n    maxHeight = Math.max(maxHeight, actor.height);\\n  });\\n\\n  for (let actorKey in actorToMessageWidth) {\\n    const actor = actors[actorKey];\\n\\n    if (!actor) {\\n      continue;\\n    }\\n\\n    const nextActor = actors[actor.nextActor];\\n\\n    // No need to space out an actor that doesn't have a next link\\n    if (!nextActor) {\\n      continue;\\n    }\\n\\n    const messageWidth = actorToMessageWidth[actorKey];\\n    const actorWidth = messageWidth + conf.actorMargin - actor.width / 2 - nextActor.width / 2;\\n\\n    actor.margin = Math.max(actorWidth, conf.actorMargin);\\n  }\\n\\n  return Math.max(maxHeight, conf.height);\\n};\\n\\nconst buildNoteModel = function (msg, actors) {\\n  let startx = actors[msg.from].x;\\n  let stopx = actors[msg.to].x;\\n  let shouldWrap = msg.wrap &amp;&amp; msg.message;\\n\\n  let textDimensions = utils.calculateTextDimensions(\\n    shouldWrap ? utils.wrapLabel(msg.message, conf.width, noteFont(conf)) : msg.message,\\n    noteFont(conf)\\n  );\\n  let noteModel = {\\n    width: shouldWrap\\n      ? conf.width\\n      : Math.max(conf.width, textDimensions.width + 2 * conf.noteMargin),\\n    height: 0,\\n    startx: actors[msg.from].x,\\n    stopx: 0,\\n    starty: 0,\\n    stopy: 0,\\n    message: msg.message,\\n  };\\n  if (msg.placement === parser.yy.PLACEMENT.RIGHTOF) {\\n    noteModel.width = shouldWrap\\n      ? Math.max(conf.width, textDimensions.width)\\n      : Math.max(\\n          actors[msg.from].width / 2 + actors[msg.to].width / 2,\\n          textDimensions.width + 2 * conf.noteMargin\\n        );\\n    noteModel.startx = startx + (actors[msg.from].width + conf.actorMargin) / 2;\\n  } else if (msg.placement === parser.yy.PLACEMENT.LEFTOF) {\\n    noteModel.width = shouldWrap\\n      ? Math.max(conf.width, textDimensions.width + 2 * conf.noteMargin)\\n      : Math.max(\\n          actors[msg.from].width / 2 + actors[msg.to].width / 2,\\n          textDimensions.width + 2 * conf.noteMargin\\n        );\\n    noteModel.startx = startx - noteModel.width + (actors[msg.from].width - conf.actorMargin) / 2;\\n  } else if (msg.to === msg.from) {\\n    textDimensions = utils.calculateTextDimensions(\\n      shouldWrap\\n        ? utils.wrapLabel(msg.message, Math.max(conf.width, actors[msg.from].width), noteFont(conf))\\n        : msg.message,\\n      noteFont(conf)\\n    );\\n    noteModel.width = shouldWrap\\n      ? Math.max(conf.width, actors[msg.from].width)\\n      : Math.max(actors[msg.from].width, conf.width, textDimensions.width + 2 * conf.noteMargin);\\n    noteModel.startx = startx + (actors[msg.from].width - noteModel.width) / 2;\\n  } else {\\n    noteModel.width =\\n      Math.abs(startx + actors[msg.from].width / 2 - (stopx + actors[msg.to].width / 2)) +\\n      conf.actorMargin;\\n    noteModel.startx =\\n      startx &lt; stopx\\n        ? startx + actors[msg.from].width / 2 - conf.actorMargin / 2\\n        : stopx + actors[msg.to].width / 2 - conf.actorMargin / 2;\\n  }\\n  if (shouldWrap) {\\n    noteModel.message = utils.wrapLabel(\\n      msg.message,\\n      noteModel.width - 2 * conf.wrapPadding,\\n      noteFont(conf)\\n    );\\n  }\\n  log.debug(\\n    `NM:[${noteModel.startx},${noteModel.stopx},${noteModel.starty},${noteModel.stopy}:${noteModel.width},${noteModel.height}=${msg.message}]`\\n  );\\n  return noteModel;\\n};\\n\\nconst buildMessageModel = function (msg, actors) {\\n  let process = false;\\n  if (\\n    [\\n      parser.yy.LINETYPE.SOLID_OPEN,\\n      parser.yy.LINETYPE.DOTTED_OPEN,\\n      parser.yy.LINETYPE.SOLID,\\n      parser.yy.LINETYPE.DOTTED,\\n      parser.yy.LINETYPE.SOLID_CROSS,\\n      parser.yy.LINETYPE.DOTTED_CROSS,\\n      parser.yy.LINETYPE.SOLID_POINT,\\n      parser.yy.LINETYPE.DOTTED_POINT,\\n    ].includes(msg.type)\\n  ) {\\n    process = true;\\n  }\\n  if (!process) {\\n    return {};\\n  }\\n  const fromBounds = activationBounds(msg.from, actors);\\n  const toBounds = activationBounds(msg.to, actors);\\n  const fromIdx = fromBounds[0] &lt;= toBounds[0] ? 1 : 0;\\n  const toIdx = fromBounds[0] &lt; toBounds[0] ? 0 : 1;\\n  const allBounds = fromBounds.concat(toBounds);\\n  const boundedWidth = Math.abs(toBounds[toIdx] - fromBounds[fromIdx]);\\n  if (msg.wrap &amp;&amp; msg.message) {\\n    msg.message = utils.wrapLabel(\\n      msg.message,\\n      Math.max(boundedWidth + 2 * conf.wrapPadding, conf.width),\\n      messageFont(conf)\\n    );\\n  }\\n  const msgDims = utils.calculateTextDimensions(msg.message, messageFont(conf));\\n\\n  return {\\n    width: Math.max(\\n      msg.wrap ? 0 : msgDims.width + 2 * conf.wrapPadding,\\n      boundedWidth + 2 * conf.wrapPadding,\\n      conf.width\\n    ),\\n    height: 0,\\n    startx: fromBounds[fromIdx],\\n    stopx: toBounds[toIdx],\\n    starty: 0,\\n    stopy: 0,\\n    message: msg.message,\\n    type: msg.type,\\n    wrap: msg.wrap,\\n    fromBounds: Math.min.apply(null, allBounds),\\n    toBounds: Math.max.apply(null, allBounds),\\n  };\\n};\\n\\nconst calculateLoopBounds = function (messages, actors) {\\n  const loops = {};\\n  const stack = [];\\n  let current, noteModel, msgModel;\\n\\n  messages.forEach(function (msg) {\\n    msg.id = utils.random({ length: 10 });\\n    switch (msg.type) {\\n      case parser.yy.LINETYPE.LOOP_START:\\n      case parser.yy.LINETYPE.ALT_START:\\n      case parser.yy.LINETYPE.OPT_START:\\n      case parser.yy.LINETYPE.PAR_START:\\n        stack.push({\\n          id: msg.id,\\n          msg: msg.message,\\n          from: Number.MAX_SAFE_INTEGER,\\n          to: Number.MIN_SAFE_INTEGER,\\n          width: 0,\\n        });\\n        break;\\n      case parser.yy.LINETYPE.ALT_ELSE:\\n      case parser.yy.LINETYPE.PAR_AND:\\n        if (msg.message) {\\n          current = stack.pop();\\n          loops[current.id] = current;\\n          loops[msg.id] = current;\\n          stack.push(current);\\n        }\\n        break;\\n      case parser.yy.LINETYPE.LOOP_END:\\n      case parser.yy.LINETYPE.ALT_END:\\n      case parser.yy.LINETYPE.OPT_END:\\n      case parser.yy.LINETYPE.PAR_END:\\n        current = stack.pop();\\n        loops[current.id] = current;\\n        break;\\n      case parser.yy.LINETYPE.ACTIVE_START:\\n        {\\n          const actorRect = actors[msg.from ? msg.from.actor : msg.to.actor];\\n          const stackedSize = actorActivations(msg.from ? msg.from.actor : msg.to.actor).length;\\n          const x =\\n            actorRect.x + actorRect.width / 2 + ((stackedSize - 1) * conf.activationWidth) / 2;\\n          const toAdd = {\\n            startx: x,\\n            stopx: x + conf.activationWidth,\\n            actor: msg.from.actor,\\n            enabled: true,\\n          };\\n          bounds.activations.push(toAdd);\\n        }\\n        break;\\n      case parser.yy.LINETYPE.ACTIVE_END:\\n        {\\n          const lastActorActivationIdx = bounds.activations\\n            .map((a) =&gt; a.actor)\\n            .lastIndexOf(msg.from.actor);\\n          delete bounds.activations.splice(lastActorActivationIdx, 1)[0];\\n        }\\n        break;\\n    }\\n    const isNote = msg.placement !== undefined;\\n    if (isNote) {\\n      noteModel = buildNoteModel(msg, actors);\\n      msg.noteModel = noteModel;\\n      stack.forEach((stk) =&gt; {\\n        current = stk;\\n        current.from = Math.min(current.from, noteModel.startx);\\n        current.to = Math.max(current.to, noteModel.startx + noteModel.width);\\n        current.width =\\n          Math.max(current.width, Math.abs(current.from - current.to)) - conf.labelBoxWidth;\\n      });\\n    } else {\\n      msgModel = buildMessageModel(msg, actors);\\n      msg.msgModel = msgModel;\\n      if (msgModel.startx &amp;&amp; msgModel.stopx &amp;&amp; stack.length &gt; 0) {\\n        stack.forEach((stk) =&gt; {\\n          current = stk;\\n          if (msgModel.startx === msgModel.stopx) {\\n            let from = actors[msg.from];\\n            let to = actors[msg.to];\\n            current.from = Math.min(\\n              from.x - msgModel.width / 2,\\n              from.x - from.width / 2,\\n              current.from\\n            );\\n            current.to = Math.max(to.x + msgModel.width / 2, to.x + from.width / 2, current.to);\\n            current.width =\\n              Math.max(current.width, Math.abs(current.to - current.from)) - conf.labelBoxWidth;\\n          } else {\\n            current.from = Math.min(msgModel.startx, current.from);\\n            current.to = Math.max(msgModel.stopx, current.to);\\n            current.width = Math.max(current.width, msgModel.width) - conf.labelBoxWidth;\\n          }\\n        });\\n      }\\n    }\\n  });\\n  bounds.activations = [];\\n  log.debug('Loop type widths:', loops);\\n  return loops;\\n};\\n\\nexport default {\\n  bounds,\\n  drawActors,\\n  drawActorsPopup,\\n  setConf,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import { log } from '../../logger';\\nimport { generateId } from '../../utils';\\nimport mermaidAPI from '../../mermaidAPI';\\nimport common from '../common/common';\\nimport * as configApi from '../../config';\\n\\nconst clone = (o) =&gt; JSON.parse(JSON.stringify(o));\\nlet rootDoc = [];\\n\\nexport const parseDirective = function (statement, context, type) {\\n  mermaidAPI.parseDirective(this, statement, context, type);\\n};\\n\\nconst setRootDoc = (o) =&gt; {\\n  log.info('Setting root doc', o);\\n  // rootDoc = { id: 'root', doc: o };\\n  rootDoc = o;\\n};\\n\\nconst getRootDoc = () =&gt; rootDoc;\\n\\nconst docTranslator = (parent, node, first) =&gt; {\\n  if (node.stmt === 'relation') {\\n    docTranslator(parent, node.state1, true);\\n    docTranslator(parent, node.state2, false);\\n  } else {\\n    if (node.stmt === 'state') {\\n      if (node.id === '[*]') {\\n        node.id = first ? parent.id + '_start' : parent.id + '_end';\\n        node.start = first;\\n      }\\n    }\\n\\n    if (node.doc) {\\n      const doc = [];\\n      // Check for concurrency\\n      let i = 0;\\n      let currentDoc = [];\\n      for (i = 0; i &lt; node.doc.length; i++) {\\n        if (node.doc[i].type === 'divider') {\\n          // debugger;\\n          const newNode = clone(node.doc[i]);\\n          newNode.doc = clone(currentDoc);\\n          doc.push(newNode);\\n          currentDoc = [];\\n        } else {\\n          currentDoc.push(node.doc[i]);\\n        }\\n      }\\n\\n      // If any divider was encountered\\n      if (doc.length &gt; 0 &amp;&amp; currentDoc.length &gt; 0) {\\n        const newNode = {\\n          stmt: 'state',\\n          id: generateId(),\\n          type: 'divider',\\n          doc: clone(currentDoc),\\n        };\\n        doc.push(clone(newNode));\\n        node.doc = doc;\\n      }\\n\\n      node.doc.forEach((docNode) =&gt; docTranslator(node, docNode, true));\\n    }\\n  }\\n};\\nconst getRootDocV2 = () =&gt; {\\n  docTranslator({ id: 'root' }, { id: 'root', doc: rootDoc }, true);\\n  return { id: 'root', doc: rootDoc };\\n  // Here\\n};\\n\\nconst extract = (_doc) =&gt; {\\n  // const res = { states: [], relations: [] };\\n  let doc;\\n  if (_doc.doc) {\\n    doc = _doc.doc;\\n  } else {\\n    doc = _doc;\\n  }\\n  // let doc = root.doc;\\n  // if (!doc) {\\n  //   doc = root;\\n  // }\\n  log.info(doc);\\n  clear();\\n\\n  log.info('Extract', doc);\\n\\n  doc.forEach((item) =&gt; {\\n    if (item.stmt === 'state') {\\n      addState(item.id, item.type, item.doc, item.description, item.note);\\n    }\\n    if (item.stmt === 'relation') {\\n      addRelation(item.state1.id, item.state2.id, item.description);\\n    }\\n  });\\n};\\n\\nconst newDoc = () =&gt; {\\n  return {\\n    relations: [],\\n    states: {},\\n    documents: {},\\n  };\\n};\\n\\nlet documents = {\\n  root: newDoc(),\\n};\\n\\nlet currentDocument = documents.root;\\n\\nlet startCnt = 0;\\nlet endCnt = 0; // eslint-disable-line\\n// let stateCnt = 0;\\n\\n/**\\n * Function called by parser when a node definition has been found.\\n *\\n * @param {any} id\\n * @param {any} type\\n * @param {any} doc\\n * @param {any} descr\\n * @param {any} note\\n */\\nexport const addState = function (id, type, doc, descr, note) {\\n  if (typeof currentDocument.states[id] === 'undefined') {\\n    currentDocument.states[id] = {\\n      id: id,\\n      descriptions: [],\\n      type,\\n      doc,\\n      note,\\n    };\\n  } else {\\n    if (!currentDocument.states[id].doc) {\\n      currentDocument.states[id].doc = doc;\\n    }\\n    if (!currentDocument.states[id].type) {\\n      currentDocument.states[id].type = type;\\n    }\\n  }\\n  if (descr) {\\n    log.info('Adding state ', id, descr);\\n    if (typeof descr === 'string') addDescription(id, descr.trim());\\n\\n    if (typeof descr === 'object') {\\n      descr.forEach((des) =&gt; addDescription(id, des.trim()));\\n    }\\n  }\\n\\n  if (note) {\\n    currentDocument.states[id].note = note;\\n    currentDocument.states[id].note.text = common.sanitizeText(\\n      currentDocument.states[id].note.text,\\n      configApi.getConfig()\\n    );\\n  }\\n};\\n\\nexport const clear = function () {\\n  documents = {\\n    root: newDoc(),\\n  };\\n  currentDocument = documents.root;\\n\\n  currentDocument = documents.root;\\n\\n  startCnt = 0;\\n  endCnt = 0; // eslint-disable-line\\n  classes = [];\\n};\\n\\nexport const getState = function (id) {\\n  return currentDocument.states[id];\\n};\\n\\nexport const getStates = function () {\\n  return currentDocument.states;\\n};\\nexport const logDocuments = function () {\\n  log.info('Documents = ', documents);\\n};\\nexport const getRelations = function () {\\n  return currentDocument.relations;\\n};\\n\\nexport const addRelation = function (_id1, _id2, title) {\\n  let id1 = _id1;\\n  let id2 = _id2;\\n  let type1 = 'default';\\n  let type2 = 'default';\\n  if (_id1 === '[*]') {\\n    startCnt++;\\n    id1 = 'start' + startCnt;\\n    type1 = 'start';\\n  }\\n  if (_id2 === '[*]') {\\n    endCnt++;\\n    id2 = 'end' + startCnt;\\n    type2 = 'end';\\n  }\\n  addState(id1, type1);\\n  addState(id2, type2);\\n  currentDocument.relations.push({\\n    id1,\\n    id2,\\n    title: common.sanitizeText(title, configApi.getConfig()),\\n  });\\n};\\n\\nconst addDescription = function (id, _descr) {\\n  const theState = currentDocument.states[id];\\n  let descr = _descr;\\n  if (descr[0] === ':') {\\n    descr = descr.substr(1).trim();\\n  }\\n  theState.descriptions.push(common.sanitizeText(descr, configApi.getConfig()));\\n};\\n\\nexport const cleanupLabel = function (label) {\\n  if (label.substring(0, 1) === ':') {\\n    return label.substr(2).trim();\\n  } else {\\n    return label.trim();\\n  }\\n};\\n\\nexport const lineType = {\\n  LINE: 0,\\n  DOTTED_LINE: 1,\\n};\\n\\nlet dividerCnt = 0;\\nconst getDividerId = () =&gt; {\\n  dividerCnt++;\\n  return 'divider-id-' + dividerCnt;\\n};\\n\\nlet classes = [];\\n\\nconst getClasses = () =&gt; classes;\\n\\nlet direction = 'TB';\\nconst getDirection = () =&gt; direction;\\nconst setDirection = (dir) =&gt; {\\n  direction = dir;\\n};\\n\\nexport const relationType = {\\n  AGGREGATION: 0,\\n  EXTENSION: 1,\\n  COMPOSITION: 2,\\n  DEPENDENCY: 3,\\n};\\n\\nconst trimColon = (str) =&gt; (str &amp;&amp; str[0] === ':' ? str.substr(1).trim() : str.trim());\\n\\nexport default {\\n  parseDirective,\\n  getConfig: () =&gt; configApi.getConfig().state,\\n  addState,\\n  clear,\\n  getState,\\n  getStates,\\n  getRelations,\\n  getClasses,\\n  getDirection,\\n  addRelation,\\n  getDividerId,\\n  setDirection,\\n  // addDescription,\\n  cleanupLabel,\\n  lineType,\\n  relationType,\\n  logDocuments,\\n  getRootDoc,\\n  setRootDoc,\\n  getRootDocV2,\\n  extract,\\n  trimColon,\\n};\\n\"</span>,<span class=\"code-string\">\"const idCache = {};\\n\\nexport const set = (key, val) =&gt; {\\n  idCache[key] = val;\\n};\\n\\nexport const get = (k) =&gt; idCache[k];\\nexport const keys = () =&gt; Object.keys(idCache);\\nexport const size = () =&gt; keys().length;\\n\\nexport default {\\n  get,\\n  set,\\n  keys,\\n  size,\\n};\\n\"</span>,<span class=\"code-string\">\"import { line, curveBasis } from 'd3';\\nimport idCache from './id-cache.js';\\nimport stateDb from './stateDb';\\nimport utils from '../../utils';\\nimport common from '../common/common';\\nimport { getConfig } from '../../config';\\nimport { log } from '../../logger';\\n\\n/**\\n * Draws a start state as a black circle\\n *\\n * @param {any} g\\n */\\nexport const drawStartState = (g) =&gt;\\n  g\\n    .append('circle')\\n    // .style('stroke', 'black')\\n    // .style('fill', 'black')\\n    .attr('class', 'start-state')\\n    .attr('r', getConfig().state.sizeUnit)\\n    .attr('cx', getConfig().state.padding + getConfig().state.sizeUnit)\\n    .attr('cy', getConfig().state.padding + getConfig().state.sizeUnit);\\n\\n/**\\n * Draws a start state as a black circle\\n *\\n * @param {any} g\\n */\\nexport const drawDivider = (g) =&gt;\\n  g\\n    .append('line')\\n    .style('stroke', 'grey')\\n    .style('stroke-dasharray', '3')\\n    .attr('x1', getConfig().state.textHeight)\\n    .attr('class', 'divider')\\n    .attr('x2', getConfig().state.textHeight * 2)\\n    .attr('y1', 0)\\n    .attr('y2', 0);\\n\\n/**\\n * Draws a an end state as a black circle\\n *\\n * @param {any} g\\n * @param {any} stateDef\\n */\\nexport const drawSimpleState = (g, stateDef) =&gt; {\\n  const state = g\\n    .append('text')\\n    .attr('x', 2 * getConfig().state.padding)\\n    .attr('y', getConfig().state.textHeight + 2 * getConfig().state.padding)\\n    .attr('font-size', getConfig().state.fontSize)\\n    .attr('class', 'state-title')\\n    .text(stateDef.id);\\n\\n  const classBox = state.node().getBBox();\\n  g.insert('rect', ':first-child')\\n    .attr('x', getConfig().state.padding)\\n    .attr('y', getConfig().state.padding)\\n    .attr('width', classBox.width + 2 * getConfig().state.padding)\\n    .attr('height', classBox.height + 2 * getConfig().state.padding)\\n    .attr('rx', getConfig().state.radius);\\n\\n  return state;\\n};\\n\\n/**\\n * Draws a state with descriptions\\n *\\n * @param {any} g\\n * @param {any} stateDef\\n * @returns\\n */\\nexport const drawDescrState = (g, stateDef) =&gt; {\\n  const addTspan = function (textEl, txt, isFirst) {\\n    const tSpan = textEl\\n      .append('tspan')\\n      .attr('x', 2 * getConfig().state.padding)\\n      .text(txt);\\n    if (!isFirst) {\\n      tSpan.attr('dy', getConfig().state.textHeight);\\n    }\\n  };\\n  const title = g\\n    .append('text')\\n    .attr('x', 2 * getConfig().state.padding)\\n    .attr('y', getConfig().state.textHeight + 1.3 * getConfig().state.padding)\\n    .attr('font-size', getConfig().state.fontSize)\\n    .attr('class', 'state-title')\\n    .text(stateDef.descriptions[0]);\\n\\n  const titleBox = title.node().getBBox();\\n  const titleHeight = titleBox.height;\\n\\n  const description = g\\n    .append('text') // text label for the x axis\\n    .attr('x', getConfig().state.padding)\\n    .attr(\\n      'y',\\n      titleHeight +\\n        getConfig().state.padding * 0.4 +\\n        getConfig().state.dividerMargin +\\n        getConfig().state.textHeight\\n    )\\n    .attr('class', 'state-description');\\n\\n  let isFirst = true;\\n  let isSecond = true;\\n  stateDef.descriptions.forEach(function (descr) {\\n    if (!isFirst) {\\n      addTspan(description, descr, isSecond);\\n      isSecond = false;\\n    }\\n    isFirst = false;\\n  });\\n\\n  const descrLine = g\\n    .append('line') // text label for the x axis\\n    .attr('x1', getConfig().state.padding)\\n    .attr('y1', getConfig().state.padding + titleHeight + getConfig().state.dividerMargin / 2)\\n    .attr('y2', getConfig().state.padding + titleHeight + getConfig().state.dividerMargin / 2)\\n    .attr('class', 'descr-divider');\\n  const descrBox = description.node().getBBox();\\n  const width = Math.max(descrBox.width, titleBox.width);\\n\\n  descrLine.attr('x2', width + 3 * getConfig().state.padding);\\n  // const classBox = title.node().getBBox();\\n\\n  g.insert('rect', ':first-child')\\n    .attr('x', getConfig().state.padding)\\n    .attr('y', getConfig().state.padding)\\n    .attr('width', width + 2 * getConfig().state.padding)\\n    .attr('height', descrBox.height + titleHeight + 2 * getConfig().state.padding)\\n    .attr('rx', getConfig().state.radius);\\n\\n  return g;\\n};\\n\\n/** Adds the creates a box around the existing content and adds a panel for the id on top of the content. */\\n/**\\n * Function that creates an title row and a frame around a substate for a composit state diagram.\\n * The function returns a new d3 svg object with updated width and height properties;\\n *\\n * @param {any} g The d3 svg object for the substate to framed\\n * @param {any} stateDef The info about the\\n * @param {any} altBkg\\n */\\nexport const addTitleAndBox = (g, stateDef, altBkg) =&gt; {\\n  const pad = getConfig().state.padding;\\n  const dblPad = 2 * getConfig().state.padding;\\n  const orgBox = g.node().getBBox();\\n  const orgWidth = orgBox.width;\\n  const orgX = orgBox.x;\\n\\n  const title = g\\n    .append('text')\\n    .attr('x', 0)\\n    .attr('y', getConfig().state.titleShift)\\n    .attr('font-size', getConfig().state.fontSize)\\n    .attr('class', 'state-title')\\n    .text(stateDef.id);\\n\\n  const titleBox = title.node().getBBox();\\n  const titleWidth = titleBox.width + dblPad;\\n  let width = Math.max(titleWidth, orgWidth); // + dblPad;\\n  if (width === orgWidth) {\\n    width = width + dblPad;\\n  }\\n  let startX;\\n  // const lineY = 1 - getConfig().state.textHeight;\\n  // const descrLine = g\\n  //   .append('line') // text label for the x axis\\n  //   .attr('x1', 0)\\n  //   .attr('y1', lineY)\\n  //   .attr('y2', lineY)\\n  //   .attr('class', 'descr-divider');\\n\\n  const graphBox = g.node().getBBox();\\n  // descrLine.attr('x2', graphBox.width + getConfig().state.padding);\\n\\n  if (stateDef.doc) {\\n    // cnsole.warn(\\n    //   stateDef.id,\\n    //   'orgX: ',\\n    //   orgX,\\n    //   'width: ',\\n    //   width,\\n    //   'titleWidth: ',\\n    //   titleWidth,\\n    //   'orgWidth: ',\\n    //   orgWidth,\\n    //   'width',\\n    //   width\\n    // );\\n  }\\n\\n  startX = orgX - pad;\\n  if (titleWidth &gt; orgWidth) {\\n    startX = (orgWidth - width) / 2 + pad;\\n  }\\n  if (Math.abs(orgX - graphBox.x) &lt; pad) {\\n    if (titleWidth &gt; orgWidth) {\\n      startX = orgX - (titleWidth - orgWidth) / 2;\\n    }\\n  }\\n\\n  const lineY = 1 - getConfig().state.textHeight;\\n  // White color\\n  g.insert('rect', ':first-child')\\n    .attr('x', startX)\\n    .attr('y', lineY)\\n    .attr('class', altBkg ? 'alt-composit' : 'composit')\\n    .attr('width', width)\\n    .attr(\\n      'height',\\n      graphBox.height + getConfig().state.textHeight + getConfig().state.titleShift + 1\\n    )\\n    .attr('rx', '0');\\n\\n  title.attr('x', startX + pad);\\n  if (titleWidth &lt;= orgWidth) title.attr('x', orgX + (width - dblPad) / 2 - titleWidth / 2 + pad);\\n\\n  // Title background\\n  g.insert('rect', ':first-child')\\n    .attr('x', startX)\\n    .attr(\\n      'y',\\n      getConfig().state.titleShift - getConfig().state.textHeight - getConfig().state.padding\\n    )\\n    .attr('width', width)\\n    // Just needs to be higher then the descr line, will be clipped by the white color box\\n    .attr('height', getConfig().state.textHeight * 3)\\n    .attr('rx', getConfig().state.radius);\\n\\n  // Full background\\n  g.insert('rect', ':first-child')\\n    .attr('x', startX)\\n    .attr(\\n      'y',\\n      getConfig().state.titleShift - getConfig().state.textHeight - getConfig().state.padding\\n    )\\n    .attr('width', width)\\n    .attr('height', graphBox.height + 3 + 2 * getConfig().state.textHeight)\\n    .attr('rx', getConfig().state.radius);\\n\\n  return g;\\n};\\n\\nconst drawEndState = (g) =&gt; {\\n  g.append('circle')\\n    // .style('stroke', 'black')\\n    // .style('fill', 'white')\\n    .attr('class', 'end-state-outer')\\n    .attr('r', getConfig().state.sizeUnit + getConfig().state.miniPadding)\\n    .attr(\\n      'cx',\\n      getConfig().state.padding + getConfig().state.sizeUnit + getConfig().state.miniPadding\\n    )\\n    .attr(\\n      'cy',\\n      getConfig().state.padding + getConfig().state.sizeUnit + getConfig().state.miniPadding\\n    );\\n\\n  return (\\n    g\\n      .append('circle')\\n      // .style('stroke', 'black')\\n      // .style('fill', 'black')\\n      .attr('class', 'end-state-inner')\\n      .attr('r', getConfig().state.sizeUnit)\\n      .attr('cx', getConfig().state.padding + getConfig().state.sizeUnit + 2)\\n      .attr('cy', getConfig().state.padding + getConfig().state.sizeUnit + 2)\\n  );\\n};\\nconst drawForkJoinState = (g, stateDef) =&gt; {\\n  let width = getConfig().state.forkWidth;\\n  let height = getConfig().state.forkHeight;\\n\\n  if (stateDef.parentId) {\\n    let tmp = width;\\n    width = height;\\n    height = tmp;\\n  }\\n  return g\\n    .append('rect')\\n    .style('stroke', 'black')\\n    .style('fill', 'black')\\n    .attr('width', width)\\n    .attr('height', height)\\n    .attr('x', getConfig().state.padding)\\n    .attr('y', getConfig().state.padding);\\n};\\n\\nexport const drawText = function (elem, textData) {\\n  // Remove and ignore br:s\\n  const nText = textData.text.replace(common.lineBreakRegex, ' ');\\n\\n  const textElem = elem.append('text');\\n  textElem.attr('x', textData.x);\\n  textElem.attr('y', textData.y);\\n  textElem.style('text-anchor', textData.anchor);\\n  textElem.attr('fill', textData.fill);\\n  if (typeof textData.class !== 'undefined') {\\n    textElem.attr('class', textData.class);\\n  }\\n\\n  const span = textElem.append('tspan');\\n  span.attr('x', textData.x + textData.textMargin * 2);\\n  span.attr('fill', textData.fill);\\n  span.text(nText);\\n\\n  return textElem;\\n};\\n\\nconst _drawLongText = (_text, x, y, g) =&gt; {\\n  let textHeight = 0;\\n\\n  const textElem = g.append('text');\\n  textElem.style('text-anchor', 'start');\\n  textElem.attr('class', 'noteText');\\n\\n  let text = _text.replace(/\\\\r\\\\n/g, '&lt;br/&gt;');\\n  text = text.replace(/\\\\n/g, '&lt;br/&gt;');\\n  const lines = text.split(common.lineBreakRegex);\\n\\n  let tHeight = 1.25 * getConfig().state.noteMargin;\\n  for (const line of lines) {\\n    const txt = line.trim();\\n\\n    if (txt.length &gt; 0) {\\n      const span = textElem.append('tspan');\\n      span.text(txt);\\n      if (tHeight === 0) {\\n        const textBounds = span.node().getBBox();\\n        tHeight += textBounds.height;\\n      }\\n      textHeight += tHeight;\\n      span.attr('x', x + getConfig().state.noteMargin);\\n      span.attr('y', y + textHeight + 1.25 * getConfig().state.noteMargin);\\n    }\\n  }\\n  return { textWidth: textElem.node().getBBox().width, textHeight };\\n};\\n\\n/**\\n * Draws a note to the diagram\\n *\\n * @param text - The text of the given note.\\n * @param g - The element the note is attached to.\\n */\\n\\nexport const drawNote = (text, g) =&gt; {\\n  g.attr('class', 'state-note');\\n  const note = g.append('rect').attr('x', 0).attr('y', getConfig().state.padding);\\n  const rectElem = g.append('g');\\n\\n  const { textWidth, textHeight } = _drawLongText(text, 0, 0, rectElem);\\n  note.attr('height', textHeight + 2 * getConfig().state.noteMargin);\\n  note.attr('width', textWidth + getConfig().state.noteMargin * 2);\\n\\n  return note;\\n};\\n\\n/**\\n * Starting point for drawing a state. The function finds out the specifics about the state and\\n * renders with approprtiate function.\\n *\\n * @param {any} elem\\n * @param {any} stateDef\\n */\\n\\nexport const drawState = function (elem, stateDef) {\\n  const id = stateDef.id;\\n  const stateInfo = {\\n    id: id,\\n    label: stateDef.id,\\n    width: 0,\\n    height: 0,\\n  };\\n\\n  const g = elem.append('g').attr('id', id).attr('class', 'stateGroup');\\n\\n  if (stateDef.type === 'start') drawStartState(g);\\n  if (stateDef.type === 'end') drawEndState(g);\\n  if (stateDef.type === 'fork' || stateDef.type === 'join') drawForkJoinState(g, stateDef);\\n  if (stateDef.type === 'note') drawNote(stateDef.note.text, g);\\n  if (stateDef.type === 'divider') drawDivider(g);\\n  if (stateDef.type === 'default' &amp;&amp; stateDef.descriptions.length === 0)\\n    drawSimpleState(g, stateDef);\\n  if (stateDef.type === 'default' &amp;&amp; stateDef.descriptions.length &gt; 0) drawDescrState(g, stateDef);\\n\\n  const stateBox = g.node().getBBox();\\n  stateInfo.width = stateBox.width + 2 * getConfig().state.padding;\\n  stateInfo.height = stateBox.height + 2 * getConfig().state.padding;\\n\\n  idCache.set(id, stateInfo);\\n  // stateCnt++;\\n  return stateInfo;\\n};\\n\\nlet edgeCount = 0;\\nexport const drawEdge = function (elem, path, relation) {\\n  const getRelationType = function (type) {\\n    switch (type) {\\n      case stateDb.relationType.AGGREGATION:\\n        return 'aggregation';\\n      case stateDb.relationType.EXTENSION:\\n        return 'extension';\\n      case stateDb.relationType.COMPOSITION:\\n        return 'composition';\\n      case stateDb.relationType.DEPENDENCY:\\n        return 'dependency';\\n    }\\n  };\\n\\n  path.points = path.points.filter((p) =&gt; !Number.isNaN(p.y));\\n\\n  // The data for our line\\n  const lineData = path.points;\\n\\n  // This is the accessor function we talked about above\\n  const lineFunction = line()\\n    .x(function (d) {\\n      return d.x;\\n    })\\n    .y(function (d) {\\n      return d.y;\\n    })\\n    .curve(curveBasis);\\n\\n  const svgPath = elem\\n    .append('path')\\n    .attr('d', lineFunction(lineData))\\n    .attr('id', 'edge' + edgeCount)\\n    .attr('class', 'transition');\\n  let url = '';\\n  if (getConfig().state.arrowMarkerAbsolute) {\\n    url =\\n      window.location.protocol +\\n      '//' +\\n      window.location.host +\\n      window.location.pathname +\\n      window.location.search;\\n    url = url.replace(/\\\\(/g, '\\\\\\\\(');\\n    url = url.replace(/\\\\)/g, '\\\\\\\\)');\\n  }\\n\\n  svgPath.attr(\\n    'marker-end',\\n    'url(' + url + '#' + getRelationType(stateDb.relationType.DEPENDENCY) + 'End' + ')'\\n  );\\n\\n  if (typeof relation.title !== 'undefined') {\\n    const label = elem.append('g').attr('class', 'stateLabel');\\n\\n    const { x, y } = utils.calcLabelPosition(path.points);\\n\\n    const rows = common.getRows(relation.title);\\n\\n    let titleHeight = 0;\\n    const titleRows = [];\\n    let maxWidth = 0;\\n    let minX = 0;\\n\\n    for (let i = 0; i &lt;= rows.length; i++) {\\n      const title = label\\n        .append('text')\\n        .attr('text-anchor', 'middle')\\n        .text(rows[i])\\n        .attr('x', x)\\n        .attr('y', y + titleHeight);\\n\\n      const boundstmp = title.node().getBBox();\\n      maxWidth = Math.max(maxWidth, boundstmp.width);\\n      minX = Math.min(minX, boundstmp.x);\\n\\n      log.info(boundstmp.x, x, y + titleHeight);\\n\\n      if (titleHeight === 0) {\\n        const titleBox = title.node().getBBox();\\n        titleHeight = titleBox.height;\\n        log.info('Title height', titleHeight, y);\\n      }\\n      titleRows.push(title);\\n    }\\n\\n    let boxHeight = titleHeight * rows.length;\\n    if (rows.length &gt; 1) {\\n      const heightAdj = (rows.length - 1) * titleHeight * 0.5;\\n\\n      titleRows.forEach((title, i) =&gt; title.attr('y', y + i * titleHeight - heightAdj));\\n      boxHeight = titleHeight * rows.length;\\n    }\\n\\n    const bounds = label.node().getBBox();\\n\\n    label\\n      .insert('rect', ':first-child')\\n      .attr('class', 'box')\\n      .attr('x', x - maxWidth / 2 - getConfig().state.padding / 2)\\n      .attr('y', y - boxHeight / 2 - getConfig().state.padding / 2 - 3.5)\\n      .attr('width', maxWidth + getConfig().state.padding)\\n      .attr('height', boxHeight + getConfig().state.padding);\\n\\n    log.info(bounds);\\n\\n    //label.attr('transform', '0 -' + (bounds.y / 2));\\n\\n    // Debug points\\n    // path.points.forEach(point =&gt; {\\n    //   g.append('circle')\\n    //     .style('stroke', 'red')\\n    //     .style('fill', 'red')\\n    //     .attr('r', 1)\\n    //     .attr('cx', point.x)\\n    //     .attr('cy', point.y);\\n    // });\\n    // g.append('circle')\\n    //   .style('stroke', 'blue')\\n    //   .style('fill', 'blue')\\n    //   .attr('r', 1)\\n    //   .attr('cx', x)\\n    //   .attr('cy', y);\\n  }\\n\\n  edgeCount++;\\n};\\n\"</span>,<span class=\"code-string\">\"import { select } from 'd3';\\nimport dagre from 'dagre';\\nimport graphlib from 'graphlib';\\nimport { log } from '../../logger';\\nimport stateDb from './stateDb';\\nimport common from '../common/common';\\nimport { parser } from './parser/stateDiagram';\\n// import idCache from './id-cache';\\nimport { drawState, addTitleAndBox, drawEdge } from './shapes';\\nimport { getConfig } from '../../config';\\nimport { configureSvgSize } from '../../utils';\\n\\nparser.yy = stateDb;\\n\\n// TODO Move conf object to main conf in mermaidAPI\\nlet conf;\\n\\nconst transformationLog = {};\\n\\nexport const setConf = function () {};\\n\\n/**\\n * Setup arrow head and define the marker. The result is appended to the svg.\\n *\\n * @param {any} elem\\n */\\nconst insertMarkers = function (elem) {\\n  elem\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', 'dependencyEnd')\\n    .attr('refX', 19)\\n    .attr('refY', 7)\\n    .attr('markerWidth', 20)\\n    .attr('markerHeight', 28)\\n    .attr('orient', 'auto')\\n    .append('path')\\n    .attr('d', 'M 19,7 L9,13 L14,7 L9,1 Z');\\n};\\n\\n/**\\n * Draws a flowchart in the tag with id: id based on the graph definition in text.\\n *\\n * @param {any} text\\n * @param {any} id\\n */\\nexport const draw = function (text, id) {\\n  conf = getConfig().state;\\n  const securityLevel = getConfig().securityLevel;\\n  // Handle root and ocument for when rendering in sanbox mode\\n  let sandboxElement;\\n  if (securityLevel === 'sandbox') {\\n    sandboxElement = select('#i' + id);\\n  }\\n  const root =\\n    securityLevel === 'sandbox'\\n      ? select(sandboxElement.nodes()[0].contentDocument.body)\\n      : select('body');\\n  const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n\\n  parser.yy.clear();\\n  parser.parse(text);\\n  log.debug('Rendering diagram ' + text);\\n\\n  // Fetch the default direction, use TD if none was found\\n  const diagram = root.select(`[id='${id}']`);\\n  insertMarkers(diagram);\\n\\n  // Layout graph, Create a new directed graph\\n  const graph = new graphlib.Graph({\\n    multigraph: true,\\n    compound: true,\\n    // acyclicer: 'greedy',\\n    rankdir: 'RL',\\n    // ranksep: '20'\\n  });\\n\\n  // Default to assigning a new object as a label for each new edge.\\n  graph.setDefaultEdgeLabel(function () {\\n    return {};\\n  });\\n\\n  const rootDoc = stateDb.getRootDoc();\\n  renderDoc(rootDoc, diagram, undefined, false, root, doc);\\n\\n  const padding = conf.padding;\\n  const bounds = diagram.node().getBBox();\\n\\n  const width = bounds.width + padding * 2;\\n  const height = bounds.height + padding * 2;\\n\\n  // zoom in a bit\\n  const svgWidth = width * 1.75;\\n  configureSvgSize(diagram, height, svgWidth, conf.useMaxWidth);\\n\\n  diagram.attr(\\n    'viewBox',\\n    `${bounds.x - conf.padding}  ${bounds.y - conf.padding} ` + width + ' ' + height\\n  );\\n};\\nconst getLabelWidth = (text) =&gt; {\\n  return text ? text.length * conf.fontSizeFactor : 1;\\n};\\n\\nconst renderDoc = (doc, diagram, parentId, altBkg, root, domDocument) =&gt; {\\n  // Layout graph, Create a new directed graph\\n  const graph = new graphlib.Graph({\\n    compound: true,\\n    multigraph: true,\\n  });\\n\\n  let i;\\n  let edgeFreeDoc = true;\\n  for (i = 0; i &lt; doc.length; i++) {\\n    if (doc[i].stmt === 'relation') {\\n      edgeFreeDoc = false;\\n      break;\\n    }\\n  }\\n\\n  // Set an object for the graph label\\n  if (parentId)\\n    graph.setGraph({\\n      rankdir: 'LR',\\n      multigraph: true,\\n      compound: true,\\n      // acyclicer: 'greedy',\\n      ranker: 'tight-tree',\\n      ranksep: edgeFreeDoc ? 1 : conf.edgeLengthFactor,\\n      nodeSep: edgeFreeDoc ? 1 : 50,\\n      isMultiGraph: true,\\n      // ranksep: 5,\\n      // nodesep: 1\\n    });\\n  else {\\n    graph.setGraph({\\n      rankdir: 'TB',\\n      multigraph: true,\\n      compound: true,\\n      // isCompound: true,\\n      // acyclicer: 'greedy',\\n      // ranker: 'longest-path'\\n      ranksep: edgeFreeDoc ? 1 : conf.edgeLengthFactor,\\n      nodeSep: edgeFreeDoc ? 1 : 50,\\n      ranker: 'tight-tree',\\n      // ranker: 'network-simplex'\\n      isMultiGraph: true,\\n    });\\n  }\\n\\n  // Default to assigning a new object as a label for each new edge.\\n  graph.setDefaultEdgeLabel(function () {\\n    return {};\\n  });\\n\\n  stateDb.extract(doc);\\n  const states = stateDb.getStates();\\n  const relations = stateDb.getRelations();\\n\\n  const keys = Object.keys(states);\\n\\n  let first = true;\\n\\n  for (let i = 0; i &lt; keys.length; i++) {\\n    const stateDef = states[keys[i]];\\n\\n    if (parentId) {\\n      stateDef.parentId = parentId;\\n    }\\n\\n    let node;\\n    if (stateDef.doc) {\\n      let sub = diagram.append('g').attr('id', stateDef.id).attr('class', 'stateGroup');\\n      node = renderDoc(stateDef.doc, sub, stateDef.id, !altBkg, root, domDocument);\\n\\n      if (first) {\\n        // first = false;\\n        sub = addTitleAndBox(sub, stateDef, altBkg);\\n        let boxBounds = sub.node().getBBox();\\n        node.width = boxBounds.width;\\n        node.height = boxBounds.height + conf.padding / 2;\\n        transformationLog[stateDef.id] = { y: conf.compositTitleSize };\\n      } else {\\n        // sub = addIdAndBox(sub, stateDef);\\n        let boxBounds = sub.node().getBBox();\\n        node.width = boxBounds.width;\\n        node.height = boxBounds.height;\\n        // transformationLog[stateDef.id] = { y: conf.compositTitleSize };\\n      }\\n    } else {\\n      node = drawState(diagram, stateDef, graph);\\n    }\\n\\n    if (stateDef.note) {\\n      // Draw note note\\n      const noteDef = {\\n        descriptions: [],\\n        id: stateDef.id + '-note',\\n        note: stateDef.note,\\n        type: 'note',\\n      };\\n      const note = drawState(diagram, noteDef, graph);\\n\\n      // graph.setNode(node.id, node);\\n      if (stateDef.note.position === 'left of') {\\n        graph.setNode(node.id + '-note', note);\\n        graph.setNode(node.id, node);\\n      } else {\\n        graph.setNode(node.id, node);\\n        graph.setNode(node.id + '-note', note);\\n      }\\n      // graph.setNode(node.id);\\n      graph.setParent(node.id, node.id + '-group');\\n      graph.setParent(node.id + '-note', node.id + '-group');\\n    } else {\\n      // Add nodes to the graph. The first argument is the node id. The second is\\n      // metadata about the node. In this case we're going to add labels to each of\\n      // our nodes.\\n      graph.setNode(node.id, node);\\n    }\\n  }\\n\\n  log.debug('Count=', graph.nodeCount(), graph);\\n  let cnt = 0;\\n  relations.forEach(function (relation) {\\n    cnt++;\\n    log.debug('Setting edge', relation);\\n    graph.setEdge(\\n      relation.id1,\\n      relation.id2,\\n      {\\n        relation: relation,\\n        width: getLabelWidth(relation.title),\\n        height: conf.labelHeight * common.getRows(relation.title).length,\\n        labelpos: 'c',\\n      },\\n      'id' + cnt\\n    );\\n  });\\n\\n  dagre.layout(graph);\\n\\n  log.debug('Graph after layout', graph.nodes());\\n  const svgElem = diagram.node();\\n\\n  graph.nodes().forEach(function (v) {\\n    if (typeof v !== 'undefined' &amp;&amp; typeof graph.node(v) !== 'undefined') {\\n      log.warn('Node ' + v + ': ' + JSON.stringify(graph.node(v)));\\n      root\\n        .select('#' + svgElem.id + ' #' + v)\\n        .attr(\\n          'transform',\\n          'translate(' +\\n            (graph.node(v).x - graph.node(v).width / 2) +\\n            ',' +\\n            (graph.node(v).y +\\n              (transformationLog[v] ? transformationLog[v].y : 0) -\\n              graph.node(v).height / 2) +\\n            ' )'\\n        );\\n      root\\n        .select('#' + svgElem.id + ' #' + v)\\n        .attr('data-x-shift', graph.node(v).x - graph.node(v).width / 2);\\n      const dividers = domDocument.querySelectorAll('#' + svgElem.id + ' #' + v + ' .divider');\\n      dividers.forEach((divider) =&gt; {\\n        const parent = divider.parentElement;\\n        let pWidth = 0;\\n        let pShift = 0;\\n        if (parent) {\\n          if (parent.parentElement) pWidth = parent.parentElement.getBBox().width;\\n          pShift = parseInt(parent.getAttribute('data-x-shift'), 10);\\n          if (Number.isNaN(pShift)) {\\n            pShift = 0;\\n          }\\n        }\\n        divider.setAttribute('x1', 0 - pShift + 8);\\n        divider.setAttribute('x2', pWidth - pShift - 8);\\n      });\\n    } else {\\n      log.debug('No Node ' + v + ': ' + JSON.stringify(graph.node(v)));\\n    }\\n  });\\n\\n  let stateBox = svgElem.getBBox();\\n\\n  graph.edges().forEach(function (e) {\\n    if (typeof e !== 'undefined' &amp;&amp; typeof graph.edge(e) !== 'undefined') {\\n      log.debug('Edge ' + e.v + ' -&gt; ' + e.w + ': ' + JSON.stringify(graph.edge(e)));\\n      drawEdge(diagram, graph.edge(e), graph.edge(e).relation);\\n    }\\n  });\\n\\n  stateBox = svgElem.getBBox();\\n\\n  const stateInfo = {\\n    id: parentId ? parentId : 'root',\\n    label: parentId ? parentId : 'root',\\n    width: 0,\\n    height: 0,\\n  };\\n\\n  stateInfo.width = stateBox.width + 2 * conf.padding;\\n  stateInfo.height = stateBox.height + 2 * conf.padding;\\n\\n  log.debug('Doc rendered', stateInfo, graph);\\n  return stateInfo;\\n};\\n\\nexport default {\\n  setConf,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import graphlib from 'graphlib';\\nimport { select } from 'd3';\\nimport stateDb from './stateDb';\\nimport state from './parser/stateDiagram';\\nimport { getConfig } from '../../config';\\nimport { render } from '../../dagre-wrapper/index.js';\\nimport { log } from '../../logger';\\nimport { configureSvgSize } from '../../utils';\\nimport common from '../common/common';\\n\\nconst conf = {};\\nexport const setConf = function (cnf) {\\n  const keys = Object.keys(cnf);\\n  for (let i = 0; i &lt; keys.length; i++) {\\n    conf[keys[i]] = cnf[keys[i]];\\n  }\\n};\\n\\nlet nodeDb = {};\\n\\n/**\\n * Returns the all the styles from classDef statements in the graph definition.\\n *\\n * @param {any} text\\n * @returns {object} ClassDef styles\\n */\\nexport const getClasses = function (text) {\\n  log.trace('Extracting classes');\\n  stateDb.clear();\\n  const parser = state.parser;\\n  parser.yy = stateDb;\\n\\n  // Parse the graph definition\\n  parser.parse(text);\\n  return stateDb.getClasses();\\n};\\n\\nconst setupNode = (g, parent, node, altFlag) =&gt; {\\n  // Add the node\\n  if (node.id !== 'root') {\\n    let shape = 'rect';\\n    if (node.start === true) {\\n      shape = 'start';\\n    }\\n    if (node.start === false) {\\n      shape = 'end';\\n    }\\n    if (node.type !== 'default') {\\n      shape = node.type;\\n    }\\n\\n    if (!nodeDb[node.id]) {\\n      nodeDb[node.id] = {\\n        id: node.id,\\n        shape,\\n        description: common.sanitizeText(node.id, getConfig()),\\n        classes: 'statediagram-state',\\n      };\\n    }\\n\\n    // Build of the array of description strings accordinging\\n    if (node.description) {\\n      if (Array.isArray(nodeDb[node.id].description)) {\\n        // There already is an array of strings,add to it\\n        nodeDb[node.id].shape = 'rectWithTitle';\\n        nodeDb[node.id].description.push(node.description);\\n      } else {\\n        if (nodeDb[node.id].description.length &gt; 0) {\\n          // if there is a description already transformit to an array\\n          nodeDb[node.id].shape = 'rectWithTitle';\\n          if (nodeDb[node.id].description === node.id) {\\n            // If the previous description was the is, remove it\\n            nodeDb[node.id].description = [node.description];\\n          } else {\\n            nodeDb[node.id].description = [nodeDb[node.id].description, node.description];\\n          }\\n        } else {\\n          nodeDb[node.id].shape = 'rect';\\n          nodeDb[node.id].description = node.description;\\n        }\\n      }\\n      nodeDb[node.id].description = common.sanitizeTextOrArray(\\n        nodeDb[node.id].description,\\n        getConfig()\\n      );\\n    }\\n\\n    //\\n    if (nodeDb[node.id].description.length === 1 &amp;&amp; nodeDb[node.id].shape === 'rectWithTitle') {\\n      nodeDb[node.id].shape = 'rect';\\n    }\\n\\n    // Save data for description and group so that for instance a statement without description overwrites\\n    // one with description\\n\\n    // group\\n    if (!nodeDb[node.id].type &amp;&amp; node.doc) {\\n      log.info('Setting cluster for ', node.id, getDir(node));\\n      nodeDb[node.id].type = 'group';\\n      nodeDb[node.id].dir = getDir(node);\\n      nodeDb[node.id].shape = node.type === 'divider' ? 'divider' : 'roundedWithTitle';\\n      nodeDb[node.id].classes =\\n        nodeDb[node.id].classes +\\n        ' ' +\\n        (altFlag ? 'statediagram-cluster statediagram-cluster-alt' : 'statediagram-cluster');\\n    }\\n\\n    const nodeData = {\\n      labelStyle: '',\\n      shape: nodeDb[node.id].shape,\\n      labelText: nodeDb[node.id].description,\\n      // typeof nodeDb[node.id].description === 'object'\\n      //   ? nodeDb[node.id].description[0]\\n      //   : nodeDb[node.id].description,\\n      classes: nodeDb[node.id].classes, //classStr,\\n      style: '', //styles.style,\\n      id: node.id,\\n      dir: nodeDb[node.id].dir,\\n      domId: 'state-' + node.id + '-' + cnt,\\n      type: nodeDb[node.id].type,\\n      padding: 15, //getConfig().flowchart.padding\\n    };\\n\\n    if (node.note) {\\n      // Todo: set random id\\n      const noteData = {\\n        labelStyle: '',\\n        shape: 'note',\\n        labelText: node.note.text,\\n        classes: 'statediagram-note', //classStr,\\n        style: '', //styles.style,\\n        id: node.id + '----note-' + cnt,\\n        domId: 'state-' + node.id + '----note-' + cnt,\\n        type: nodeDb[node.id].type,\\n        padding: 15, //getConfig().flowchart.padding\\n      };\\n      const groupData = {\\n        labelStyle: '',\\n        shape: 'noteGroup',\\n        labelText: node.note.text,\\n        classes: nodeDb[node.id].classes, //classStr,\\n        style: '', //styles.style,\\n        id: node.id + '----parent',\\n        domId: 'state-' + node.id + '----parent-' + cnt,\\n        type: 'group',\\n        padding: 0, //getConfig().flowchart.padding\\n      };\\n      cnt++;\\n\\n      g.setNode(node.id + '----parent', groupData);\\n\\n      g.setNode(noteData.id, noteData);\\n      g.setNode(node.id, nodeData);\\n\\n      g.setParent(node.id, node.id + '----parent');\\n      g.setParent(noteData.id, node.id + '----parent');\\n\\n      let from = node.id;\\n      let to = noteData.id;\\n\\n      if (node.note.position === 'left of') {\\n        from = noteData.id;\\n        to = node.id;\\n      }\\n      g.setEdge(from, to, {\\n        arrowhead: 'none',\\n        arrowType: '',\\n        style: 'fill:none',\\n        labelStyle: '',\\n        classes: 'transition note-edge',\\n        arrowheadStyle: 'fill: #333',\\n        labelpos: 'c',\\n        labelType: 'text',\\n        thickness: 'normal',\\n      });\\n    } else {\\n      g.setNode(node.id, nodeData);\\n    }\\n  }\\n\\n  if (parent) {\\n    if (parent.id !== 'root') {\\n      log.trace('Setting node ', node.id, ' to be child of its parent ', parent.id);\\n      g.setParent(node.id, parent.id);\\n    }\\n  }\\n  if (node.doc) {\\n    log.trace('Adding nodes children ');\\n    setupDoc(g, node, node.doc, !altFlag);\\n  }\\n};\\nlet cnt = 0;\\nconst setupDoc = (g, parent, doc, altFlag) =&gt; {\\n  // cnt = 0;\\n  log.trace('items', doc);\\n  doc.forEach((item) =&gt; {\\n    if (item.stmt === 'state' || item.stmt === 'default') {\\n      setupNode(g, parent, item, altFlag);\\n    } else if (item.stmt === 'relation') {\\n      setupNode(g, parent, item.state1, altFlag);\\n      setupNode(g, parent, item.state2, altFlag);\\n      const edgeData = {\\n        id: 'edge' + cnt,\\n        arrowhead: 'normal',\\n        arrowTypeEnd: 'arrow_barb',\\n        style: 'fill:none',\\n        labelStyle: '',\\n        label: common.sanitizeText(item.description, getConfig()),\\n        arrowheadStyle: 'fill: #333',\\n        labelpos: 'c',\\n        labelType: 'text',\\n        thickness: 'normal',\\n        classes: 'transition',\\n      };\\n      let startId = item.state1.id;\\n      let endId = item.state2.id;\\n\\n      g.setEdge(startId, endId, edgeData, cnt);\\n      cnt++;\\n    }\\n  });\\n};\\nconst getDir = (nodes, defaultDir) =&gt; {\\n  let dir = defaultDir || 'TB';\\n  if (nodes.doc) {\\n    for (let i = 0; i &lt; nodes.doc.length; i++) {\\n      const node = nodes.doc[i];\\n      if (node.stmt === 'dir') {\\n        dir = node.value;\\n      }\\n    }\\n  }\\n  return dir;\\n};\\n/**\\n * Draws a flowchart in the tag with id: id based on the graph definition in text.\\n *\\n * @param {any} text\\n * @param {any} id\\n */\\nexport const draw = function (text, id) {\\n  log.info('Drawing state diagram (v2)', id);\\n  stateDb.clear();\\n  nodeDb = {};\\n  const parser = state.parser;\\n  parser.yy = stateDb;\\n\\n  // Parse the graph definition\\n  parser.parse(text);\\n\\n  // Fetch the default direction, use TD if none was found\\n  let dir = stateDb.getDirection();\\n  if (typeof dir === 'undefined') {\\n    dir = 'LR';\\n  }\\n\\n  const conf = getConfig().state;\\n  const nodeSpacing = conf.nodeSpacing || 50;\\n  const rankSpacing = conf.rankSpacing || 50;\\n\\n  const securityLevel = getConfig().securityLevel;\\n\\n  log.info(stateDb.getRootDocV2());\\n  stateDb.extract(stateDb.getRootDocV2());\\n  log.info(stateDb.getRootDocV2());\\n\\n  // Create the input mermaid.graph\\n  const g = new graphlib.Graph({\\n    multigraph: true,\\n    compound: true,\\n  })\\n    .setGraph({\\n      rankdir: getDir(stateDb.getRootDocV2()),\\n      nodesep: nodeSpacing,\\n      ranksep: rankSpacing,\\n      marginx: 8,\\n      marginy: 8,\\n    })\\n    .setDefaultEdgeLabel(function () {\\n      return {};\\n    });\\n\\n  setupNode(g, undefined, stateDb.getRootDocV2(), true);\\n\\n  // Set up an SVG group so that we can translate the final graph.\\n  let sandboxElement;\\n  if (securityLevel === 'sandbox') {\\n    sandboxElement = select('#i' + id);\\n  }\\n  const root =\\n    securityLevel === 'sandbox'\\n      ? select(sandboxElement.nodes()[0].contentDocument.body)\\n      : select('body');\\n  const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n  const svg = root.select(`[id=\\\"${id}\\\"]`);\\n\\n  // Run the renderer. This is what draws the final graph.\\n\\n  const element = root.select('#' + id + ' g');\\n  render(element, g, ['barb'], 'statediagram', id);\\n\\n  const padding = 8;\\n\\n  const bounds = svg.node().getBBox();\\n\\n  const width = bounds.width + padding * 2;\\n  const height = bounds.height + padding * 2;\\n\\n  // Zoom in a bit\\n  svg.attr('class', 'statediagram');\\n\\n  const svgBounds = svg.node().getBBox();\\n\\n  configureSvgSize(svg, height, width * 1.75, conf.useMaxWidth);\\n\\n  // Ensure the viewBox includes the whole svgBounds area with extra space for padding\\n  const vBox = `${svgBounds.x - padding} ${svgBounds.y - padding} ${width} ${height}`;\\n  log.debug(`viewBox ${vBox}`);\\n  svg.attr('viewBox', vBox);\\n\\n  // Add label rects for non html labels\\n  // if (!evaluate(conf.htmlLabels) || true) {\\n  const labels = document.querySelectorAll('[id=\\\"' + id + '\\\"] .edgeLabel .label');\\n  for (let k = 0; k &lt; labels.length; k++) {\\n    const label = labels[k];\\n\\n    // Get dimensions of label\\n    const dim = label.getBBox();\\n\\n    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');\\n    rect.setAttribute('rx', 0);\\n    rect.setAttribute('ry', 0);\\n    rect.setAttribute('width', dim.width);\\n    rect.setAttribute('height', dim.height);\\n\\n    label.insertBefore(rect, label.firstChild);\\n    // }\\n  }\\n};\\n\\nexport default {\\n  setConf,\\n  getClasses,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"import mermaidAPI from '../../mermaidAPI';\\nimport * as configApi from '../../config';\\n\\nlet title = '';\\nlet currentSection = '';\\n\\nconst sections = [];\\nconst tasks = [];\\nconst rawTasks = [];\\n\\nexport const parseDirective = function (statement, context, type) {\\n  mermaidAPI.parseDirective(this, statement, context, type);\\n};\\n\\nexport const clear = function () {\\n  sections.length = 0;\\n  tasks.length = 0;\\n  currentSection = '';\\n  title = '';\\n  rawTasks.length = 0;\\n};\\n\\nexport const setTitle = function (txt) {\\n  title = txt;\\n};\\n\\nexport const getTitle = function () {\\n  return title;\\n};\\n\\nexport const addSection = function (txt) {\\n  currentSection = txt;\\n  sections.push(txt);\\n};\\n\\nexport const getSections = function () {\\n  return sections;\\n};\\n\\nexport const getTasks = function () {\\n  let allItemsProcessed = compileTasks();\\n  const maxDepth = 100;\\n  let iterationCount = 0;\\n  while (!allItemsProcessed &amp;&amp; iterationCount &lt; maxDepth) {\\n    allItemsProcessed = compileTasks();\\n    iterationCount++;\\n  }\\n\\n  tasks.push(...rawTasks);\\n\\n  return tasks;\\n};\\n\\nconst updateActors = function () {\\n  const tempActors = [];\\n  tasks.forEach((task) =&gt; {\\n    if (task.people) {\\n      tempActors.push(...task.people);\\n    }\\n  });\\n\\n  const unique = new Set(tempActors);\\n  return [...unique].sort();\\n};\\n\\nexport const addTask = function (descr, taskData) {\\n  const pieces = taskData.substr(1).split(':');\\n\\n  let score = 0;\\n  let peeps = [];\\n  if (pieces.length === 1) {\\n    score = Number(pieces[0]);\\n    peeps = [];\\n  } else {\\n    score = Number(pieces[0]);\\n    peeps = pieces[1].split(',');\\n  }\\n  const peopleList = peeps.map((s) =&gt; s.trim());\\n\\n  const rawTask = {\\n    section: currentSection,\\n    type: currentSection,\\n    people: peopleList,\\n    task: descr,\\n    score,\\n  };\\n\\n  rawTasks.push(rawTask);\\n};\\n\\nexport const addTaskOrg = function (descr) {\\n  const newTask = {\\n    section: currentSection,\\n    type: currentSection,\\n    description: descr,\\n    task: descr,\\n    classes: [],\\n  };\\n  tasks.push(newTask);\\n};\\n\\nconst compileTasks = function () {\\n  const compileTask = function (pos) {\\n    return rawTasks[pos].processed;\\n  };\\n\\n  let allProcessed = true;\\n  for (let i = 0; i &lt; rawTasks.length; i++) {\\n    compileTask(i);\\n\\n    allProcessed = allProcessed &amp;&amp; rawTasks[i].processed;\\n  }\\n  return allProcessed;\\n};\\n\\nconst getActors = function () {\\n  return updateActors();\\n};\\n\\nexport default {\\n  parseDirective,\\n  getConfig: () =&gt; configApi.getConfig().journey,\\n  clear,\\n  setTitle,\\n  getTitle,\\n  addSection,\\n  getSections,\\n  getTasks,\\n  addTask,\\n  addTaskOrg,\\n  getActors,\\n};\\n\"</span>,<span class=\"code-string\">\"import { arc as d3arc } from 'd3';\\n\\nexport const drawRect = function (elem, rectData) {\\n  const rectElem = elem.append('rect');\\n  rectElem.attr('x', rectData.x);\\n  rectElem.attr('y', rectData.y);\\n  rectElem.attr('fill', rectData.fill);\\n  rectElem.attr('stroke', rectData.stroke);\\n  rectElem.attr('width', rectData.width);\\n  rectElem.attr('height', rectData.height);\\n  rectElem.attr('rx', rectData.rx);\\n  rectElem.attr('ry', rectData.ry);\\n\\n  if (typeof rectData.class !== 'undefined') {\\n    rectElem.attr('class', rectData.class);\\n  }\\n\\n  return rectElem;\\n};\\n\\nexport const drawFace = function (element, faceData) {\\n  const radius = 15;\\n  const circleElement = element\\n    .append('circle')\\n    .attr('cx', faceData.cx)\\n    .attr('cy', faceData.cy)\\n    .attr('class', 'face')\\n    .attr('r', radius)\\n    .attr('stroke-width', 2)\\n    .attr('overflow', 'visible');\\n\\n  const face = element.append('g');\\n\\n  //left eye\\n  face\\n    .append('circle')\\n    .attr('cx', faceData.cx - radius / 3)\\n    .attr('cy', faceData.cy - radius / 3)\\n    .attr('r', 1.5)\\n    .attr('stroke-width', 2)\\n    .attr('fill', '#666')\\n    .attr('stroke', '#666');\\n\\n  //right eye\\n  face\\n    .append('circle')\\n    .attr('cx', faceData.cx + radius / 3)\\n    .attr('cy', faceData.cy - radius / 3)\\n    .attr('r', 1.5)\\n    .attr('stroke-width', 2)\\n    .attr('fill', '#666')\\n    .attr('stroke', '#666');\\n\\n  /** @param {any} face */\\n  function smile(face) {\\n    const arc = d3arc()\\n      .startAngle(Math.PI / 2)\\n      .endAngle(3 * (Math.PI / 2))\\n      .innerRadius(radius / 2)\\n      .outerRadius(radius / 2.2);\\n    //mouth\\n    face\\n      .append('path')\\n      .attr('class', 'mouth')\\n      .attr('d', arc)\\n      .attr('transform', 'translate(' + faceData.cx + ',' + (faceData.cy + 2) + ')');\\n  }\\n\\n  /** @param {any} face */\\n  function sad(face) {\\n    const arc = d3arc()\\n      .startAngle((3 * Math.PI) / 2)\\n      .endAngle(5 * (Math.PI / 2))\\n      .innerRadius(radius / 2)\\n      .outerRadius(radius / 2.2);\\n    //mouth\\n    face\\n      .append('path')\\n      .attr('class', 'mouth')\\n      .attr('d', arc)\\n      .attr('transform', 'translate(' + faceData.cx + ',' + (faceData.cy + 7) + ')');\\n  }\\n\\n  /** @param {any} face */\\n  function ambivalent(face) {\\n    face\\n      .append('line')\\n      .attr('class', 'mouth')\\n      .attr('stroke', 2)\\n      .attr('x1', faceData.cx - 5)\\n      .attr('y1', faceData.cy + 7)\\n      .attr('x2', faceData.cx + 5)\\n      .attr('y2', faceData.cy + 7)\\n      .attr('class', 'mouth')\\n      .attr('stroke-width', '1px')\\n      .attr('stroke', '#666');\\n  }\\n\\n  if (faceData.score &gt; 3) {\\n    smile(face);\\n  } else if (faceData.score &lt; 3) {\\n    sad(face);\\n  } else {\\n    ambivalent(face);\\n  }\\n\\n  return circleElement;\\n};\\n\\nexport const drawCircle = function (element, circleData) {\\n  const circleElement = element.append('circle');\\n  circleElement.attr('cx', circleData.cx);\\n  circleElement.attr('cy', circleData.cy);\\n  circleElement.attr('class', 'actor-' + circleData.pos);\\n  circleElement.attr('fill', circleData.fill);\\n  circleElement.attr('stroke', circleData.stroke);\\n  circleElement.attr('r', circleData.r);\\n\\n  if (typeof circleElement.class !== 'undefined') {\\n    circleElement.attr('class', circleElement.class);\\n  }\\n\\n  if (typeof circleData.title !== 'undefined') {\\n    circleElement.append('title').text(circleData.title);\\n  }\\n\\n  return circleElement;\\n};\\n\\nexport const drawText = function (elem, textData) {\\n  // Remove and ignore br:s\\n  const nText = textData.text.replace(/&lt;br\\\\s*\\\\/?&gt;/gi, ' ');\\n\\n  const textElem = elem.append('text');\\n  textElem.attr('x', textData.x);\\n  textElem.attr('y', textData.y);\\n  textElem.attr('class', 'legend');\\n\\n  textElem.style('text-anchor', textData.anchor);\\n\\n  if (typeof textData.class !== 'undefined') {\\n    textElem.attr('class', textData.class);\\n  }\\n\\n  const span = textElem.append('tspan');\\n  span.attr('x', textData.x + textData.textMargin * 2);\\n  span.text(nText);\\n\\n  return textElem;\\n};\\n\\nexport const drawLabel = function (elem, txtObject) {\\n  /**\\n   * @param {any} x\\n   * @param {any} y\\n   * @param {any} width\\n   * @param {any} height\\n   * @param {any} cut\\n   */\\n  function genPoints(x, y, width, height, cut) {\\n    return (\\n      x +\\n      ',' +\\n      y +\\n      ' ' +\\n      (x + width) +\\n      ',' +\\n      y +\\n      ' ' +\\n      (x + width) +\\n      ',' +\\n      (y + height - cut) +\\n      ' ' +\\n      (x + width - cut * 1.2) +\\n      ',' +\\n      (y + height) +\\n      ' ' +\\n      x +\\n      ',' +\\n      (y + height)\\n    );\\n  }\\n  const polygon = elem.append('polygon');\\n  polygon.attr('points', genPoints(txtObject.x, txtObject.y, 50, 20, 7));\\n  polygon.attr('class', 'labelBox');\\n\\n  txtObject.y = txtObject.y + txtObject.labelMargin;\\n  txtObject.x = txtObject.x + 0.5 * txtObject.labelMargin;\\n  drawText(elem, txtObject);\\n};\\n\\nexport const drawSection = function (elem, section, conf) {\\n  const g = elem.append('g');\\n\\n  const rect = getNoteRect();\\n  rect.x = section.x;\\n  rect.y = section.y;\\n  rect.fill = section.fill;\\n  rect.width = conf.width;\\n  rect.height = conf.height;\\n  rect.class = 'journey-section section-type-' + section.num;\\n  rect.rx = 3;\\n  rect.ry = 3;\\n  drawRect(g, rect);\\n\\n  _drawTextCandidateFunc(conf)(\\n    section.text,\\n    g,\\n    rect.x,\\n    rect.y,\\n    rect.width,\\n    rect.height,\\n    { class: 'journey-section section-type-' + section.num },\\n    conf,\\n    section.colour\\n  );\\n};\\n\\nlet taskCount = -1;\\n/**\\n * Draws an actor in the diagram with the attaced line\\n *\\n * @param {any} elem The HTML element\\n * @param {any} task The task to render\\n * @param {any} conf The global configuration\\n */\\nexport const drawTask = function (elem, task, conf) {\\n  const center = task.x + conf.width / 2;\\n  const g = elem.append('g');\\n  taskCount++;\\n  const maxHeight = 300 + 5 * 30;\\n  g.append('line')\\n    .attr('id', 'task' + taskCount)\\n    .attr('x1', center)\\n    .attr('y1', task.y)\\n    .attr('x2', center)\\n    .attr('y2', maxHeight)\\n    .attr('class', 'task-line')\\n    .attr('stroke-width', '1px')\\n    .attr('stroke-dasharray', '4 2')\\n    .attr('stroke', '#666');\\n\\n  drawFace(g, {\\n    cx: center,\\n    cy: 300 + (5 - task.score) * 30,\\n    score: task.score,\\n  });\\n\\n  const rect = getNoteRect();\\n  rect.x = task.x;\\n  rect.y = task.y;\\n  rect.fill = task.fill;\\n  rect.width = conf.width;\\n  rect.height = conf.height;\\n  rect.class = 'task task-type-' + task.num;\\n  rect.rx = 3;\\n  rect.ry = 3;\\n  drawRect(g, rect);\\n\\n  let xPos = task.x + 14;\\n  task.people.forEach((person) =&gt; {\\n    const colour = task.actors[person].color;\\n\\n    const circle = {\\n      cx: xPos,\\n      cy: task.y,\\n      r: 7,\\n      fill: colour,\\n      stroke: '#000',\\n      title: person,\\n      pos: task.actors[person].position,\\n    };\\n\\n    drawCircle(g, circle);\\n    xPos += 10;\\n  });\\n\\n  _drawTextCandidateFunc(conf)(\\n    task.task,\\n    g,\\n    rect.x,\\n    rect.y,\\n    rect.width,\\n    rect.height,\\n    { class: 'task' },\\n    conf,\\n    task.colour\\n  );\\n};\\n\\n/**\\n * Draws a background rectangle\\n *\\n * @param {any} elem The html element\\n * @param {any} bounds The bounds of the drawing\\n */\\nexport const drawBackgroundRect = function (elem, bounds) {\\n  const rectElem = drawRect(elem, {\\n    x: bounds.startx,\\n    y: bounds.starty,\\n    width: bounds.stopx - bounds.startx,\\n    height: bounds.stopy - bounds.starty,\\n    fill: bounds.fill,\\n    class: 'rect',\\n  });\\n  rectElem.lower();\\n};\\n\\nexport const getTextObj = function () {\\n  return {\\n    x: 0,\\n    y: 0,\\n    fill: undefined,\\n    'text-anchor': 'start',\\n    width: 100,\\n    height: 100,\\n    textMargin: 0,\\n    rx: 0,\\n    ry: 0,\\n  };\\n};\\n\\nexport const getNoteRect = function () {\\n  return {\\n    x: 0,\\n    y: 0,\\n    width: 100,\\n    anchor: 'start',\\n    height: 100,\\n    rx: 0,\\n    ry: 0,\\n  };\\n};\\n\\nconst _drawTextCandidateFunc = (function () {\\n  /**\\n   * @param {any} content\\n   * @param {any} g\\n   * @param {any} x\\n   * @param {any} y\\n   * @param {any} width\\n   * @param {any} height\\n   * @param {any} textAttrs\\n   * @param {any} colour\\n   */\\n  function byText(content, g, x, y, width, height, textAttrs, colour) {\\n    const text = g\\n      .append('text')\\n      .attr('x', x + width / 2)\\n      .attr('y', y + height / 2 + 5)\\n      .style('font-color', colour)\\n      .style('text-anchor', 'middle')\\n      .text(content);\\n    _setTextAttrs(text, textAttrs);\\n  }\\n\\n  /**\\n   * @param {any} content\\n   * @param {any} g\\n   * @param {any} x\\n   * @param {any} y\\n   * @param {any} width\\n   * @param {any} height\\n   * @param {any} textAttrs\\n   * @param {any} conf\\n   * @param {any} colour\\n   */\\n  function byTspan(content, g, x, y, width, height, textAttrs, conf, colour) {\\n    const { taskFontSize, taskFontFamily } = conf;\\n\\n    const lines = content.split(/&lt;br\\\\s*\\\\/?&gt;/gi);\\n    for (let i = 0; i &lt; lines.length; i++) {\\n      const dy = i * taskFontSize - (taskFontSize * (lines.length - 1)) / 2;\\n      const text = g\\n        .append('text')\\n        .attr('x', x + width / 2)\\n        .attr('y', y)\\n        .attr('fill', colour)\\n        .style('text-anchor', 'middle')\\n        .style('font-size', taskFontSize)\\n        .style('font-family', taskFontFamily);\\n      text\\n        .append('tspan')\\n        .attr('x', x + width / 2)\\n        .attr('dy', dy)\\n        .text(lines[i]);\\n\\n      text\\n        .attr('y', y + height / 2.0)\\n        .attr('dominant-baseline', 'central')\\n        .attr('alignment-baseline', 'central');\\n\\n      _setTextAttrs(text, textAttrs);\\n    }\\n  }\\n\\n  /**\\n   * @param {any} content\\n   * @param {any} g\\n   * @param {any} x\\n   * @param {any} y\\n   * @param {any} width\\n   * @param {any} height\\n   * @param {any} textAttrs\\n   * @param {any} conf\\n   */\\n  function byFo(content, g, x, y, width, height, textAttrs, conf) {\\n    const body = g.append('switch');\\n    const f = body\\n      .append('foreignObject')\\n      .attr('x', x)\\n      .attr('y', y)\\n      .attr('width', width)\\n      .attr('height', height)\\n      .attr('position', 'fixed');\\n\\n    const text = f\\n      .append('xhtml:div')\\n      .style('display', 'table')\\n      .style('height', '100%')\\n      .style('width', '100%');\\n\\n    text\\n      .append('div')\\n      .attr('class', 'label')\\n      .style('display', 'table-cell')\\n      .style('text-align', 'center')\\n      .style('vertical-align', 'middle')\\n      .text(content);\\n\\n    byTspan(content, body, x, y, width, height, textAttrs, conf);\\n    _setTextAttrs(text, textAttrs);\\n  }\\n\\n  /**\\n   * @param {any} toText\\n   * @param {any} fromTextAttrsDict\\n   */\\n  function _setTextAttrs(toText, fromTextAttrsDict) {\\n    for (const key in fromTextAttrsDict) {\\n      if (key in fromTextAttrsDict) {\\n        // eslint-disable-line\\n        // noinspection JSUnfilteredForInLoop\\n        toText.attr(key, fromTextAttrsDict[key]);\\n      }\\n    }\\n  }\\n\\n  return function (conf) {\\n    return conf.textPlacement === 'fo' ? byFo : conf.textPlacement === 'old' ? byText : byTspan;\\n  };\\n})();\\n\\nconst initGraphics = function (graphics) {\\n  graphics\\n    .append('defs')\\n    .append('marker')\\n    .attr('id', 'arrowhead')\\n    .attr('refX', 5)\\n    .attr('refY', 2)\\n    .attr('markerWidth', 6)\\n    .attr('markerHeight', 4)\\n    .attr('orient', 'auto')\\n    .append('path')\\n    .attr('d', 'M 0,0 V 4 L6,2 Z'); // this is actual shape for arrowhead\\n};\\n\\nexport default {\\n  drawRect,\\n  drawCircle,\\n  drawSection,\\n  drawText,\\n  drawLabel,\\n  drawTask,\\n  drawBackgroundRect,\\n  getTextObj,\\n  getNoteRect,\\n  initGraphics,\\n};\\n\"</span>,<span class=\"code-string\">\"import { select } from 'd3';\\nimport { parser } from './parser/journey';\\nimport journeyDb from './journeyDb';\\nimport svgDraw from './svgDraw';\\nimport { getConfig } from '../../config';\\nimport { configureSvgSize } from '../../utils';\\n\\nparser.yy = journeyDb;\\n\\nexport const setConf = function (cnf) {\\n  const keys = Object.keys(cnf);\\n\\n  keys.forEach(function (key) {\\n    conf[key] = cnf[key];\\n  });\\n};\\n\\nconst actors = {};\\n\\n/** @param {any} diagram */\\nfunction drawActorLegend(diagram) {\\n  const conf = getConfig().journey;\\n  // Draw the actors\\n  let yPos = 60;\\n  Object.keys(actors).forEach((person) =&gt; {\\n    const colour = actors[person].color;\\n\\n    const circleData = {\\n      cx: 20,\\n      cy: yPos,\\n      r: 7,\\n      fill: colour,\\n      stroke: '#000',\\n      pos: actors[person].position,\\n    };\\n    svgDraw.drawCircle(diagram, circleData);\\n\\n    const labelData = {\\n      x: 40,\\n      y: yPos + 7,\\n      fill: '#666',\\n      text: person,\\n      textMargin: conf.boxTextMargin | 5,\\n    };\\n    svgDraw.drawText(diagram, labelData);\\n\\n    yPos += 20;\\n  });\\n}\\nconst conf = getConfig().journey;\\nconst LEFT_MARGIN = getConfig().journey.leftMargin;\\nexport const draw = function (text, id) {\\n  const conf = getConfig().journey;\\n  parser.yy.clear();\\n  parser.parse(text + '\\\\n');\\n\\n  const securityLevel = getConfig().securityLevel;\\n  // Handle root and ocument for when rendering in sanbox mode\\n  let sandboxElement;\\n  if (securityLevel === 'sandbox') {\\n    sandboxElement = select('#i' + id);\\n  }\\n  const root =\\n    securityLevel === 'sandbox'\\n      ? select(sandboxElement.nodes()[0].contentDocument.body)\\n      : select('body');\\n  const doc = securityLevel === 'sandbox' ? sandboxElement.nodes()[0].contentDocument : document;\\n\\n  bounds.init();\\n  const diagram = root.select('#' + id);\\n  diagram.attr('xmlns:xlink', 'http://www.w3.org/1999/xlink');\\n\\n  svgDraw.initGraphics(diagram);\\n\\n  const tasks = parser.yy.getTasks();\\n  const title = parser.yy.getTitle();\\n\\n  const actorNames = parser.yy.getActors();\\n  for (let member in actors) delete actors[member];\\n  let actorPos = 0;\\n  actorNames.forEach((actorName) =&gt; {\\n    actors[actorName] = {\\n      color: conf.actorColours[actorPos % conf.actorColours.length],\\n      position: actorPos,\\n    };\\n    actorPos++;\\n  });\\n\\n  drawActorLegend(diagram);\\n  bounds.insert(0, 0, LEFT_MARGIN, Object.keys(actors).length * 50);\\n  drawTasks(diagram, tasks, 0);\\n\\n  const box = bounds.getBounds();\\n  if (title) {\\n    diagram\\n      .append('text')\\n      .text(title)\\n      .attr('x', LEFT_MARGIN)\\n      .attr('font-size', '4ex')\\n      .attr('font-weight', 'bold')\\n      .attr('y', 25);\\n  }\\n  const height = box.stopy - box.starty + 2 * conf.diagramMarginY;\\n  const width = LEFT_MARGIN + box.stopx + 2 * conf.diagramMarginX;\\n\\n  configureSvgSize(diagram, height, width, conf.useMaxWidth);\\n\\n  // Draw activity line\\n  diagram\\n    .append('line')\\n    .attr('x1', LEFT_MARGIN)\\n    .attr('y1', conf.height * 4) // One section head + one task + margins\\n    .attr('x2', width - LEFT_MARGIN - 4) // Subtract stroke width so arrow point is retained\\n    .attr('y2', conf.height * 4)\\n    .attr('stroke-width', 4)\\n    .attr('stroke', 'black')\\n    .attr('marker-end', 'url(#arrowhead)');\\n\\n  const extraVertForTitle = title ? 70 : 0;\\n  diagram.attr('viewBox', `${box.startx} -25 ${width} ${height + extraVertForTitle}`);\\n  diagram.attr('preserveAspectRatio', 'xMinYMin meet');\\n  diagram.attr('height', height + extraVertForTitle + 25);\\n};\\n\\nexport const bounds = {\\n  data: {\\n    startx: undefined,\\n    stopx: undefined,\\n    starty: undefined,\\n    stopy: undefined,\\n  },\\n  verticalPos: 0,\\n\\n  sequenceItems: [],\\n  init: function () {\\n    this.sequenceItems = [];\\n    this.data = {\\n      startx: undefined,\\n      stopx: undefined,\\n      starty: undefined,\\n      stopy: undefined,\\n    };\\n    this.verticalPos = 0;\\n  },\\n  updateVal: function (obj, key, val, fun) {\\n    if (typeof obj[key] === 'undefined') {\\n      obj[key] = val;\\n    } else {\\n      obj[key] = fun(val, obj[key]);\\n    }\\n  },\\n  updateBounds: function (startx, starty, stopx, stopy) {\\n    const conf = getConfig().journey;\\n    const _self = this;\\n    let cnt = 0;\\n    /** @param {any} type */\\n    function updateFn(type) {\\n      return function updateItemBounds(item) {\\n        cnt++;\\n        // The loop sequenceItems is a stack so the biggest margins in the beginning of the sequenceItems\\n        const n = _self.sequenceItems.length - cnt + 1;\\n        _self.updateVal(item, 'starty', starty - n * conf.boxMargin, Math.min);\\n        _self.updateVal(item, 'stopy', stopy + n * conf.boxMargin, Math.max);\\n\\n        _self.updateVal(bounds.data, 'startx', startx - n * conf.boxMargin, Math.min);\\n        _self.updateVal(bounds.data, 'stopx', stopx + n * conf.boxMargin, Math.max);\\n\\n        if (!(type === 'activation')) {\\n          _self.updateVal(item, 'startx', startx - n * conf.boxMargin, Math.min);\\n          _self.updateVal(item, 'stopx', stopx + n * conf.boxMargin, Math.max);\\n\\n          _self.updateVal(bounds.data, 'starty', starty - n * conf.boxMargin, Math.min);\\n          _self.updateVal(bounds.data, 'stopy', stopy + n * conf.boxMargin, Math.max);\\n        }\\n      };\\n    }\\n\\n    this.sequenceItems.forEach(updateFn());\\n  },\\n  insert: function (startx, starty, stopx, stopy) {\\n    const _startx = Math.min(startx, stopx);\\n    const _stopx = Math.max(startx, stopx);\\n    const _starty = Math.min(starty, stopy);\\n    const _stopy = Math.max(starty, stopy);\\n\\n    this.updateVal(bounds.data, 'startx', _startx, Math.min);\\n    this.updateVal(bounds.data, 'starty', _starty, Math.min);\\n    this.updateVal(bounds.data, 'stopx', _stopx, Math.max);\\n    this.updateVal(bounds.data, 'stopy', _stopy, Math.max);\\n\\n    this.updateBounds(_startx, _starty, _stopx, _stopy);\\n  },\\n  bumpVerticalPos: function (bump) {\\n    this.verticalPos = this.verticalPos + bump;\\n    this.data.stopy = this.verticalPos;\\n  },\\n  getVerticalPos: function () {\\n    return this.verticalPos;\\n  },\\n  getBounds: function () {\\n    return this.data;\\n  },\\n};\\n\\nconst fills = conf.sectionFills;\\nconst textColours = conf.sectionColours;\\n\\nexport const drawTasks = function (diagram, tasks, verticalPos) {\\n  const conf = getConfig().journey;\\n  let lastSection = '';\\n  const sectionVHeight = conf.height * 2 + conf.diagramMarginY;\\n  const taskPos = verticalPos + sectionVHeight;\\n\\n  let sectionNumber = 0;\\n  let fill = '#CCC';\\n  let colour = 'black';\\n  let num = 0;\\n\\n  // Draw the tasks\\n  for (let i = 0; i &lt; tasks.length; i++) {\\n    let task = tasks[i];\\n    if (lastSection !== task.section) {\\n      fill = fills[sectionNumber % fills.length];\\n      num = sectionNumber % fills.length;\\n      colour = textColours[sectionNumber % textColours.length];\\n\\n      const section = {\\n        x: i * conf.taskMargin + i * conf.width + LEFT_MARGIN,\\n        y: 50,\\n        text: task.section,\\n        fill,\\n        num,\\n        colour,\\n      };\\n\\n      svgDraw.drawSection(diagram, section, conf);\\n      lastSection = task.section;\\n      sectionNumber++;\\n    }\\n\\n    // Collect the actors involved in the task\\n    const taskActors = task.people.reduce((acc, actorName) =&gt; {\\n      if (actors[actorName]) {\\n        acc[actorName] = actors[actorName];\\n      }\\n\\n      return acc;\\n    }, {});\\n\\n    // Add some rendering data to the object\\n    task.x = i * conf.taskMargin + i * conf.width + LEFT_MARGIN;\\n    task.y = taskPos;\\n    task.width = conf.diagramMarginX;\\n    task.height = conf.diagramMarginY;\\n    task.colour = colour;\\n    task.fill = fill;\\n    task.num = num;\\n    task.actors = taskActors;\\n\\n    // Draw the box with the attached line\\n    svgDraw.drawTask(diagram, task, conf);\\n    bounds.insert(task.x, task.y, task.x + task.width + conf.taskMargin, 300 + 5 * 30); // stopy is the length of the descenders.\\n  }\\n};\\n\\nexport default {\\n  setConf,\\n  draw,\\n};\\n\"</span>,<span class=\"code-string\">\"/** Created by knut on 14-12-11. */\\nimport { select } from 'd3';\\nimport { log } from './logger';\\n\\nconst conf = {};\\n\\n/**\\n * Merges the value of `conf` with the passed `cnf`\\n *\\n * @param {object} cnf Config to merge\\n */\\nexport const setConf = function (cnf) {\\n  const keys = Object.keys(cnf);\\n\\n  keys.forEach(function (key) {\\n    conf[key] = cnf[key];\\n  });\\n};\\n\\n/**\\n * Draws a an info picture in the tag with id: id based on the graph definition in text.\\n *\\n * @param {string} id The text for the error\\n * @param {string} ver The version\\n */\\nexport const draw = (id, ver) =&gt; {\\n  try {\\n    log.debug('Renering svg for syntax error\\\\n');\\n\\n    const svg = select('#' + id);\\n\\n    const g = svg.append('g');\\n\\n    g.append('path')\\n      .attr('class', 'error-icon')\\n      .attr(\\n        'd',\\n        'm411.313,123.313c6.25-6.25 6.25-16.375 0-22.625s-16.375-6.25-22.625,0l-32,32-9.375,9.375-20.688-20.688c-12.484-12.5-32.766-12.5-45.25,0l-16,16c-1.261,1.261-2.304,2.648-3.31,4.051-21.739-8.561-45.324-13.426-70.065-13.426-105.867,0-192,86.133-192,192s86.133,192 192,192 192-86.133 192-192c0-24.741-4.864-48.327-13.426-70.065 1.402-1.007 2.79-2.049 4.051-3.31l16-16c12.5-12.492 12.5-32.758 0-45.25l-20.688-20.688 9.375-9.375 32.001-31.999zm-219.313,100.687c-52.938,0-96,43.063-96,96 0,8.836-7.164,16-16,16s-16-7.164-16-16c0-70.578 57.422-128 128-128 8.836,0 16,7.164 16,16s-7.164,16-16,16z'\\n      );\\n\\n    g.append('path')\\n      .attr('class', 'error-icon')\\n      .attr(\\n        'd',\\n        'm459.02,148.98c-6.25-6.25-16.375-6.25-22.625,0s-6.25,16.375 0,22.625l16,16c3.125,3.125 7.219,4.688 11.313,4.688 4.094,0 8.188-1.563 11.313-4.688 6.25-6.25 6.25-16.375 0-22.625l-16.001-16z'\\n      );\\n\\n    g.append('path')\\n      .attr('class', 'error-icon')\\n      .attr(\\n        'd',\\n        'm340.395,75.605c3.125,3.125 7.219,4.688 11.313,4.688 4.094,0 8.188-1.563 11.313-4.688 6.25-6.25 6.25-16.375 0-22.625l-16-16c-6.25-6.25-16.375-6.25-22.625,0s-6.25,16.375 0,22.625l15.999,16z'\\n      );\\n\\n    g.append('path')\\n      .attr('class', 'error-icon')\\n      .attr(\\n        'd',\\n        'm400,64c8.844,0 16-7.164 16-16v-32c0-8.836-7.156-16-16-16-8.844,0-16,7.164-16,16v32c0,8.836 7.156,16 16,16z'\\n      );\\n\\n    g.append('path')\\n      .attr('class', 'error-icon')\\n      .attr(\\n        'd',\\n        'm496,96.586h-32c-8.844,0-16,7.164-16,16 0,8.836 7.156,16 16,16h32c8.844,0 16-7.164 16-16 0-8.836-7.156-16-16-16z'\\n      );\\n\\n    g.append('path')\\n      .attr('class', 'error-icon')\\n      .attr(\\n        'd',\\n        'm436.98,75.605c