thickness-thick {\\n    stroke-width: 3.5px\\n  }\\n  .edge-pattern-solid {\\n    stroke-dasharray: 0;\\n  }\\n\\n  .edge-pattern-dashed{\\n    stroke-dasharray: 3;\\n  }\\n  .edge-pattern-dotted {\\n    stroke-dasharray: 2;\\n  }\\n\\n  .marker {\\n    fill: ${options.lineColor};\\n    stroke: ${options.lineColor};\\n  }\\n  .marker.cross {\\n    stroke: ${options.lineColor};\\n  }\\n\\n  svg {\\n    font-family: ${options.fontFamily};\\n    font-size: ${options.fontSize};\\n  }\\n\\n  ${themes[type](options)}\\n\\n  ${userStyles}\\n`;\\n};\\n\\nexport default getStyles;\\n\"</span>,<span class=\"code-string\">\"const getStyles = (options) =&gt;\\n  `.actor {\\n    stroke: ${options.actorBorder};\\n    fill: ${options.actorBkg};\\n  }\\n\\n  text.actor &gt; tspan {\\n    fill: ${options.actorTextColor};\\n    stroke: none;\\n  }\\n\\n  .actor-line {\\n    stroke: ${options.actorLineColor};\\n  }\\n\\n  .messageLine0 {\\n    stroke-width: 1.5;\\n    stroke-dasharray: none;\\n    stroke: ${options.signalColor};\\n  }\\n\\n  .messageLine1 {\\n    stroke-width: 1.5;\\n    stroke-dasharray: 2, 2;\\n    stroke: ${options.signalColor};\\n  }\\n\\n  #arrowhead path {\\n    fill: ${options.signalColor};\\n    stroke: ${options.signalColor};\\n  }\\n\\n  .sequenceNumber {\\n    fill: ${options.sequenceNumberColor};\\n  }\\n\\n  #sequencenumber {\\n    fill: ${options.signalColor};\\n  }\\n\\n  #crosshead path {\\n    fill: ${options.signalColor};\\n    stroke: ${options.signalColor};\\n  }\\n\\n  .messageText {\\n    fill: ${options.signalTextColor};\\n    stroke: ${options.signalTextColor};\\n  }\\n\\n  .labelBox {\\n    stroke: ${options.labelBoxBorderColor};\\n    fill: ${options.labelBoxBkgColor};\\n  }\\n\\n  .labelText, .labelText &gt; tspan {\\n    fill: ${options.labelTextColor};\\n    stroke: none;\\n  }\\n\\n  .loopText, .loopText &gt; tspan {\\n    fill: ${options.loopTextColor};\\n    stroke: none;\\n  }\\n\\n  .loopLine {\\n    stroke-width: 2px;\\n    stroke-da